# #249 STAGE 5: THE HTTPS ADDRESS VIA TAILSCALE, one line per state of
# `crow_remote.tailscale_state`. Crow only reads the state; every command in
# here is the person's to run, once.
REMOTE_TAILNET_ADMIN = "https://login.tailscale.com/admin/dns"


def remote_tailnet_line(state: str, name: str = "", command: str = "") -> str:
    """The Remote dialog's status line for the HTTPS (Tailscale) address."""
    if state == "ready":
        return ("ready -- https://%s/ works wherever the phone has Tailscale "
                "on. A phone paired on the LAN address pairs once more here."
                % name)
    if state == "serve-missing":
        return ("one-time setup (survives reboots, the certificate renews "
                "itself): %s" % command)
    if state == "https-off":
        return ("HTTPS certificates are off for this tailnet -- turn on "
                "\"Enable HTTPS\" at %s" % REMOTE_TAILNET_ADMIN)
    if state == "funnel":
        return ("Tailscale Funnel is on for %s:443 -- that is public on the "
                "internet, so Crow does not serve it. Turn it off: "
                "sudo tailscale funnel --https=443 off" % name)
    if state == "down":
        return ("Tailscale is installed but not connected -- run: "
                "sudo tailscale up")
    return ("Tailscale is not installed -- install it and log in to reach "
            "Crow over HTTPS from anywhere (docs/user-guide/remote.md).")


def remote_ask_line(name: str) -> str:
    """The desktop's pairing card: a new device, named by what it said it is."""
    return "%s wants to connect" % (" ".join(str(name or "").split())
                                    or "a device")


def remote_devices_text(devices: "list[dict]") -> str:
    """`/remote devices`: one line per paired device, newest contact first."""
    if not devices:
        return "no paired devices -- /remote on shows the QR code."
    rows = sorted(devices, key=lambda d: d.get("last_seen") or 0, reverse=True)
    out = []
    for d in rows:
        seen = d.get("last_seen")
        when = (time.strftime("%Y-%m-%d %H:%M", time.localtime(seen))
                if isinstance(seen, (int, float)) and seen > 0 else "never")
        out.append("  %s%s  · last seen %s" % (
            d.get("name") or d.get("id") or "?",
            "  · online" if d.get("online") else "", when))
    return "paired devices:\n" + "\n".join(out)


def remote_status_text(*, on: bool, url: str, devices: "list[dict]",
                       firewall: str = "") -> str:
    """`/remote status`: on or off, where, who -- and the firewall line if one
    is in the way. Nothing here changes anything."""
    head = ("the phone mirror is on at %s" % url) if on else \
        "the phone mirror is off -- /remote on starts it."
    online = sum(1 for d in devices if d.get("online"))
    lines = [head, "%d paired device%s, %d online" % (
        len(devices), "" if len(devices) == 1 else "s", online)]
    if firewall:
        lines.append(firewall)
    return "\n".join(lines)


def firewall_active() -> str:
    """"ufw", "firewalld" or "" -- which Linux firewall is running, if any.

    ASKED, NEVER CHANGED (#249): the mirror prints the one command that opens
    its port for the LAN and leaves the decision to the person. `systemctl
    is-active` needs no root, unlike `ufw status`."""
    if crow_platform.IS_WINDOWS or not shutil.which("systemctl"):
        return ""
    for unit in ("ufw", "firewalld"):
        try:
            done = subprocess.run(["systemctl", "is-active", "--quiet", unit],
                                  capture_output=True, timeout=5)
        except (OSError, subprocess.SubprocessError):
            continue
        if done.returncode == 0:
            return unit
    return ""


def remote_firewall_line(port: int, host: str, active: str) -> str:
    """The one command that lets the LAN reach `port`, for the firewall that is
    `active`, or "". The source is the host's /24 -- the home network, never
    the world."""
    parts = str(host or "").split(".")
    lan = (".".join(parts[:3]) + ".0/24") if len(parts) == 4 else "<your-lan>/24"
    if active == "ufw":
        return ("ufw is active; to let the phone in: sudo ufw allow from %s "
                "to any port %d proto tcp" % (lan, int(port)))
    if active == "firewalld":
        return ("firewalld is active; to let the phone in: sudo firewall-cmd "
                "--add-rich-rule='rule family=\"ipv4\" source address=\"%s\" "
                "port port=\"%d\" protocol=\"tcp\" accept'" % (lan, int(port)))
    return ""


# #249: THE PAIRED DEVICES LIVE IN THE SECRETS STORE, under this key, as a
# list of records `{id, name, created, last_seen, token_sha256}` -- only the
# hash, never the cookie. `secret()` reads string values only, so a list here
# is invisible to every other reader of the file.
REMOTE_DEVICES_KEY = "remote_devices"


def remote_devices_load() -> "list[dict]":
    """The paired devices, or []. Never raises (see `_secret_stored`)."""
    found = _secret_stored().get(REMOTE_DEVICES_KEY)
    if not isinstance(found, list):
        return []
    return [d for d in found if isinstance(d, dict)]


def remote_devices_save(devices: "list[dict]") -> bool:
    """Write the device list back into the store, keeping every other entry.

    A STORE THAT DOES NOT PARSE IS NOT OVERWRITTEN. `_secret_stored` reads a
    broken file as "empty", and writing that empty back plus one list would
    delete every key the user put there by hand. Atomic (temp file + replace)
    and owner-only, like the token store."""
    doc: dict = {}
    if os.path.exists(SECRETS_FILE):
        try:
            with open(SECRETS_FILE, encoding="utf-8-sig") as fh:
                doc = json.load(fh)
        except (OSError, ValueError):
            log_note("remote: %s is not readable JSON; the device list was "
                     "not written" % SECRETS_FILE, "remote")
            return False
        if not isinstance(doc, dict):
            log_note("remote: %s is not a JSON object; the device list was "
                     "not written" % SECRETS_FILE, "remote")
            return False
    doc[REMOTE_DEVICES_KEY] = [dict(d) for d in devices]
    try:
        os.makedirs(os.path.dirname(SECRETS_FILE) or ".", exist_ok=True)
        fd, tmp = tempfile.mkstemp(prefix=".secrets-",
                                   dir=os.path.dirname(SECRETS_FILE) or ".")
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump(doc, fh, indent=1)
        try:
            os.chmod(tmp, 0o600)
        except OSError:
            pass
        os.replace(tmp, SECRETS_FILE)
    except OSError as exc:
        log_note("remote: the device list could not be written: %s" % exc,
                 "remote")
        return False
    return True


def goal_command(argument: str) -> "tuple[str, dict | None, bool]":
    """`/goal` zeigt, `/goal <Zeilen>` setzt, `/goal off` loescht,
    `/goal skip <n> [Grund]` gibt einen Schritt auf (#289).

    (Satz, Ziel, geaendert) -- dieselbe Form wie `reasoning_command`, damit beide
    Oberflaechen dasselbe Wort gleich beantworten.

    DER TITEL IST DIE ERSTE ZEILE, die Schritte sind die folgenden. Einzeilig
    getippt trennt `|`, weil ein Terminal keine zweite Zeile hergibt.

    EIN ZIEL OHNE SCHRITTE WIRD ABGELEHNT statt angelegt: der Zaehler waere 0/0
    und der Kopf traege eine Ueberschrift, an der nichts haengt.
    """
    text = (argument or "").strip()
    if not text:
        said = goal_summary()
        return (said or "no goal. `/goal <title>` then one step per line, "
                        "or `title | step | step`.", goal_load(), False)
    # #289: `/goal skip <n> [reason]` -- ONE LINE, a number after the word.
    # "skip the intro | a | b" stays a goal title.
    redo = _GOAL_REDO.match(text)                              # #296
    if redo:
        n = int(redo.group(1))
        goal, why = goal_step_redo(n - 1)
        if goal is None:
            return (why or "nothing reopened.", goal_load(), False)
        return ("step %d is open again." % n, goal, True)
    skip = _GOAL_SKIP.match(text)
    if skip:
        n, reason = int(skip.group(1)), (skip.group(2) or "").strip()
        goal, why = goal_step_skip(n - 1, reason)
        if goal is None:
            return (why or "nothing skipped.", goal_load(), False)
        nxt = goal_next_open(goal)
        after = ("next is step %d: %s" % (nxt + 1, goal["steps"][nxt]["text"])
                 if nxt is not None else goal_summary(goal))
        return ("step %d skipped%s. %s"
                % (n, " (%s)" % reason if reason else "", after), goal, True)
    if text.lower() in ("off", "clear", "done"):
        if goal_load() is None:
            return ("no goal to clear.", None, False)
        goal_write(None)
        goal_check_set(None)                                   # #250
        goal_accept_set(None)                                  # #266
        goal_references_set(None)                              # #295
        return ("goal cleared.", None, True)
    lines = [p.strip() for p in text.splitlines() if p.strip()]
    if len(lines) == 1:
        lines = [p.strip() for p in lines[0].split("|") if p.strip()]
    # #250: `check: <command>` is the acceptance check, not a step.
    checks = [ln[len(GOAL_CHECK_PREFIX):].strip() for ln in lines
              if ln.lower().startswith(GOAL_CHECK_PREFIX)]
    lines = [ln for ln in lines if not ln.lower().startswith(GOAL_CHECK_PREFIX)]
    # #266: `accept: <criterion>` is the judge's rubric, not a step.
    accepts = [ln[len(GOAL_ACCEPT_PREFIX):].strip() for ln in lines
               if ln.lower().startswith(GOAL_ACCEPT_PREFIX)]
    accepts = [a for a in accepts if a]
    lines = [ln for ln in lines if not ln.lower().startswith(GOAL_ACCEPT_PREFIX)]
    # #295: `reference: <image> -- <criterion>` is a reference image for
    # the judge, not a step. A missing file refuses the whole line: a goal
    # whose reference silently vanished would be judged on less than asked.
    refs, ref_bad = [], []
    for ln in lines:
        if ln.lower().startswith(GOAL_REFERENCE_PREFIX):
            ref, bad = goal_reference_parse(ln[len(GOAL_REFERENCE_PREFIX):])
            if ref is not None:
                refs.append(ref)
            else:
                ref_bad.append(bad)
    if ref_bad:
        return ("not set: %s." % "; ".join(ref_bad), goal_load(), False)
    lines = [ln for ln in lines
             if not ln.lower().startswith(GOAL_REFERENCE_PREFIX)]
    if len(lines) < 2:
        return ("a goal needs steps: `/goal <title>` then one step per line, "
                "or `title | step | step`.", goal_load(), False)
    goal = goal_start(lines[0], lines[1:], by=GOAL_BY_USER)
    if goal is None:
        return ("that is not a goal I can hold.", goal_load(), False)
    check = next((c for c in reversed(checks) if c), None)
    goal_check_set(check)
    goal_accept_set(accepts)                                   # #266
    goal_references_set(refs)                                  # #295
    # DIE KOSTEN STEHEN VOR DER TAT, wie bei jeder Kopfaenderung: das Ziel geht
    # in den gepinnten Block, also zahlt der naechste Zug einen vollen Prefill.
    return ("goal: %s -- %d steps%s%s%s.\n%s"
            % (goal["title"], len(goal["steps"]),
               ", acceptance check: %s" % check if check else "",
               ", %d accept line%s for the judge"
               % (len(accepts), "" if len(accepts) == 1 else "s")
               if accepts else "",
               ", %d reference image%s (advisory)"
               % (len(refs[:GOAL_REFERENCE_MAX]),
                  "" if len(refs) == 1 else "s") if refs else "",
               GOAL_COST_NOTE), goal, True)


# #289: `/goal skip 4 not verifiable here`.
_GOAL_SKIP = re.compile(r"(?i)^skip[ \t]+(\d+)(?:[ \t]+([^\n]*))?$")
# #296: `/goal redo 4` -- the user takes their skip back.
_GOAL_REDO = re.compile(r"(?i)^redo[ \t]+(\d+)[ \t]*$")


# #240: who wrote a plan -- the user through `/goal`, or the model through
# `goal_set`. Only the user's plan names places the user named.
GOAL_BY_USER = "user"
GOAL_BY_MODEL = "model"

GOAL_COST_NOTE = ("the goal goes into the head of every prompt -- "
                  "the next turn pays a full prefill")


# #196. EIN STRING IST KEIN PLAN, auch wenn `for` ihn klaglos durchlaeuft. Live
# am 2026-09-18: das Modell rief `goal_set` mit `steps` als JSON-STRING statt
# als Liste -- 976 Zeichen, und mitten darin ein verrutschtes Anfuehrungszeichen.
# Der Handler nahm den String und iterierte ihn: 852 Schritte, jeder ein
# einzelnes Zeichen (`[`, `{`, `"`, `i`, `t`, ...), und das Panel zeigte 0/852.
# Kein Aufruf ist fehlgeschlagen, nichts hat gewarnt -- das ist das Teure daran.
#
# ZWEIMAL DASSELBE NEIN. Der Text unten ist der ganze Vertrag: was nicht die
# deklarierte Form hat, wird NICHT iteriert, sondern zurueckgewiesen, damit das
# Modell es in der naechsten Runde richtig schickt.
_GOAL_STEPS_SHAPE = "steps must be a JSON array of strings, got %s"

# WELCHER SCHLUESSEL EIN SCHRITT IST, wenn das Modell Objekte statt Zeilen
# schickt -- was es tut, obwohl das Schema `string` sagt (gesehen am 2026-09-18:
# `{"item": "...", "status": "done"}`). Das ist kein Fehler, den man dem Modell
# vorhalten muss; es ist eine Schreibweise, die dieselbe Absicht traegt.
_GOAL_STEP_KEYS = ("item", "title", "text", "step")


def goal_steps_from(steps) -> "tuple[list[str] | None, str | None]":
    """Was als `steps` ankam, als Liste von Zeilen -- oder ein Fehler, nie beides.

    DER EINE PARSE-VERSUCH: ein Modell, das sein JSON doppelt verpackt, hat sich
    vertippt und soll daran nicht scheitern. Was dabei nicht aufgeht, kommt als
    Fehlertext zurueck -- mit der Stelle, an der das JSON bricht, weil genau die
    dem Modell sagt, was es anders schreiben muss.

    DIE EINZELZEICHEN-PROBE ist Guertel neben Hosentraeger: sie beschreibt die
    Havarie aus #196 in ihrer reinen Form. Ein Plan aus 852 Schritten der Laenge
    eins ist kein Plan, sondern ein iterierter String, und selbst wenn er hier
    auf einem anderen Weg ankaeme, wird er nicht zum Ziel.
    """
    if isinstance(steps, str):
        try:
            steps = json.loads(steps)
        except (json.JSONDecodeError, ValueError) as exc:
            return None, _GOAL_STEPS_SHAPE % (
                "a string that is not valid JSON: %s" % exc)
        if not isinstance(steps, list):
            return None, _GOAL_STEPS_SHAPE % (
                "a string holding %s" % type(steps).__name__)
    if steps is None:
        steps = []
    if not isinstance(steps, (list, tuple)):
        return None, _GOAL_STEPS_SHAPE % type(steps).__name__
    steps = list(steps)
    if len(steps) > 20 and all(isinstance(s, str) and len(s) == 1 for s in steps):
        return None, _GOAL_STEPS_SHAPE % (
            "%d single-character items -- a JSON string was iterated instead of "
            "parsed" % len(steps))
    out = []
    for n, item in enumerate(steps):
        if isinstance(item, str):
            out.append(item)
            continue
        if isinstance(item, dict):
            named = next((item[k] for k in _GOAL_STEP_KEYS
                          if isinstance(item.get(k), str) and item[k].strip()), None)
            if named is None:
                return None, _GOAL_STEPS_SHAPE % (
                    "an object with no item/title/text/step key at index %d" % n)
            out.append(named)
            continue
        return None, _GOAL_STEPS_SHAPE % (
            "%s at index %d" % (type(item).__name__, n))
    return out, None


def _goal_step_norm(text: str) -> str:
    """#210: Kleinschreibung und Weite gefaltet -- derselbe Schritt, anders
    getippt, ist fuer die Marken-Uebertragung derselbe Schritt."""
    return " ".join(str(text or "").lower().split())


# #260: what a carried step keeps -- everything but its text.
_GOAL_CARRIED_FIELDS = ("status", "note", "started", "started_tokens",
                        "seconds", "tokens", "delegated",
                        "failures", "skipped_by")             # #289
# #294/#295: what every matched step keeps, whatever its status.
_GOAL_LADDER_FIELDS = ("checklist", "checklist_from", "checklist_at", "passed",
                       "judge", "failures", "env_failures", "unknowns",
                       "pending", "env_seen", "fail_log", "reflections", "subs",
                       "capture", "budget_base")
# ... and what the goal keeps: its clock and its bill, in pairs.
_GOAL_CARRIED_TOTALS = ("spent", "last_spent", "delegated", "created",
                        "started", "last_at")


def _carry_goal_marks(old: "dict | None", new: "dict") -> "dict | None":
    """#210. Die Haken eines laufenden Ziels auf den neuen Plan uebertragen.

    GEMESSEN AM 2026-09-22: nach einem Rollover (der Stand stand nirgends --
    siehe `goal_block`) baute das Modell denselben Plan drei Mal neu, und
    jeder `goal_set` loeschte alle Haken des Ziels, an dem es gerade sass.
    `goal_start` ersetzt ein laufendes Ziel absichtlich (eines zur Zeit) --
    aber ERSETZEN heisst nicht VERGESSEN: ein Schritt, der da steht und
    wieder da steht, war fertig und bleibt es.

    GETROFFEN WIRD NACH TEXT, normalisiert. Ein Modell, das neu plant,
    formuliert Schritte um; exakte Gleichheit finge fast nichts. Gross- und
    Kleinschreibung und Leerraum sind keine anderen Schritte, inhaltliche
    Umstellungen sind es -- und die bleiben dann ehrlich offen.

    NUR DONE UND FAILED REITEN. Ein `running` gehoert zu dem Zug, der gerade
    abgeschnitten oder beendet wurde -- der neue Plan sagt selbst, wo er
    anfaengt.

    #260: DER GANZE SCHRITT REITET, NICHT NUR SEIN HAKEN.
    Bis hierher stand: "niemand schreibt Zeiten oder Token um, das getragene
    Zeichen ist die Marke, nicht die Rechnung" -- und mit der Rechnung ging
    die NOTIZ. Gemessen am 2026-09-23 (Diorama-Lauf): ein `goal_set` mitten
    im Ziel meldete "carried: done 6/9", und danach stand in goal.json bei
    allen neun Schritten `note: ""` -- die Belege ("Verified by screenshot:
    ...") waren weg, und #250s Pruefung "done nach failed braucht eine Notiz"
    liest genau dieses Feld. Getragen wird deshalb alles, was der Schritt
    ueber sich weiss (`_GOAL_CARRIED_FIELDS`), und die Bilanz des Ziels
    (`_GOAL_CARRIED_TOTALS`) mit: sonst stuende in der Schrittspalte mehr,
    als das Ziel gekostet haben will. `last_at`/`last_spent` gehen PAARWEISE
    mit `spent`: `goal_step_end` rechnet dem naechsten Schritt `spent -
    last_spent` an, und ein getragenes `spent` ueber einem frischen
    `last_spent` 0 schriebe ihm die Kosten des ganzen Ziels zu. Der Text bleibt der
    des neuen Plans -- er ist das, was das Modell gerade geschrieben hat.
    """
    steps_old = (old or {}).get("steps") or []
    # #294/#295: THE CONTRACT AND THE LADDER RIDE WITH ANY MATCHED STEP, also
    # a running one -- a replan must not be the way out of a frozen
    # checklist or a failure count.
    ladder = {_goal_step_norm(s.get("text")): s for s in steps_old}
    for step in new.get("steps") or []:
        found = ladder.get(_goal_step_norm(step.get("text")))
        if found is not None:
            for field in _GOAL_LADDER_FIELDS:
                if field in found:
                    step[field] = found[field]
    marks = {_goal_step_norm(s.get("text")): s
             for s in steps_old
             if s.get("status") in (GOAL_DONE, GOAL_FAILED, GOAL_SKIPPED)}
    if not marks:
        return None
    hits = 0
    for step in new.get("steps") or []:
        found = marks.get(_goal_step_norm(step.get("text")))
        if found is not None:
            for field in _GOAL_CARRIED_FIELDS:
                if field in found:
                    step[field] = found[field]
            hits += 1
    if not hits:
        return None
    for field in _GOAL_CARRIED_TOTALS:
        if (old or {}).get(field) is not None:
            new[field] = old[field]
    return {"done": sum(1 for s in steps_old if s.get("status") == GOAL_DONE),
            "of": len(steps_old), "matched": hits}


def tool_goal_set(title: str, steps: "list | None" = None) -> str:
    """#165. Das Modell schreibt seinen eigenen Plan. Gibt JSON zurueck.

    OHNE ZWEITE MEINUNG UEBER DEN INHALT: was ein guter Plan ist, entscheidet
    das Modell. Was hier geprueft wird, ist nur, ob es ueberhaupt einer ist --
    ein Titel und mindestens zwei Schritte. Ein einziger Schritt ist kein Plan,
    sondern die Aufgabe noch einmal.

    UND OB ES UEBERHAUPT EINE LISTE IST (#196). `run_tool` faengt die verpackte
    Form schon an der Naht ab; dieser Handler prueft trotzdem selbst, weil er
    auch direkt gerufen wird und ein Ziel aus einem String nie entstehen darf.

    #210. EIN LAUFENDES ZIEL WIRD ERSETZT, ABER NICHT VERGESSEN: Haken auf
    treffende Schritte reiten mit, und die Antwort sagt es dem Modell -- es
    liest daraus, wie weit der alte Plan war, ohne ihn neu zu erraten.
    """
    packed = isinstance(steps, str)
    steps, bad = goal_steps_from(steps)
    if bad is not None:
        return json.dumps({"ok": False, "error": bad})
    clean = [str(s).strip() for s in steps if str(s).strip()]
    if len(clean) < 2:
        return json.dumps({"ok": False,
                           "error": "a plan needs at least two steps"})
    # #210. DER ALTE PLAN VOR DEM NEUEN GELESEN -- `goal_start` ueberschreibt
    # goal.json, und was dann noch in ihm stand, steht nur noch hier.
    before = goal_load()
    # #294: A PAUSED GOAL IS THE USER'S TO RESUME. A fresh plan written over it
    # would clear the pause without them -- the silent move-on again.
    if goal_paused(before) is not None:
        return json.dumps({"ok": False, "error": (
            "the goal is PAUSED and waits for the user's line; a new plan "
            "cannot replace it now. Write your report and stop.")})
    goal = goal_start(str(title or "").strip() or "the task", clean,
                      by=GOAL_BY_MODEL)
    if goal is None:
        return json.dumps({"ok": False, "error": "could not write the plan"})
    carried = _carry_goal_marks(before, goal)
    # #294/#295: written also when only the ladder fields rode along.
    goal_write(goal)
    # #210. `next` NENNT DEN ERSTEN OFFENEN SCHRITT, nicht blind den ersten:
    # ein getragener Haken vorn im Plan waere eine Anweisung, Fertigtes noch
    # einmal zu tun -- genau die Schleife, die das Panel zeigen wuerde.
    nxt = next((n for n, s in enumerate(goal["steps"], 1)
                if s.get("status") not in (GOAL_DONE, GOAL_SKIPPED)), 1)
    out = {"ok": True, "title": goal["title"],
           "steps": len(goal["steps"]),
           "next": nxt, "first": goal["steps"][nxt - 1]["text"]}
    if carried:
        out["carried"] = carried
    if packed:
        out["note"] = ("steps arrived as a JSON string and was parsed into an "
                       "array of %d" % len(clean))
    return json.dumps(out)


def tool_goal_step(step: int, status: str, note: str = "", checklist=None,
                   substeps=None, sub=None) -> str:
    """#165. Einen Schritt bewegen. Gibt JSON mit dem naechsten offenen zurueck.

    DIE ANTWORT NENNT DEN NAECHSTEN SCHRITT, und das ist der Motor selbst: das
    Modell bekommt nach jedem Haken gesagt, was als Naechstes ansteht, ohne
    danach fragen zu muessen.

    EINS-BASIERT NACH AUSSEN, weil der Plan so aufgezaehlt wird, wie ein Mensch
    ihn liest -- und weil das Modell die Nummer aus genau dieser Liste abliest.

    #294: `failed` has a class and a ladder (`goal_fail`), never a skip;
    `split` writes the sub-steps of the ADaPT rung, `sub` reports one.
    #295: `checklist` on `running` is the step's contract, written once.
    """
    try:
        index = int(step) - 1
    except (TypeError, ValueError):
        return json.dumps({"ok": False, "error": "step must be a number"})
    state = str(status or "").strip().lower()
    current = goal_load()
    steps = (current or {}).get("steps") or []
    if 0 <= index < len(steps):
        # #294: A PAUSED GOAL WAITS FOR THE USER. The report turn says "no
        # tools"; a model that moves a step anyway would move it past them.
        pause = goal_paused(current)
        if pause is not None:
            return json.dumps({"ok": False, "error": (
                "the goal is PAUSED at step %s and waits for the user's line (%s). "
                "Call no tools: write your report for them and stop."
                % (pause.get("step"), _clip(pause.get("why") or "", 200)))})
        # #296: THE USER'S SKIP IS THEIR WORD. The model may not turn it into
        # `done` (2026-09-24: step 4 "skipped by the owner" stored as done) nor
        # take it up again; `/goal redo n` is the way back, and it is theirs.
        mine = steps[index]
        if (mine.get("status") == GOAL_SKIPPED
                and mine.get("skipped_by") == GOAL_BY_USER):
            return json.dumps({"ok": False, "error": (
                "step %d was skipped by the user (\"%s\"); only the user can "
                "take it back with `/goal redo %d`. Continue with the next "
                "step." % (index + 1, _clip(mine.get("note") or "", 160),
                           index + 1))})
    if sub is not None and str(sub).strip() != "":
        try:
            k = int(sub) - 1
        except (TypeError, ValueError):
            return json.dumps({"ok": False, "error": "sub must be a number"})
        if state not in (GOAL_DONE, GOAL_FAILED):
            return json.dumps({"ok": False, "error": "a sub-step is reported "
                                                     "done or failed"})
        goal, bad = goal_sub_end(index, k, state == GOAL_DONE, note)
        if goal is None:
            return json.dumps({"ok": False, "error": bad})
        own = goal["steps"][index]
        out = {"ok": True, "step": index + 1, "sub": "%d.%d" % (index + 1, k + 1),
               "status": state}
        if goal_paused(goal):
            out["paused"] = goal_fail_said(index, {"action": "pause"})
        else:
            nxt = goal_sub_next(own)
            out["next"] = ("sub-step %d.%d: %s" % (index + 1, nxt + 1,
                                                  own["subs"][nxt]["text"])
                           if nxt is not None else
                           "all sub-steps are done -- now verify step %d "
                           "itself and report it done" % (index + 1))
        return json.dumps(out)
    if state == "split":
        goal, bad = goal_step_split(index, substeps)
        if goal is None:
            return json.dumps({"ok": False, "error": bad})
        subs = goal["steps"][index]["subs"]
        return json.dumps({"ok": True, "step": index + 1, "split": len(subs),
                           "next": "sub-step %d.1: %s" % (index + 1,
                                                          subs[0]["text"])})
    reflected = False
    if state == GOAL_RUNNING:
        reflected = goal_reflect(index, note)                   # #294
        goal = goal_step_begin(index, note=note)                # #275
    elif state in (GOAL_DONE, GOAL_FAILED):
        passed = None
        if state == GOAL_DONE:
            refused, passed = goal_done_refusal(index, note)   # #250
            if refused:
                return json.dumps({"ok": False, "error": refused})
        goal = goal_step_end(index, ok=(state == GOAL_DONE), note=note)
    else:
        return json.dumps({"ok": False,
                           "error": "status must be running, done, failed or "
                                    "split"})
    if goal is None:
        return json.dumps({"ok": False,
                           "error": "no such step, or it is already done, or "
                                    "another step is still running"})
    verdict = None
    if state == GOAL_FAILED:
        # #294: THE CLASS COMES FROM THE EVIDENCE, NOT FROM THE NOTE. A
        # model's own account of why it failed is what ToolMaze warns
        # about; the step's last capture says whether the instrument worked.
        cap = goal["steps"][index].get("capture") or {}
        env = capture_precheck([cap["capture"]] if cap.get("capture") else [],
                               cap, goal, index) if cap else None
        verdict = goal_fail(index, GOAL_ENV if env else GOAL_CAP,
                            "%s%s" % (note, (" [capture: %s]" % env) if env
                                      else ""),
                            capture=cap.get("capture") if env else None)
        goal = goal_load() or goal
    done, total = goal_counts(goal)
    nxt = goal_next_open(goal)
    out = {"ok": True, "done": done, "total": total,
           "complete": goal.get("status") == GOAL_DONE,
           "next_step": None if nxt is None else nxt + 1,
           "next": None if nxt is None else goal["steps"][nxt]["text"]}
    if state == GOAL_DONE and passed:
        out["acceptance_check"] = "passed: %s" % passed
    if verdict is not None:
        out["failure"] = {"class": verdict["class"],
                          "counted": verdict["counted"],
                          "action": verdict["action"]}
        out["then"] = goal_fail_said(index, verdict)
    if reflected:
        out["reflection"] = "kept; attempt 2 may start"
    if state == GOAL_RUNNING and checklist is not None:        # #295
        items, bad = goal_checklist_write(index, checklist)
        if bad:
            out["checklist_error"] = bad
        out["checklist"] = [("" if c.get("must") else "optional: ") + c["item"]
                            for c in items]
    if goal.get("status") == GOAL_PARTIAL:
        out["ended"] = "complete with %d skipped" % len(goal_skipped(goal))
    return json.dumps(out)


# #250. `done` WITHOUT EVIDENCE. 2026-09-23, diorama run: step 4 went
# `done` with the note "Step treated as done-with-deviation only in spirit",
# step 3 with "the 128^3 3D texture literally cannot be created here", and
# step 9 went `failed` ("no fps figure can be read") and then `done` with no
# note two messages later -- 9/9 "complete" over a 1.4 KB index.html that
# draws nothing. The tool took every word. Two checks, both on what the call
# itself carries: a `done` whose own note says it is not done, and a `done`
# with no note on a step whose last report was `failed`. Narrow on purpose:
# a false refusal costs a round and teaches the model to drop its caveats.
_GOAL_NOT_DONE = re.compile(
    r"(?i)\b(?:in spirit|not done|is not (?:done|finished|working|verified)|"
    r"not verified|unverified|could not (?:be )?verif\w*|"
    r"(?:cannot|can't|could not) be (?:built|drawn|created|verified|done|bound|"
    r"linked|finished|measured|reached|rendered)|impossible|unreachable|"
    r"with[- ]deviation|does not work|doesn't work|paints nothing|"
    r"nothing draws)\b")

# THE ACCEPTANCE CHECK IS THE USER'S WORD, so it lives where the model's
# write_file cannot reach: goal.json sits in the working area, and a command
# the model wrote there would run unasked at `allowedit`. One file in
# SESSION_DIR, keyed by the goal's path.
GOAL_CHECK_PREFIX = "check:"
GOAL_CHECKS_FILE = "goal-checks.json"


def _goal_checks_path() -> str:
    return os.path.join(SESSION_DIR, GOAL_CHECKS_FILE)


def _goal_checks() -> dict:
    try:
        with open(_goal_checks_path(), encoding="utf-8") as fh:
            found = json.load(fh)
    except (OSError, ValueError):
        return {}
    return found if isinstance(found, dict) else {}


def goal_check_get() -> "str | None":
    """The acceptance check the user set for the goal in this working area."""
    check = _goal_checks().get(os.path.abspath(goal_path()))
    return check if isinstance(check, str) and check.strip() else None


def goal_check_set(check: "str | None") -> None:
    """Set (or with None, drop) this working area's acceptance check."""
    checks = _goal_checks()
    key = os.path.abspath(goal_path())
    if check:
        checks[key] = check
    elif checks.pop(key, None) is None:
        return
    try:
        os.makedirs(SESSION_DIR, exist_ok=True)
        tmp = _goal_checks_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(checks, fh, indent=1, ensure_ascii=False)
        os.replace(tmp, _goal_checks_path())
    except OSError:
        pass


def goal_done_refusal(index: int, note: str = "",
                      goal: "dict | None" = None) -> "tuple[str | None, str | None]":
    """(why `done` on step `index` is refused, or None; the check that passed,
    or None). The acceptance check runs only on the `done` that would close
    the goal, through run_command -- its clock, capture cap and memory scope."""
    goal = goal if goal is not None else goal_load()
    if not goal or not 0 <= index < len(goal.get("steps") or []):
        return None, None
    step = goal["steps"][index]
    said = str(note or "")
    hit = _GOAL_NOT_DONE.search(said)
    if hit:
        return ("refused: the note says this step is not done (\"%s\"). 'done' "
                "means verified working. Finish it and report done with what "
                "proves it, or call goal_step with 'failed' and this note."
                % hit.group(0)), None
    if not said.strip() and step.get("status") in (GOAL_FAILED, GOAL_SKIPPED):
        return ("refused: step %d was last reported failed (\"%s\"). A 'done' "
                "after that needs a note saying what proves it works now."
                % (index + 1, str(step.get("note") or "")[:160])), None
    # #294: A SPLIT STEP IS DONE AFTER ITS SUB-STEPS, not instead of them.
    open_sub = goal_sub_next(step) if step.get("subs") else None
    if open_sub is not None:
        return ("refused: step %d is split and sub-step %d.%d is not done: %s. "
                "Report it with goal_step(step=%d, sub=%d, ...) first."
                % (index + 1, index + 1, open_sub + 1,
                   step["subs"][open_sub]["text"], index + 1,
                   open_sub + 1)), None
    evidence = goal_evidence_refusal(goal, index, said)        # #267
    if evidence:
        return evidence, None
    check = goal_check_get()
    closes = all(s.get("status") == GOAL_DONE
                 for n, s in enumerate(goal["steps"]) if n != index)
    if not check or not closes:
        return None, None
    result = tool_run_command(check)
    if result.startswith("[exit 0]"):
        return None, check
    return ("refused: this would close the goal, and its acceptance check "
            "failed. The goal stays open until it passes.\ncheck: %s\n%s"
            % (check, _clip(result, 2000))), None


# #267. A VISUAL STEP IS DONE ON A PICTURE, NOT ON A SENTENCE.
# 2026-09-23, diorama run: 9/9 `done`, every note "verified on screen", and
# the deliverable was a small purple box in a black frame. #250 refuses a
# note that SAYS it is not done; it cannot refuse a note that says "verified"
# about nothing. Anthropic's long-running-agent harness gates "done" on
# evidence the harness can check, not on the agent's own report
# ("Effective harnesses for long-running agents", 2025) -- here the evidence
# is a capture made during this goal, named in the note, and, when a judge
# with fresh eyes scored it, that judge's lowest score.
#
# WHICH GOALS: the ones whose title or steps name visual work. A goal that
# builds a parser is not asked for a screenshot. `visual: true|false` in
# goal.json overrides the guess either way.
_GOAL_VISUAL = re.compile(
    r"(?i)\b(?:render(?:s|ed|ing)?|screenshots?|visual(?:ly)?|webgl2?|html|"
    r"css|canvas|web ?page|website|landing page|scene|diorama|voxels?|3d|"
    r"shaders?|svg|sprites?|ui)\b")
# A STEP THAT ONLY PLANS makes no picture: "Think and plan: read this file,
# research ..., write PLAN.md" was step 1 of the diorama goal. Exempt only
# when it builds nothing -- "plan and build the scene" still needs one.
_GOAL_PLANNING = re.compile(r"(?i)^\W*(?:think|plan|research|read|outline|"
                            r"design doc|write (?:the |a )?plan)\b")
_GOAL_BUILDS = re.compile(r"(?i)\b(?:build|implement|render|draw|code|write "
                          r"(?:the )?(?:page|html|shader|scene)|fix|verify)\b")
# #267 follow-up, 2026-09-24 diorama run: "Think and plan: read
# DIORAMA-PROMPT.md, research ..., verify findings, write PLAN.md (...)" was
# refused `done` because "verify" is a build verb. The step's LEADING PHRASE
# (before the first ':', ',' or '(') says what kind of step it is; "verify"
# and "fix" further on are part of planning when the step's deliverable is a
# document. A real making verb anywhere ("build", "render", "write the page")
# still makes it visual, so "Think and plan the page, then build it" keeps
# the gate, and so does the owner's "Verify offline via file://, fix, report fps".
_GOAL_MAKES = re.compile(r"(?i)\b(?:build|implement|render|draw|code|write "
                         r"(?:the )?(?:page|html|shader|scene))\b")
_GOAL_DOC = re.compile(r"(?i)(?:\.(?:md|txt|rst)\b|\b(?:plan|notes|report|"
                       r"design doc)\b)")
_GOAL_IMAGE_CITED = re.compile(r"[^\s'\"`(),;<>\[\]]+\.(?:png|jpe?g|webp)\b",
                               re.I)

# THE JUDGE'S BAR. 8 of 10 by default: the diorama prompt asked for 9+ from
# the model's own eyes and got a black frame; a fresh judge at 8 is the
# stricter test. `judge_threshold` in settings.json (window) or
# --judge-threshold (terminal) moves it.
JUDGE_THRESHOLD_DEFAULT = 8
JUDGE_THRESHOLD = JUDGE_THRESHOLD_DEFAULT


def judge_threshold_set(value) -> None:
    """None or nonsense restores the default; a number is clamped to 1..10."""
    global JUDGE_THRESHOLD
    try:
        JUDGE_THRESHOLD = (JUDGE_THRESHOLD_DEFAULT if value is None
                           else max(1, min(10, int(value))))
    except (TypeError, ValueError):
        JUDGE_THRESHOLD = JUDGE_THRESHOLD_DEFAULT


def goal_nudge_evidence(goal: "dict | None", index: int) -> str:
    """The sentence the step nudge adds on a visual step, or "". Said where
    the step is handed out, so the gate's first refusal is not the first
    time the model hears the rule."""
    if not goal_step_needs_render(goal, index):
        return ""
    return (" This is visual work: render_page it, read_image the capture, "
            "call judge on it, and put the capture's path in the done note.")


def goal_is_visual(goal: "dict | None") -> bool:
    """Does this goal make something to be looked at?"""
    if not goal:
        return False
    flag = goal.get("visual")
    if isinstance(flag, bool):
        return flag
    text = " ".join([str(goal.get("title") or "")]
                    + [str(s.get("text") or "") for s in goal.get("steps") or []])
    return _GOAL_VISUAL.search(text) is not None


def goal_step_needs_render(goal: "dict | None", index: int) -> bool:
    """Must `done` on this step cite a capture? Visual goal, not a pure
    planning step."""
    if not goal_is_visual(goal):
        return False
    steps = goal.get("steps") or []
    if not 0 <= index < len(steps):
        return False
    text = str(steps[index].get("text") or "")
    head = re.split(r"[:,(]", text, maxsplit=1)[0]
    if not _GOAL_PLANNING.search(head) or _GOAL_BUILDS.search(head):
        return True
    if _GOAL_MAKES.search(text):
        return True
    # Only "verify"/"fix" past the leading phrase: planning, when the rest of
    # the step names a document it writes ("Plan: verify the page" does not).
    return (bool(_GOAL_BUILDS.search(text))
            and not _GOAL_DOC.search(text[len(head):]))


def _render_candidates(cited: str) -> "list[str]":
    """Where a cited image may be: as written, under the working area, or by
    its name in the render folder -- the diorama notes wrote the bare name."""
    expanded = os.path.expanduser(cited)
    if os.path.isabs(expanded):
        return [expanded]
    out = []
    root = get_root()
    if root:
        out.append(os.path.join(root, expanded))
    out.append(os.path.join(_render_dir(), os.path.basename(expanded)))
    return out


def goal_note_renders(note: str, goal: "dict | None") -> "list[str]":
    """The images the note cites that exist and were written during this
    goal (mtime at or after its creation). An old capture proves nothing
    about today's page."""
    since = float((goal or {}).get("created") or 0.0)
    found: "list[str]" = []
    for cited in _GOAL_IMAGE_CITED.findall(str(note or "")):
        for path in _render_candidates(cited.rstrip(".:")):
            try:
                fresh = os.path.getmtime(path) >= since - 1.0
            except OSError:
                continue
            if fresh and os.path.isfile(path):
                if path not in found:
                    found.append(path)
                break
    return found


def goal_evidence_refusal(goal: "dict | None", index: int,
                          note: str = "") -> "str | None":
    """Why `done` on a visual step is refused, or None. Two rules, in order:
    a cited capture from this goal, and -- only when a judge scored this step
    -- a lowest score at or over `JUDGE_THRESHOLD`."""
    if not goal_step_needs_render(goal, index):
        return None
    if not goal_note_renders(note, goal):
        where = os.path.relpath(_render_dir(), get_root()) if get_root() \
            else _render_dir()
        return ("refused: step %d is visual work, and 'done' needs a picture "
                "you can point at. The note cites no capture made during this "
                "goal. Call render_page on the deliverable, read_image the "
                "capture, call judge on it, then report done with the capture's "
                "path in the note (e.g. %s/render-YYYYMMDD-HHMMSS.png). If "
                "nothing can be rendered, call goal_step with 'failed' and say "
                "why. (Planning steps are exempt: one that starts with "
                "think/plan/research/read and writes a document such as "
                "PLAN.md needs no picture. This step's text reads as making "
                "or checking something visible.)"
                % (index + 1, where.replace(os.sep, "/")))
    verdict = goal["steps"][index].get("judge")
    # #295: THE FROZEN CHECKLIST IS THE BAR. Every must-item "yes" in the
    # judge's last verdict, and a step with a checklist is not done
    # without one. The min-score rule below only reads verdicts stored
    # before the checklist (goal.json files from v2.6.0).
    if isinstance(verdict, dict) and "pass" in verdict:
        if verdict.get("pass"):
            return None
        open_items = ["%s: %s" % (k, v) for k, v in
                      (verdict.get("checklist") or {}).items()
                      if v != "yes" and k in (verdict.get("must") or [])]
        return ("refused: the judge (%s) did not pass step %d -- every "
                "must-item of its frozen checklist needs 'yes'. Open: %s. "
                "Fix those, render again, call judge again."
                % (verdict.get("model") or "?", index + 1,
                   "; ".join(open_items[:6]) or "?"))
    if goal_checklist(goal, index):
        return ("refused: step %d has a frozen checklist and no judge verdict "
                "on it. Call judge on the capture, then report done."
                % (index + 1))
    low = verdict.get("min") if isinstance(verdict, dict) else None
    if isinstance(low, (int, float)) and low < JUDGE_THRESHOLD:
        scores = verdict.get("scores") or {}
        worst = sorted(scores.items(), key=lambda kv: kv[1])[:3]
        weakest = verdict.get("weakest") or []
        return ("refused: the judge (%s, fresh context) scored step %d at %s "
                "lowest -- under the bar of %d. Lowest: %s. Its weakest "
                "points: %s. Fix those, render again, call judge again; 'done' "
                "passes once every criterion scores %d or more."
                % (verdict.get("model") or "?", index + 1, low,
                   JUDGE_THRESHOLD,
                   ", ".join("%s %s" % kv for kv in worst) or "?",
                   "; ".join(str(w) for w in weakest[:3]) or "none given",
                   JUDGE_THRESHOLD))
    return None


# #266. `accept: <criterion>` LINES in `/goal` are the user's rubric
# for the judge. Beside the acceptance check and for the same reason: the
# model's `goal_set` rewrites goal.json, and the user's word must outlive it.
GOAL_ACCEPT_PREFIX = "accept:"
GOAL_ACCEPT_FILE = "goal-accept.json"


def _goal_accept_path() -> str:
    return os.path.join(SESSION_DIR, GOAL_ACCEPT_FILE)


def goal_accept_get() -> "list[str]":
    """The user's accept lines for the goal in this working area."""
    try:
        with open(_goal_accept_path(), encoding="utf-8") as fh:
            found = json.load(fh)
    except (OSError, ValueError):
        return []
    lines = found.get(os.path.abspath(goal_path())) if isinstance(found, dict) \
        else None
    return [str(x) for x in lines if str(x).strip()] \
        if isinstance(lines, list) else []


def goal_accept_set(lines: "list[str] | None") -> None:
    """Set (or with an empty list / None, drop) this area's accept lines."""
    try:
        with open(_goal_accept_path(), encoding="utf-8") as fh:
            found = json.load(fh)
    except (OSError, ValueError):
        found = {}
    if not isinstance(found, dict):
        found = {}
    key = os.path.abspath(goal_path())
    clean = [str(x).strip() for x in lines or [] if str(x).strip()]
    if clean:
        found[key] = clean
    elif found.pop(key, None) is None:
        return
    try:
        os.makedirs(SESSION_DIR, exist_ok=True)
        tmp = _goal_accept_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(found, fh, indent=1, ensure_ascii=False)
        os.replace(tmp, _goal_accept_path())
    except OSError:
        pass


def goal_next_open(goal: "dict | None" = None) -> "int | None":
    """Der erste Schritt, der noch Arbeit ist -- laufend, offen oder gescheitert.
    None, wenn nichts mehr aussteht. Das ist die Frage, die der Motor nach jedem
    Zug stellt.

    #289: UEBERSPRUNGEN IST KEINE ARBEIT MEHR. Ein gescheiterter Schritt kommt
    noch einmal dran (`GOAL_STEP_TRIES`); ein uebersprungener -- zweimal
    gescheitert, oder vom Owner per `/goal skip` -- nicht, sonst stuende der
    Motor wieder vor derselben Wand wie am 2026-09-24."""
    goal = goal if goal is not None else goal_load()
    if not goal:
        return None
    for n, step in enumerate(goal.get("steps") or []):
        if step.get("status") not in (GOAL_DONE, GOAL_SKIPPED):
            return n
    return None


def goal_retry_note(goal: "dict | None", index: int) -> "str | None":
    """#289. The step's failure note when it is being sent back after ONE
    `failed`, or None. The engine quotes it in the nudge: the note is what
    the model learned, and a retry that does not read it is the same attempt
    again."""
    steps = (goal or {}).get("steps") or []
    if not 0 <= index < len(steps):
        return None
    step = steps[index]
    if step.get("status") != GOAL_FAILED:
        return None
    return str(step.get("note") or "").strip() or "(no reason given)"


def goal_retry_nudge(goal: dict, index: int, note: str) -> str:
    """#289. The one nudge a failed step gets before it is retried."""
    return ("[Goal mode. Step %d failed: \"%s\"\nTry it ONCE more with a "
            "different approach -- not the one that failed. Step %d: %s\n"
            "If it fails again, call goal_step with 'failed' and say why: the "
            "step is never skipped -- it gets a fresh context, then a split, "
            "then it pauses for the user (#294).%s]"
            % (index + 1, _clip(note, 600), index + 1,
               goal["steps"][index]["text"],
               goal_nudge_evidence(goal, index)))


# ------------------------------------------- #294, the failure ladder ------
#
# NO SILENT SKIP. The owner's decision of 2026-09-25, after the diorama goal ended
# "complete with 4 skipped": steps 5-8 were skipped by #289 on their second
# `failed`, every one of them judged on a software-GL capture, and nobody was
# asked. A failure now has a class, and each class a ladder:
#
#   environment  the instrument failed, not the model: the capture is
#                `render_mode` unavailable, or software on a GPU step; the
#                precheck finds it uniform, blank or near-black; the frames
#                are identical on a step that needs motion; no judge answered.
#                -> retry at most GOAL_ENV_RETRIES times, GOAL_ENV_DELAY apart,
#                then PAUSE. The same capture counts once.
#   capability   a valid capture, and the judge says the checklist is not met
#                (or the model reports `failed` on valid evidence).
#                -> attempt 2 after a written reflection on the judge's
#                feedback (Reflexion), attempt 3 in a fresh context (Claude
#                Code: "after two failed corrections, /clear"), then the step
#                is DECOMPOSED into 2-3 sub-steps (ADaPT); a failed sub-step,
#                or a miss after all of them are done, PAUSES.
#   unknown      the judge could not tell on a must-item: twice -> PAUSE.
#
# A RUNG IS CLIMBED ONLY ONCE THE ONE BEFORE WAS TAKEN (`pending`): a model
# that calls judge three times in one turn has had one attempt, not three.
# Every PAUSE ends in a report the model writes for the user and a question;
# goal mode then waits for a typed line (the window's `_goal_nudge`).

GOAL_LADDER_REFLECT = "reflect"
GOAL_LADDER_FRESH = "fresh"
GOAL_LADDER_SPLIT = "decompose"
GOAL_LADDER_SUBS = "subs"
GOAL_LADDER_RETRY = "retry"
GOAL_SUBSTEPS_MIN, GOAL_SUBSTEPS_MAX = 2, 3
GOAL_REFLECTIONS_KEEP = 3


def goal_limits_set(minutes=None, turns=None) -> None:
    """#294: the settings.json values (None or nonsense: the default)."""
    global GOAL_STEP_MINUTES, GOAL_NO_PROGRESS_TURNS

    def num(value, default):
        try:
            return default if value is None else max(0, int(value))
        except (TypeError, ValueError):
            return default
    GOAL_STEP_MINUTES = num(minutes, GOAL_STEP_MINUTES_DEFAULT)
    GOAL_NO_PROGRESS_TURNS = num(turns, GOAL_NO_PROGRESS_DEFAULT)


def _goal_env_int(name: str, fallback: int) -> int:
    raw = (os.environ.get(name) or "").strip()
    try:
        return max(0, int(raw)) if raw else fallback
    except ValueError:
        return fallback


def goal_step_minutes() -> int:
    """#294: the per-step budget in minutes; the environment wins."""
    return _goal_env_int("CROW_GOAL_STEP_MINUTES", GOAL_STEP_MINUTES)


def goal_no_progress_turns() -> int:
    """#294: nudges without a newly passed checklist item before a pause."""
    return _goal_env_int("CROW_GOAL_NO_PROGRESS_TURNS", GOAL_NO_PROGRESS_TURNS)


def goal_step_active(step: dict, now: "float | None" = None) -> float:
    """Seconds this step has run: billed windows plus the open one."""
    at = float(now if now is not None else time.time())
    began = step.get("started")
    open_window = max(0.0, at - float(began)) if began is not None else 0.0
    return float(step.get("seconds") or 0.0) + open_window


def goal_budget_due(goal: "dict | None", index: int,
                    now: "float | None" = None) -> "str | None":
    """#294: why step `index` is over its budget, or None. Counted from the
    last resume (`budget_base`), so a typed line gives the step a new hour."""
    minutes = goal_step_minutes()
    steps = (goal or {}).get("steps") or []
    if minutes <= 0 or not 0 <= index < len(steps):
        return None
    step = steps[index]
    used = goal_step_active(step, now) - float(step.get("budget_base") or 0.0)
    if used < minutes * 60:
        return None
    return ("step %d has run %d min, over its budget of %d min"
            % (index + 1, int(used // 60), minutes))


def goal_paused(goal: "dict | None" = None) -> "dict | None":
    """#294: the pause record when the goal waits for the user, else None."""
    goal = goal if goal is not None else goal_load()
    if not goal or goal.get("status") != GOAL_PAUSED:
        return None
    pause = goal.get("pause")
    return pause if isinstance(pause, dict) else {"step": None, "why": "?"}


def _goal_pause_in(goal: dict, index: int, cls: str, why: str,
                   at: float) -> None:
    """Pause a loaded goal (the caller holds the lock and writes it). The
    running step's clock is billed and stopped: a night on a paused step
    is not work (step 5 of 2026-09-24/25 carried 8 idle hours)."""
    steps = goal.get("steps") or []
    if 0 <= index < len(steps):
        step = steps[index]
        if step.get("started") is not None:
            spent = int(goal.get("spent") or 0)
            _goal_close_window(goal, step, at, spent)
            goal["last_at"], goal["last_spent"] = at, spent
    goal["status"] = GOAL_PAUSED
    goal["pause"] = {"step": index + 1 if 0 <= index < len(steps) else None,
                     "class": cls, "why": str(why or "")[:600], "at": at,
                     "asked": False, "report": ""}


def goal_pause(index: int, cls: str, why: str,
               now: "float | None" = None) -> "dict | None":
    """#294: pause the goal at step `index` (0-based). The goal after."""
    with _GOAL_LOCK:
        goal = goal_load()
        if goal is None:
            return None
        if goal.get("status") != GOAL_PAUSED:
            _goal_pause_in(goal, index, cls, why,
                           float(now if now is not None else time.time()))
            goal_write(goal)
        return goal


def goal_pause_asked() -> "dict | None":
    """#294: mark that the report turn went out. The pause after, or None."""
    with _GOAL_LOCK:
        goal = goal_load()
        pause = goal_paused(goal)
        if pause is None:
            return None
        pause["asked"] = True
        goal["pause"] = pause
        goal_write(goal)
        return pause


def goal_pause_report(text: str) -> None:
    """#294: keep the model's report for the user on the pause record."""
    with _GOAL_LOCK:
        goal = goal_load()
        pause = goal_paused(goal)
        if pause is None:
            return
        pause["report"] = str(text or "").strip()[:4000]
        goal["pause"] = pause
        goal_write(goal)


def goal_resume(now: "float | None" = None) -> "dict | None":
    """#294: the user typed a line -- the pause is over. The step's counters
    start again and so does its budget; the pause is kept as `last_pause`
    for the record. None when nothing was paused."""
    with _GOAL_LOCK:
        goal = goal_load()
        pause = goal_paused(goal)
        if pause is None:
            return None
        at = float(now if now is not None else time.time())
        index = int(pause.get("step") or 0) - 1
        steps = goal.get("steps") or []
        if 0 <= index < len(steps):
            step = steps[index]
            for key in ("env_failures", "unknowns", "failures", "pending",
                        "env_seen"):
                step.pop(key, None)
            step["budget_base"] = float(step.get("seconds") or 0.0)
            for sub in step.get("subs") or []:
                if sub.get("status") == GOAL_FAILED:
                    sub["status"] = GOAL_OPEN
            if step.get("subs") and not all(
                    s.get("status") == GOAL_DONE for s in step["subs"]):
                step["pending"] = GOAL_LADDER_SUBS
        goal["last_pause"] = dict(pause, resumed=at)
        goal.pop("pause", None)
        goal["status"] = GOAL_OPEN
        _goal_settle(goal)
        goal_write(goal)
        return goal


def goal_pending(goal: "dict | None", index: int) -> "str | None":
    """#294: the rung the engine owes step `index`, or None."""
    steps = (goal or {}).get("steps") or []
    if not 0 <= index < len(steps):
        return None
    return steps[index].get("pending") or None


def goal_pending_clear(index: int, rung: str) -> None:
    """#294: the engine took rung `rung` (the retry went out, the roll is
    arranged) -- it is not owed any more."""
    with _GOAL_LOCK:
        goal = goal_load()
        steps = (goal or {}).get("steps") or []
        if 0 <= index < len(steps) and steps[index].get("pending") == rung:
            steps[index].pop("pending", None)
            goal_write(goal)


def goal_fail(index: int, cls: str, why: str, capture: "str | None" = None,
              source: str = "model", now: "float | None" = None) -> dict:
    """#294. Count one failure of class `cls` on step `index` and decide the
    next rung. Returns {"counted", "action", "class", "count"}; `action` is
    one of retry/reflect/fresh/decompose/subs/unknown/pause, or "paused"
    when the goal already waits for the user."""
    at = float(now if now is not None else time.time())
    with _GOAL_LOCK:
        goal = goal_load()
        steps = (goal or {}).get("steps") or []
        if not 0 <= index < len(steps):
            return {"counted": False, "action": None, "class": cls, "count": 0}
        if goal.get("status") == GOAL_PAUSED:
            return {"counted": False, "action": "paused", "class": cls,
                    "count": 0}
        step = steps[index]
        why = str(why or "").strip() or "(no reason given)"
        counted, action, count, pause_why = True, None, 0, None
        if cls == GOAL_ENV:
            # ONE PER RETRY: the same capture again, or another failure
            # before the engine's retry (with its wait) went out, is the
            # same attempt -- three render calls in one turn are not three
            # retries.
            if (capture and capture == step.get("env_seen")) or \
                    step.get("pending") == GOAL_LADDER_RETRY:
                counted, action = False, GOAL_LADDER_RETRY
                count = int(step.get("env_failures") or 0)
            else:
                count = int(step.get("env_failures") or 0) + 1
                step["env_failures"] = count
                if capture:
                    step["env_seen"] = capture
                if count > GOAL_ENV_RETRIES:
                    pause_why = ("the environment failed %d times: %s"
                                 % (count, why))
                else:
                    action = step["pending"] = GOAL_LADDER_RETRY
        elif cls == GOAL_UNKNOWN:
            count = int(step.get("unknowns") or 0) + 1
            step["unknowns"] = count
            if count >= GOAL_UNKNOWN_PAUSE:
                pause_why = ("the judge answered 'unknown' %d times on this "
                             "step: %s" % (count, why))
            else:
                action = GOAL_UNKNOWN
        else:
            cls = GOAL_CAP
            owed = step.get("pending")
            if owed in (GOAL_LADDER_REFLECT, GOAL_LADDER_FRESH,
                        GOAL_LADDER_SPLIT, GOAL_LADDER_SUBS):
                # The rung before is not taken yet: same attempt.
                counted, action = False, owed
                count = int(step.get("failures") or 0)
            else:
                count = int(step.get("failures") or 0) + 1
                step["failures"] = count
                if step.get("subs"):
                    pause_why = ("step %d still fails after it was split into "
                                 "sub-steps: %s" % (index + 1, why))
                elif count == 1:
                    action = step["pending"] = GOAL_LADDER_REFLECT
                elif count == 2:
                    action = step["pending"] = GOAL_LADDER_FRESH
                else:
                    action = step["pending"] = GOAL_LADDER_SPLIT
        if counted:
            fails = step.get("fail_log") or []
            fails.append({"class": cls, "why": why[:400], "at": at,
                          "source": source, "capture": capture})
            step["fail_log"] = fails[-8:]
        if pause_why is not None:
            step.pop("pending", None)
            _goal_pause_in(goal, index, cls, pause_why, at)
            action = "pause"
        goal_write(goal)
        return {"counted": counted, "action": action, "class": cls,
                "count": count}


def goal_fail_said(index: int, verdict: dict) -> str:
    """#294: what a `goal_fail` result means, for the tool answer."""
    n, action = index + 1, verdict.get("action")
    if action in ("pause", "paused"):
        return ("goal PAUSED at step %d: this goes to the user now. Stop working, "
                "call no more tools, and wait -- the next turn asks you for "
                "a report." % n)
    if action == GOAL_LADDER_RETRY:
        return ("environment failure %d of %d allowed on step %d -- not your "
                "work. Render again later; the goal pauses after %d."
                % (verdict.get("count", 0), GOAL_ENV_RETRIES, n,
                   GOAL_ENV_RETRIES))
    if action == GOAL_LADDER_REFLECT:
        return ("attempt 1 of step %d failed. Before changing anything, write "
                "a reflection on the judge's feedback: goal_step(step=%d, "
                "status='running', note='reflection: what the judge saw, why, "
                "what you will do differently'). Then attempt 2." % (n, n))
    if action == GOAL_LADDER_FRESH:
        return ("attempt 2 of step %d failed. End this turn: attempt 3 starts "
                "in a fresh context that carries the judge's feedback and your "
                "reflections." % n)
    if action == GOAL_LADDER_SPLIT:
        return ("attempt 3 of step %d failed. Split the step into %d-%d smaller "
                "sub-steps, the hardest part first: goal_step(step=%d, "
                "status='split', substeps=[...])."
                % (n, GOAL_SUBSTEPS_MIN, GOAL_SUBSTEPS_MAX, n))
    if action == GOAL_LADDER_SUBS:
        return ("step %d is split: finish its sub-steps first, reporting each "
                "with goal_step(step=%d, sub=k, status=...)." % (n, n))
    if action == GOAL_UNKNOWN:
        return ("the judge could not tell on a must-item. Make the capture "
                "show it (frames, framing, a closer view) and judge again -- "
                "a second 'unknown' pauses the goal.")
    return ""


def goal_reflect(index: int, note: str) -> bool:
    """#294: a `running` note while a reflection is owed IS the reflection."""
    text = str(note or "").strip()
    if not text:
        return False
    with _GOAL_LOCK:
        goal = goal_load()
        steps = (goal or {}).get("steps") or []
        if not 0 <= index < len(steps):
            return False
        step = steps[index]
        if step.get("pending") != GOAL_LADDER_REFLECT:
            return False
        kept = step.get("reflections") or []
        kept.append(text[:800])
        step["reflections"] = kept[-GOAL_REFLECTIONS_KEEP:]
        step.pop("pending", None)
        goal_write(goal)
        return True


def goal_step_split(index: int, substeps) -> "tuple[dict | None, str | None]":
    """#294, ADaPT: the failed step becomes 2-3 sub-steps under it. The
    step keeps its number, its checklist and its gate; the sub-steps are the
    road to it. (goal, None) or (None, why not)."""
    items, bad = goal_steps_from(substeps)
    if bad is not None:
        return None, bad.replace("steps must", "substeps must")
    items = [str(x).strip() for x in items or [] if str(x).strip()]
    if not GOAL_SUBSTEPS_MIN <= len(items) <= GOAL_SUBSTEPS_MAX:
        return None, ("a split needs %d to %d sub-steps, got %d"
                      % (GOAL_SUBSTEPS_MIN, GOAL_SUBSTEPS_MAX, len(items)))
    with _GOAL_LOCK:
        goal = goal_load()
        steps = (goal or {}).get("steps") or []
        if not 0 <= index < len(steps):
            return None, "no such step"
        step = steps[index]
        if step.get("subs"):
            return None, ("step %d is already split; a failed sub-step pauses "
                          "the goal for the user" % (index + 1))
        if step.get("pending") != GOAL_LADDER_SPLIT:
            return None, ("step %d is not due for a split -- that comes after "
                          "three failed attempts" % (index + 1))
        step["subs"] = [{"text": t[:300], "status": GOAL_OPEN, "note": ""}
                        for t in items]
        step["pending"] = GOAL_LADDER_SUBS
        goal_write(goal)
        return goal, None


def goal_sub_next(step: dict) -> "int | None":
    """The first sub-step not done, 0-based, or None."""
    for n, sub in enumerate(step.get("subs") or []):
        if sub.get("status") != GOAL_DONE:
            return n
    return None


def goal_sub_end(index: int, sub: int, ok: bool, note: str,
                 now: "float | None" = None) -> "tuple[dict | None, str | None]":
    """#294: sub-step `sub` (0-based) of step `index` done or failed. A
    failed sub-step pauses the goal: the decomposition was the last rung."""
    at = float(now if now is not None else time.time())
    with _GOAL_LOCK:
        goal = goal_load()
        steps = (goal or {}).get("steps") or []
        if not 0 <= index < len(steps):
            return None, "no such step"
        step = steps[index]
        subs = step.get("subs") or []
        if not 0 <= sub < len(subs):
            return None, ("step %d has no sub-step %d" % (index + 1, sub + 1)
                          if subs else "step %d is not split" % (index + 1))
        said = str(note or "").strip()
        if ok and not said:
            return None, "a sub-step's 'done' needs a note saying what proves it"
        if ok:
            hit = _GOAL_NOT_DONE.search(said)
            if hit:
                return None, ("refused: the note says this sub-step is not done "
                              "(\"%s\")" % hit.group(0))
        subs[sub]["status"] = GOAL_DONE if ok else GOAL_FAILED
        subs[sub]["note"] = said[:400]
        if ok and goal_sub_next(step) is None:
            step.pop("pending", None)
        if not ok:
            step.pop("pending", None)
            _goal_pause_in(goal, index, GOAL_CAP,
                           "sub-step %d.%d failed after the split: %s"
                           % (index + 1, sub + 1, said or "(no reason given)"),
                           at)
        goal_write(goal)
        return goal, None


# ------------------------------------------- #295, the frozen checklist ----
#
# THE STEP'S CONTRACT, fixed when the step starts and never rewritten by the
# model: the user's `accept:` lines when there are any (`accept: 5: ...`
# binds to step 5, a line without a number to every visual step), else the
# list the model writes ONCE with goal_step(n, 'running', checklist=[...]),
# else -- at the first judge call -- the step's own text and "not blank".
# The judge answers each item yes/no/unknown; the step passes when every
# must-item is "yes". Anthropic's sprint contract (harness design, 2026)
# fixes the done-criteria before the work; ArtifactsBench judges rendered
# artifacts against a per-task checklist.

GOAL_CHECK_OPTIONAL = re.compile(r"(?i)^\s*(?:optional|nice)\s*:\s*")
_GOAL_ACCEPT_STEP = re.compile(r"^\s*(\d+)\s*:\s*(.+)$", re.S)
GOAL_CHECK_DEFAULT_FRAME = ("the frame shows the scene itself -- not a blank, "
                            "black or placeholder frame")


def _checklist_entry(text: str, must: bool = True) -> "dict | None":
    text = re.sub(r"\s+", " ", str(text or "")).strip()
    if GOAL_CHECK_OPTIONAL.match(text):
        text, must = GOAL_CHECK_OPTIONAL.sub("", text).strip(), False
    return {"item": text[:200], "must": must} if text else None


def goal_accept_for(index: int) -> "list[str]":
    """#295: the user's accept items that bind step `index` (0-based)."""
    out: "list[str]" = []
    for line in goal_accept_get():
        hit = _GOAL_ACCEPT_STEP.match(line)
        if hit:
            if int(hit.group(1)) - 1 != index:
                continue
            line = hit.group(2)
        for item in _rubric_split(line):
            if item not in out:
                out.append(item)
    return out


def _checklist_refs(goal: "dict | None") -> "list[dict]":
    """#295: the pairwise reference items -- advisory, see `goal_references`."""
    out = []
    for ref in goal_references():
        what = ref.get("criterion") or "overall look"
        out.append({"item": "as good as the reference image %s on: %s"
                            % (os.path.basename(ref["path"]), what),
                    "must": False, "reference": ref["path"]})
    return out


def _checklist_build(goal: dict, index: int, items, source: str) -> list:
    step_text = re.sub(r"\s+", " ", str(goal["steps"][index].get("text")
                                        or "")).strip()
    entries = [e for e in (_checklist_entry(x) for x in items or []) if e]
    if source != GOAL_CHECK_FROM_USER and step_text:
        own = "delivers: " + step_text[:160]
        entries = [{"item": own, "must": True}] + [
            e for e in entries if e["item"] != own]
    return (entries[:JUDGE_MAX_CRITERIA]
            + (_checklist_refs(goal) if goal_step_needs_render(goal, index)
               else []))


GOAL_CHECK_FROM_USER = "the user's accept lines"
GOAL_CHECK_FROM_MODEL = "the model, at step start"
GOAL_CHECK_FROM_JUDGE = "the first judge call"


def _checklist_freeze_in(goal: dict, index: int, items, source: str,
                         at: float) -> bool:
    step = goal["steps"][index]
    if step.get("checklist"):
        return False
    built = _checklist_build(goal, index, items, source)
    if not built:
        return False
    step["checklist"] = built
    step["checklist_from"] = source
    step["checklist_at"] = at
    return True


def goal_checklist(goal: "dict | None", index: int) -> "list[dict]":
    steps = (goal or {}).get("steps") or []
    if not 0 <= index < len(steps):
        return []
    found = steps[index].get("checklist")
    return [c for c in found if isinstance(c, dict) and c.get("item")] \
        if isinstance(found, list) else []


def goal_checklist_write(index: int, items,
                         now: "float | None" = None) -> "tuple[list, str | None]":
    """#295: the model's one checklist for step `index`. (checklist, error)."""
    items, bad = goal_steps_from(items)
    if bad is not None:
        return [], bad.replace("steps must", "checklist must")
    with _GOAL_LOCK:
        goal = goal_load()
        steps = (goal or {}).get("steps") or []
        if not 0 <= index < len(steps):
            return [], "no such step"
        frozen = goal_checklist(goal, index)
        if frozen:
            return frozen, ("step %d's checklist is frozen (from %s) and was "
                            "not changed -- it is the contract the judge "
                            "checks: %s" % (index + 1,
                                            steps[index].get("checklist_from")
                                            or "?",
                                            "; ".join(c["item"] for c in frozen)))
        at = float(now if now is not None else time.time())
        if not _checklist_freeze_in(goal, index, items, GOAL_CHECK_FROM_MODEL,
                                    at):
            return [], "an empty checklist was not stored"
        goal_write(goal)
        return goal_checklist(goal, index), None


def goal_progress(goal: "dict | None", index: int) -> "int | None":
    """#294: how many checklist items of step `index` have ever passed, or
    None when the step has no checklist (then only the budget watches it)."""
    if not goal_checklist(goal, index) or \
            not goal_step_needs_render(goal, index):
        return None
    return len(goal["steps"][index].get("passed") or [])


# ------------------------------------------- #295, the render contract -----
#
# WHAT render_page SAYS ABOUT ITS CAPTURE. The render ticket adds
# `render_mode` (gpu | software | unavailable), `renderer`, `frames` (clock-
# stepped captures), `contact_sheet` and `precheck` {uniform,
# distinct_colours, dark_pct, identical_frames, max_frame_diff}. Read from
# the result text as a JSON object on a line, or as `key: value` lines; the
# #213 line ("gpu (angle)" / "software (swiftshader)") is the fallback. Every
# field is optional: a result without them is judged as before.

_CONTRACT_KEYS = ("render_mode", "renderer", "frames", "contact_sheet",
                  "precheck")
_CONTRACT_KV = re.compile(r"(?im)^\s*(render_mode|renderer|contact_sheet|"
                          r"frames|precheck)\s*[:=]\s*(.+?)\s*$")
_CONTRACT_LEGACY = re.compile(r"\b(gpu|software) \((angle|swiftshader)\)")
_RENDER_CONTRACTS: "dict[str, dict]" = {}
_RENDER_CONTRACTS_KEEP = 64


def render_contract(text: str) -> "dict | None":
    """The render facts of one render_page result, or None."""
    text = text if isinstance(text, str) else ""
    if not text:
        return None
    found: dict = {}
    for line in text.splitlines():
        start = line.find("{")
        if start < 0:
            continue
        try:
            doc = json.loads(line[start:])
        except ValueError:
            continue
        if isinstance(doc, dict) and any(k in doc for k in _CONTRACT_KEYS):
            found.update({k: doc[k] for k in _CONTRACT_KEYS if k in doc})
            if isinstance(doc.get("capture"), str):
                found["capture"] = doc["capture"]
    for key, value in _CONTRACT_KV.findall(text):
        key = key.lower()
        if key in found:
            continue
        if key == "precheck":
            try:
                doc = json.loads(value)
            except ValueError:
                continue
            if isinstance(doc, dict):
                found[key] = doc
        elif key == "frames":
            found[key] = [p.strip() for p in re.split(r"[,\s]+", value)
                          if p.strip().lower().endswith((".png", ".jpg",
                                                         ".jpeg", ".webp"))]
        else:
            found[key] = value.strip().strip("`'\"")
    legacy = _CONTRACT_LEGACY.search(text)
    if legacy:
        found.setdefault("render_mode", legacy.group(1))
        found.setdefault("renderer", legacy.group(2))
    shot = _RENDER_SHOT.search(text)
    if shot and "capture" not in found:
        found["capture"] = shot.group(1)
    if not found:
        return None
    mode = str(found.get("render_mode") or "").strip().lower() or None
    found["render_mode"] = mode
    if not isinstance(found.get("frames"), list):
        found.pop("frames", None)
    if not isinstance(found.get("precheck"), dict):
        found.pop("precheck", None)
    return found


def render_contract_of(path: "str | None",
                       goal: "dict | None" = None) -> "dict | None":
    """The contract recorded for capture `path` (this process, else the
    goal step that saw it)."""
    if not path:
        return None
    hit = _RENDER_CONTRACTS.get(os.path.abspath(path))
    if hit is not None:
        return hit
    for step in (goal or {}).get("steps") or []:
        cap = step.get("capture")
        if isinstance(cap, dict) and cap.get("capture") and \
                os.path.abspath(cap["capture"]) == os.path.abspath(path):
            return cap
    return None


def goal_capture_seen(result: str, target: str = "") -> "dict | None":
    """#295: run_tool hands every render_page result here. The contract is
    kept by capture path and on the running goal step (`capture`), so the
    judge and the failure class read the render's own facts."""
    contract = render_contract(result)
    if contract and contract.get("render_mode") == "unavailable" \
            and not contract.get("capture"):
        # #293's contract: "unavailable" comes as `error: ENVIRONMENT -- ...`
        # with no image at all. That is an environment failure of the
        # running step as it stands -- no judge call will ever see it.
        goal = goal_load()
        running = next((n for n, st in enumerate((goal or {}).get("steps")
                                                 or [])
                        if st.get("status") == GOAL_RUNNING), None)
        if running is not None:
            first = str(result or "").strip().splitlines()[0][:300]
            goal_fail(running, GOAL_ENV, "render_page: %s" % first,
                      source="render_page")
        return contract
    if not contract or not contract.get("capture"):
        return None
    contract = dict(contract, target=str(target or ""), at=round(time.time(), 1))
    key = os.path.abspath(contract["capture"])
    _RENDER_CONTRACTS[key] = contract
    while len(_RENDER_CONTRACTS) > _RENDER_CONTRACTS_KEEP:
        _RENDER_CONTRACTS.pop(next(iter(_RENDER_CONTRACTS)))
    with _GOAL_LOCK:
        goal = goal_load()
        if goal is None:
            return contract
        for step in goal.get("steps") or []:
            if step.get("status") == GOAL_RUNNING:
                step["capture"] = contract
                goal_write(goal)
                break
    return contract


# A STEP THAT NEEDS THE GPU: software GL is the environment failing, not the
# model (R14: 4/4 visible step 5-8 captures software, judged 2/2/3/4). A CSS
# page renders fine in software, so only these words make a step a GPU step.
# `"gpu": true|false` in goal.json overrides the guess.
_GOAL_GPU = re.compile(r"(?i)\b(?:webgl2?|webgpu|shaders?|glsl|gpu|3d|voxels?|"
                       r"ray[- ]?(?:trac\w*|march\w*|lit|lighting)|"
                       r"g-?buffer|diorama|three(?:\.js)?)\b")
# A STEP THAT NEEDS MOTION: identical frames cannot show it.
_GOAL_MOTION = re.compile(r"(?i)\b(?:animat\w*|motion|moving|moves|rain\w*|"
                          r"splash\w*|steam|weather|flicker\w*|particles?|"
                          r"ripples?|waves?|day[- ]night)\b")


def goal_step_gpu(goal: "dict | None", index: int) -> bool:
    if not goal:
        return False
    flag = goal.get("gpu")
    if isinstance(flag, bool):
        return flag
    steps = goal.get("steps") or []
    text = " ".join([str(goal.get("title") or "")]
                    + ([str(steps[index].get("text") or "")]
                       if 0 <= index < len(steps) else []))
    return _GOAL_GPU.search(text) is not None


def goal_step_motion(goal: "dict | None", index: int) -> bool:
    steps = (goal or {}).get("steps") or []
    if not 0 <= index < len(steps):
        return False
    text = " ".join([str(steps[index].get("text") or "")]
                    + [c["item"] for c in goal_checklist(goal, index)])
    return _GOAL_MOTION.search(text) is not None


def _num(value) -> "float | None":
    try:
        return None if value is None or isinstance(value, bool) \
            else float(value)
    except (TypeError, ValueError):
        return None


def capture_precheck(paths: "list[str]", contract: "dict | None",
                     goal: "dict | None", index: "int | None") -> "str | None":
    """#295: the cheap check before the judge model. Why the capture is an
    ENVIRONMENT failure, or None when it may be judged."""
    contract = contract or {}
    mode = contract.get("render_mode")
    renderer = contract.get("renderer") or "?"
    idx = -1 if index is None else index
    if mode == "unavailable":
        return "render_mode is unavailable (renderer %s): no capture" % renderer
    if mode == "software" and goal_step_gpu(goal, idx):
        return ("the capture is software-rendered (renderer %s) on a step "
                "that needs the GPU" % renderer)
    pre = contract.get("precheck") or {}
    if pre.get("uniform") is True:
        return "the render's precheck says the frame is uniform"
    colours = _num(pre.get("distinct_colours"))
    if colours is not None and colours < _WARN_COLOURS:
        return "the render's precheck counts only %d distinct colours" % colours
    dark = _num(pre.get("dark_pct"))
    if dark is not None:
        dark = dark * 100 if dark <= 1.0 else dark
        if dark >= 100 * _RENDER_NEAR_BLANK:
            return "the render's precheck says %.1f %% of the frame is dark" % dark
    if pre.get("identical_frames") is True and goal_step_motion(goal, idx):
        return ("the frames are identical, and this step needs motion "
                "(max frame diff %s)" % pre.get("max_frame_diff", "0"))
    for path in paths[:1]:
        if not str(path).lower().endswith(".png"):
            continue
        try:
            with open(path, "rb") as fh:
                img = _png_pixels(fh.read(_PNG_DECODE_BUDGET))
        except OSError:
            img = None
        if img is None:
            continue
        stats = _pixel_stats(img)
        name = os.path.basename(path)
        if stats["share"] is not None and stats["share"] >= _RENDER_NEAR_BLANK:
            return "%s is %.1f %% one colour" % (name, 100 * stats["share"])
        if stats["luma"] <= _RENDER_DARK_LUMA:
            return "%s is near-black (luma mean %d/255)" % (
                name, int(round(stats["luma"])))
        if stats["colours"] < _WARN_COLOURS:
            return "%s has only %d distinct colours" % (name, stats["colours"])
    return None


# ------------------------------------------- #295, reference images --------
#
# THE USER'S PICTURES OF WHAT GOOD LOOKS LIKE. `reference: <path> -- <criterion>`
# in `/goal`: the judge gets the image after the capture and answers "is the
# capture as good as the reference on <criterion>" (MLLM-as-a-Judge: pairwise
# is where MLLM judges agree with humans; GPTEval3D, Prometheus-Vision). The
# user's word, so it lives beside the accept lines in SESSION_DIR, keyed by
# the goal's path -- never a path written into the code. ADVISORY for now
# (`must: false`): a local model against the user's reference would never pass,
# and a gate that cannot pass is a pause generator until it is calibrated.
GOAL_REFERENCE_PREFIX = "reference:"
GOAL_REFERENCE_FILE = "goal-references.json"
GOAL_REFERENCE_MAX = 2


def _goal_reference_path() -> str:
    return os.path.join(SESSION_DIR, GOAL_REFERENCE_FILE)


def goal_references() -> "list[dict]":
    """[{path, criterion}] for the goal in this working area."""
    try:
        with open(_goal_reference_path(), encoding="utf-8") as fh:
            found = json.load(fh)
    except (OSError, ValueError):
        return []
    refs = found.get(os.path.abspath(goal_path())) if isinstance(found, dict) \
        else None
    return [r for r in refs if isinstance(r, dict) and r.get("path")] \
        if isinstance(refs, list) else []


def goal_references_set(refs: "list[dict] | None") -> None:
    try:
        with open(_goal_reference_path(), encoding="utf-8") as fh:
            found = json.load(fh)
    except (OSError, ValueError):
        found = {}
    if not isinstance(found, dict):
        found = {}
    key = os.path.abspath(goal_path())
    if refs:
        found[key] = list(refs)[:GOAL_REFERENCE_MAX]
    elif found.pop(key, None) is None:
        return
    try:
        os.makedirs(SESSION_DIR, exist_ok=True)
        tmp = _goal_reference_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(found, fh, indent=1, ensure_ascii=False)
        os.replace(tmp, _goal_reference_path())
    except OSError:
        pass


def goal_reference_parse(line: str) -> "tuple[dict | None, str | None]":
    """`<path> -- <criterion>` -> ({path, criterion}, None) or (None, why)."""
    raw = str(line or "").strip()
    path, _sep, criterion = raw.partition(" -- ")
    path = os.path.expanduser(path.strip().strip("'\""))
    if not path:
        return None, "a reference line needs a path"
    if not os.path.isabs(path) and get_root():
        path = os.path.join(get_root(), path)
    path = os.path.abspath(path)
    if not os.path.isfile(path):
        return None, "no such reference image: %s" % path
    if os.path.splitext(path)[1].lower() not in IMAGE_TYPES:
        return None, "not an image: %s" % path
    return {"path": path, "criterion": criterion.strip()[:160]}, None


# ------------------------------------------- #294, what the engine says -----

def goal_pause_nudge(goal: dict) -> str:
    """#294 B: the one turn a pause gets -- the model prepares it for the user."""
    pause = goal_paused(goal) or {}
    n = pause.get("step")
    steps = goal.get("steps") or []
    step = steps[n - 1] if isinstance(n, int) and 0 < n <= len(steps) else {}
    fails = step.get("fail_log") or []
    last = "\n".join("- %s: %s" % (f.get("class"), _clip(f.get("why") or "", 240))
                     for f in fails[-4:])
    return ("%s PAUSED at step %s (%s): %s\n%s"
            "Do not call any tools now. Write a short report for the user, in this "
            "order:\n1. What you identified -- the facts, with the captures, "
            "judge answers and log lines that show them.\n2. Why you cannot "
            "proceed on your own.\n3. Two or three concrete proposals, each with "
            "what the user would do or decide.\n4. Ask the user whether they have "
            "further input. Then stop: goal mode continues only after their "
            "reply.]"
            % (GOAL_NUDGE_MARK, n if n is not None else "?",
               pause.get("class") or "?", pause.get("why") or "?",
               ("What failed on this step:\n%s\n" % last) if last else ""))


def _goal_feedback(step: dict) -> str:
    """The judge's last word on a step, as a few lines for a nudge."""
    verdict = step.get("judge") if isinstance(step.get("judge"), dict) else {}
    lines = []
    for item, answer in (verdict.get("checklist") or {}).items():
        if answer != "yes":
            why = (verdict.get("evidence") or {}).get(item) or ""
            lines.append("- %s: %s%s" % (item, answer,
                                         (" -- " + _clip(why, 200)) if why else ""))
    for weak in (verdict.get("weakest") or [])[:3]:
        lines.append("- weakest: %s" % _clip(str(weak), 200))
    return "\n".join(lines[:8])


def goal_ladder_nudge(goal: dict, index: int, rung: str) -> str:
    """#294: the nudge for rung `rung` of step `index`."""
    step = goal["steps"][index]
    n, text = index + 1, step["text"]
    fails = step.get("fail_log") or []
    last = fails[-1] if fails else {}
    why = _clip(str(last.get("why") or step.get("note") or "?"), 600)
    feedback = _goal_feedback(step)
    evidence = goal_nudge_evidence(goal, index)
    if rung == GOAL_LADDER_RETRY:
        return ("%s. Step %d: the ENVIRONMENT failed, not your work: %s\n"
                "Retry %d of %d: render again with render_page and read its "
                "render_mode and precheck before you judge. If this machine "
                "cannot produce a valid capture now, say so plainly -- after "
                "the %s retry the goal pauses for the user. Step %d: %s]"
                % (GOAL_NUDGE_MARK, n, why,
                   int(step.get("env_failures") or 1), GOAL_ENV_RETRIES,
                   "second" if GOAL_ENV_RETRIES == 2 else "last", n, text))
    if rung == GOAL_LADDER_REFLECT:
        return ("%s. Step %d, attempt 1 failed: \"%s\"\n%s"
                "Before you change anything, reflect: what did the judge see, "
                "why did your approach produce that, and what will you do "
                "differently? Write it with goal_step(step=%d, "
                "status='running', note='reflection: ...'). Then attempt 2 "
                "with a different approach -- not the one that failed. "
                "Step %d: %s%s]"
                % (GOAL_NUDGE_MARK, n, why,
                   ("The judge's feedback:\n%s\n" % feedback) if feedback else "",
                   n, n, text, evidence))
    if rung == GOAL_LADDER_FRESH:
        tried = "\n".join("- attempt %d (%s): %s" % (k, f.get("class"),
                                                    _clip(f.get("why") or "", 300))
                          for k, f in enumerate(fails[-3:], 1))
        thoughts = "\n".join("- " + _clip(r, 400)
                             for r in step.get("reflections") or [])
        return ("%s. Step %d, attempt 3, in a FRESH context: the conversation "
                "before was cut so the failed approaches do not steer you.\n"
                "What failed:\n%s\n%s%s"
                "Start step %d again with an approach that avoids all of "
                "that: %s%s]"
                % (GOAL_NUDGE_MARK, n, tried or "- " + why,
                   ("Your reflections:\n%s\n" % thoughts) if thoughts else "",
                   ("The judge's last feedback:\n%s\n" % feedback)
                   if feedback else "", n, text, evidence))
    if rung == GOAL_LADDER_SPLIT:
        return ("%s. Step %d failed three attempts: \"%s\"\n%s"
                "Decompose it: split step %d into %d-%d smaller sub-steps, "
                "each verifiable on its own, the hardest part isolated first. "
                "Call goal_step(step=%d, status='split', substeps=[...]), then "
                "work sub-step %d.1. Step %d: %s]"
                % (GOAL_NUDGE_MARK, n, why,
                   ("The judge's feedback:\n%s\n" % feedback) if feedback else "",
                   n, GOAL_SUBSTEPS_MIN, GOAL_SUBSTEPS_MAX, n, n, n, text))
    subs = step.get("subs") or []
    k = goal_sub_next(step)
    if k is None:
        return ("%s. All sub-steps of step %d are done. Now verify step %d "
                "itself: %s%s]" % (GOAL_NUDGE_MARK, n, n, text, evidence))
    return ("%s. Step %d is split. Sub-step %d.%d of %d: %s\nReport it with "
            "goal_step(step=%d, sub=%d, status='done' and what proves it, or "
            "'failed' and why). A failed sub-step pauses the goal for the user. "
            "(Step %d: %s)]"
            % (GOAL_NUDGE_MARK, n, n, k + 1, len(subs), subs[k]["text"], n,
               k + 1, n, text))


def goal_checklist_ask(goal: "dict | None", index: int) -> str:
    """#295: the sentence the first nudge of a visual step adds when the
    step has no checklist yet."""
    if not goal_step_needs_render(goal, index) or goal_checklist(goal, index):
        return ""
    return (" Before you build, write this step's checklist ONCE: "
            "goal_step(step=%d, status='running', checklist=[3-6 yes/no "
            "statements a reviewer can check on the capture; prefix "
            "'optional:' for nice-to-haves]). It is frozen after that, and the "
            "judge answers each item yes, no or unknown." % (index + 1))


# ---------------------------------------------------- #202, die Notbremse ----
#
# WAS HIER GEBREMST WIRD, am 2026-09-18 live gesehen: der Motor schickte
# denselben Anstoss noch einmal, das Modell antwortete mit dem einzelnen Token
# `I` und einem EOS, und das fuenfunddreissig Mal hintereinander -- bis der
# 60-Zuege-Deckel es beendete. Am Tag davor dasselbe mit `3`, achtundvierzig Mal.
#
# WARUM ES SICH SELBST TRAEGT: jeder wiedergeschickte Zug steht danach im
# Kontext. Das Modell liest also nicht nur einen Auftrag, sondern fuenfunddreissig
# Beispiele dafuer, wie in diesem Gespraech geantwortet wird -- und antwortet
# genauso. Der Motor bringt dem Modell bei, sich zu wiederholen.
#
# DIE ANTWORT DARAUF IST NICHT NUR AUFHOEREN. Wer nur anhaelt, laesst die
# Beispiele stehen; wer nur anders fragt, fragt vor denselben Beispielen. Also:
# erkennen, die Kreiszuege aus der Geschichte NEHMEN, einmal anders fragen, und
# wenn auch das leer zurueckkommt, Schluss.
#
# DER KERN ENTSCHEIDET NICHT, WANN GEBREMST WIRD -- er sagt nur, was eine
# Wiederholung ist, was leer ist und wo geschnitten werden muss. Die Schleife
# gehoert der Oberflaeche, die sie faehrt.

# WORAN CROW SEINE EIGENE ZIELZEILE WIEDERERKENNT. Der Anstoss ist keine
# Nutzerzeile, sondern Crows Anweisung an das Modell -- und wenn er spaeter
# wieder aus der Geschichte genommen werden muss, ist dieses Praefix das
# einzige, was ihn von einer getippten Zeile unterscheidet. Beide Formen, der
# volle Block und die kurze Variante, fangen damit an.
GOAL_NUDGE_MARK = "[Goal mode"

# WIE OFT DIESELBE ANTWORT KOMMEN DARF, bevor gebremst wird. Zwei gleiche
# Antworten sind ein Zufall -- ein Modell, das zweimal "ok" sagt, kann trotzdem
# arbeiten. Drei sind ein Kreis, und der dritte ist frueh genug: bis dahin
# stehen drei Beispiele im Kontext und nicht fuenfunddreissig.
GOAL_LOOP_ANSWERS = 3

# WAS "LEER" HEISST: ein einzelnes Token ohne Werkzeugaufruf. Nicht die leere
# Zeichenkette allein -- die beiden live gesehenen Faelle waren `I` und `3`,
# also je ein Zeichen, und eine Grenze, die nur die Null kennt, haette keinen
# von beiden gefangen.
GOAL_EMPTY_CHARS = 2


def goal_message_text(message: "dict | None") -> str:
    """Der Text einer Nachricht -- auch wenn sie als Bloecke kam (#142)."""
    content = (message or {}).get("content")
    if isinstance(content, list):
        return "".join(part.get("text") or "" for part in content
                       if isinstance(part, dict) and part.get("type") == "text")
    return content if isinstance(content, str) else ""


# #258. THE LINES `run_turn` ITSELF WRITES INSIDE ONE TURN. They are user
# messages, but they do not open a turn: the round behind them belongs to the
# turn the nudge (or the owner's line) opened.
_GOAL_IN_TURN_NOTES = (BUDGET_SPENT, TOKEN_BUDGET_SPENT, THINK_ONLY_NUDGE)


def goal_last_answer(messages: "list | None") -> "dict | None":
    """Die letzte Antwort des Modells, mit den Werkzeugaufrufen IHRES ZUGES.

    #258. DER ZUG WIRD BEURTEILT, NICHT SEINE LETZTE NACHRICHT. Ein Zug, der
    sein Werkzeugbudget aufbraucht, endet auf der erzwungenen Runde -- und
    deren Aufrufe werden verworfen (`unanswerable` in `run_turn`), ihr Content
    ist oft leer. Allein gelesen sah diese Nachricht aus wie `I`: live am
    2026-09-23 las die Bremse drei Zuege mit je 24 Werkzeugrunden als "leer",
    schnitt 157 Nachrichten Arbeit weg (20:05:47Z, COLD 106,376 Token) und
    danach den Erholungszug mit 25 Runden (20:15:07Z, COLD 106,336 Token).

    Zurueckgegeben wird eine KOPIE der letzten Antwort, deren `tool_calls`
    alle Aufrufe des Zuges tragen -- ab der Zeile, die ihn eroeffnet hat;
    Crows eigene Protokollzeilen im Zug (Budget, Denk-Stups) eroeffnen keinen.
    Damit sagt `goal_answer_empty` ueber den ZUG aus: wer gearbeitet hat,
    ist nicht leer.
    """
    last = None
    calls: list = []
    for message in reversed(messages or []):
        role = message.get("role")
        if role == "assistant":
            if last is None:
                last = message
            calls[:0] = list(message.get("tool_calls") or [])
        elif role == "user":
            if goal_message_text(message) in _GOAL_IN_TURN_NOTES:
                continue
            break
    if last is None:
        return None
    answer = dict(last)
    if calls:
        answer["tool_calls"] = calls
    return answer


def goal_answer_empty(message: "dict | None") -> bool:
    """Eine Antwort, die nichts ist: hoechstens `GOAL_EMPTY_CHARS` Zeichen und
    kein Werkzeugaufruf.

    DER AUFRUF FAELLT ZUERST, und das ist keine Feinheit: ein Zug, der `ok` sagt
    und dabei eine Datei schreibt, hat gearbeitet. Kurz ist nur dann leer, wenn
    daneben nichts passiert ist.
    """
    if message is None or message.get("tool_calls"):
        return False
    text = goal_message_text(message)
    # #259: CROW'S STAND-IN IS NOT THE MODEL SPEAKING. A final
    # round with no visible text now shows its reasoning under SURFACED_MARK;
    # for the brake that answer is as empty as it was before.
    if is_surfaced(text):
        return True
    return len(text.strip()) <= GOAL_EMPTY_CHARS


def goal_turn_mark(messages: "list | None") -> "str | None":
    """#259: the fingerprint of the LAST TURN, not of its last
    message. None when there is no answer yet.

    A fingerprint of the last message alone made every turn that ended on
    an empty forced answer the SAME answer -- sha of ("", no calls) -- however
    different the 24 calls before it were. The last answer's text plus every
    call of the turn, with arguments: the same text over the same calls is
    still a loop; different work is not.
    """
    answer = goal_last_answer(messages)
    if answer is None:
        return None
    import hashlib

    start = goal_turn_start(messages) or 0
    calls = [[(call.get("function") or {}).get("name") or "",
              (call.get("function") or {}).get("arguments") or ""]
             for message in (messages or [])[start:]
             if message.get("role") == "assistant"
             for call in message.get("tool_calls") or []]
    material = json.dumps([goal_message_text(answer).strip(), calls],
                          sort_keys=True)
    return hashlib.sha256(material.encode("utf-8")).hexdigest()[:16]


def goal_turn_empty(messages: "list | None") -> bool:
    """#259: was the LAST TURN empty -- not only its last message?

    THE BRAKE READ ONE MESSAGE AND JUDGED A WHOLE TURN BY IT. Measured
    2026-09-23 (diorama goal run): turns of 24-26 rounds that ran tools and
    wrote files each ended on the forced answer after BUDGET_SPENT, which came
    back reasoning-only -- and three of them in a row counted as "three empty
    answers": the brake cut 157 messages of real work from the history, sent
    the recovery line, and when the answer to THAT (24 tool calls, message
    263 reasoning-only again) was judged empty too, goal mode stopped at 6/9.

    A turn that ran a tool worked, whatever its last message says. Only a
    turn with no tool result anywhere since it began is judged by its answer.
    """
    start = goal_turn_start(messages)
    for message in (messages or [])[(start or 0):]:
        if message.get("role") == "tool" or (
                message.get("role") == "assistant" and message.get("tool_calls")):
            return False
    return goal_answer_empty(goal_last_answer(messages))


def goal_is_nudge(message: "dict | None") -> bool:
    """Ist diese Nachricht Crows eigener Anstoss und nicht die Zeile des Nutzers?"""
    return ((message or {}).get("role") == "user"
            and goal_message_text(message).startswith(GOAL_NUDGE_MARK))


def goal_loop_cut(messages: "list | None", turns: int) -> "int | None":
    """Wo geschnitten wird, damit die letzten `turns` Motorzuege verschwinden.

    GEZAEHLT WIRD AN DEN ANSTOESSEN, nicht an den Antworten: ein Motorzug faengt
    mit Crows Zeile an, und alles dahinter gehoert dazu -- die Antwort, ihre
    Werkzeugergebnisse und jede weitere Runde. Wer nur die Antworten wegnaehme,
    liesse die Anstoesse stehen, und die Geschichte behauptete danach, das
    Modell habe auf sie geschwiegen.

    ALLES VOR DEM ERSTEN DIESER ZUEGE BLEIBT. Ein Kreis ist kein Grund, die
    Arbeit davor zu verlieren.

    None heisst: hier steht kein Motorzug, also gibt es nichts zu schneiden.
    """
    marks = [n for n, message in enumerate(messages or []) if goal_is_nudge(message)]
    if not marks or turns < 1:
        return None
    return marks[-turns] if len(marks) >= turns else marks[0]


def goal_worked_on_nudge(messages: "list | None") -> bool:
    """Lief der letzte Zug auf Crows Anstoss UND hat er ein Werkzeug gerufen?

    Die Frage, an der die kurze Variante des Anstosses haengt: wer arbeitet,
    braucht den ganzen Block nicht noch einmal -- und ein Verlauf, in dem
    hundertmal derselbe 330-Byte-Block steht, ist selbst schon das Muster, das
    das Modell dann fortsetzt.
    """
    worked = False
    for message in reversed(messages or []):
        if message.get("role") == "user":
            return worked and goal_is_nudge(message)
        if message.get("role") == "assistant" and message.get("tool_calls"):
            worked = True
    return False


# ------------------------------- #202, dieselbe Fehlerklasse je Schritt ----
#
# WAS DIE BREMSE OBEN NICHT SIEHT, am 2026-09-22 zweimal gemessen: ein Modell,
# das ARBEITET -- jeder Zug ruft Werkzeuge, keine zwei Antworten gleich --, und
# trotzdem seit Stunden gegen dieselbe Wand laeuft. 48 blinde Runden mit toter
# Suche (Tavily 401) und toten Delegaten (403); in der 655-Nachrichten-Sitzung
# 22 edit_file-Aufrufe, von denen keiner landete, sechs Pfade, die das Modell
# nie angelegt hatte, und render_page-Fehlschlaege, auf die es mit wait_ms 6000
# -> 12000 -> 20000 antwortete und dann mit einem eigenen chromium ueber
# run_command. Der Anstoss dazwischen wiederholte jedes Mal nur den Schritt.
#
# DER FINGERABDRUCK DER ANTWORT hilft hier nicht: web_search mit drei
# verschiedenen Fragen sind drei verschiedene Zuege und EIN toter Dienst.
# Gezaehlt wird deshalb die KLASSE des Ergebnisses, nicht der Aufruf -- und das
# ist auch der Unterschied zu dem, was andere Harnesses zaehlen: OpenHands'
# StuckDetector verlangt dieselbe Aktion mit denselben Argumenten (action_error,
# Schwelle 3), Clines MistakeTracker zaehlt jeden Fehler gleich
# (maxConsecutiveMistakes), Aider (max_reflections 3) und SWE-agent
# (max_requeries 3) begrenzen Wiederholungen ohne sie zu benennen. Keiner sagt
# dem Modell, WAS tot ist und was es stattdessen tun soll.
#
# DER KERN KLASSIFIZIERT UND FORMULIERT, die Oberflaeche zaehlt pro Schritt und
# entscheidet, wann ein Anstoss faellig ist -- dieselbe Teilung wie bei der
# Bremse oben.

# WIE OFT DIESELBE KLASSE IN EINEM SCHRITT KOMMEN DARF, bevor der Anstoss sie
# beim Namen nennt. Dieselbe Drei wie `GOAL_LOOP_ANSWERS`, und aus demselben
# Grund: zweimal ist ein Zufall (ein 401 kann ein Tippfehler im Schluessel
# sein, der gleich behoben ist), dreimal ist ein Zustand. Es ist auch die Zahl,
# die OpenHands, Aider und SWE-agent unabhaengig voneinander gewaehlt haben.
# Gemessen: die drei web_search-401 vom 2026-09-22 kamen in EINEM Zug -- bei
# drei ist der naechste Anstoss der erste, der es sagt.
GOAL_TROUBLE_TRIPS = 3

# DIE KLASSEN, in der Reihenfolge, in der ein Ergebnis gegen sie geprueft wird.
# Die Reihenfolge ist Absicht: ein 401 ist kein Verweigern des Werkzeugs, ein
# ENOENT ist keine beliebige Ausnahme, und ein Fang-Timeout keine Weigerung --
# die spezifischere Klasse hat den besseren Rat.
GOAL_TROUBLE_DEAD = "dead"          # externer Dienst antwortet 401/402/403
GOAL_TROUBLE_PHANTOM = "phantom"    # ENOENT auf einen Pfad, den nie jemand anlegte
GOAL_TROUBLE_TIMEOUT = "timeout"    # Render/Pruefung lief in die Zeit
GOAL_TROUBLE_REFUSED = "refused"    # ein Werkzeug sagt wieder dasselbe Nein
GOAL_TROUBLE_ERROR = "error"        # dieselbe Ausnahme im Befehl, wieder und wieder

# Eine Zeile, die Crow selbst vor ein Ergebnis setzt ("[took old_string as
# old]", vor #215 "[unknown argument(s) ignored: ...]") -- sie verdeckt, ob
# darunter ein Fehler steht.
_TROUBLE_NOTE = re.compile(r"^\[[^\]\n]*\]\n")
_TROUBLE_HTTP = re.compile(r"\bHTTP (40[123])\b")
_TROUBLE_HOST = re.compile(r"https?://([^/\s:'\"]+)")
_TROUBLE_EXIT = re.compile(r"^\[exit (-?\d+)\]")
# DIE FORMEN, IN DENEN EIN FEHLENDER PFAD ANKOMMT, jede so, wie sie in den
# Transkripten steht: node (`ENOENT: ..., open '/tmp/water.js'`), Python
# (`[Errno 2] No such file or directory: '...'`), Crows eigene Werkzeuge
# (`no such file: ...`, `no such page: ...`) und die coreutils.
_TROUBLE_MISSING = (
    re.compile(r"ENOENT: no such file or directory, \w+ '([^']+)'"),
    re.compile(r"No such file or directory: '([^']+)'"),
    re.compile(r"^error: no such (?:file|page|directory): (\S+)", re.M),
    re.compile(r"cannot (?:access|open|stat|create regular file) '([^']+)'"),
    re.compile(r"^[\w.-]+: ([^\s:']+): No such file or directory", re.M),
)
# DIE SIGNATUR EINER AUSNAHME: die Zeile, an der ein Mensch sie wiedererkennt.
# esbuilds `✘ [ERROR] ...`, eine Python-/JS-Ausnahme `XyzError: ...`, und die
# Shell, die an einer offenen Anfuehrung scheitert.
_TROUBLE_SIGNATURE = (
    re.compile(r"✘ \[ERROR\] (.+)"),
    re.compile(r"^\s*((?:[A-Za-z_][\w.]*)?(?:Error|Exception)\b:?.*)$", re.M),
    re.compile(r"(unexpected EOF while looking for matching .+)"),
)
# WINDOWS ZUERST (windows-latest CI, 2026-09-24): `D:\a\_temp\x\a.py` hat
# keinen Schraegstrich, also blieb der Pfad stehen und zwei gleiche Weigerungen
# an zwei Dateien zaehlten als zwei verschiedene.
_TROUBLE_PATHLIKE = re.compile(
    r"\b[A-Za-z]:[\\/][^\s'\"`,;()]+|\b[\w.-]+\\[\w.\\-]+"
    r"|(?:~|\.{1,2})?/[^\s'\"`,;:()]+|\b[\w.-]+/[\w./-]+")


def _trouble_norm(text: str) -> str:
    """Eine Zeile ohne das, was sich von Mal zu Mal aendert: Pfade und Zahlen.

    "read src/app.js before editing it" und "read /tmp/shot2/index.html before
    editing it" sind DIESELBE Weigerung -- gemessen 2026-09-22, elf Mal mit
    wechselnden Pfaden. Wer sie nach Pfad trennte, zaehlte elf Einzelfaelle.
    """
    text = _TROUBLE_PATHLIKE.sub("<path>", text.strip())
    return re.sub(r"\d+", "N", text)[:160]


def _trouble_tool(name: str) -> str:
    """`collect` meldet, was `delegate` losschickte: ein toter Delegat ist
    EINE Klasse, egal an welchem der beiden Aufrufe er sichtbar wird."""
    return "delegate" if name in ("delegate", "collect") else name


def _trouble_first_line(text: str) -> str:
    return (text.strip().splitlines() or [""])[0][:200]


def goal_trouble_of(name: str, result: str, seen: "Callable[[str], bool]"
                    ) -> "tuple[str, str, str] | None":
    """Die Fehlerklasse eines Werkzeugergebnisses: `(klasse, schluessel,
    detail)`, oder None fuer ein Ergebnis, das kein Fehler ist.

    `seen(pfad)` sagt, ob ein Pfad VOR diesem Aufruf schon irgendwo im
    Gespraech stand. Der Kern liest das Gespraech nicht selbst, damit dieselbe
    Funktion live und in der Nachrechnung eines gespeicherten Verlaufs laeuft.

    NUR FEHLSCHLAEGE WERDEN GEZAEHLT: `error: ...` von einem Werkzeug oder ein
    run_command mit Exit ungleich 0. Ein grep, der "HTTP 401" in einer Quelle
    findet, ist Arbeit und kein toter Dienst.
    """
    text = result if isinstance(result, str) else json.dumps(result)
    # Das Exit-Praefix von run_command steht auch in eckigen Klammern -- es
    # ist aber das Ergebnis und keine Notiz davor, also wird es nicht
    # abgeschaelt.
    while _TROUBLE_NOTE.match(text) and not _TROUBLE_EXIT.match(text):
        text = _TROUBLE_NOTE.sub("", text, count=1)
    exit_code = _TROUBLE_EXIT.match(text)
    failed = text.startswith("error") or (exit_code is not None
                                          and exit_code.group(1) != "0")
    if not failed:
        return None
    tool = _trouble_tool(name)
    # 1. EIN TOTER DIENST. Nur an Crows eigenem Fehlerpraefix: ein 401 im
    # Ausgabetext eines Befehls sagt nichts ueber einen Dienst dieses Laufs.
    http = _TROUBLE_HTTP.search(text) if text.startswith("error") else None
    if http:
        host = _TROUBLE_HOST.search(text)
        host = host.group(1) if host else ""
        return (GOAL_TROUBLE_DEAD, "%s|%s|%s" % (tool, host, http.group(1)),
                "HTTP %s%s" % (http.group(1), " from " + host if host else ""))
    # 2. EIN PFAD, DEN ES NIE GAB. Der Pfad steht zum ERSTEN Mal im Aufruf, der
    # an ihm scheitert -- gemessen in allen sechs Faellen vom 2026-09-22.
    missing = []
    for pattern in _TROUBLE_MISSING:
        for path in pattern.findall(text):
            path = path.strip().rstrip(".")
            if path and path not in missing and not seen(path):
                missing.append(path)
    if missing:
        return (GOAL_TROUBLE_PHANTOM, GOAL_TROUBLE_PHANTOM, "\n".join(missing))
    # 3. EIN FANG, DER NICHT KAM. render_page sagt es in eigenen Worten, alles
    # andere mit "timed out" oder dem Deckel von run_command.
    if (text.startswith("error: the browser wrote no screenshot")
            or (text.startswith("error") and ("timed out" in text
                                              or "and was killed" in text))):
        # Der Grund steht in der ersten Klammer ("timed out after 9000 ms and
        # was stopped"); die Konsolenzeilen dahinter hat das Modell schon.
        reason = re.search(r"\(([^()\n]+)\)", text)
        return (GOAL_TROUBLE_TIMEOUT, tool,
                reason.group(1) if reason else _trouble_first_line(text))
    # 4. DAS WERKZEUG SAGT NEIN, und zwar dasselbe.
    if text.startswith("error"):
        line = re.sub(r"^error:\s*", "", _trouble_first_line(text))
        return (GOAL_TROUBLE_REFUSED, "%s|%s" % (tool, _trouble_norm(line)), line)
    # 5. DIESELBE AUSNAHME IM BEFEHL. Ein Exit ungleich 0 ohne erkennbare
    # Signatur zaehlt nicht: `grep` ohne Treffer ist Exit 1 und kein Fehler.
    for pattern in _TROUBLE_SIGNATURE:
        hit = pattern.search(text)
        if hit:
            line = hit.group(1).strip()[:200]
            return (GOAL_TROUBLE_ERROR, _trouble_norm(line), line)
    return None


def _trouble_mentions(message: dict) -> str:
    """Was in einer Nachricht an Pfaden stehen KANN: Text und Aufrufargumente."""
    parts = [goal_message_text(message)]
    for call in message.get("tool_calls") or []:
        parts.append((call.get("function") or {}).get("arguments") or "")
    return "\n".join(p for p in parts if p)


def _trouble_phantoms(counts: dict) -> "set[str]":
    return {path for entry in counts.values()
            if entry["cls"] == GOAL_TROUBLE_PHANTOM
            for path in entry["detail"].split("\n") if path}


def _trouble_mentioned(path: str, text: str) -> bool:
    """Steht `path` als PFAD in `text`, nicht als Teil eines anderen?

    GEMESSEN 2026-09-22: `/tmp/water.js` stand vorher nur als Ende von
    `~/.local/state/crow/tmp/water.js` im Gespraech -- einer anderen Datei.
    Ein absoluter Pfad braucht deshalb eine Grenze davor; ein relativer darf
    das Ende eines laengeren sein (`src/app.js` in `/srv/.../src/app.js`),
    denn so schreibt man ihn aus dem Arbeitsverzeichnis heraus. Dahinter
    duerfen weder Pfadzeichen noch eine Endung folgen: `src/water.js` ist
    nicht `src/water.js.bak`.
    """
    lead = r"(?<![\w.~-])" if path[:1] in ("/", "~") else ""
    return re.search(lead + re.escape(path) + r"(?![\w/-]|\.\w)", text) is not None


def goal_trouble_scan(messages: "list | None", start: int,
                      counts: "dict | None" = None,
                      new_step: bool = False) -> dict:
    """Die Werkzeugergebnisse ab `start` in `counts` zaehlen und es zurueckgeben.

    `counts` gehoert dem Schritt: `{schluessel: {"cls", "tool", "n", "detail",
    "at", "said"}}`. `at` ist der Index des Ergebnisses, an dem die Klasse die
    Schwelle erreichte -- das, was die Nachrechnung berichtet.

    EIN `goal_step` MIT 'done' LEERT DIE ZAEHLER mitten im Zug: ein Schritt,
    der abgeschlossen wurde, vererbt seine Fehler nicht dem naechsten, auch
    wenn beide im selben Zug liegen. 'failed' NICHT: ein gescheiterter Schritt
    bleibt der naechste offene, Crow stoesst ihn wieder an -- gemessen
    2026-09-22, [97] 'failed' auf Schritt 9 und danach 550 Nachrichten
    Schritt 9. Wer dort die Zaehler leerte, vergaesse die Wand genau dann,
    wenn das Modell selbst gesagt hat, dass es an ihr scheitert.

    `new_step`: der Schritt hat seit dem letzten Anstoss gewechselt. Dann
    gehoert der Zug bis zum abschliessenden `goal_step` dem ALTEN Schritt und
    wird nicht gezaehlt -- ohne einen solchen Aufruf im Zug (der Owner hat im
    Panel gewechselt) gar nichts davon.

    WAS "SCHON GESEHEN" HEISST, fuer einen Pfad: er steht in irgendeiner
    Nachricht VOR der Antwort, die den scheiternden Aufruf enthielt -- als
    Text, als Werkzeugergebnis oder als Argument. Der Text davor wird erst
    gebaut, wenn ein Pfad fehlt: ein gesunder Lauf zahlt nichts dafuer.
    """
    counts = counts if counts is not None else {}
    messages = messages or []
    calls: dict = {}
    counting = not new_step
    for n in range(max(0, start), len(messages)):
        message = messages[n]
        role = message.get("role")
        if role == "assistant":
            for call in message.get("tool_calls") or []:
                fn = call.get("function") or {}
                calls[call.get("id")] = (n, fn.get("name") or "",
                                         fn.get("arguments") or "")
            continue
        if role != "tool":
            continue
        at, name, arguments = calls.get(message.get("tool_call_id"), (n, "", ""))
        if name == "goal_step":
            try:
                status = (json.loads(arguments or "{}") or {}).get("status")
            except (ValueError, AttributeError):
                status = None
            if status == GOAL_DONE:
                counts.clear()
                counting = True
            continue
        if not counting:
            continue
        before: "list[str]" = []

        def seen(path: str, _at: int = at) -> bool:
            # EIN PFAD, DER SCHON EINMAL INS LEERE GING, BLEIBT EIN PHANTOM,
            # auch wenn er inzwischen im Gespraech steht: gemessen 2026-09-22,
            # `cp` nach /tmp/s21/index.html scheiterte (kein mkdir), und der
            # naechste Aufruf, render_page auf genau diesen Pfad, erwaehnte
            # ihn damit "schon".
            if path in _trouble_phantoms(counts):
                return False
            if not before:
                before.append("\n".join(_trouble_mentions(m)
                                        for m in messages[:_at]))
            return _trouble_mentioned(path, before[0])

        kind = goal_trouble_of(name, message.get("content") or "", seen)
        if kind is None:
            continue
        cls, key, detail = kind
        entry = counts.setdefault(cls + "|" + key, {
            "cls": cls, "tool": _trouble_tool(name), "n": 0, "detail": "",
            "at": None, "said": 0})
        entry["n"] += 1
        if cls == GOAL_TROUBLE_PHANTOM:
            paths = entry["detail"].split("\n") if entry["detail"] else []
            entry["detail"] = "\n".join(paths + [p for p in detail.split("\n")
                                                 if p not in paths])
        else:
            entry["detail"] = detail
        if entry["n"] == GOAL_TROUBLE_TRIPS:
            entry["at"] = n
    return counts


# WAS STATT DES TOTEN DIENSTES ZU TUN IST, je Werkzeug. Nur fuer die, deren
# Ausweg feststeht; jedes andere bekommt den allgemeinen Satz.
_TROUBLE_DEAD_INSTEAD = {
    "web_search": "work from local sources (files on disk, installed docs, "
                  "--help) or ask the user for a working key",
    "fetch_url": "work from local sources or ask the user to fetch it",
    "delegate": "do the work yourself in this conversation",
}


def goal_trouble_line(entry: dict) -> str:
    """Die EINE Zeile, die eine ausgeloeste Klasse im Anstoss bekommt: Klasse,
    Zahl und der Ausweg -- nicht der Schritt noch einmal."""
    cls, tool, n, detail = entry["cls"], entry["tool"], entry["n"], entry["detail"]
    if cls == GOAL_TROUBLE_DEAD:
        return ("%s is dead this session (%s, %d×) -- stop calling it; %s."
                % (tool, detail, n, _TROUBLE_DEAD_INSTEAD.get(
                    tool, "do the step without it or ask the user")))
    if cls == GOAL_TROUBLE_PHANTOM:
        paths = detail.split("\n")
        return ("these paths were never created in this conversation (%d "
                "failures): %s -- create them first, or use the files that "
                "exist (list_dir, find_files)."
                % (n, ", ".join(paths[-5:])))
    if cls == GOAL_TROUBLE_TIMEOUT:
        if tool == "render_page":
            return ("render_page failed to capture %d× (%s) -- a larger "
                    "wait_ms will not help: lower wait_ms or make the scene "
                    "cheaper (fewer draw calls, a smaller canvas); do not "
                    "drive a browser through run_command." % (n, detail))
        return ("%s timed out %d× (%s) -- make the work smaller instead of "
                "running it again." % (tool, n, detail))
    if cls == GOAL_TROUBLE_REFUSED:
        return ("%s refused %d× the same way: %s -- do what that message "
                "names before calling it again." % (tool, n, detail))
    return ("the same error came back %d× from %s: %s -- the approach is "
            "wrong, not the detail; change it instead of patching the same "
            "spot again." % (n, tool, detail))


def goal_trouble_due(counts: "dict | None") -> "list[dict]":
    """Die Klassen, die in den naechsten Anstoss gehoeren, und merkt sie sich.

    FAELLIG IST EINE KLASSE, die die Schwelle erreicht hat UND seit dem letzten
    Anstoss wieder vorkam. Wer nach der Zeile aufhoert, hoert sie nicht noch
    einmal -- dieselbe Zeile vor jedem Zug waere wieder der 105-mal-Block, den
    #202 abgeschafft hat. Wer weitermacht, hoert sie mit der neuen Zahl.
    """
    due = []
    for entry in (counts or {}).values():
        if entry["n"] >= GOAL_TROUBLE_TRIPS and entry["n"] > entry["said"]:
            due.append(entry)
            entry["said"] = entry["n"]
    return due


def goal_trouble_label(entry: dict) -> str:
    """Die kurze Form fuer die Notiz des Nutzers: was ausgeloest hat, wie oft."""
    cls, tool, n = entry["cls"], entry["tool"], entry["n"]
    if cls == GOAL_TROUBLE_DEAD:
        return "%s dead (%s, %d×)" % (tool, entry["detail"], n)
    if cls == GOAL_TROUBLE_PHANTOM:
        return "%d calls on paths never created" % n
    if cls == GOAL_TROUBLE_TIMEOUT:
        return "%s timed out %d×" % (tool, n)
    if cls == GOAL_TROUBLE_REFUSED:
        return "%s refused %d× the same way" % (tool, n)
    return "the same error %d× from %s" % (n, tool)


def goal_turn_start(messages: "list | None") -> "int | None":
    """Wo der letzte Zug anfing: Crows Anstoss oder die getippte Zeile des Nutzers.

    NICHT JEDE NUTZERZEILE BEGINNT EINEN ZUG. Die Notiz ueber das verbrauchte
    Werkzeugbudget und die Rollover-Notiz stehen mitten in einem -- beide in
    eckigen Klammern, wie Crows eigene Zeilen, aber ohne dessen Praefix. Wer
    ab ihnen zaehlte, verloere alles, was der Zug davor gerufen hat.
    """
    for n in range(len(messages or []) - 1, -1, -1):
        message = messages[n]
        if message.get("role") != "user":
            continue
        if goal_is_nudge(message) or not goal_message_text(message).startswith("["):
            return n
    return None


def goal_trouble_nudge(step: int, due: "list[dict]") -> str:
    """Der Anstoss, wenn eine Klasse ausgeloest hat: je Klasse eine Zeile aus
    `goal_trouble_line`. `step` zaehlt ab 1.

    DER SCHRITTTEXT STEHT NICHT DRIN. Das Modell kennt ihn -- es arbeitet seit
    mindestens drei Fehlschlaegen daran --, und ihn noch einmal zu schicken
    hiesse, dieselbe Aufgabe vor dieselbe Wand zu stellen. Was es nicht weiss,
    ist, dass die Wand eine ist.
    """
    return ("%s, step %d still open -- the same failure keeps coming back:\n"
            "%s\nDo not repeat what failed. If the step cannot be done "
            "another way, call goal_step with 'failed' and say why.]"
            % (GOAL_NUDGE_MARK, step,
               "\n".join("- " + goal_trouble_line(entry) for entry in due)))


# --------------------------------- #268, der Debug-Kreis, den keiner sieht ----
#
# WAS WEDER DIE BREMSE NOCH DIE FEHLERKLASSEN SEHEN, am 2026-09-23 gemessen:
# ein Modell, das arbeitet -- jeder Zug ruft Werkzeuge, keine zwei Antworten
# gleich, kein einziger Fehlschlag --, und trotzdem kommt dasselbe Bild
# zurueck. 22:30:28-22:48:12 sieben Fangs in Folge zu 99,2-99,4 % einer Farbe
# (ein schwarzer Rahmen mit fps-Zeile), 20:07-21:03 fuenfmal der 13.622-Byte-
# Fang, 21:17-21:24 dreimal 424 kB mit derselben Farbverteilung. Dazwischen
# Edit auf Edit an den Passes, statt zu halbieren.
#
# GEZAEHLT WIRD DER FANG, NICHT DER FEHLER: ein Fang ist "fest", wenn er leer
# aussieht (#213-Warnung, #175 byte-gleich, #265 "only N distinct
# colours", oder selbst dekodiert >= 98 % einer Farbe) oder wenn er dem
# vorigen Fang DERSELBEN Seite fast gleicht -- die `metrics:`-Zahlen von
# #265, wo es sie gibt, sonst Farbanteil und Groesse. Bei drei in
# Folge ein Anstoss: halbieren statt editieren. Bei sechs ein erzwungener
# Rollover, dessen erste Zeile auflistet, was schon versucht wurde -- Claude
# Code's eigene Regel: "If you've corrected Claude more than twice on the
# same issue ... the context is cluttered with failed approaches ... start
# fresh with a more specific prompt that incorporates what you learned."
#
# DER KERN ZAEHLT UND FORMULIERT, die Oberflaeche entscheidet und rollt --
# dieselbe Teilung wie bei #202.
GOAL_RENDER_NUDGE = 3
GOAL_RENDER_ROLL = 6
# Ein Fang, der zu so viel einer Farbe ist, zeigt kein Bild (gemessen:
# die schwarzen Diorama-Fangs 0,987-0,998, der fertige Rahmen 0,598-0,704).
_RENDER_NEAR_BLANK = 0.98
# #277. SCHWARZ MIT EINEM HELLEN FLECK IST AUCH KEIN BILD. 2026-09-24, Schritt
# 2 des Diorama-Laufs: neun Fangs von index.html zu luma 0,66-2,35/255 (die
# metrics-Zeile: 1-2), aber mit HUD-Zeile und kleinem Fleck nur 0,908-0,964
# einer Farbe -- unter 0,98, also kein Urteil, und jeder setzte die Serie auf
# null. Die einzige echte Szene des Tages (iso-test.html) lag bei 30,9, die
# weissen Textseiten bei 251-255. Die Linie bei 4 liegt ueber allem, was
# schwarz war, und weit unter allem, was ein Bild war; eine Nachtszene, die im
# Mittel unter 4/255 bleibt, ist auf jedem Schirm schwarz. NUR DUNKEL: eine
# weisse Textseite ist eine Seite, kein fehlendes Bild.
_RENDER_DARK_LUMA = 4
_RENDER_LUMA = re.compile(r"luma mean (\d+)/255")
_RENDER_SHOT = re.compile(r"^(\S+\.png) -- (\d+) bytes", re.M)
_RENDER_STUCK_WARNS = ("looks blank", "almost one colour", "byte-identical",
                       "distinct colours in the capture")
# Unsigned: the metrics lines write ranges as "x 530-760", and a minus
# there is a dash, not a sign.
_RENDER_METRIC_NUM = re.compile(r"\d+(?:\.\d+)?")
_RENDER_WRITES = ("write_file", "append_file", "edit_file")
# #277: how many counted capture paths a step remembers (a step of the
# 2026-09-24 run made 11; a replay or a carry is never older than a turn).
_RENDER_SEEN_KEEP = 64


def render_signature(result: str, target: str = "") -> "dict | None":
    """What one render_page result says about its capture, or None when it
    captured nothing (a failed render is #202's business, not this one's)."""
    text = result if isinstance(result, str) else ""
    shot = _RENDER_SHOT.search(text)
    if text.startswith("error") or shot is None:
        return None
    path, size = shot.group(1), int(shot.group(2))
    metrics: "list[float]" = []
    luma = None
    for line in text.splitlines():
        if line.startswith("metrics:") and not line.startswith("metrics: crop"):
            metrics.extend(float(n) for n in _RENDER_METRIC_NUM.findall(line))
            seen = _RENDER_LUMA.search(line)
            if seen:
                luma = int(seen.group(1))
    share = None
    try:
        with open(path, "rb") as fh:
            img = _png_pixels(fh.read(_PNG_DECODE_BUDGET))
        if img is not None:
            stats = _pixel_stats(img)
            share = stats["share"]
            if luma is None:
                luma = int(round(stats["luma"]))
    except OSError:
        pass
    warned = next((w for w in _RENDER_STUCK_WARNS if w in text), None)
    blank = None
    if warned:
        blank = warned
    elif share is not None and share >= _RENDER_NEAR_BLANK:
        blank = "%.1f %% one colour" % (100 * share)
    elif luma is not None and luma <= _RENDER_DARK_LUMA:
        blank = "near-black (luma mean %d/255)" % luma                # #277
    return {"target": target, "path": path, "size": size, "share": share,
            "metrics": metrics, "blank": blank, "luma": luma}


def _render_close(a: float, b: float, rel: float, floor: float) -> bool:
    return abs(a - b) <= max(floor, rel * max(abs(a), abs(b)))


def render_same(prev: "dict | None", cur: "dict | None") -> bool:
    """Is `cur` near-identical to `prev`, the same page captured again?"""
    if not prev or not cur or prev.get("target") != cur.get("target"):
        return False
    pm, cm = prev.get("metrics") or [], cur.get("metrics") or []
    if pm and cm:
        return len(pm) == len(cm) and all(
            _render_close(a, b, 0.03, 2.0) for a, b in zip(pm, cm))
    if prev.get("share") is not None and cur.get("share") is not None:
        return (abs(prev["share"] - cur["share"]) <= 0.005
                and _render_close(prev["size"], cur["size"], 0.03, 0))
    return _render_close(prev["size"], cur["size"], 0.01, 0)


def goal_render_scan(messages: "list | None", start: int,
                     state: "dict | None" = None,
                     new_step: bool = False) -> dict:
    """Count the render_page captures from `start` into `state` and return it.

    `state` belongs to the step. Per page (`targets`): `last` (the previous
    capture's signature), `streak` (stuck captures of that page in a row) and
    `tried` (one line per stuck capture: its verdict and what was written
    before it). Beside them: `edits` (paths written since the last capture),
    `current` (the page captured last) and `rolls` (forced rollovers in this
    step). PER PAGE, because the 2026-09-23 loop rendered the same black
    index.html seven times with other pages in between; a page never
    captured before in this step is a changed approach and starts at zero.
    A `goal_step` 'done' clears it mid-turn, and `new_step` skips the turn
    up to that call -- the rules of `goal_trouble_scan`.

    #277: `seen` holds the capture paths already counted. The duplicate-call
    guard replays a result ("you already called render_page ..."), and a
    rollover carries the last ones across the cut; neither is a new capture,
    and a caller that scans from the payload's start after a mid-turn cut
    must not count them twice."""
    state = state if state is not None else {}
    state.setdefault("targets", {})
    state.setdefault("edits", [])
    state.setdefault("rolls", 0)
    state.setdefault("current", None)
    state.setdefault("seen", [])
    calls: dict = {}
    counting = not new_step
    for message in (messages or [])[max(0, start):]:
        role = message.get("role")
        if role == "assistant":
            for call in message.get("tool_calls") or []:
                fn = call.get("function") or {}
                calls[call.get("id")] = (fn.get("name") or "",
                                         fn.get("arguments") or "")
            continue
        if role != "tool":
            continue
        name, arguments = calls.get(message.get("tool_call_id"), ("", ""))
        try:
            args = json.loads(arguments or "{}")
        except ValueError:
            args = {}
        args = args if isinstance(args, dict) else {}
        if name == "goal_step":
            if args.get("status") == GOAL_DONE:
                state.update(targets={}, edits=[], current=None)
                counting = True
            continue
        if not counting:
            continue
        content = message.get("content")
        content = content if isinstance(content, str) else goal_message_text(message)
        if name in _RENDER_WRITES:
            path = str(canonical_arguments(name, args).get("path") or "")
            if path and not content.startswith("error") \
                    and path not in state["edits"]:
                state["edits"].append(path)
            continue
        if name != "render_page":
            continue
        target = str(args.get("path") or "")
        sig = render_signature(content, target)
        if sig is None or sig["path"] in state["seen"]:
            continue
        state["seen"] = (state["seen"] + [sig["path"]])[-_RENDER_SEEN_KEEP:]
        page = state["targets"].setdefault(
            target, {"last": None, "streak": 0, "tried": [], "said": 0})
        same = render_same(page["last"], sig)
        if sig["blank"] or same:
            if page["streak"] == 0:
                page["tried"] = []
                if same and not sig["blank"]:
                    page["streak"] = 1
                    page["tried"].append(_render_tried(page["last"], []))
            page["streak"] += 1
            page["tried"].append(_render_tried(sig, state["edits"]))
        else:
            page.update(streak=0, tried=[], said=0)
        page["last"] = sig
        state["edits"] = []
        state["current"] = target
    return state


def _render_page_state(state: "dict | None") -> "dict | None":
    """The per-page entry of the page captured last, or None."""
    if not state or state.get("current") is None:
        return None
    return (state.get("targets") or {}).get(state["current"])


def _render_tried(sig: dict, edits: "list[str]") -> str:
    verdict = sig.get("blank") or "same as the capture before"
    after = (" after writing %s" % ", ".join(edits[-4:])) if edits else ""
    return "%s: %s%s" % (os.path.basename(sig["path"]), verdict, after)


def goal_render_due(state: "dict | None") -> "str | None":
    """'roll', 'nudge' or None for the page captured last -- and marks it
    said. One forced roll per step; past it, the nudge again at every
    further multiple of three."""
    page = _render_page_state(state)
    if page is None:
        return None
    streak = page.get("streak", 0)
    if streak >= GOAL_RENDER_ROLL and not state.get("rolls"):
        state["rolls"] = state.get("rolls", 0) + 1
        page["said"] = streak
        return "roll"
    if streak >= GOAL_RENDER_NUDGE and streak // GOAL_RENDER_NUDGE \
            > page.get("said", 0) // GOAL_RENDER_NUDGE:
        page["said"] = streak
        return "nudge"
    return None


GOAL_BISECT = ("stop editing -- bisect: render a minimal probe (the clear "
               "colour only, then one lit cube), then re-enable the passes one "
               "by one and render after each; the pass that breaks the picture "
               "is the bug.")
# #277. A BLACK FRAME HAS NOTHING TO COMPARE AN EDIT AGAINST, so the probe
# must make the pipeline report on itself. The isolation order is the one
# LearnOpenGL's "Debugging" page teaches (a non-colour value written to the
# colour output; a framebuffer shown on screen), the checks are the two
# calls MDN names for a silent render target (getError's
# INVALID_FRAMEBUFFER_OPERATION, checkFramebufferStatus) plus a readback.
# Checks, not code: the model writes the probe its own way.
GOAL_BISECT_BLACK = ("stop editing -- the frame is black, so an edit has "
                     "nothing to be judged against. Make the pipeline report "
                     "on itself: render ONE pass in isolation straight to the "
                     "screen -- the albedo/base colour only, no lighting; then "
                     "the normals as colour; then the depth. After each draw "
                     "check gl.getError() and gl.checkFramebufferStatus(), "
                     "read a few pixels back with gl.readPixels, and log "
                     "those values to the console (render_page shows it). "
                     "The first pass that comes back black or reports an "
                     "error is the bug.")


def render_no_signal(sig: "dict | None") -> bool:
    """#277: does this capture show no picture at all -- near-black, blank,
    one colour -- rather than a picture that did not change?"""
    if not sig or not sig.get("blank"):
        return False
    luma = sig.get("luma")
    return (sig["blank"] != "byte-identical"
            or (luma is not None and luma <= _RENDER_DARK_LUMA))


def goal_render_nudge(step: int, state: dict, rolled: bool = False) -> str:
    """The nudge for a stuck streak; with `rolled`, the carry of the forced
    rollover, listing what was tried. `step` counts from 1."""
    page = _render_page_state(state) or {}
    tried, streak = page.get("tried") or [], page.get("streak", 0)
    where = os.path.basename(str(state.get("current") or "")) or "the page"
    black = render_no_signal(page.get("last"))                         # #277
    bisect = GOAL_BISECT_BLACK if black else GOAL_BISECT
    what = "showed no picture" if black else "came back the same"
    if not rolled:
        return ("%s, step %d: the last %d captures of %s %s "
                "(%s) -- %s]" % (GOAL_NUDGE_MARK, step, streak, where, what,
                         "; ".join(t.split(": ", 1)[-1].split(" after ")[0]
                                   for t in tried[-3:]), bisect))
    return ("%s, step %d: %d captures of %s in a row %s, so "
            "the context was cut to leave that loop behind. What was tried "
            "(Crow's record from the render_page results):\n%s\n"
            "Do not repeat these edits. %s]"
            % (GOAL_NUDGE_MARK, step, streak, where, what,
               "\n".join("- " + t for t in tried[-8:]),
               bisect[0].upper() + bisect[1:]))


def needs_approval(name: str, mode: str) -> bool:
    """Does this tool stop and ask at this level?

    An unknown tool is treated as `executing`: the strictest class, because a
    tool this table has not heard of is one nobody has classified yet, and
    guessing "safe" for it is the one guess with a cost.
    """
    return TOOL_CLASS.get(name, "executing") in MODE_ASKS.get(mode, ())


def stops_for(name: str, mode: str, outside: bool) -> bool:
    """Does this call stop and ask at this level? The ONE predicate the turn
    gate reads, so the three sources of a question cannot drift apart: the
    table (what the level holds back by class), the #144 outside-path
    question (carried by the call's own arguments), and #156's acts outside
    the table.

    ORDER IS THE CONTRACT. `publish` first, BEFORE the dial -- no level
    releases it, yolo included (the owner, 2026-09-19: NIEMALS). yolo next,
    because its whole point is that the other two sources go silent for the
    AFK run. Everything else reads the table exactly as it always has.
    """
    if TOOL_CLASS.get(name, "executing") in NEVER_RELEASED:
        return True
    if mode in RELEASES_ALL:
        return False
    return needs_approval(name, mode) or outside or always_asks(name)


def mode_description(mode: str) -> str:
    """What a level holds back, in a line that does NOT grow with the table.

    WRITTEN ONCE FOR BOTH SURFACES. Until 2026-08-24 the terminal and the window
    each built this sentence themselves, and both built it the same way: join
    every name that asks. That reads well for twelve built-in tools and breaks
    the moment a server arrives -- higgsfield contributes 73, so the window's
    level menu became ninety lines with no way to scan it, and the terminal
    printed the same wall on one line.

    THE BUILT-INS ARE NAMED AND THE REST IS COUNTED, which is the only shape
    that stays readable at any size. A person recognises `write_file`; nobody
    recognises the 41st name of a server they connected last week, and the
    place that lists those per tool -- with a switch beside each -- is the MCP
    sheet. Cloudflare's API server reports around 3,300 tools, so a menu that
    spells names out has no size at which it starts working again.
    """
    asks = [t for t in sorted(TOOL_IMPL) if needs_approval(t, mode)]
    if not asks:
        if mode in RELEASES_ALL:
            # THE GENERIC BUILDER WOULD LIE HERE. "Every tool runs unasked"
            # is true of the table and false of the gate: yolo keeps the
            # #144 outside-path question silent AND the git_push ask on
            # (the owner, 2026-09-19). One honest line, said the same way in
            # both surfaces.
            return ("every tool runs unasked -- outside paths and git commit "
                    "included; git_push still asks")
        return "every tool runs unasked"
    named = [t for t in asks if not t.startswith("mcp_")]
    served = len(asks) - len(named)
    counted = "%d MCP tool%s" % (served, "" if served == 1 else "s") if served else ""
    head = ", ".join(named)
    if head and counted:
        what = "%s and %s" % (head, counted)
    else:
        what = head or counted
    return "asks before %s" % what


# STANDING APPROVALS, per session and never written to disk. #88 point 3:
# "without a memory, manual is unusable -- a 24-round turn asks 24 times, and
# everyone switches to auto within two minutes". Cleared by new_session().
_ALLOWED: set[tuple[str, str]] = set()


def approval_scope(name: str, arguments: str) -> tuple[str, str] | None:
    """What one "always" covers -- and, more importantly, what it does NOT.

    A DIRECTORY FOR WRITES, A PROGRAM FOR COMMANDS. "Yes, and from now on"
    against `write_file C:/x/a.py` releases writes under `C:/x`, not writes
    everywhere; against `run_command git status` it releases `git`, not every
    command. The narrower the key, the less an "always" can widen into `auto`
    by accident -- which is the failure #88 asks for a test against.

    #156: `git_commit` AND `git_push` HAVE NO SCOPE, and that absence is the
    feature. None means `remembered` is always False and `remember` records
    nothing, so the two calls that write history and leave the machine ask
    every single time -- there is no answer a user can give that makes the
    next one silent. The card for them therefore shows no "always" button.

    None means this call cannot be remembered at all: unparseable arguments, a
    missing path, an empty command. Then every occurrence asks again, which is
    the safe direction for a case nobody has thought about.
    """
    try:
        args = json.loads(arguments or "{}")
    except json.JSONDecodeError:
        return None
    if not isinstance(args, dict):
        return None

    if name in ("write_file", "append_file", "edit_file"):
        path = canonical_arguments(name, args).get("path")   # #215
        if not isinstance(path, str) or not path.strip():
            return None
        return ("writing", os.path.dirname(os.path.abspath(path)).lower())

    if name == "run_command":
        command = args.get("command")
        if not isinstance(command, str) or not command.strip():
            return None
        # #144: an outside path narrows the key to the PATH, so an "always"
        # for `git` can never release `git` pointed outside the area -- and an
        # "always" for one outside path releases that path, not the program.
        cwd = args.get("cwd")
        outside = command_outside_paths(command, cwd if isinstance(cwd, str) and cwd else None)
        if outside:
            return ("outside", os.path.normcase(outside[0]))
        # The program, not the line: `git status` and `git log` share a key,
        # `git` and `rm` do not.
        return ("executing", command.split()[0].lower())

    # #212: one fixed program with a fixed argv, and its write is fenced by
    # the tool itself -- so an "always" can safely cover the tool, the way it
    # covers one program under run_command. Its own key: it never releases
    # `run_command esbuild ...` with arguments nobody saw.
    if name == "build_bundle":
        entry = args.get("entry")
        if not isinstance(entry, str) or not entry.strip():
            return None
        return ("executing", "build_bundle")

    return None


# The owner's Ansage vom 2026-08-28 spaetabends: "allowed, and from now on" hiess
# bis hierher "bis zum naechsten Chat" -- die Freigaben lebten im Prozess-Set
# und starben mit jedem /reset, jedem neuen Chat und jedem Fensterstart, und
# der Owner gab dieselben Vault-Pfade jede Sitzung neu frei. AB JETZT heisst
# "from now on" genau das: jede "always"-Entscheidung wird neben
# providers.json abgelegt und gilt, bis jemand sie aus der Datei nimmt.
#
# NUR WAS DER NUTZER KLICKTE steht darin: ein Scope entsteht ausschliesslich
# aus einer beantworteten Frage-Karte, und verschleierte Pfade haben keinen
# Scope (approval_scope: None) und landen nie hier. Die Datei ist von Hand
# editierbares JSON; eine unlesbare Datei liest sich als LEER und reisst das
# Tor nicht mit um -- read_root_mode's rule. Eine Dauer-Freigabe loeschen
# heisst: ihre Zeile aus der Datei nehmen.
APPROVALS_FILE = os.path.join(crow_platform.config_dir(), "approvals.json")
_STORED_APPROVALS: "set[tuple[str, str]] | None" = None


def _approvals_stored() -> "set[tuple[str, str]]":
    """The standing approvals: loaded once per process, refreshed on write."""
    global _STORED_APPROVALS
    if _STORED_APPROVALS is None:
        found: "set[tuple[str, str]]" = set()
        try:
            with open(APPROVALS_FILE, encoding="utf-8") as fh:
                raw = json.load(fh)
            for pair in (raw.get("allowed") or []):
                if isinstance(pair, list) and len(pair) == 2:
                    found.add((str(pair[0]), str(pair[1])))
        except (OSError, ValueError, AttributeError):
            found = set()
        _STORED_APPROVALS = found
    return _STORED_APPROVALS


def _approval_scopes(name: str, arguments: str) -> "list[tuple[str, str]] | None":
    """Every scope one call touches -- run_command with N outside paths has N.

    des Owners Live-Bild vom 2026-08-28 nachts: ein Kommando nannte Chrome, Edge
    UND Firefox, gemerkt wurde nur der erste Pfad -- die naechste Frage las
    sich als Vergessen. Und die Gegenrichtung war ein LOCH: remembered prüfte
    nur den ersten Pfad, ein fremder zweiter ritt auf dessen Freigabe durch.
    Eine Freigabe deckt ab jetzt ALLE Pfade der gezeigten Karte, und verlangt
    wird sie fuer jeden einzeln.
    """
    scope = approval_scope(name, arguments)
    if scope is None:
        return None
    if name == "run_command" and scope[0] == "outside":
        try:
            args = json.loads(arguments or "{}")
        except json.JSONDecodeError:
            return [scope]
        command = args.get("command") if isinstance(args, dict) else ""
        cwd = args.get("cwd") if isinstance(args, dict) else None
        outside = command_outside_paths(
            command if isinstance(command, str) else "",
            cwd if isinstance(cwd, str) and cwd else None)
        if outside:
            return [("outside", os.path.normcase(p)) for p in outside]
    return [scope]


def scope_from_a_store(scope: "tuple[str, str] | None") -> bool:
    """Did the assistant read this outside path out of a store, not derive it?

    #178, seen live 2026-08-31. For a step whose own text said "write a file
    only in this folder", the model's first attempt was a `run_command` into
    `%USERPROFILE%\\Desktop\\Test runs` -- a path out of the USER PROFILE
    block of the system prompt, named by nobody in the chat. The card asked, the
    answer was "and from now on", and the path stood in approvals.json for good.

    A PATH THE USER TYPED NEVER REACHES A CARD. `mandated_paths` reads user
    messages only, `run_command_boundary` filters what it finds, so every
    outside path on a card was picked by the assistant. What separates the
    ordinary case from this one is therefore not who typed it, but WHERE THE
    ASSISTANT GOT IT: a path derived from the work at hand is a guess that
    happens once, a path read out of a store is a standing invitation that comes
    back in every single turn -- and a permanent answer to it is a permanent
    answer to a question the model will keep asking.

    So a store path stays releasable for the session and is never written down.
    Refusing it outright would be the wrong trade: the model does reach for
    those paths for good reasons, and a card that cannot be answered at all
    turns into a wall in the middle of somebody's work.

    THE MATCH IS A SUBSTRING, AND THAT IS DELIBERATE UNTIL #179 IS FIXED. The
    precise rule would be to pull the paths out of the entry and ask `_inside`,
    so that a store path releases itself and what is under it and nothing else.
    Measured 2026-08-31 against the live profile: `_PATH_IN_TEXT` ends a path at
    the first space, so the entry `LP-50-Auftrag (%USERPROFILE%\\Desktop\\Test
    runs)` yields `%USERPROFILE%\\Desktop\\Test`, and `_inside` on that answers
    False for the very path this rule exists to catch. The precise version would
    silently switch the protection off.

    The price of the substring is over-reach in one direction: a PARENT of a
    store path (`%USERPROFILE%\\Desktop`) matches too and is likewise not
    written down. That errs toward asking again rather than toward a standing
    release, so it is the safe side of the trade -- but it is a side, not the
    intended rule, and it goes away with #179.
    """
    if not scope or scope[0] != "outside" or not scope[1]:
        return False
    where = os.path.normcase(scope[1])
    for path in (USER_PATH, memory_path()):
        if not path:
            continue
        for entry in read_store(path):
            if where in os.path.normcase(entry):
                return True
    return False


def remembered(name: str, arguments: str) -> bool:
    """Has the user said "always" for something covering this call -- in this
    chat, or written down in any earlier one (the standing store). EVERY
    scope the call touches must be covered; one released path carries no
    foreign second one through."""
    scopes = _approval_scopes(name, arguments)
    if not scopes:
        return False
    stored = _approvals_stored()
    return all(s in _ALLOWED or s in stored for s in scopes)


def remember(name: str, arguments: str) -> tuple[str, str] | None:
    """Record an "always" for every scope this call touches. Returns the
    first one -- the card's label -- or None for a call nobody can remember.

    WRITTEN THROUGH TO DISK (2026-08-28): "from now on" outlives the chat and
    the process, not just the turn -- see APPROVALS_FILE above. A write that
    fails leaves the session release standing, so the turn still proceeds.
    """
    scopes = _approval_scopes(name, arguments)
    if not scopes:
        return None
    stored = _approvals_stored()
    fresh = False
    for scope in scopes:
        _ALLOWED.add(scope)
        # #178. DIE SITZUNG JA, DIE PLATTE NEIN, fuer einen Pfad, den das Modell
        # aus einem Speicher gelesen hat -- siehe `scope_from_a_store`. Getrennt
        # wird hier und nicht schon in `_approval_scopes`, weil ein Kommando
        # beide Sorten nennen kann und der Speicherpfad dann die Freigabe des
        # anderen nicht mitnehmen darf.
        if scope_from_a_store(scope):
            continue
        if scope not in stored:
            stored.add(scope)
            fresh = True
    if fresh:
        try:
            with open(APPROVALS_FILE, "w", encoding="utf-8") as fh:
                json.dump({"format": 1, "allowed": sorted(stored)}, fh,
                          indent=1, ensure_ascii=False)
        except OSError:
            pass
    return scopes[0]


def forget_approvals() -> None:
    """Drop every standing approval. Called when the user drops the chat.

    NOT FROM Conversation.reset(), and the difference is the point. reset() also
    runs inside roll_over(): the context is archived and started again while the
    user carries on with the same work. Clearing there would ask again for the
    directory they released four rounds ago, mid-turn, for a reason invisible
    from where they sit. `/reset` and the window's new-chat button are the
    places a session actually ends, and they are what call this.

    THE STANDING STORE STAYS (2026-08-28, des Owners Ansage): dropping a chat ends
    the chat, not the user's written "from now on" decisions -- those live in
    APPROVALS_FILE until somebody removes them there.
    """
    _ALLOWED.clear()
    # #128: THE STAGED MEMORY WRITES GO WITH THEM, from in here rather than
    # from eight call sites. A write the review proposed belongs to the chat
    # that produced it exactly as much as a standing approval does, so the two
    # have one lifetime and one place that ends it. A second call beside each of
    # the eight would be eight chances to forget one, and the forgotten one
    # would carry a note out of a conversation the user has already dropped.
    forget_pending()
    # AND EVERY WAITING QUESTION, as `cancel`. A server blocked on an
    # answer from a conversation that has ended is a tool call hanging
    # until its own timeout, in a chat nobody is looking at.
    forget_asks()


# #128. THE MEMORY GATE -- what the background review wants to write, held back
# until a person says yes.
#
# WHY THIS IS NOT A `MODE_ASKS` CLASS. The three levels gate calls the MODEL
# makes inside a turn: `run_turn` reaches one, asks the surface through
# `approve`, and the user is sitting there because their answer is what the turn
# is waiting on. The review is the opposite case in every respect -- it runs
# BEHIND the visible end of the turn, `run_turn` does not know it exists, and
# `review_turn`'s own comment says why a question there is useless: "the user is
# not at the keyboard for a background pass, so a write or a shell command here
# would have nobody to refuse it".
#
# So this gate does not ask. It STAGES, and the surface raises a state the user
# meets whenever they next look. A question needs someone in the chair; a state
# waits.
#
# NOTHING IS EVER WRITTEN BY A TIMER, and that is the difference between a gate
# and a delay. An entry nobody approves EXPIRES and is dropped. Expiry has to
# fall on the side of not writing, or the gate is a speed bump.
#
# ON BY DEFAULT (the owner, 2026-08-22), against this file's own precedent, and the
# reason the precedent loses here. `DEFAULT_MODE` is `auto` because every
# release before it ran the tools unasked and a commit that adds a CHOICE must
# not change what an existing session does -- a good rule, and it was the first
# answer here too. It does not hold for this one: a gate that ships off is not a
# gate, it is a setting nobody finds. What it guards is the one writer in this
# client that runs with nobody at the keyboard and writes into the head of every
# later session, and the whole reason it exists is that "the review writes
# unasked" was the behaviour worth changing. `--no-memory-approval` is one word
# away for anyone who wants the old shape back.
MEMORY_APPROVAL_DEFAULT = True

# How long a staged entry waits. Hermes uses 300 s for elicitation and the
# reasoning transfers: long enough that an answer noticed on the way back from
# the kettle still counts, short enough that a note nobody looked at does not
# surface days later out of a conversation that has since ended.
#
# CHECKED WHEN SOMEBODY LOOKS, NOT BY A THREAD. A timer would be a second thing
# in this client that can write to memory, and the entire point of the gate is
# that there is exactly one.
PENDING_TTL = 300.0

# Per session, never written to disk -- the same shape and the same reason as
# `_ALLOWED` above. A staged write that survived a restart would be a decision
# the user made in a conversation they have already forgotten.
_PENDING: "list[dict]" = []
_PENDING_SEQ = 0

# #285. WHAT EXPIRED, KEPT ASIDE UNTIL SOMEBODY ANSWERS. Dropping an expired
# entry on the read is right -- it must never run -- but dropping it without a
# trace made a late "save" approve nothing and say nothing. The entry still
# never runs; it only stays nameable, so the answer can say it came too late.
_EXPIRED: "list[dict]" = []


def _pending_summary(name: str, arguments: str) -> str:
    """One line naming what WOULD be written, in the note's words not the API's.

    THE CONTENT, NOT THE CALL. `memory(action=add, target=memory)` is a
    keystroke; the sentence that would stand in the head of every later session
    is a decision. Same reasoning that put the arguments into the terminal's
    approval prompt (#88 point 2) -- a prompt that does not show what it
    releases is not a question.
    """
    try:
        args = json.loads(arguments or "{}")
    except (json.JSONDecodeError, AttributeError):
        args = {}
    if not isinstance(args, dict):
        args = {}
    action = str(args.get("action") or "?")
    where = str(args.get("target") or args.get("name") or name)
    body = args.get("content") or args.get("old_text") or args.get("description") or ""
    body = " ".join(str(body).split())
    if len(body) > 160:
        body = body[:157] + "..."
    return "%s %s: %s" % (action, where, body) if body else "%s %s" % (action, where)


def stage_memory(name: str, arguments: str) -> dict:
    """Hold one write until a person answers. Returns the staged entry."""
    global _PENDING_SEQ
    _PENDING_SEQ += 1
    try:
        args = json.loads(arguments or "{}")
        action = str((args or {}).get("action") or "add")
    except (json.JSONDecodeError, AttributeError):
        action = "add"
    entry = {"id": _PENDING_SEQ, "name": name, "arguments": arguments,
             # #128. THE ACTION IS CARRIED SEPARATELY from the summary, because
             # the window counts with it: `add` is a line gained, `remove` a
             # line lost, `replace` is both at once. A surface that had to parse
             # that back out of the summary string would be reading its own
             # prose, and the prose is for people.
             "action": action,
             "summary": _pending_summary(name, arguments),
             "staged": time.monotonic()}
    _PENDING.append(entry)
    return entry


def pending_memory() -> "list[dict]":
    """What is still waiting.

    EXPIRED ENTRIES ARE DROPPED HERE, on the read, and therefore never run. Any
    caller that is about to show the state or act on it passes through this
    function first, so there is no path on which an expired write survives long
    enough to be approved.
    """
    now = time.monotonic()
    _EXPIRED.extend(e for e in _PENDING if now - e["staged"] >= PENDING_TTL)
    _PENDING[:] = [e for e in _PENDING if now - e["staged"] < PENDING_TTL]
    return list(_PENDING)


def _pending_args(entry: dict) -> dict:
    """The staged arguments as a dict; anything unreadable is an empty one."""
    try:
        args = json.loads(entry.get("arguments") or "{}")
    except (json.JSONDecodeError, AttributeError, TypeError):
        return {}
    return args if isinstance(args, dict) else {}


def _pending_old(entry: dict, args: dict) -> "str | None":
    """#285. The whole entry a `replace`/`remove` would hit, READ, NEVER WRITTEN.

    The same match `tool_memory` makes -- `old_text` inside exactly one entry
    -- so the tile names the entry the write will actually take out. None when
    there is no single match: then the write will fail, and the approval says
    so; guessing an entry here would show a removal that will not happen.
    """
    if entry.get("name") != "memory" or not args.get("old_text"):
        return None
    target = str(args.get("target") or "memory")
    if target not in MEMORY_TARGETS:
        return None
    try:
        path = _store(target)[0]
        hits = [e for e in read_store(path) if str(args["old_text"]) in e] if path else []
    except Exception:                       # noqa: BLE001 - a preview never breaks the tile
        return None
    return hits[0] if len(hits) == 1 else None


def pending_view() -> "list[dict]":
    """What the surfaces draw: the action and the text, nothing else.

    ONE SHAPE FOR BOTH SURFACES and neither of them reaches into the entry. The
    window counts lines gained and lost off `action`; the terminal prints
    `text`. `arguments`, `id` and the staged clock are this module's business.

    #285. `text` STAYS THE 160-CHAR PREVIEW; `full` is the untruncated body and
    `old` the whole entry a replace or remove takes out, looked up now. The owner
    could not tell an append from a swap in the middle of the file, because the
    preview showed only the new words and cut those. `find` is the `old_text`
    itself, for the case where no single entry matches it.
    """
    out = []
    for e in pending_memory():
        args = _pending_args(e)
        row = {"action": e["action"], "text": e["summary"],
               "full": str(args.get("content") or args.get("description") or "")}
        if e["action"] in ("replace", "remove"):
            row["old"] = _pending_old(e, args)
            row["find"] = str(args.get("old_text") or "")
        out.append(row)
    return out


def _pending_clip(text: str, n: int = 120) -> str:
    """One line, at most `n` characters -- for a reason, not for the entry."""
    text = " ".join(str(text).split())
    return text if len(text) <= n else text[:n - 3] + "..."


def _pending_failure(result: dict) -> "str | None":
    """#285. Why one approved write did not land, shortened; None if it did.

    A SUCCESS WITHOUT AN ACTION IS NOT A SAVE. `tool_memory` answers a
    duplicate with success -- the wanted state is already the state -- and
    that is right for the model; for the person who pressed save, nothing was
    written, and the reason is the one thing worth telling them.
    """
    if result.get("success") and result.get("action"):
        return None
    if result.get("success"):
        return ("already in memory" if result.get("note") == "no duplicate added"
                else _pending_clip(result.get("note") or "nothing changed"))
    error = str(result.get("error") or "failed")
    if "exceed the limit" in error:
        usage = str(result.get("usage") or "")
        if "/" in usage:
            used, limit = usage.split("/", 1)
            return "over the %s-char limit (%s used)" % (limit, used)
        return "over the limit"
    return _pending_clip(error)


def approve_pending(ident: "int | None" = None) -> "tuple[list[str], list[dict]]":
    """Run what was staged. `None` means all of it. Returns (saved, failed).

    THE SAME `run_tool` THE REVIEW WOULD HAVE CALLED. An approved write and an
    ungated write are one code path, so the character cap, the duplicate check
    and the injection scan all still answer -- the gate adds a question, it does
    not add a second way to write.

    #285. EVERY ENTRY GETS AN OUTCOME. `failed` holds one {"what", "why"} per
    entry that did not land: the tool's refusal, shortened, or the expiry. The
    old version swallowed both -- the owner pressed save, the file stayed as it was
    and the window said nothing. A write that did not happen is announced as
    surely as one that did, and the same line goes to crow.log.
    """
    ready = [e for e in pending_memory() if ident is None or e["id"] == ident]
    late = [e for e in _EXPIRED if ident is None or e["id"] == ident]
    saved: "list[str]" = []
    failed: "list[dict]" = []
    for entry in late:
        _EXPIRED.remove(entry)
        failed.append({"what": entry["summary"],
                       "why": "expired after %d min" % (PENDING_TTL // 60)})
    for entry in ready:
        _PENDING.remove(entry)
        try:
            result = json.loads(run_tool(entry["name"], entry["arguments"]))
            if not isinstance(result, dict):
                raise ValueError("not a JSON object")
        except Exception as exc:            # noqa: BLE001 - reported, not raised
            failed.append({"what": entry["summary"], "why": _pending_clip("failed: %s" % exc)})
            continue
        why = _pending_failure(result)
        if why:
            failed.append({"what": entry["summary"], "why": why})
            continue
        saved.append("%s %s" % (result["action"],
                                result.get("target") or result.get("name")
                                or entry["name"]))
    for miss in failed:
        log_note("not saved (%s): %s" % (miss["why"], miss["what"]), "memory")
    return saved, failed


def pending_failed_note(failed: "list[dict]") -> str:
    """#285. The one line both surfaces show for writes that did not land.

    THE REASON FIRST, the entry after it, cut short: the person needs to know
    why before which, and the full text is in crow.log. Empty for an empty
    list, so a caller can test the string.
    """
    if not failed:
        return ""
    return "Memory: not saved -- " + " / ".join(
        "%s (%s)" % (f["why"], _pending_clip(f["what"], 60)) for f in failed)


def decline_pending(ident: "int | None" = None) -> int:
    """Drop what was staged, writing nothing. `None` means all of it."""
    doomed = [e for e in pending_memory() if ident is None or e["id"] == ident]
    for entry in doomed:
        _PENDING.remove(entry)
    # #285. A "no" answers the expired ones too; they were never going to run.
    _EXPIRED[:] = [e for e in _EXPIRED if ident is not None and e["id"] != ident]
    return len(doomed)


def forget_pending() -> None:
    """Drop every staged write. Called where `forget_approvals` is called, and
    for the same reason: `/reset` and the window's new-chat button are where a
    session actually ends."""
    _PENDING.clear()
    _EXPIRED.clear()


# ---------------------------------------------------------------- E6 ------
# ELICITATION: THE SERVER ASKS, A PERSON ANSWERS, AND THE SERVER NEVER DRAWS.
#
# This was refused outright until 2026-08-22, and the reason was real: it is the
# only place in the protocol where a foreign server puts words in front of a
# human who then acts on them. What changed is that the risk turned out to be
# SEPARABLE, and Hermes had already separated it -- form mode through the
# client's own approval surface, URL mode declined as unsupported.
#
# THE SPLIT IS THE WHOLE DESIGN:
#
#   * what the server sends is a SCHEMA, not a rendering. Crow draws the fields
#     from `requestedSchema` itself, so there is no markup, no link and no
#     button that came off the wire;
#   * the subset is deliberately tiny -- a flat object of primitives. Anything
#     nested, an array, a `$ref`, a URL mode, or a schema with no properties at
#     all is DECLINED with a reason. That refusal is what covers every future
#     mode nobody has read yet;
#   * every string that reaches a screen goes through the tag filter first, the
#     same one tool descriptions get;
#   * the answer is validated against the schema the person was shown, so a
#     server cannot get back a field it never asked for.
#
# AND IT BLOCKS, on purpose. The tool call that triggered it is waiting, the
# server is waiting, and the person is the only one who can move it. That is the
# opposite of the OAuth rule one file above -- and the difference is consent:
# nobody asked for a browser mid-turn, and this server was asked to do something
# by the model in this very turn.

# The five shapes a field may have. A `format` is read and then ignored: it is a
# hint for a nicer input, never a reason to refuse a schema.
ELICIT_TYPES = ("string", "number", "integer", "boolean")

# How many fields a form may carry. A server that wants more than this is not
# asking a question, it is handing over a configuration screen -- and a screen
# nobody reads is a screen everybody confirms.
ELICIT_FIELDS = 12

# Seconds a question stands. Hermes uses 300 and the reasoning transfers: long
# enough that somebody coming back to the machine still answers it, short enough
# that a tool call does not hang for an afternoon. A timeout is `cancel`, which
# the specification defines as dismissed without a choice -- and it is NOT
# `decline`, because the person never said no.
ELICIT_TTL = 300.0

_ASKS: "list[dict]" = []
_ASKS_SEQ = 0
_ASKS_LOCK = threading.Lock()

# What a surface installs so it can draw the question the moment it is asked.
# ONE PLUG PER SURFACE AND NO SECOND GATE: the core still owns the staging, the
# waiting, the validation and the answer. This only says "somebody is asking
# now", because a terminal has to prompt in line and a window has to push.
ELICIT_ANNOUNCE = None


def elicit_fields(schema) -> "tuple[list, str | None]":
    """The restricted subset out of `requestedSchema`, or why it is refused.

    THE REFUSAL IS THE SECURITY BOUNDARY, not the parsing. Everything this
    function does not understand is declined by name -- which is how a mode that
    does not exist yet, a nested object that would need a layout, and a `$ref`
    that would need fetching all end up in the same safe place.
    """
    if not isinstance(schema, dict):
        return [], "the server sent no requestedSchema"
    if schema.get("type") != "object":
        return [], ("this client answers a flat object of primitives, and that "
                    "schema is %r" % strip_tag_characters(str(schema.get("type")))[:40])
    properties = schema.get("properties")
    if not isinstance(properties, dict) or not properties:
        return [], "that schema asks for nothing"
    if len(properties) > ELICIT_FIELDS:
        return [], ("that schema asks for %d values, and this client draws at "
                    "most %d" % (len(properties), ELICIT_FIELDS))
    required = schema.get("required")
    required = [str(r) for r in required] if isinstance(required, list) else []

    fields = []
    for name in properties:
        spec = properties[name]
        if not isinstance(spec, dict):
            return [], "the field %r has no description" % strip_tag_characters(str(name))[:40]
        kind = spec.get("type")
        if kind not in ELICIT_TYPES:
            return [], ("the field %r is a %r, and this client answers only %s"
                        % (strip_tag_characters(str(name))[:40],
                           strip_tag_characters(str(kind))[:40],
                           ", ".join(ELICIT_TYPES)))
        # AN ENUM IS A LIST OF STRINGS AND NOTHING ELSE. A number enum would
        # render fine and come back as text, and the mismatch would be the
        # server's problem to discover at the worst moment.
        choices = spec.get("enum")
        if choices is not None:
            if (kind != "string" or not isinstance(choices, list) or not choices
                    or not all(isinstance(c, str) for c in choices)):
                return [], ("the field %r offers choices this client cannot draw"
                            % strip_tag_characters(str(name))[:40])
            choices = [strip_tag_characters(c)[:80] for c in choices][:ELICIT_FIELDS * 2]
        fields.append({
            "name": str(name),
            "type": kind,
            # EVERY STRING THROUGH THE FILTER. A title is prompt-head text
            # written by a stranger exactly as a tool description is, except
            # this one is read by a person rather than a model.
            "title": strip_tag_characters(str(spec.get("title") or name))[:80],
            "description": strip_tag_characters(str(spec.get("description") or ""))[:200],
            "enum": choices,
            "required": str(name) in required,
        })
    return fields, None


def stage_elicitation(server: str, message: str, fields: list) -> dict:
    """Hold one question until a person answers it."""
    global _ASKS_SEQ
    with _ASKS_LOCK:
        _ASKS_SEQ += 1
        entry = {"id": _ASKS_SEQ, "server": server, "message": message,
                 "fields": fields, "staged": time.monotonic(),
                 "action": None, "content": None,
                 "answered": threading.Event()}
        _ASKS.append(entry)
    return entry


def pending_asks() -> "list[dict]":
    """What is still being asked. Expired questions are dropped on the read, the
    same construction `pending_memory` uses and for the same reason."""
    now = time.monotonic()
    with _ASKS_LOCK:
        _ASKS[:] = [e for e in _ASKS if now - e["staged"] < ELICIT_TTL]
        return list(_ASKS)


def elicit_view() -> "list[dict]":
    """What the surfaces draw. ONE SHAPE FOR BOTH, and neither reaches into the
    entry: the event and the clock are this module's business."""
    return [{"id": e["id"], "server": e["server"], "message": e["message"],
             "fields": e["fields"]} for e in pending_asks()]


def _elicit_value(field: dict, given):
    """One answer, coerced to the type the person was shown, or `None`.

    STRICT, BECAUSE THE SERVER TRUSTS THIS. It declared a boolean; handing it
    the string "false" -- which is true in most languages that will read it --
    is worse than handing it nothing.
    """
    kind = field["type"]
    if kind == "boolean":
        if isinstance(given, bool):
            return given
        if isinstance(given, str) and given.strip().lower() in ("true", "false"):
            return given.strip().lower() == "true"
        return None
    if kind in ("number", "integer"):
        try:
            number = float(str(given).strip())
        except (TypeError, ValueError):
            return None
        if kind == "integer":
            return int(number) if number == int(number) else None
        return number
    text = "" if given is None else str(given)
    if field.get("enum") is not None and text not in field["enum"]:
        return None
    return text


def answer_elicitation(ident: int, action: str, content=None) -> "str | None":
    """What a person decided, checked against the schema they were shown.

    THE SERVER GETS BACK ONLY WHAT IT ASKED FOR. A surface that passed extra
    keys through would let whatever filled that form reach a foreign process,
    and the form is the one thing on screen a stranger wrote the labels for.
    """
    if action not in ("accept", "decline", "cancel"):
        return "%r is not accept, decline or cancel" % strip_tag_characters(str(action))[:40]
    entry = next((e for e in pending_asks() if e["id"] == ident), None)
    if entry is None:
        return "that question is no longer waiting"

    kept = {}
    if action == "accept":
        given = content if isinstance(content, dict) else {}
        for field in entry["fields"]:
            raw = given.get(field["name"])
            # ABSENT AND WRONG ARE NOT THE SAME ANSWER. An optional field left
            # empty is a decision and travels as nothing; a field somebody
            # filled in with something the schema does not allow is a mistake,
            # and dropping it silently would send the server a form that looks
            # like it was answered.
            if raw is None or (isinstance(raw, str) and not raw.strip()):
                if field["required"]:
                    return "%s is needed" % field["title"]
                continue
            value = _elicit_value(field, raw)
            if value is None:
                if field.get("enum") is not None:
                    return "%s must be one of: %s" % (field["title"],
                                                      ", ".join(field["enum"]))
                return "%s is not a %s" % (field["title"], field["type"])
            kept[field["name"]] = value

    with _ASKS_LOCK:
        if entry in _ASKS:
            _ASKS.remove(entry)
    entry["action"] = action
    entry["content"] = kept
    entry["answered"].set()
    return None


def forget_asks() -> None:
    """Release every waiting question as `cancel`. Called where the session
    ends, because a server blocked on an answer nobody will ever give is a tool
    call that hangs until its own timeout."""
    with _ASKS_LOCK:
        waiting, _ASKS[:] = list(_ASKS), []
    for entry in waiting:
        entry["action"] = "cancel"
        entry["content"] = {}
        entry["answered"].set()


# What has already been asked this turn, and what came back. Cleared per user
# turn, not per round.
#
# THE KEY IS NOT (name, arguments) FOR EVERY TOOL -- see `_cache_key`. That pair
# is the whole input only where the answer is a function of the arguments, and
# #93 is the run where it was not.
_SEEN: dict[tuple, str] = {}


# #93. The two tools whose result is NOT a function of their arguments alone.
#
# MEASURED 2026-08-14, in the run that closed #55: `write_file` was refused for
# want of a read, `read_file` supplied it, and the identical `write_file` came
# back as a repeat carrying the OLD REFUSAL -- three times, until the model gave
# up and reached for `edit_file` instead. In the same turn a `run_command` after
# an `edit_file` on the same file replayed the output from before the edit, and
# the model escaped by appending `2>&1` to change the key rather than the
# command. 4 of that turn's 12 calls were replays of a state that had moved.
#
# THE FIX IS NOT TO RECOGNISE REFUSAL TEXT. A cache keyed on less than its
# inputs is wrong whatever the text says, so the inputs go into the key:
#
#   run_command           depends on everything a shell can reach -> never cached
#   write_file/edit_file  depend on `_READ` -> the key carries the path's read
#                         state (#215-H: unread, or the stamp and whether the
#                         disk still matches it), so a read between two
#                         identical calls IS a different call, and so is an
#                         edit of crow's own -- it moved the stamp
#   everything else       is a function of its arguments -> keyed as before
#
# That last line is what keeps the 2026-08-09 loop closed: it happened on
# `read_file` for a path that did not exist, and a path does not start existing
# because it was asked for twice.
# #120 PUTS `memory` HERE, and it is the same reason `run_command` is: the
# result is not a function of the arguments. `add` the same entry twice must be
# able to answer "no duplicate" the second time, and `remove` then `add` of one
# entry are two identical calls with two different correct answers. Answering
# the second from the first would turn a correction into a silent no-op.
# #156: EVERY GIT CALL IS `run_command`'S CASE. The repository moves BECAUSE of
# the calls in this list -- status, commit, status again is the ordinary shape
# of one turn, and answering the second status from the first would report the
# working tree as it stood before the commit the model just made. `github_connect`
# is here for the same reason in time rather than in state: the answer changes
# the moment somebody types the code on github.com.
# #212: `build_bundle` is #93's run_command-after-edit_file case exactly. Edit a
# source, build again with the same arguments -- the ordinary loop -- and a
# cached answer would report the bundle from before the fix.
# #273: `render_page` is the same loop with a picture. 2026-09-24, session.json
# msg 72/74/76: edit `work/iso-test.html`, render it with the same arguments,
# and the answer was the capture from BEFORE the edit under "The result was,
# and still is:" -- the model then saved "render_page DEDUPES an identical
# (path,width,height) triple" to memory. A missing page still stops at
# RETRY_CAP, and #175's byte-identical check still names a frozen canvas.
NEVER_CACHED = frozenset({"run_command", "memory", "skill",
                          "git_status", "git_diff", "git_log",
                          "git_commit", "git_push", "github_connect",
                          "build_bundle", "render_page",
                          # #300 phase 3: two calls with one prompt are two
                          # pictures (a random seed each), never a replay.
                          "generate_image", "edit_image", "animate_image"})
READ_GATED = frozenset({"write_file", "edit_file"})


def _cache_key(name: str, arguments: str) -> tuple | None:
    """What this call's result depends on, or None when it depends on too much.

    None means "do not cache", NOT "cache miss": the caller must not write the
    result back either, or the next identical call is answered from a key that
    was never a promise about anything.
    """
    # EVERY MCP TOOL IS `run_command`'S CASE, and it is not in the set above
    # because the set cannot hold it: the names arrive from `mcp.json` at import,
    # `NEVER_CACHED` is a frozenset, and rebinding it would leave any module
    # that imported the VALUE holding the old one. A prefix test also holds for a
    # server added after this line was written, which a list would not.
    #
    # The reason is the one `run_command` carries: the result is not a function
    # of the arguments. A foreign process asked the same thing twice may answer
    # twice on purpose -- creating one issue and then a second one is two calls --
    # and answering the second from the first is a write the model is told
    # happened while nothing did.
    if name in NEVER_CACHED or name.startswith("mcp_"):
        return None
    if name not in READ_GATED:
        return (name, arguments)
    try:
        args = json.loads(arguments or "{}")
    except json.JSONDecodeError:
        args = None
    # #215: read under the name the handler will see, or a
    # `file_path` call keys as never-read forever and replays its refusal
    # after the read that should have lifted it.
    path = canonical_arguments(name, args).get("path") if isinstance(args, dict) else None
    # A call whose path is missing or not a string cannot have been read, and it
    # is about to fail on its arguments -- which IS a function of its arguments,
    # so caching it under `("unread",)` is correct rather than a fallback.
    seen = _read_state(path) if isinstance(path, str) else ("unread",)
    return (name, arguments, seen)


def run_tool_cached(name: str, arguments: str) -> tuple[str, bool]:
    """Run a tool, unless this exact call was already made. Returns (result, repeated).

    THE LOOP THIS PREVENTS, observed 2026-08-09: the model asked for
    `server-context.c` -- a file that does not exist, the real one ends in .cpp --
    got an error, and asked for the same path again. Eight times, twice within a
    single round. Each attempt cost a prefill of the error text, so the run spent
    minutes going nowhere and would have hit the round limit rather than an answer.

    Re-running would produce the identical failure, so the second call is answered
    from the first and told plainly that it is a repeat. That turns a loop into a
    fact the model has to react to.

    THAT SENTENCE IS TRUE ONLY WHERE THE RESULT IS A FUNCTION OF THE ARGUMENTS,
    and for two of the seven tools it is not. `_cache_key` is where that is
    decided and why; #93 carries the turn in which it was measured.
    """
    key = _cache_key(name, arguments)
    if key is not None and key in _SEEN:
        return _with_background_notes(
            f"[you already called {name} with these exact arguments this turn. "
            f"The result was, and still is:]\n{_SEEN[key]}"), True
    out = run_tool(name, arguments)
    if key is not None:
        _SEEN[key] = out
    # #309: what a job left in the background did since, beside -- never
    # inside -- the cached answer.
    return _with_background_notes(out), False


# ---------------------------------------------------------------- #196 -----
# WAS NICHT SEINE DEKLARIERTE FORM HAT, ERREICHT DEN HANDLER NICHT. Dies ist die
# einzige Stelle, an der ein Werkzeugaufruf die DEKLARATION und die ARGUMENTE
# zugleich sieht, also die einzige, an der der Vergleich ueberhaupt moeglich ist.
#
# EIN PARSE-VERSUCH, NICHT ZWEI. Ein `array` oder `object`, das als String
# ankommt, ist fast immer doppelt verpacktes JSON -- ein Vertipper des Modells,
# kein Irrtum ueber die Absicht, und er wird still ausgepackt. Was sich nicht
# auspacken laesst, wird zum Fehler an das Modell statt zu einem Wert, den ein
# Handler dann Zeichen fuer Zeichen durchlaeuft (852 davon, am 2026-09-18).
_ARGUMENT_SHAPES = {"array": list, "object": dict}


def _declared_properties(name: str) -> dict:
    """Die deklarierten Parameter eines Werkzeugs. `{}` fuer einen Namen, den
    niemand deklariert hat -- MCP-Namen kommen aus `mcp.json` und stehen in
    `TOOLS`, ein unbekannter bekommt einfach keine Pruefung statt einen Fehler."""
    for entry in TOOLS:
        function = entry.get("function") or {}
        if function.get("name") == name:
            return (function.get("parameters") or {}).get("properties") or {}
    return {}


def _declared_required(name: str) -> list:
    """Die Pflichtschluessel eines Werkzeugs, in der deklarierten Reihenfolge.
    `[]` fuer einen unbekannten Namen -- dieselbe Nachsicht wie oben."""
    for entry in TOOLS:
        function = entry.get("function") or {}
        if function.get("name") == name:
            required = (function.get("parameters") or {}).get("required")
            return list(required) if isinstance(required, list) else []
    return []


def _shape_phrase(spec: dict) -> str:
    """"a JSON array of strings" -- die deklarierte Form, wie ein Fehler sie nennt."""
    if spec.get("type") == "object":
        return "a JSON object"
    items = (spec.get("items") or {}).get("type")
    return "a JSON array of %ss" % items if items else "a JSON array"


def coerce_declared_containers(name: str, args: dict) -> "tuple[str | None, list[str]]":
    """Packt deklarierte Container aus, die als String ankamen. (Fehler, Noten)."""
    notes = []
    for key, spec in _declared_properties(name).items():
        if not isinstance(spec, dict):
            continue
        want = _ARGUMENT_SHAPES.get(spec.get("type"))
        if want is None or not isinstance(args.get(key), str):
            continue
        try:
            parsed = json.loads(args[key])
        except (json.JSONDecodeError, ValueError) as exc:
            return ("%s must be %s, got a string that is not valid JSON: %s"
                    % (key, _shape_phrase(spec), exc)), notes
        if not isinstance(parsed, want):
            return ("%s must be %s, got a string holding %s"
                    % (key, _shape_phrase(spec), type(parsed).__name__)), notes
        args[key] = parsed
        notes.append("%s arrived as a JSON string and was parsed into %s"
                     % (key, _shape_phrase(spec)))
    return None, notes


# ---------------------------------------------------- #215 -----
# A SIBLING SCHEMA'S NAME IS TAKEN, AND SAID. After the rollover of 2026-09-22
# the model wrote edit_file as the edit tool it was trained on -- 22 of 22
# calls with `old_string`/`new_string`, Claude Code's names -- and #207's note
# ("unknown argument(s) ignored") told it so 22 times without it ever changing
# the call. The names are not a misunderstanding of intent: the value under
# `old_string` IS the old text, and refusing it only buys rounds.
#
# A DECLARED TABLE, NOT A FUZZY MATCH. Every entry is a name a major harness
# documents for the same argument (Claude Code: file_path/old_string/
# new_string; Anthropic's and OpenHands' text editor: old_str/new_str/
# file_text; grep, ripgrep and Claude Code's Grep/Glob: path for the search
# root) or one measured in a crow transcript (`new_text` on memory, twice).
# A name nobody declared stays #207's business: ignored and said, and when a
# required argument is missing with it, the signature is the answer and
# nothing runs (#214, below in run_tool).
#
# SAID, NOT SWALLOWED -- the #207 rule holds. Every mapping puts one bracket
# note ahead of the result ("[took old_string as old]"), so the model sees
# the real name on the call that worked. Two names for one argument with
# DIFFERENT values is an error, not a pick: there is no right one to guess.
ARGUMENT_ALIASES: dict = {
    "read_file":   {"file_path": "path"},
    "write_file":  {"file_path": "path", "file_text": "content"},
    "append_file": {"file_path": "path"},
    "edit_file":   {"file_path": "path",
                    "old_string": "old", "old_str": "old",
                    "new_string": "new", "new_str": "new"},
    "search_text": {"path": "root"},
    "find_files":  {"path": "root"},
    "memory":      {"new_text": "content"},
}


def resolve_argument_aliases(name: str, args: dict) -> "tuple[str | None, list[str]]":
    """Renames declared sibling names in place. (Error, notes) -- the error
    names both keys when they disagree, and then nothing has been renamed
    that the caller would act on: the call does not run."""
    table = ARGUMENT_ALIASES.get(name) or {}
    origin: dict = {}                               # canonical -> key it came from
    taken, same = [], []
    for alias, canonical in table.items():
        if alias not in args:
            continue
        value = args.pop(alias)
        if canonical in args:
            seen = origin.get(canonical, canonical)
            if args[canonical] != value:
                return ("%s and %s both given with different values -- %s is "
                        "one argument, send it once as %s"
                        % (seen, alias, canonical, canonical)), []
            same.append(alias)
            continue
        args[canonical] = value
        origin[canonical] = alias
        taken.append("%s as %s" % (alias, canonical))
    notes = []
    if taken:
        notes.append("took %s" % ", ".join(taken))
    if same:
        notes.append("dropped %s, the same value as its declared name"
                     % ", ".join(same))
    return None, notes


def canonical_arguments(name: str, args: dict) -> dict:
    """The arguments as the handler will see them, for the readers that look
    at a call without running it -- the repeat cache, the approval key,
    /verify. A copy; a conflict leaves them as sent, and run_tool refuses it."""
    copy = dict(args)
    bad, _notes = resolve_argument_aliases(name, copy)
    return dict(args) if bad else copy


def run_tool(name: str, arguments: str) -> str:
    """Execute one tool call and return what the model gets back.

    EVERY FAILURE IS A RESULT, NOT AN EXCEPTION. A tool that raises kills the
    turn and costs the whole prefix; a tool that returns "no such file" lets the
    model correct itself in the next round. At ~10 tok/s a lost turn is minutes,
    so the difference is not cosmetic.
    """
    try:
        args = json.loads(arguments or "{}")
    except json.JSONDecodeError:
        return f"error: arguments were not valid JSON: {arguments[:200]}"
    if not isinstance(args, dict):
        return f"error: arguments must be a JSON object, got {type(args).__name__}"

    impl = TOOL_IMPL.get(name)
    if impl is None:
        return f"error: no tool named {name!r}. Available: {', '.join(sorted(TOOL_IMPL))}"
    bad, taken = resolve_argument_aliases(name, args)
    if bad is not None:
        return f"error: wrong arguments for {name}: {bad}"
    bad, notes = coerce_declared_containers(name, args)
    if bad is not None:
        return f"error: {bad}"
    notes = taken + notes
    # #207. UNKNOWN KEYS ARE SAID, NOT SWALLOWED. The live incident rode in on
    # `search_text` arguments carrying `pattern`, `pattern_2: "placeholder"`
    # and `regex` -- three keys for one argument, two of them declared by no
    # tool, and `**_` absorbed both without a trace. The corruption stayed
    # invisible on every surface until the session transcript was read by
    # hand. One bracket note, the same shape as the coercion notes, makes it a
    # fact the model and the screen both see; no declaration, no note.
    declared = _declared_properties(name)
    extra = sorted(k for k in args if k not in declared)
    # #214. UNBEKANNT UND FEHLEND ZUGLEICH IST KEIN
    # STOWAWAY, SONDERN EIN FALSCHER NAME -- und dann laeuft nichts. Gemessen
    # in der Sitzung des Owners vom 2026-09-22 nach dem Schnitt um 17:12: 22 von 22
    # `edit_file`-Aufrufen kamen mit `old_string`/`new_string` (der Name eines
    # anderen Harness), 22 von 22 scheiterten, keiner korrigierte sich. 15 der
    # 22 Antworten sagten zuerst "read ... before editing it" -- die
    # Lese-Sperre im Werkzeug lief VOR jeder Pruefung der Argumente, also las
    # das Modell brav und schickte dieselben falschen Schluessel noch einmal.
    # Die Note oben stand zwar davor, nannte aber nur, was ignoriert wurde,
    # nicht, wie es richtig heisst. Hier steht die Signatur im Fehler, vor
    # dem Werkzeug und vor seiner Sperre -- dieselbe Form, in der Claude Code
    # ein Schema-Fehler meldet (InputValidationError, "The required parameter
    # `content` is missing"). Nur wenn BEIDES zutrifft: ein fehlender Pflicht-
    # schluessel allein bleibt die Sache des Werkzeugs und seiner Saetze.
    #
    # #215: WAS HIER ANKOMMT, IST SCHON UEBERSETZT. Die Namen
    # anderer Harnesses, die `ARGUMENT_ALIASES` deklariert (old_string,
    # old_str, file_path ...), sind oben uebernommen und gesagt worden; diese
    # Pruefung sieht nur noch, was niemand deklariert hat.
    missing = [k for k in _declared_required(name) if k not in args]
    if declared and extra and missing:
        return ("error: %s was called with unknown argument(s) %s and without "
                "the required %s -- nothing was run. Its arguments are: %s."
                % (name, ", ".join(extra)[:120], ", ".join(missing),
                   ", ".join(declared)))
    if declared and extra:
        notes.append("unknown argument(s) ignored: %s" % ", ".join(extra)[:120])
    try:
        out = impl(**args)
    except TypeError as exc:
        return f"error: wrong arguments for {name}: {exc}"
    except Exception as exc:  # a tool must never take the turn down with it
        return f"error: {name} failed: {exc!r}"
    if name == "render_page":
        # #295: the render's own facts (render_mode, frames, precheck) for
        # the judge and the failure class -- read here, beside the tool.
        try:
            goal_capture_seen(out, str(args.get("path") or ""))
        except Exception as exc:        # noqa: BLE001 -- never the turn
            log_note("goal: render contract not read: %r" % exc, "goal")
    # DIE NOTE STEHT VOR DEM ERGEBNIS, in derselben Klammerform, in der
    # `run_tool_cached` einen Wiederholer meldet: eine Zeile, die sagt, dass an
    # den Argumenten etwas geradegezogen wurde, damit es niemanden ueberrascht.
    for note in notes:
        out = "[%s]\n%s" % (note, out)
    return out


# ---------------------------------------------------------------- #122 -----
# THE BACKGROUND REVIEW. Twice per window -- see `MEMORY_REVIEW_AT` -- the model
# is asked to read the conversation so far and decide what a future session
# would need from it. Curation is the hard half of a bounded memory: a model
# that only saves when it happens to think of it mid-answer saves almost
# nothing, and one asked after every turn saves the turn.
#
# IT RIDES THE PREFIX IT WAS JUST GIVEN. llama-server reuses a prompt by common
# token prefix, so replaying the finished conversation plus one short question
# is a cache hit up to the question -- and the NEXT user turn matches that same
# conversation again, because the review sits behind it. Cost is therefore one
# short prefill plus whatever the review decides to write, not a second pass.
#
# WHICH IS A DERIVATION FROM `server-context.cpp`, NOT A MEASUREMENT. On a
# single slot (`-np 1`) the review holds the server while it runs, and nobody has
# yet timed how long that is or whether a fast typist waits behind it. The
# measurement is owed before this ships and is written down in #122.
#
# THE TOOL LIST IS SENT WHOLE, NOT NARROWED TO `memory`. Narrowing it looks
# obviously right and would throw away the entire saving above: `tools` is
# rendered into the HEAD of the prompt, so a shorter list is a different byte 0
# and the whole conversation would be re-read. The restriction is stated in the
# question instead, and enforced here by ignoring every call that is not
# `memory`.
MEMORY_REVIEW_PROMPT = (
    "[system] Read the WHOLE conversation above, not just the last exchange. It "
    "has already been shown to the user; nothing you write now reaches them. "
    "Decide what a future session would need to know at its very first turn.\n"
    "SAVE, at most two or three entries: a decision and the reason for it; a "
    "convention, command or path that turned out to be the right one; a "
    "correction the user made; a constraint they stated; a trap that cost time "
    "and how it was avoided.\n"
    "DO NOT SAVE: the question or the answer; anything one read of a file would "
    "tell you again; a restatement of code; anything true only inside this "
    "conversation; progress, plans or what you are about to do next.\n"
    "Prefer ONE dense entry over three thin ones -- merge related facts into a "
    "single line. If an existing entry already covers it, use `replace` to "
    "sharpen that one instead of adding beside it. The store is small and is "
    "never trimmed for you.\n"
    "SEPARATELY, AND USUALLY NOT: if this conversation worked out a repeatable "
    "WAY of doing something -- an order of steps, the flags that worked, the "
    "check that catches the usual mistake -- save it with the `skill` tool "
    "instead. A skill is what to DO; memory is what is TRUE. Do not save a "
    "summary of this conversation as a skill, and do not save a procedure you "
    "have not actually seen work here.\n"
    "Saying nothing is the normal outcome and the right one whenever you are "
    "unsure: an entry you regret costs every future session, an entry you "
    "skipped costs nothing. If nothing qualifies, call nothing and reply with "
    "the single word NOTHING. Call no tool other than `memory`."
)


def review_question(incidents: "list[str] | None" = None) -> str:
    """#145: the review's question, with this turn's failures attached.

    The article's CONSTRAINTS.md pattern on Crow's own store: a decline, a
    capped retry or a spent budget is exactly the 'trap that cost time' the
    prompt already asks for -- but the review reads the CONVERSATION, and half
    of these incidents never appear in it as text the model would notice. So
    they are named in the question. Text, one line each, nothing to parse."""
    if not incidents:
        return MEMORY_REVIEW_PROMPT
    lines = "\n".join("- " + i for i in incidents[:8])
    return (MEMORY_REVIEW_PROMPT
            + "\nThis turn also recorded these incidents:\n" + lines
            + "\nAn incident that will repeat without a remembered rule is a "
              "trap worth one line; a one-off is not.")


def review_turn(conversation: "Conversation", *, base_url: str, model: str,
                api_key: str, temperature: float, top_p: float, min_p: float,
                top_k: int | None = None, reasoning_effort: str | None = None,
                presence_penalty: "float | None" = None,
                reasoning_budget: "int | None" = None,
                reasoning_budget_message: "str | None" = None,
                served_name: "str | None" = None,
                timeout: float = 180.0, gate: bool = False,
                extra_headers: "dict | None" = None,
                transport: str = TRANSPORT_CHAT,
                max_tokens: "int | None" = None,
                remote: bool = False,
                routing: "dict | None" = None,
                incidents: "list[str] | None" = None,
                events: "TurnEvents | None" = None,
                # #217: where this pass's seed is recorded, or None -- see
                # `rollover_digest`.
                seeds: "list | None" = None) -> "list[str]":
    """Ask once whether this turn left anything worth keeping. Returns what was saved.

    IT IS CALLED AFTER THE TURN IS OVER ON SCREEN, never inside it. It sat
    inside `run_turn` for one afternoon and the owner found it live on 2026-08-21:
    the answer was complete, the cost line never came and the composer still
    said `Stop`, because the turn does not end until this returns -- and at
    `high` it thinks about a 20k conversation first. What a person waits for is
    the answer; the review is something that happens afterwards.

    `events` FIRES PER SAVED ENTRY, IN THE LOOP, not once at the end -- the owner,
    same evening. The return value still carries everything, for the caller that
    wants the total rather than the moments.

    NOTHING IT DOES REACHES THE CONVERSATION. The question and the answer are
    built into a throwaway list and dropped; appending them would put the review
    into the history, which would move the head of every later turn and cost the
    prefix this whole design protects.

    IT NEVER RAISES. A review that takes a finished turn down with it would turn
    a working answer into an error after the user has already read it. Every
    failure here is silence.
    """
    if len(conversation) < 2:
        return []
    messages = conversation.payload() + [{"role": "user",
                                          "content": review_question(incidents)}]
    body = {"model": model, "messages": messages, "tools": TOOLS, "stream": False,
            "temperature": temperature, "top_p": top_p, "min_p": min_p}
    # The same rule as the turn's body, for the same reason: a review cut off at
    # a server default writes half a memory line and never says why.
    body["max_tokens"] = max_tokens or MAX_TOKENS
    if top_k is not None:
        body["top_k"] = top_k
    if presence_penalty is not None:
        body["presence_penalty"] = presence_penalty
    # #225: the review asks with the turn's fixed word, too.
    reasoning_effort = effective_reasoning(served_name or model, reasoning_effort)
    if reasoning_effort:
        # #176: dieselbe Tuer wie der Zug, aus demselben Grund. Ein Nachlauf, der
        # eine andere Tuer benutzt, waere ein zweiter Prompt-Stil im selben Chat.
        body["reasoning_effort"] = reasoning_effort
    capped = resolve_reasoning_budget(served_name or model, reasoning_budget)
    if capped is not None:
        # #176: derselbe Deckel wie der Zug, aus demselben Grund wie die Stufe
        # eine Zeile darueber. Ein Nachlauf, der ohne Deckel denkt, ist der
        # teuerste Aufruf des Chats -- und niemand sieht ihm dabei zu.
        body["reasoning_budget_tokens"] = capped
        body["reasoning_budget_message"] = (
            REASONING_BUDGET_MESSAGE if reasoning_budget_message is None
            else reasoning_budget_message)
    # AND IT CARRIES THE SAME ROUTING KEY AS THE TURN IT FOLLOWS. Same chat, own
    # body, nobody watching -- without this it is a second session inside the
    # first, answered by whichever upstream happened to be cheapest that second.
    # Hermes shipped exactly that gap and fixed it as their #70820.
    if routing and transport != TRANSPORT_MESSAGES:
        body.update(routing)
    # #217: A SEED OF ITS OWN, like every round of the turn. Without it
    # crow-nest samples this pass at seed 0 -- the seed that reproduced the
    # 2026-09-22 corruption byte for byte. Set before the gate below, which
    # takes it back out for a remote endpoint.
    body["seed"] = draw_seed()
    # THE SAME GATE THE TURN PASSES. This body is built here and not there, so
    # a fix applied once would leave this the only request still carrying them.
    if remote:
        remote_body(body)
    if seeds is not None and "seed" in body and transport != TRANSPORT_MESSAGES:
        seeds.append(body["seed"])
    # THE UNASKED PASS SPEAKS THE SAME DIALECT AS THE TURN IT FOLLOWS. It builds
    # its own body and its own headers -- that is what makes it the one easiest
    # to forget -- so the translation happens here as well or this pass alone
    # talks to an endpoint in a language it does not answer.
    if transport == TRANSPORT_MESSAGES:
        body = anthropic_body(body)
        url = f"{base_url.rstrip('/')}/messages"
    else:
        url = f"{base_url.rstrip('/')}/chat/completions"
    try:
        request = urllib.request.Request(
            url, data=json.dumps(body).encode("utf-8"), method="POST",
            headers=dict(_stream_headers(api_key, extra_headers),
                         # NOT AN EVENT STREAM. This pass asks once and reads
                         # one object; `_stream_headers` owns everything else,
                         # including which way the credential is spelled.
                         **{"Accept": "application/json"}))
        with urllib.request.urlopen(request, timeout=timeout) as resp:
            answer = json.loads(resp.read().decode("utf-8") or "{}")
        # #217 / crow-nest #99: A PASS THE SERVER ABORTED WRITES NOTHING. Its
        # calls are whatever stood when the generation was cut, and this pass
        # has nobody at the keyboard to notice half a memory entry.
        if transport != TRANSPORT_MESSAGES and (
                (answer.get("choices") or [{}])[0].get("finish_reason")
                == FINISH_ABORT):
            return []
        calls = (anthropic_calls(answer) if transport == TRANSPORT_MESSAGES else
                 (answer.get("choices") or [{}])[0].get("message", {}).get("tool_calls") or [])
    except Exception:                       # noqa: BLE001 - see the docstring
        return []
    saved, staged = [], []
    for call in calls:
        function = call.get("function") or {}
        # THE TWO THIS PASS MAY CALL, and nothing else. Anything further is a
        # model that did not read the question, and it is dropped rather than
        # run: the user is not at the keyboard for a background pass, so a write
        # or a shell command here would have nobody to refuse it.
        if function.get("name") not in ("memory", "skill"):
            continue
        # #128. STAGED, NOT WRITTEN. The gate cannot ask here -- see
        # MEMORY_APPROVAL_DEFAULT for why a question in a background pass is a
        # question put to an empty chair. What it can do is leave the write
        # where the user will meet it.
        if gate:
            staged.append(stage_memory(function["name"],
                                       function.get("arguments") or "{}"))
            continue
        try:
            result = json.loads(run_tool(function["name"],
                                         function.get("arguments") or "{}"))
        except Exception:                   # noqa: BLE001
            continue
        if result.get("success") and result.get("action"):
            one = "%s %s" % (result["action"],
                             result.get("target") or result.get("name")
                             or function["name"])
            saved.append(one)
            # The moment it is on disk, not the moment the pass is done.
            if events is not None:
                events.memory_saved([one])
    # ONE REPORT FOR THE WHOLE PASS, unlike `memory_saved` which fires per entry
    # at the moment of writing. Nothing has happened yet here: what the surface
    # raises is a state ("something is waiting"), and a state does not need to
    # be told twice.
    if staged and events is not None:
        events.memory_pending([e["summary"] for e in staged])
    return saved


class TurnEvents:
    """What `run_turn` reports while ONE USER TURN runs. Thirteen prints, named.

    Same seam as `ReplyEvents` one level up: the names say what HAPPENED, not
    what a terminal should do about it. Every method does nothing here, so a
    caller that passes nothing gets a turn that runs in silence -- which is
    what a probe, a test or a batch run wants.

    THESE ARE THE TWELVE TERMINAL LINES THE LOOP CARRIED while it sat in
    cli/crow.py's `repl()` (:2501, 2508, 2516, 2536, 2547, 2561, 2573, 2587,
    2593, 2595, 2611, 2617 of the file before the split). They are eleven
    methods, because "interrupted" fires from two places with the same text:

      turn_failed          :2501  the endpoint said no
      turn_interrupted     :2508  Ctrl+C raised out of the stream
                           :2516  ... or set the flag and returned quietly
      round_finished       :2536  one round is in the conversation
      cache_promise_broken :2547  the start line said "cache warm" and lied
      budget_spent         :2561  the tool budget is gone; one forced round left
      tool_started         :2573  before the call runs, not after
      tool_finished        :2587  it came back
      tool_failed          :2593  ... and the result began with "error: "
      tools_finished       :2595  every call of this round is appended
      rollover_refused     :2611  the window filled twice inside one turn
      rolled_over          :2617  the window filled once and was archived

    `tools_reported` is the one that had no line to move: it belongs to the
    operating mode this stage added, where calls are reported and not run.
    `boundary_escaped` is the second (#98), and for a different reason: it
    reports a sequence across two calls, and no single print ever carried it.

    `reply_events` is not a report at all -- it is the sink for the stream
    INSIDE each round, handed down so the two seams stay one decision. None
    means silence there too.
    """

    def reply_events(self) -> "ReplyEvents | None":
        """The sink for this round's stream. None is silence."""
        return None

    def turn_failed(self, message: str) -> None:
        """The endpoint could not be reached, or answered with an error."""

    def turn_interrupted(self) -> None:
        """Ctrl+C. The partial turn was discarded; the context is unchanged."""

    def round_finished(self, timings: dict) -> None:
        """One round is in the conversation. Fires on EVERY round, including
        the forced one, because the line it replaced did too."""

    def cache_promise_broken(self) -> None:
        """The start line claimed a warm cache and the first round disagreed."""

    def budget_spent(self, budget: int) -> None:
        """The tool budget is gone. One forced round follows."""

    def tool_started(self, name: str, arguments: str) -> None:
        """Before the call runs, so a slow call is not silence."""

    def tool_finished(self, name: str, seconds: float, repeated: bool) -> None:
        """The call came back. `repeated` means it was answered from `_SEEN`."""

    def tool_failed(self, name: str, result: str) -> None:
        """The result began with "error: ". The whole result is handed over,
        not its first line: how much of it fits on a screen is the screen's
        decision."""

    def tool_result(self, name: str, result: str) -> None:
        """What the call answered -- EVERY call, not only the failed ones.

        ADDITIVE RATHER THAN A WIDER `tool_finished`, and the reason is the
        seam. `tool_finished` is implemented by both surfaces and pinned by the
        cases; growing its signature would move every one of them to serve one
        reader. A surface that does not want the answer simply does not
        implement this.

        THE WHOLE RESULT, like `tool_failed` and for the same reason: how much
        of it fits on a screen is the screen's decision. A window showing four
        thousand characters and a terminal showing one line are then two
        answers to that question rather than two different truths.
        """

    def boundary_escaped(self, name: str, refused: list[str]) -> None:
        """A shell command ran in a turn where the boundary refused a write (#98).

        The thirteenth line, and the only one that had no terminal ancestor: it
        reports a SEQUENCE rather than a call, so there was nothing in `repl()`
        to move. `refused` is what the boundary turned away this turn, so the
        surface can name the path instead of saying that something happened.
        """

    def page_rendered(self, url: str, shot: str) -> None:
        """`render_page` came back with a picture of `url` (#175).

        Its own callback rather than a note: the surface that HAS a browser
        shows the page there, and one that has none says nothing.
        """

    def tool_progress(self, name: str, state: dict) -> None:
        """#308. A RUNNING call says where it is, between `tool_started` and
        `tool_finished`. Fired from the turn's thread while the call blocks it.

        THE CLOCK (#172) ANSWERS "IS A CALL OUTSTANDING", THIS ANSWERS "HOW
        FAR". On 2026-09-27 the owner watched 10 min 47 s of an image generation
        with nothing on the screen naming a phase, a step or an error.

        `state` keys, all present on every event:
          job     str, one id for the whole call (an edit's two stages share it)
          kind    "generate" | "edit"
          phase   "queued" | "loading" | "encoding" | "sampling" | "decoding"
                  | "refining" | "saved" | "error" | "stopped"
          stage   "1/2", "2/2" for an edit, "" otherwise
          i, n    int step/tile/tensor counters, or None (indeterminate)
          eta_s   float seconds left in sampling, or None
          line    one human line for the phase
          width, height  the FINAL picture's size, from the first event on --
                  a placeholder has its shape before the server answers.
        """

    def image_created(self, path: str, source: str, job: str = "") -> None:
        """#311. A tool saved a picture the user should see -- fired after the
        call's `tool_result`, once per picture, with the absolute path, the
        tool that made it and the `job` its `tool_progress` events carried."""

    def video_created(self, path: str, source: str, job: str = "") -> None:
        """#340. A tool saved a clip the user should see -- `image_created`'s
        twin, fired after the call's `tool_result`. The live check: "the MP4
        plays at 1920x1080 in the window"."""

    def tools_finished(self) -> None:
        """Every call of this round has run and been appended."""

    def tools_reported(self, calls: list[dict]) -> None:
        """`execute_tools=False`: these calls were NOT run and never will be."""

    def rolled_over(self, tokens: int, path: str) -> None:
        """The window filled mid-turn and the conversation was archived."""

    def rollover_refused(self) -> None:
        """Twice in one turn. The question itself does not fit."""

    def memory_pending(self, what: "list[str]") -> None:
        """#128. The review wants to write and the gate held it. Nothing is on
        disk yet.

        A STATE, NOT AN EVENT, and the surfaces draw it that way: `memory_saved`
        reports something that happened and is over, so the window's line glows
        once and settles. This one reports something that is still true and will
        stay true until the user answers or it expires -- so it breathes, the
        same grammar the recording microphone already uses.

        AND IT HAS TO BE ACTIONABLE. A state nobody can act on is furniture with
        a colour (the owner, on the microphone, and it holds here): whatever the
        surface raises has to be the thing you press to see the entries.
        """

    def memory_saved(self, what: "list[str]") -> None:
        """#122. The background review saved something, and this is how anyone knows.

        NOT OPTIONAL AND NOT SWITCHABLE. There is no write-approval gate here --
        the owner declined it on 2026-08-21 -- so this line is the ONLY moment a
        person finds out that something entered the head of their next session.
        A silent learner is a system nobody can correct.

        FIRED ONLY WHEN SOMETHING WAS WRITTEN. The review runs after every turn
        and saves after almost none of them; a line saying "nothing to remember"
        after each answer would be noise that teaches the reader to skip the one
        line that matters.
        """


class TurnResult:
    """What one user turn left behind, for the caller that owns the session.

    THE STATE THE LOOP MUTATES IS RETURNED, NOT HIDDEN. `context_tokens`,
    `promised_warm` and `rolled` were local variables of `repl()` that the loop
    wrote through; a second surface has to be able to carry the same three
    across turns or it will resume against numbers that stopped being true.

    `cost` is the DATA behind the one line printed per turn -- its fields and
    their order live in `TurnCost.line`, over here, so that two surfaces cannot
    assemble the same six numbers into two different sentences. The caller
    decides the colour and nothing else.
    """

    def __init__(self, *, cost: TurnCost, context_tokens: int, promised_warm: bool,
                 rolled: bool, stopped: bool, reported: list[dict],
                 incidents: "list[str] | None" = None) -> None:
        self.cost = cost
        self.context_tokens = context_tokens
        self.promised_warm = promised_warm
        self.rolled = rolled
        # True when the turn ended on an error, an interrupt or a refused second
        # rollover. Those have already said what happened, so the caller's cost
        # line is not printed under them -- it would read like a finished turn.
        self.stopped = stopped
        # Only ever non-empty with execute_tools=False: the calls that were
        # reported instead of run.
        self.reported = reported
        # #145's feedback half: what went WRONG this turn, one line each --
        # declines, outside asks, capped retries, spent budgets. The memory
        # review reads these; a failure nobody feeds forward repeats.
        self.incidents = incidents or []


def run_turn(
    conversation: Conversation,
    *,
    base_url: str,
    model: str,
    api_key: str,
    temperature: float,
    # NO DEFAULTS FOR THE SAMPLING VALUES, and that is a rule rather than an
    # oversight: manifests/operating-point.json wants each of them written
    # exactly once, in this file, and `stream_reply` below is where that one
    # copy sits. A convenience default here would be a second literal to bump
    # and the one that goes stale is the one no measurement reads.
    top_p: float,
    min_p: float,
    # top_k KEEPS ITS DEFAULT WHILE THE THREE ABOVE MAY NOT HAVE ONE, and the
    # difference is what the checker counts. None is not a value: it means "this
    # model declares no top_k", which is 0731's case and the case of every
    # endpoint this client has ever talked to. A number here would be a literal.
    top_k: int | None = None,
    # The same None as top_k: the model's manifest entry names one or nothing does.
    presence_penalty: "float | None" = None,
    reasoning_effort: str | None = None,
    # #176. Durchgereicht, nicht entschieden: was ein Deckel ist, sagt
    # `budget_command`, und wo er wirkt, sagt `stream_reply`.
    reasoning_budget: "int | None" = None,
    reasoning_budget_message: "str | None" = None,
    # #220. The model the server HAS OPEN, for the manifest
    # lookups -- see `stream_reply`. Passed through to both senders.
    served_name: "str | None" = None,
    timeout: float,
    carry: str | None = None,
    context_tokens: int = 0,
    n_ctx: int = 0,
    rollover_at: float = ROLLOVER_AT,
    max_tool_rounds: int = MAX_TOOL_ROUNDS,
    # #145: decoded tokens this turn may spend. 0 is off, and off is what every
    # release up to 1.4.0 meant -- the cap is opt-in, the article's bank-vs-
    # hackathon warning taken at its word.
    token_budget: int = 0,
    promised_warm: bool = False,
    rolled: bool = False,
    execute_tools: bool = True,
    # #88. `mode` picks which classes stop and ask; `approve` is how they ask.
    # A surface that passes neither keeps the behaviour every release up to
    # 0.3.1 had: everything runs. A surface that passes a mode but no `approve`
    # gets refusals rather than silent execution -- the safe half of a
    # half-wired client.
    mode: str = DEFAULT_MODE,
    approve: "Callable[[str, str], str] | None" = None,
    # THE PROVIDER'S OWN HEADERS, threaded rather than resolved here: this
    # function does not know which endpoint it is talking to and must not start
    # asking, or there would be a second answer to that question. Same for the
    # dialect and for the output cap.
    extra_headers: "dict | None" = None,
    transport: str = TRANSPORT_CHAT,
    max_tokens: "int | None" = None,
    remote: bool = False,
    routing: "dict | None" = None,
    # #143. Threaded through to `stream_reply`: False means the subtask case --
    # no tools declared at all. See the parameter there for why `[]` would not do.
    send_tools: bool = True,
    # #143. TRUE FOR EVERY TURN A USER RUNS, FALSE ONLY ON A DELEGATION THREAD.
    # The per-turn state this loop clears -- `_SEEN`, `_REFUSED`, `_MANDATED`,
    # and the INTERRUPT flag -- is module state, owned by the ONE turn a
    # surface runs at a time; so is `_READ`, which since #215-H this loop
    # does not clear but ADOPTS (`adopt_read_state`). A subtask's `run_turn` rides beside that
    # turn on its own thread: clearing here would wipe the read-permissions of
    # the turn that spawned it mid-round, and consuming the INTERRUPT flag would
    # swallow a Ctrl+C meant for the turn the user is watching. A subtask still
    # STOPS on the flag -- it just leaves it standing for its owner.
    owns_turn_state: bool = True,
    # #173. DIE MARKENLISTE DES AUFRUFERS, oder None. Sie wird hier nicht
    # gefuehrt -- der Kern zeichnet nichts --, aber ein Rollover MITTEN in einem
    # Zug legt den Kontext weg, zu dem sie gehoert: sie geht ins Archiv mit und
    # wird geleert. Ohne das saessen die Marken danach ueber einem Gespraech, in
    # dem sie nie passiert sind, und zeigten auf Nachrichten, die es nicht gibt.
    notes: "list | None" = None,
    # #171. DIE ZUGBILANZEN DES AUFRUFERS, aus demselben Grund wie `notes`
    # daneben: sie gehoeren zu dem Kontext, den ein Rollover weglegt.
    #
    # `bills` UND NICHT `timings`, und der Name ist der ganze Grund: `timings`
    # heisst in dieser Schleife seit jeher das Zeitdiktionar EINER Runde. Als
    # Parameter gleichen Namens hat es dieses hier ueberdeckt, und `del
    # timings[:]` traf die Runde statt das Band -- vier Faelle rot, alle im
    # Rollover.
    bills: "list | None" = None,
    events: "TurnEvents | None" = None,
) -> TurnResult:
    """Run one USER turn to its end: however many tool rounds it takes.

    THIS IS THE TOOL LOOP OUT OF `repl()`, moved rather than rewritten. It was
    the one place in this client that did five jobs at once -- read a key, run a
    turn, run tools, archive a full window and price the result -- and the only
    one a second surface could not call. Nothing about the four loop rules
    changed on the way over; what changed is that they are now written once.

    `carry` is the line the user typed, needed only by a mid-turn rollover: the
    archive takes everything up to here and the fresh conversation opens with
    the question, so the model is not left answering a note about a file.

    EXECUTE_TOOLS=FALSE IS AN OPERATING MODE, NOT A DRY RUN. A client that sends
    `tools` in the body gets tool calls back whether it can run them or not --
    and it must send them, because this model's template drops a previous turn's
    thoughts when the array is empty (measured 2026-08-08 over /apply-template:
    132 characters against 132 without tools, 1197 against 1215 with them). The
    rule about what happens to the prefix then is the same rule the budget uses,
    and it lives here rather than in the surface that discovered it: the
    assistant turn is appended WITHOUT its `tool_calls`, so the next turn
    against the same prefix is still valid. The calls are handed to the caller
    through `tools_reported` and `TurnResult.reported`.

    Returns a `TurnResult`. Raises nothing that the loop can name: a `CrowError`
    from the endpoint and a `KeyboardInterrupt` from the user both end the turn
    through `stopped`.
    """
    if events is None:
        events = TurnEvents()

    # #169. WO DER ZUG AUFSETZT, ohne es dem Ziel anzurechnen. Ein Zug auf einem
    # wiederhergestellten Chat findet dort Tiefe vor, die niemand jetzt ausgibt;
    # ohne diese Marke verbuchte die erste Runde den ganzen Chat als Wachstum des
    # Ziels. Gesetzt wird hier, weil hier der Stand bekannt ist -- und weil ein
    # `goal_set` MITTEN in diesem Zug sonst von 0 aus zaehlte.
    goal_tokens_mark(context_tokens)

    # THE TOOL LOOP. Everything is appended, never inserted: the assistant
    # turn with its calls, then one `tool` message per call, then the next
    # request. The prefix only grows, so the cache holds across rounds --
    # and this template keeps every reasoning block while tools are present,
    # which is why the loop is affordable at all.
    #
    # CLEARED HERE, NOT BY THE CALLER, and that line moved with the loop on
    # purpose. `_SEEN` is what stops the model asking for the same missing file
    # eight times in one turn; left behind in `repl()` it would go on being
    # cleared for the CLI and never for anybody else, and every later turn of a
    # second surface would be answered out of a stale result, forever.
    #
    # E6 ANSWERED THE LIFETIME QUESTION THIS LINE LEFT OPEN, and put `_READ`
    # beside it for one user turn. #215-H TOOK `_READ` BACK OUT: a read counts
    # while the file still carries the stamp it was read with, and the set
    # empties when the model stops holding the contents -- a rollover, a new or
    # resumed chat -- which `adopt_read_state` learns from the conversation's
    # `read_epoch`. The reasons are written out where `_READ` is declared.
    #
    # THE HALF-STATE E6 FEARED IS GONE WITH THE PAIRING, not ignored. `_SEEN`
    # emptied while `_READ` stays was "a stale permission outliving the results
    # that earned it"; the permission is now the file's stamp, checked against
    # the disk at every call, and `_cache_key` keys on that verdict -- so no
    # cached answer can outlive a read-state change inside a turn either.
    #
    # `_REFUSED` JOINED THEM WITH #98 and fails the same way: left behind, the
    # next turn's first `run_command` is marked as an escape from a refusal that
    # happened before the user typed again. That is a false alarm, and a false
    # alarm on a marker is worse than no marker -- it is the one failure mode
    # that trains the reader to skip the line.
    # #143: ONLY THE TURN THAT OWNS THE STATE CLEARS IT. A delegation thread
    # runs no tools -- none are declared on it -- so it needs none of the four,
    # and touching them from a second thread is the race the parameter names.
    if owns_turn_state:
        # #266: where this turn goes, for `judge`'s last fallback -- the same
        # endpoint in a FRESH context (images and rubric, no transcript).
        _TURN_SPOT.clear()
        _TURN_SPOT.update({"base_url": base_url, "model": model,
                           "api_key": api_key, "remote": remote,
                           "headers": dict(extra_headers or {}),
                           "transport": transport,
                           "served": served_name or model})
        adopt_read_state(conversation)      # #215-H: not a clear
        _SEEN.clear()
        _REFUSED.clear()
        # NOT CLEARED -- REBUILT, and from the conversation rather than this turn's
        # line. The user's addresses accumulate: a path named two turns ago is still
        # the place the user asked for, and forgetting it would start refusing in the
        # middle of the very task that named it. It happens here rather than in the
        # surfaces because a client that forgot to build the list would silently
        # refuse everything its user typed -- the failure #98 already recorded once.
        _MANDATED.clear()
        _MANDATED.update(mandated_paths(conversation))
        # #288: THE SAME REBUILD for the web hosts `render_page`/`fetch_url`
        # may reach -- from the conversation, which after a cut holds the
        # hosts the rollover note carried.
        adopt_known_hosts(conversation)
    stopped = False
    cost = TurnCost()
    budget = max_tool_rounds
    # #145: identical failing calls, counted by their exact (name, arguments).
    # A different argument is a different attempt, and only FAILURES count --
    # a slow success repeated on purpose is the model's business.
    failures: dict[tuple, int] = {}
    # #98-Nachtrag (the owner, 2026-08-28 abends): which refused paths this turn
    # has ALREADY ANNOUNCED. One refused path and a dozen shell calls papered
    # the chat with the same warning -- a line that is always there is a line
    # nobody reads. Per turn like `_REFUSED` itself.
    escapes_said: set[str] = set()
    # #145's feedback half: one line per thing that went wrong or was decided,
    # handed to the memory review through TurnResult. Text, not structures --
    # the only reader is a prompt.
    incidents: list[str] = []
    reported: list[dict] = []
    # One iteration past the budget, for the forced answer. It is not a tool
    # round -- its calls are discarded -- so it does not quietly hand out a
    # round more than was asked for.
    forced = False
    # #150: the one visible-answer nudge this turn may spend.
    nudged = False
    # #151: the one broken-stream retry this turn may spend.
    stream_retried = False
    # 2026-08-28 spaetnachts: Serien-Tode. EIN Reboot je Turn reichte nicht --
    # der zweite Tod im selben langen Lernkit-Turn endete rot, waehrend der
    # Heiler daneben stand. Drei je Turn; der vierte endet ehrlich rot. Und
    # ein Zug, der einen frisch bootenden Server trifft (HTTP 503 "Loading
    # model"), wartet ihn EINMAL aus, statt am Boot zu sterben.
    reboots = 0
    waited_ready = False
    # #217: the one re-request a degenerate round may spend, and the seed of
    # the round before -- so the next one is guaranteed a different draw.
    degenerate: "list[tuple[str, int | None]]" = []
    seed: "int | None" = None
    # ONE MORE INDEX THAN THE BUDGET NEEDS, and it belongs to #217: a
    # degenerate round that arrives as the forced answer (the last index
    # before this) still gets its one re-request instead of ending the loop
    # with nothing appended behind BUDGET_SPENT. Only `continue` paths can
    # reach it; a tool round past the budget is forced, and a forced round
    # always breaks.
    # #263: a turn that STARTS above the trigger (a resumed chat, a long
    # answer last turn) clears before its first request, not after it.
    context_tokens = clear_before_roll(conversation, context_tokens, n_ctx,
                                       remote=remote,
                                       forget_reads=owns_turn_state,
                                       served=served_name or model)
    for round_no in range(budget + 3):
        # #310: A STOP BETWEEN ROUNDS SENDS NOTHING. Without this the next
        # request went out and only the stream reader dropped it -- 535
        # tokens prefilled and 2 generated for nobody (engine.log, 00:27:39).
        if INTERRUPT.is_set():
            if owns_turn_state:
                INTERRUPT.clear()
            events.turn_interrupted()
            stopped = True
            break
        seed = None if remote else draw_seed(avoid=seed)
        try:
            reply, reasoning, timings = stream_reply(
                conversation,
                base_url=base_url,
                model=model,
                api_key=api_key,
                temperature=temperature,
                top_p=top_p,
                min_p=min_p,
                top_k=top_k,
                presence_penalty=presence_penalty,
                reasoning_effort=reasoning_effort,
                reasoning_budget=reasoning_budget,
                reasoning_budget_message=reasoning_budget_message,
                served_name=served_name,
                timeout=timeout,
                extra_headers=extra_headers,
                transport=transport,
                max_tokens=max_tokens,
                remote=remote,
                routing=routing,
                send_tools=send_tools,
                seed=seed,
                events=events.reply_events(),
            )
        except CrowError as exc:
            # #151. A BROKEN STREAM IS NOT YET A BROKEN TURN. Found live on
            # 2026-08-28: sixteen rounds and 7m28s of work died on one
            # `[WinError 10054]` mid-round. Nothing has been appended for this
            # round -- the exception path runs before the append -- so the
            # prefix is intact and ONE re-request costs a cached prefill, not
            # the turn. Once per turn; a server that is actually gone refuses
            # the retry too, and that failure is then reported as before.
            said = str(exc).lower()
            # 2026-08-28 spaetabends, des Owners Abend in einem Satz: der Server,
            # den dieses Fenster selbst gebootet hat, beendet sich unter Last
            # still mit Exit 1 -- und jeder Tod riss den Lauf rot ab, fuenf
            # Laeufe an einem Abend. Crow ist der Booter: EIN Neustart des
            # EIGENEN Servers und EIN weiterer Versuch auf intaktem Prefix je
            # Turn (die Ausnahme laeuft vor dem Append, wie beim #151-Retry).
            # Fremde Server werden NIE gebootet -- deren Fehlen endet rot wie
            # bisher, und ein zweiter Tod im selben Turn auch.
            if not remote:
                note = getattr(events, "turn_note", lambda _t: None)
                port = urllib.parse.urlsplit(base_url).port
                # Auch der Boot eines FRUEHEREN Crow-Fensters zaehlt (die
                # Datei traegt ihn) -- das Fenster-Neustart-Loch der Nacht.
                # Nur der Exit-Code bleibt dem Handle-Halter vorbehalten.
                known = booted_entry(port) if port else None
                if (isinstance(exc, Unreachable) and known is not None
                        and reboots < 3):
                    reboots += 1
                    code = booted_exit(port)
                    note("the crow-booted server on port %s is gone%s -- "
                         "booting it again (%d/3)"
                         % (port, " (exit code %d, 0x%08X)"
                            % (code, code & 0xFFFFFFFF) if code is not None
                            else "", reboots))
                    if reboot_booted(port, log=note) is not None:
                        incidents.append(
                            "the local server died mid-turn%s; reboot %d "
                            "recovered the turn"
                            % (" with exit code %d" % code
                               if code is not None else "", reboots))
                        continue
                if (not waited_ready
                        and "503" in said and "loading model" in said):
                    # Der Boot ist kein Fehler: einmal je Turn ausharren,
                    # bis der Server antwortet, dann weitermachen.
                    #
                    # #167. OHNE DIE EIGENTUMSFRAGE, und das ist der Fix: hier
                    # stand `known is not None`, also "nur warten, wenn ICH den
                    # gebootet habe". Fuer den REBOOT ist das richtig -- einen
                    # fremden Server neu zu starten ist die Entscheidung eines
                    # anderen. Fuers WARTEN ist es sinnlos: ein ladender Server
                    # laedt, egal wer ihn gestartet hat, und Warten kostet
                    # niemanden etwas.
                    #
                    # Bezahlt am 2026-08-30 abends: `booted.json` kannte den
                    # Betriebspunkt-Port 8083 nicht, also war `known` None, also
                    # lief dieser Zweig nicht -- und ein 26-Runden-Zug starb an
                    # einem Server, der 72 s spaeter bereit war. Die Bedingung
                    # verknuepfte zwei Fragen, von denen nur eine hierher
                    # gehoert.
                    waited_ready = True
                    note("the server on port %s is still loading -- waiting"
                         % port)
                    load_deadline = time.monotonic() + 240.0
                    ready = False
                    while time.monotonic() < load_deadline:
                        if server_model_path(base_url, timeout=2.0) is not None:
                            ready = True
                            break
                        time.sleep(2.0)
                    if ready:
                        continue
            if (not stream_retried
                    and any(m in said for m in ("10054", "connection", "reset",
                                                "stream broke", "broken"))):
                stream_retried = True
                incidents.append("the stream broke mid-round and one retry "
                                 "recovered the turn: %s" % str(exc)[:120])
                time.sleep(2.0)
                continue
            events.turn_failed(failure_line(exc))
            stopped = True
            break
        except KeyboardInterrupt:
            # The partial turn is discarded rather than appended: a truncated
            # assistant message would poison the prefix for every later turn.
            INTERRUPT.clear()
            events.turn_interrupted()
            stopped = True
            break

        # The generator returns quietly on an interrupt rather than raising,
        # so the flag is what tells a stopped turn from a finished one.
        # #143: A SUBTASK STOPS ON THE FLAG BUT DOES NOT CONSUME IT. The flag
        # belongs to the turn the user is watching; a delegation thread that
        # cleared it first would race that turn's own check and swallow the
        # only Ctrl+C there is.
        if INTERRUPT.is_set():
            if owns_turn_state:
                INTERRUPT.clear()
            events.turn_interrupted()
            stopped = True
            break

        calls = timings.get("_tool_calls") or []
        finish = timings.get("_finish_reason")
        # #217. CLASSIFIED BEFORE ANYTHING IS APPENDED, because the append is
        # what made a degenerate round a lesson: stored as the answer, re-sent
        # on every later request, imitated (the markup shape four times in 30
        # minutes on 2026-09-22), and -- in goal mode -- answered by a nudge.
        malformed = timings.get("_malformed_calls") or []
        kind = classify_round(reply, calls, finish, reasoning, tools=send_tools,
                              malformed=malformed)
        # #262: both lines below are Crow's own diagnostics and go
        # to crow.log; `incidents` still carries them to the memory review.
        if kind == "stub" and degenerate:
            # A STUB ON THE RE-REQUEST IS KEPT, NOT REFUSED (lead review of
            # ba48641). Two short, unpunctuated answers in a row from two
            # different seeds are as likely the answer -- "Erledigt", a
            # file name -- as a cut, and refusing an answer twice is the one
            # failure that must not happen to a real one. It is stored below
            # like any answer; the note and the incident say what it was.
            log_note("kept the re-asked reply although it looks unfinished "
                     "(stub again%s)" % (", seed %s" % timings.get("_seed")
                                         if timings.get("_seed") is not None
                                         else ""), "turn")
            incidents.append("the re-asked round was a stub again and was "
                             "kept as the answer")
        elif kind in DEGENERATE_ROUNDS:
            # THE TOKENS WERE SPENT, so the round is billed and drawn like any
            # other; only the conversation never hears of it.
            cost.add_round(timings)
            events.round_finished(timings)
            degenerate.append((kind, timings.get("_seed")))
            if len(degenerate) == 1:
                # ONCE, IN THE SAME TURN, ON THE SAME PREFIX. No user message
                # is added, so the read ledger, the goal step and the prompt
                # cache all stand where they stood; the loop head draws a
                # seed that differs from this round's, which is the whole
                # difference between a resample and a replay.
                said = ("discarded a degenerate reply (%s, %d chars%s) -- "
                        "asking again with a new seed"
                        % (kind, len((reply or "").strip()),
                           ", seed %s" % degenerate[0][1]
                           if degenerate[0][1] is not None else ""))
                log_note(said, "turn")
                incidents.append("a degenerate round (%s) was discarded "
                                 "unstored and asked again" % kind)
                continue
            # MARKUP ON THE RE-REQUEST (a stub never gets here, see above):
            # TWICE IS THE MODEL'S ANSWER, NOT BAD LUCK -- and a third try is
            # the silent loop #202 had to brake. One loud line, one
            # placeholder so the history keeps its alternation (a user line
            # after a user line is what the next nudge would otherwise make),
            # and the turn ends.
            placeholder = "[no usable reply: %s]" % kind
            conversation.append("assistant", placeholder)
            seeds = [s for _k, s in degenerate if s is not None]
            line = ("the model sent no usable reply twice (%s, then %s%s) -- "
                    "neither was stored, the turn stops here"
                    % (degenerate[0][0], kind,
                       "; seeds " + " and ".join(map(str, seeds))
                       if seeds else ""))
            incidents.append(line)
            events.turn_failed(line)
            stopped = True
            break
        # #203: THE CUT CALLS ARE MADE SAFE TO STORE BEFORE THE TURN THAT
        # CARRIES THEM EXISTS. An unterminated arguments string in the stored
        # assistant turn kills every later request against the llama.cpp arm
        # with a 500 the history cannot recover from; here it never gets in.
        # The calls named in `cut` do not run -- the loop below answers each
        # with the structured result instead.
        # #217: which argument each cut call was writing -- read before the
        # salvage below may replace an unparseable string with `{}`.
        cut_params = {c.get("id") or "": cut_parameter(c.get("arguments"))
                      for c in calls}
        # THE ENGINE'S RECORD PER CALL, by stream index. `_tool_calls` is the
        # stream's slots in index order and serve numbers the calls it emits
        # without gaps, so the position in the list is the index.
        records = {r.get("index"): r for r in malformed
                   if isinstance(r.get("index"), int)}
        record_of = {c.get("id") or "": records.get(n)
                     for n, c in enumerate(calls)}
        cut = salvage_cut_calls(calls)
        # #217 point 3: A CALL THAT ARRIVED PARSED IS NOT ALSO KEPT AS TEXT.
        if calls:
            reply = strip_call_markup(reply)
        # #259: THE ROUND THAT ENDS THE TURN SPEAKS. Decided
        # before the append, because the conversation has no edit: a forced
        # round (tool or token budget), or a final round whose #150 nudge is
        # spent or does not apply, and nothing visible in it. The reasoning is
        # kept beside it, so the prefix the server holds stays valid up to the
        # end of the think block.
        final = execute_tools and (forced or not calls) and not (
            not forced and not nudged and kind == "think_only")
        if final and not _strip_think(reply or "").strip():
            reply = surfaced_answer(reasoning, forced, cost.tool_calls)
            sink = events.reply_events()
            if sink is not None:
                sink.reply_started()
                sink.answer_started()
                sink.answer_text(reply)
                sink.reply_finished()
            incidents.append(
                "the turn ended with no visible answer%s%s"
                % (" after the budget stop" if forced
                   else " despite the nudge" if nudged else "",
                   "; its reasoning was shown as the answer"
                   if (reasoning or "").strip() else " and no reasoning"))
        # CALLS THAT WILL NEVER RUN ARE NOT APPENDED, and that is not
        # tidiness. An assistant turn whose tool_calls have no `tool` message
        # behind them is a broken prefix for every later turn of the session.
        #
        # Three rounds are in that position, and missing the first one is a
        # mistake the probe caught: the round that SPENDS the budget, whose
        # calls are refused, the forced round after it, whose calls are
        # discarded, and -- since this loop grew an operating mode -- every
        # round of a turn that reports its calls instead of running them.
        # Keeping the text and losing the calls is the only shape that stays
        # valid.
        unanswerable = not execute_tools or forced or (bool(calls) and round_no >= budget)
        conversation.append("assistant", reply, reasoning,
                            tool_calls=None if unanswerable else calls)
        context_tokens = next_context_tokens(context_tokens, timings)
        # #169. JE RUNDE, NICHT JE ZUG. Ein Zug mit 27 Runden hakte neun Schritte
        # ab, waehrend der Zielspeicher noch den Stand des vorigen Zuges trug --
        # drei Schritte lasen 0, der vierte trug alles. Dies ist dieselbe Zahl,
        # die die Kostenzeile eine Zeile spaeter aufsummiert, nur eher gemeldet.
        goal_tokens_seen(context_tokens)
        cost.add_round(timings)
        events.round_finished(timings)

        # THE PROMISE IS SETTLED HERE, BECAUSE HERE IS WHERE IT IS PAID.
        # Everything before this is the server saying it read a file. Only
        # `cached` says whether the prefix it holds is the one being sent,
        # and it is the number the user is charged against: on 2026-08-10 a
        # start that said "cache warm" was followed by `cached 0/21004` and
        # 469.51 s to the first token, with nothing in between admitting it.
        if promised_warm:
            promised_warm = False
            if timings.get("_cached_tokens") == 0:
                events.cache_promise_broken()

        # REPORTED AND NOT RUN. One round only: there is no tool result to feed
        # back, so a second round would ask the same question against the same
        # prefix and get the same answer.
        if not execute_tools:
            if calls:
                reported = list(calls)
                events.tools_reported(reported)
            break

        if forced or not calls:
            # #150. A REASONING MODEL CAN CLOSE THE TURN INSIDE ITS OWN HEAD:
            # the final round carries reasoning and an empty `content`, and on
            # screen the turn "just stops" -- found live on 2026-08-28, ten
            # rounds into a skill, thinking share 100 %. ONE nudge, ONCE per
            # turn: the model is told to say it visibly. If the second attempt
            # is silent too, the turn ends and the incident says so -- looping
            # on a model that will not speak would spend the window on nothing.
            # #217: the same question `classify_round` answered above.
            if not forced and not nudged and kind == "think_only":
                nudged = True
                conversation.append("user", THINK_ONLY_NUDGE)
                continue
            break

        # THE BUDGET BUYS TOOL ROUNDS, NOT THE TURN. Until 2026-08-10 this
        # was a bare `break`, and a turn that ran out ended on a bracket:
        # driven live with --max-tool-rounds 0 the model produced 102 tokens,
        # `thinking 100%`, and the user was shown nothing at all -- the reply
        # was a tool request that would never run. One more round, with the
        # tools still declared so the prompt cache holds (#60), spends what
        # is left on saying where things stood.
        if round_no >= budget:
            events.budget_spent(budget)
            conversation.append("user", BUDGET_SPENT)
            forced = True
            continue
        # #145: same protocol, other meter. `cost.decoded` holds the rounds
        # already streamed, so the check reads last round's total -- a budget
        # of N refuses the round AFTER the one that crossed it, which is the
        # round-budget's own shape. The event rides a getattr because every
        # surface predates it; the message to the model is the load-bearing
        # half either way.
        if token_budget and cost.decoded >= token_budget:
            getattr(events, "token_budget_spent", lambda n: None)(token_budget)
            conversation.append("user", TOKEN_BUDGET_SPENT)
            incidents.append("the turn token budget of %d was spent before the "
                             "task finished" % token_budget)
            forced = True
            continue
        for call in calls:
            # REPORTED BEFORE THE CALL RUNS, and that is the fix rather than a detail (#70).
            # Until here the order on screen was: run the tool, then say what was run. A slow
            # call left the terminal silent for its whole duration with nothing naming what it
            # was waiting on -- and the previous round's six figures as the last thing visible.
            events.tool_started(call["name"], call["arguments"])
            started = time.monotonic()
            # #310: A CALL AFTER A STOP DOES NOT RUN and asks nobody; it
            # still gets its answer, so the prefix stays valid (DECLINED's
            # reason).
            halted = INTERRUPT.is_set()

            # #203: A CALL THE OUTPUT CAP CUT IN HALF RUNS NOTHING AND ASKS
            # NOBODY. There is nothing to approve -- the arguments are gone or
            # half-invented -- and an approval card for `{}` would be a
            # question about a call that cannot happen. The structured result
            # below is the answer, and it is a RESULT so the prefix stays
            # valid for the next round (#88 point 1, DECLINED's reason).
            cut_why = cut.get(call.get("id") or "")

            # #88: THE LEVEL DECIDES, THE SURFACE ASKS. This loop knows which
            # class a tool is in and whether the level releases it; it does not
            # know how to put a question on a screen, and a core that did would
            # have one implementation per surface. `approve` is that seam --
            # None means nobody can be asked, which is the same answer as "no"
            # for anything the level holds back.
            declined = False
            # #144: an outside path in a run_command asks at EVERY level --
            # auto included, which is the level the live case ran at. The
            # question and the memory of a yes ride the existing seam:
            # approval_scope already answers ("outside", path) for these.
            # #98's mandate carries over: a path the USER spelled out is not
            # asked about -- the guard protects the inattentive user from the
            # model, never from their own typed address.
            # #221: A CWD THAT DOES NOT EXIST IS ANSWERED HERE,
            # before the card. Its path would otherwise stand on the card as
            # an outside path -- a question about a place that is not there,
            # for a call that runs nothing whatever the answer (cwd_refusal).
            cwd_refused = (run_command_cwd_refusal(call["arguments"])
                           if cut_why is None and call["name"] == "run_command"
                           else None)
            outside = (run_command_boundary(call["arguments"])
                       if call["name"] == "run_command" and cwd_refused is None
                       else [])
            outside = [p for p in outside
                       if not any(_inside(m, p) for m in _MANDATED)]
            # #156: `git_commit` and `git_push` join `outside` here rather than
            # in MODE_ASKS -- see ALWAYS_ASKS for why the level table is the
            # wrong place. `remembered` cannot release them: they have no
            # scope. Since 2026-09-19 the three sources read through ONE
            # predicate: `stops_for` keeps git_push on at every level, lets
            # yolo silence the outside-path ask and the git_commit ask, and
            # leaves every other level exactly where #88 put it.
            if (not halted and cut_why is None and cwd_refused is None
                    and (stops_for(call["name"], mode, bool(outside))
                         and not remembered(call["name"], call["arguments"]))):
                answer = "no"
                if approve is not None:
                    answer = approve(call["name"], call["arguments"]) or "no"
                if answer == "always":
                    remember(call["name"], call["arguments"])
                elif answer != "yes":
                    declined = True
                if outside:
                    incidents.append(
                        ("the user %s run_command for %s, outside the working "
                         "area") % ("declined" if answer not in ("yes", "always")
                                    else "released", ", ".join(outside[:2])))
            elif not halted and outside and mode in RELEASES_ALL:
                # YOLO WAS NOT ASKED, SO "THE USER RELEASED" WOULD BE A LIE --
                # and a silent outside run would be worse (#98: the working
                # area leaving is the one fact the screen must carry). The
                # run is reported for what it is; the GUI draws it in
                # `boundary_escaped`'s own colour.
                incidents.append(
                    "run_command ran unasked for %s, outside the working "
                    "area (yolo)" % ", ".join(outside[:2]))

            if halted:
                result, repeated = STOPPED + STOPPED_NOT_RUN, False
                declined = True
            elif declined:
                # A REFUSAL IS A RESULT. Same shape as a failed call: the text
                # goes back as the tool message, the round continues, and the
                # prefix stays valid for every later turn. #88 point 1.
                result, repeated = (declined_outside(outside) if outside
                                    else DECLINED), False
                if not outside:
                    incidents.append("the user declined %s(%s)"
                                     % (call["name"], call["arguments"][:80]))
            elif failures.get((call["name"], call["arguments"]), 0) >= RETRY_CAP:
                # #145: the fourth identical failure is refused BEFORE it runs.
                # It stands BEFORE the #203 branch on purpose: the sanitized
                # arguments of a cut call make every repeat the SAME key, so
                # the cap -- which the live run's ever-different cuts could
                # never trip -- is what stops a model from re-sending the
                # same call to be cut a fifth time.
                result, repeated = retry_capped(call["name"]), False
                incidents.append("%s failed %d times with identical arguments "
                                 "and was capped" % (call["name"], RETRY_CAP))
            elif cwd_refused is not None:
                # #221: nothing ran and nobody was asked; the
                # incident keeps the record on the user's side too.
                result, repeated = cwd_refused, False
                incidents.append("a run_command named a cwd that is not an "
                                 "existing directory and did not run")
            elif cut_why is not None:
                # #203: THE RECOVERY SIGNAL. The call never ran, the result
                # says why and what to do instead, and the incident keeps a
                # record that does not depend on the model choosing to
                # mention it. `failed` counts it below through the "error: "
                # prefix.
                # #217: WHICH CUT -- the engine's record when it sent one,
                # else the finish. `stop` is the model's own EOS inside the
                # arguments, and blaming the limit for it sent the model
                # splitting a path into parts. `length`, and llama-server's
                # `tool_calls` that masks a cap cut (see TRUNCATED_CALL),
                # keep the limit's answer. `cut_answer` holds the table.
                cid = call.get("id") or ""
                result, cut_kind = cut_answer(cut_why, finish,
                                              record_of.get(cid),
                                              cut_params.get(cid))
                if cut_kind == "unclosed":
                    incidents.append("a %s call stopped inside its arguments "
                                     "(finish stop, not the output limit) and "
                                     "did not run" % call["name"])
                elif cut_kind == "bad-parameter":
                    incidents.append("a %s call was abandoned on an unreadable "
                                     "parameter name and did not run"
                                     % call["name"])
                else:
                    incidents.append("a %s call was cut off at the output token "
                                     "limit and did not run" % call["name"])
                repeated = False
            else:
                # #308: THE SINK IS ARMED AROUND THIS ONE CALL and disarmed in
                # `finally`, so a tool reporting after its call -- a warm-up
                # thread, a test -- reports into nothing. Thread-local: a
                # subtask's turn runs on its own thread with its own events.
                take_announced_images()
                progress = getattr(events, "tool_progress", None)
                _TURN_LOCAL.progress = (
                    None if progress is None
                    else (lambda st, n=call["name"]: progress(n, st)))
                try:
                    result, repeated = run_tool_cached(call["name"],
                                                       call["arguments"])
                finally:
                    _TURN_LOCAL.progress = None
                # #288: WHERE A TOOL RESULT IS RECORDED, ITS HOSTS ARE NAMED --
                # a search in this call releases the fetch in the next one.
                note_known_hosts(result)
                # #310: A CALL STOP ENDED IS BOOKED LIKE A REFUSAL -- the
                # user's choice, not a failed tool, no same-failure streak.
                if result.startswith(STOPPED):
                    declined = True
                    log_note("stop pressed during %s after %.0f s"
                             % (call["name"], time.monotonic() - started),
                             "turn")
            took = time.monotonic() - started
            # TWO NAMES FOR WHAT WAS ONE LINE, and #95 is the reason. `errored`
            # is what the MODEL sees: the "error: " prefix that makes a result
            # recoverable instead of terminal, which `DECLINED` carries on
            # purpose. `failed` is what the COUNTER means: a tool that
            # malfunctioned. A refusal the user made is the first and not the
            # second, and one predicate could not say so.
            errored = result.startswith("error: ")
            failed = errored and not declined
            if failed:
                key = (call["name"], call["arguments"])
                failures[key] = failures.get(key, 0) + 1
            cost.add_tool(took, failed, declined)
            events.tool_finished(call["name"], took, repeated)
            # BESIDE `tool_finished`, NOT INSIDE IT. The duration and the answer
            # are read by different surfaces -- a terminal wants the clock, a
            # panel wants the text -- and a `tool_failed` below already proves
            # the answer may travel this seam. Fires for a declined call too:
            # `DECLINED` is what the model was told, so it is what the screen
            # has to be able to show.
            events.tool_result(call["name"], result)
            # #311: AFTER THE RESULT, so the surface has closed the call's
            # tile before the picture lands where it belongs.
            for made in take_announced_images():
                getattr(events, "image_created", lambda *a: None)(
                    made["path"], made["source"], made["job"])
            for made in take_announced_videos():
                getattr(events, "video_created", lambda *a: None)(
                    made["path"], made["source"], made["job"])
            # #98: THE USER HEARS THIS FROM CROW, NOT FROM THE MODEL'S APOLOGY.
            # In the measured turn the only notice that the working area had been
            # left came from the model itself, after the fact, phrased as a
            # courtesy -- "mein Datei-Werkzeug ist beschraenkt, daher habe ich es
            # ueber die Shell angelegt". A client whose only account of its own
            # limits is the sentence of the thing that just went around them has
            # no account at all.
            #
            # AFTER THE CALL, NOT BEFORE: the marker is a report of what ran, and
            # a declined call ran nothing. `not declined` is therefore the
            # condition, not `not errored` -- a shell command that failed on its
            # own terms still reached the shell, and that is the fact being
            # reported.
            # #310: a call Stop ended DID reach the shell, so it still counts.
            ran = not declined or (not halted and result.startswith(STOPPED))
            if ran and escaped_the_working_area(call["name"]):
                # ONCE PER PATH, NOT PER CALL: the mark is a rare-event
                # report, and repeating it with unchanged content per shell
                # call trains the reader to skip it. A call that names
                # nothing new says nothing; a fresh refusal speaks again.
                fresh = sorted(p for p in _REFUSED if p not in escapes_said)
                if fresh:
                    escapes_said.update(fresh)
                    events.boundary_escaped(call["name"], fresh)
            # A FAILED CALL STAYS ON SCREEN even once the model has recovered from it (#70).
            # It is not the user's problem to solve, but it is the reason the turn took longer
            # than it looks like it should have, and a turn that hides its retries reads as
            # slower for no reason.
            #
            # THE SCREEN KEEPS THE WIDER OF THE TWO. A declined call is still
            # printed: that the delay was the user's own choice does not make it
            # less of a reason the turn went the way it did. Only the count
            # separates them, which is all #95 asked for.
            if errored:
                events.tool_failed(call["name"], result)
            # #170. WENN EIN BILD MITFAEHRT, IST DER INHALT EINE LISTE. Genau
            # die Blockform, die eine Nutzerzeile mit Bild seit #142 traegt --
            # der Server liest sie ROLLENUNABHAENGIG (server-common.cpp, die
            # Schleife ueber `messages` fragt nicht nach der Rolle), also sieht
            # das Modell das Bild in der naechsten Runde so, wie `/image` es
            # ihm zeigt. Und weil es die Wire-Form ist, ueberlebt sie
            # session.json und einen Neustart wie jede andere Zeile.
            #
            # DIE BLINDE MASCHINE WIRD HIER ABGEFANGEN, nicht im Werkzeug: die
            # Basis-URL steht in diesem Rahmen und nirgends sonst, und ein
            # Bildblock an einen Server ohne `--mmproj` ist kein Fehlversuch,
            # sondern ein HTTP 500, der den ganzen Zug kostet. Der Satz ist der
            # eine, den beide Oberflaechen schon sagen.
            # #175. DAS FENSTER ERFAEHRT, WAS DAS MODELL ANGESEHEN HAT. Ohne
            # das ist der Browser im Fenster leer, waehrend das Modell von
            # einer Seite erzaehlt -- gefragt vom Owner am 2026-08-31: "wieso
            # sieht man google nicht in seinem browser?".
            page = take_render_ride()
            if page is not None:
                events.page_rendered(page[0], page[1])
            ride = take_image_ride()
            if ride is not None:
                blind = refuse_images(base_url)
                if blind and call["name"] in IMAGE_TOOL_NAMES:
                    # #300 phase 3: THE PICTURE EXISTS, only the model cannot
                    # look at it. An "error: " here would tell it the
                    # generation failed and send it generating again.
                    result = (result.replace(IMAGE_HANDED, "")
                              .replace(VIDEO_HANDED, "")
                              + " It is not shown to you: " + blind)
                    conversation.append("tool", result, tool_call_id=call["id"])
                    continue
                if blind:
                    result = "error: " + blind
                    events.tool_failed(call["name"], result)
                    conversation.append("tool", result, tool_call_id=call["id"])
                    continue
                conversation.append(
                    "tool", [{"type": "text", "text": result}] + ride,
                    tool_call_id=call["id"])
                continue
            conversation.append("tool", result, tool_call_id=call["id"])
        events.tools_finished()
        # #310: THE ROUND IS WHOLE (every call answered), so a Stop ends the
        # turn HERE -- before the rollover's digest request and before the
        # next round's, neither of which anyone is waiting for.
        if INTERRUPT.is_set():
            if owns_turn_state:
                INTERRUPT.clear()
            events.turn_interrupted()
            stopped = True
            break

        # THE CHECK BELONGS HERE TOO, NOT ONLY BETWEEN TURNS. One tool round
        # has been measured adding 5,253 tokens, and up to MAX_TOOL_ROUNDS of
        # them run without the user typing anything. A turn that starts under
        # the threshold can still walk into the server's wall inside itself,
        # and the wall costs the whole turn.
        #
        # At the end of a round, never in the middle of one: the assistant
        # message and its tool results are both in by now, so what gets
        # archived is a conversation and not half of one.
        #
        # #263: OLD TOOL RESULTS GO FIRST, the cut stays the last resort. A
        # batch fires at 0.65 of the window by default and only when it frees
        # a tenth of it; below that this is a no-op that reads no file.
        context_tokens = clear_before_roll(conversation, context_tokens, n_ctx,
                                           remote=remote,
                                           forget_reads=owns_turn_state,
                                           served=served_name or model)
        if should_roll(context_tokens, n_ctx, rollover_at):
            if rolled:
                # Twice in one turn means the question itself does not fit.
                # Rolling again would archive the note and ask the same
                # thing again, forever.
                events.rollover_refused()
                stopped = True
                break
            # #154: VOR roll_over, solange der volle Praefix noch warm im
            # Server-Cache liegt -- danach ist dieselbe Frage ein 180k-Prefill.
            # #205: DIE REASONING-FELDER REISEN MIT, genau die, die der Zug
            # oben selbst bekommen hat -- ein Koerper ohne sie (oder mit dem
            # alten `enable_thinking: False`) rendert einen anderen Prompt
            # und schiesst den warmen Cache ab. Und `context_tokens`, dieselbe
            # Schaetzung, die `should_roll` hier bewertet, skaliert das
            # Timeout, damit ein kalter Praefix die Leg nicht mehr an einem
            # festen 120s-Wert sterben laesst.
            digest = rollover_digest(
                conversation, base_url=base_url, model=model, api_key=api_key,
                temperature=temperature, top_p=top_p, min_p=min_p, top_k=top_k,
                presence_penalty=presence_penalty,
                reasoning_effort=reasoning_effort,
                reasoning_budget=reasoning_budget,
                reasoning_budget_message=reasoning_budget_message,
                served_name=served_name,
                prompt_tokens=context_tokens,
                extra_headers=extra_headers,
                transport=transport, remote=remote, routing=routing,
                seeds=cost.leg_seeds)
            # #173: DIE MARKEN DES SCHREIBERS, wenn er welche fuehrt. Sie sind
            # eine Liste, die dem Aufrufer gehoert -- sie wandert ins Archiv und
            # wird DANN geleert, weil ihre Positionen Nachrichten zaehlen, die
            # es nach dem Schnitt nicht mehr gibt.
            archived = roll_over(conversation, base_url, context_tokens,
                                 carry=carry, digest=digest, notes=notes,
                                 timings=bills)
            # #163: der Kopf gilt weiter -- Gedaechtnis, Faehigkeiten, Ziel.
            # #210: MIT DEN MARKEN -- der Zug, der den Stand sagt, ist der,
            # der gerade weggeschnitten wurde; ohne sie im Kopf steht der
            # Stand nirgends (Messung 2026-09-22: drei Neu-Planungen).
            repin_head(conversation, get_root(), include_status=True)
            # #215-H: THE REST OF THIS TURN WRITES FROM THE NOTE, NOT FROM
            # WHAT WAS READ -- the reads went into the archive. `reset()` gave
            # the conversation a new epoch; adopting it empties the set now,
            # not at the next user line.
            if owns_turn_state:
                adopt_read_state(conversation)
            if archived:
                if notes is not None:
                    del notes[:]
                if bills is not None:
                    del bills[:]
                events.rolled_over(context_tokens, archived)
                context_tokens = 0
                rolled = True

        # #278: THE BUDGET IS SAID AFTER THE LAST TOOL ROUND, NOT ONE ROUND
        # LATE. Checked only at the start of a round, the round that spends
        # it was decoded in full -- reasoning and a call -- and then its call
        # was refused: 6 of 6 budget turns on 2026-09-24, 298-4,290 tokens
        # each, 11,240 tokens / 271 s of decode for nothing. The forced answer
        # now follows the last tool results directly. Budget 0 has no last
        # tool round and keeps the refusal above.
        if not forced and budget > 0 and round_no + 1 >= budget:
            events.budget_spent(budget)
            conversation.append("user", BUDGET_SPENT)
            forced = True

    return TurnResult(cost=cost, context_tokens=context_tokens,
                      promised_warm=promised_warm, rolled=rolled,
                      stopped=stopped, reported=reported, incidents=incidents)


# ----------------------------------------------------------- remote models

# A REMOTE ENDPOINT HAS NO SLOT, NO PREFIX CACHE AND NO OPERATING POINT. Every
# cache rule in this file belongs to llama-server -- SLOT_FILE and its save,
# `prefix_fingerprint`, `check_operating_point`, every "pays a full prefill"
# line. None of them describes a model somebody else is serving: there is no
# slot to keep warm, no /props to ask and no byte 0 that survives a turn. So a
# remote endpoint SAYS SO ONCE, where it is chosen, instead of leaving a screen
# full of local promises standing.
#
# WHAT IS DELIBERATELY NOT HERE: a price display. Whoever brings their own key
# knows their own costs (the owner, 2026-08-22), and a figure this client invents
# about somebody else's billing is one nobody can hold it to.
#
# THE FILE, beside `mcp.json` and `settings.json` because a provider binds the
# machine and not one conversation:
#
#   %LOCALAPPDATA%\Crow\providers.json
#   {"active": "openrouter",
#    "model": {"openrouter": "z-ai/glm-5.2:free"},   what was picked, PER provider
#    "catalog": {"openrouter": {"fetched": 1755, "models": [
#        {"id": "...", "name": "...", "context": 131072,
#         "params": ["tools", "temperature", ...]}]}}}
#
# `params` ARRIVED AFTER THE FILE DID, and it needs no migration: a catalogue
# written before it exists reads back as "did not say", which is the answer
# that asks for no filter. Same rule `context` already follows with 0.
PROVIDERS_FILE = os.path.join(crow_platform.config_dir(), "providers.json")

# Die Boot-Registry der Nacht vom 2026-08-28 -- der Kommentar steht bei
# `_BOOTED`, die Konstante hier, weil SESSION_DIR erst hier gebunden ist.
BOOTED_FILE = os.path.join(crow_platform.state_dir(), "booted.json")

# THE KEYS ARE NOT IN IT, and the reason is the one MCP_TOKEN_FILE already
# carries: `providers.json` is drawn by a sheet, pasted into bug reports and
# edited by hand. This one is written by Crow alone and leaves the process as a
# mask or not at all.
PROVIDER_KEYS_FILE = os.path.join(crow_platform.config_dir(), "provider_keys.json")

LOCAL_PROVIDER = "local"

# Anthropic's native endpoints refuse a request without it, and the value is a
# date rather than a number: it pins the request shape, so a client that stopped
# sending it would be asking for whatever is current.
ANTHROPIC_VERSION = "2023-06-01"

# WHAT AN OAUTH CREDENTIAL COSTS IN HEADERS, per provider. A pasted key needs
# none of this; a token minted by a sign-in is only accepted when the request
# says that is what it is carrying.
PROVIDER_OAUTH_HEADERS = {"anthropic": {"anthropic-beta": "oauth-2025-04-20"}}

# ORDERED, because the sheet draws it in this order: the machine first, then the
# one key that reaches everything else. Step 2 of the decided order -- direct
# keys per vendor -- adds entries HERE and nowhere else, which is the whole
# reason the shape is this thin. Step 4 -- OAuth per vendor -- adds a second way
# to fill the key, not a second way to choose a model.
#
# `catalog` IS A URL OR IT IS EMPTY, and empty is not a defect: a local server
# has one model open and says which in /props, so there is nothing to list.
PROVIDERS = {
    LOCAL_PROVIDER: {
        "label": "This machine",
        "base_url": DEFAULT_BASE_URL,
        "needs_key": False,
        "key_hint": "",
        "catalog": "",
        "blurb": "The llama-server on this box. Warm slot, no bill.",
    },
    "openrouter": {
        "label": "OpenRouter",
        "base_url": "https://openrouter.ai/api/v1",
        "needs_key": True,
        "key_hint": "sk-or-...",
        "catalog": "https://openrouter.ai/api/v1/models",
        "blurb": "One key, hundreds of models.",
        # THE ONLY BROKER HERE: one slug is served by many upstream companies,
        # and which one answers is otherwise decided per request by somebody
        # else. This is where a field that steers that choice would go.
        #
        # IT IS EMPTY, AND `require_parameters` IS WHY IT STAYS EMPTY. Measured
        # 2026-08-23 in the window, `nvidia/nemotron-3.5-lightning:free`, one
        # variable changed against a turn that had answered minutes earlier:
        #
        #   HTTP 404 -- "No endpoints found that can handle the requested
        #   parameters"
        #
        # The mechanism is documented and it is the whole point of the field:
        # by default an upstream that does not know a parameter IGNORES it, and
        # `require_parameters` turns that into an exclusion. Crow's body carried
        # `timings_per_token` and `chat_template_kwargs`, llama.cpp extensions
        # nobody outside llama.cpp supports, so requiring full support excluded
        # every upstream there is and the request never left OpenRouter.
        #
        # THE FIELD IS NOT WRONG, AND A STATIC ANSWER TO IT WOULD BE. Those two
        # fields are gone from a remote body now, and the flag still cannot live
        # here: measured the same day, 87 of 337 tool-capable models refuse
        # `temperature` or `top_p`, and for those the filter is the same 404
        # again. Whether it travels is a question about the MODEL, so it is
        # asked in `turn_routing` against what the catalogue declares. `filter`
        # below says only that asking is meaningful at this provider.
        "routing": {},
        # It reads `session_id` as a sticky routing key, and that one costs
        # nothing: it is metadata, not a constraint on who may answer.
        "sticky": True,
        # AND IT IS THE ONLY ENTRY THAT UNDERSTANDS `provider.require_parameters`,
        # because it is the only one with upstreams to choose between. Whether
        # the flag actually travels is decided per MODEL in `turn_routing`; this
        # says no more than that asking here is meaningful.
        "filter": True,
    },
    # THE OPENAI-SHAPED LAYER, NOT THE NATIVE API. Read as raw text on
    # 2026-08-22: `https://api.anthropic.com/v1/` answers `chat/completions`,
    # `authorization` is "fully supported", and so are `stream`, `stream_options`
    # and `tools`. So this is an ENTRY and not a second transport -- which the
    # native `/v1/messages` with its own body shape would have been.
    #
    # WHAT THE PAGE ALSO SAYS, and it belongs beside the entry rather than in a
    # release note: the layer exists to compare models, is not offered as a
    # production path, and prompt caching does not work through it. The last one
    # costs nothing here -- there is no cache on a remote endpoint anyway.
    #
    # `temperature` is capped at 1 and Crow sends exactly 1.0; `min_p` and
    # `timings_per_token` are not fields it knows and are ignored rather than
    # refused.
    "anthropic": {
        "label": "Anthropic",
        "base_url": "https://api.anthropic.com/v1",
        "needs_key": True,
        "key_hint": "sk-ant-...",
        "catalog": "https://api.anthropic.com/v1/models",
        "catalog_auth": "anthropic",
        # ITS OWN DIALECT, AND FOR BOTH CREDENTIAL KINDS. The OpenAI-shaped
        # layer at the same host takes an API key and is documented by Anthropic
        # as a way to compare models rather than a way to run on them -- and a
        # subscription token does not reach it at all. One transport for the
        # provider is one answer; one per credential kind would be two.
        "transport": TRANSPORT_MESSAGES,
        # `max_input_tokens` is where Anthropic reports the window; there is no
        # `context_length` field on that endpoint at all.
        "context_keys": ("max_input_tokens", "context_length"),
        "blurb": "Claude, on its own Messages API.",
        "sub_blurb": "Sign in with your Claude subscription.",
        "oauth": {},
    },
    "openai": {
        "label": "OpenAI",
        "base_url": "https://api.openai.com/v1",
        "needs_key": True,
        "key_hint": "sk-...",
        "catalog": "https://api.openai.com/v1/models",
        # ITS CATALOGUE REPORTS NO WINDOW, so every model off it carries 0 and
        # the bar stays off. That is the honest outcome of the rule one line
        # further down in `provider_context`, not an oversight here.
        "blurb": "GPT models, straight from the source.",
        "sub_blurb": "Sign in with your ChatGPT account.",
        # MEASURED 2026-08-22: auth.openai.com publishes an
        # openid-configuration with authorize and token endpoints. It publishes
        # NO registration_endpoint, so the client_id still has to be named.
        "oauth": {"issuer": "https://auth.openai.com"},
    },
}

# Said once, where the endpoint is chosen, in the form MEMORY_COST_NOTE has.
# NOT a second answer to "where did my context go" -- MODEL_SWITCH_NOTE is that
# answer and is reused for the switch itself. This one says the part that has no
# local equivalent at all.
#
# IT SPEAKS ABOUT CROW AND NOT ABOUT THE PROVIDER, and the first version did
# not. It said "no prefix cache", which is simply untrue of Anthropic -- prompt
# caching is one of that API's headline features, with its own breakpoints and
# its own `cache_read_input_tokens`. What is true is that CROW marks nothing
# for caching; the endpoint's own abilities are not this line's to describe. It
# also said "on your own key", which stops being true the moment a subscription
# is the credential.
#
# AND IT SAID "NOTHING IS KEPT WARM BETWEEN TURNS" UNTIL 2026-08-23. That was
# the same mistake a second time, and it survived because the inference looked
# sound: Crow sets no breakpoints, therefore nothing is warm. IT DOES NOT
# FOLLOW. An endpoint may cache without being asked -- OpenRouter's endpoint
# listing carries `supports_implicit_caching` per provider -- and `session_id`
# went into this client precisely to keep the turns of one chat on the upstream
# that holds that cache, "maximizing prompt cache hits" in their own words. The
# line was telling the user the opposite of what the client had just been built
# to do.
REMOTE_ENDPOINT_NOTE = ("a remote model has no slot here -- Crow marks nothing "
                        "for caching, and every turn sends the whole prompt "
                        "again")

# The catalog call. It is not a turn -- nobody is watching tokens per second --
# so it is seconds and not minutes.
PROVIDER_TIMEOUT = 20.0


def crow_agent() -> str:
    """How Crow signs an outgoing request.

    ITS OWN FUNCTION BECAUSE THE STRING DECIDES WHETHER A SERVER ANSWERS AT ALL.
    Measured 2026-08-22: `Python-urllib/3.13` gets HTTP 403 error 1010 from
    Cloudflare's MCP endpoint, and the identical client with this line gets 200.
    Naming yourself is not disguising yourself -- a tool that lies about where it
    came from cannot be rate-limited fairly, and a service that would rather not
    answer Crow may say so.
    """
    return "Crow/%s (+%s)" % (CLIENT_VERSION or "dev", REPO_URL)


def provider_doc(path: "str | None" = None) -> dict:
    """The providers document, or an empty one. Never raises."""
    try:
        with open(path or PROVIDERS_FILE, encoding="utf-8") as fh:
            doc = json.load(fh)
    except (OSError, ValueError):
        return {}
    return doc if isinstance(doc, dict) else {}


def provider_write(doc: dict, path: "str | None" = None) -> "str | None":
    """Write it back, then READ IT BACK. The reason it did not, or None.

    The read is not caution, it is the contract: a writer that never reads has
    only proved that `json.dump` did not raise.
    """
    target = path or PROVIDERS_FILE
    try:
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "w", encoding="utf-8") as fh:
            json.dump(doc, fh, indent=1)
    except OSError as exc:
        return "providers.json could not be written: %s" % exc
    if provider_doc(target) != doc:
        return "providers.json did not read back as it was written"
    return None


def provider_keys(path: "str | None" = None) -> dict:
    """Every stored key by provider. NEVER handed to a surface as it stands."""
    try:
        with open(path or PROVIDER_KEYS_FILE, encoding="utf-8") as fh:
            doc = json.load(fh)
    except (OSError, ValueError):
        return {}
    if not isinstance(doc, dict):
        return {}
    return {k: v for k, v in doc.items() if isinstance(v, str) and v}


def provider_key_set(name: str, key: str, path: "str | None" = None) -> "str | None":
    """Store or clear one key. The reason it failed, or None.

    AN EMPTY STRING CLEARS THE ENTRY rather than storing emptiness: a field a
    person blanked means "I am not using this one", and a stored "" would leave
    `needs_key` looking satisfied.
    """
    target = path or PROVIDER_KEYS_FILE
    doc = provider_keys(target)
    key = (key or "").strip()
    if key:
        doc[name] = key
    else:
        doc.pop(name, None)
    try:
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "w", encoding="utf-8") as fh:
            json.dump(doc, fh, indent=1)
        # Best effort, and the real answer is the ACL on %LOCALAPPDATA%. It
        # costs one call and is right on the systems where it means anything.
        try:
            os.chmod(target, 0o600)
        except OSError:
            pass
    except OSError as exc:
        return "provider_keys.json could not be written: %s" % exc
    if provider_keys(target).get(name, "") != key:
        return "provider_keys.json did not read back as it was written"
    return None


def provider_key_for(name: str, path: "str | None" = None) -> str:
    """The key for a provider, or "" -- including for one that needs none."""
    return provider_keys(path).get(name, "")


def provider_key_mask(key: str) -> str:
    """`sk-o...786c`, or "" for nothing at all.

    Four from each end. A mask exists so a person can tell WHICH key is in the
    box, not so they can read it back: anything longer starts being the secret.
    """
    key = (key or "").strip()
    if not key:
        return ""
    if len(key) <= 12:
        return "*" * len(key)
    return "%s...%s" % (key[:4], key[-4:])


def provider_models(name: str, doc: "dict | None" = None) -> list:
    """What this provider last said it serves. From disk, never the network.

    THE LIST IS NOT FETCHED AT START, for the reason `TOOLS` is not: a provider
    slow to answer would otherwise decide how long a window takes to open. It is
    fetched when a key lands and when a person asks, and it sits on disk between.
    """
    doc = provider_doc() if doc is None else doc
    block = (doc.get("catalog") or {}).get(name) or {}
    models = block.get("models")
    if not isinstance(models, list):
        return []
    return [m for m in models if isinstance(m, dict) and m.get("id")]


def provider_fetch_models(name: str, key: "str | None" = None,
                          timeout: float = PROVIDER_TIMEOUT,
                          kind: str = "key") -> "tuple[list, str | None]":
    """Ask the provider what it serves. (models, problem).

    THE SLUG IS COPIED WHOLE, SUFFIX AND ALL. OpenRouter's `:free` is not a
    label beside a model, it is part of the id -- `nvidia/nemotron-3-ultra-550b-
    a55b` and `...:free` are two entries with two bills, and a client that tidies
    the suffix away sends the paid twin. `:extended` is a DIFFERENT window under
    the same name; `:nitro` and `:floor` change which provider serves it.
    """
    spec = PROVIDERS.get(name) or {}
    url = spec.get("catalog") or ""
    if not url:
        return [], "%s does not publish a model list" % (spec.get("label") or name)
    headers = {"Accept": "application/json", "User-Agent": crow_agent()}
    # THE CATALOGUE IS NOT ALWAYS ON THE SAME DOOR AS THE CHAT. Anthropic's
    # OpenAI-shaped layer answers `chat/completions` with a bearer, while
    # `/v1/models` is the native API and wants `x-api-key` and a version -- one
    # provider, two dialects, and a client that assumed one of them gets a 401
    # from an endpoint it can otherwise talk to.
    if key and spec.get("catalog_auth") == "anthropic" and kind != "oauth":
        headers["x-api-key"] = key
        headers["anthropic-version"] = ANTHROPIC_VERSION
    elif key:
        headers["Authorization"] = "Bearer %s" % key
        if spec.get("catalog_auth") == "anthropic":
            headers["anthropic-version"] = ANTHROPIC_VERSION
            headers.update(PROVIDER_OAUTH_HEADERS.get(name) or {})
    try:
        request = urllib.request.Request(url, headers=headers, method="GET")
        with urllib.request.urlopen(request, timeout=timeout) as resp:
            doc = json.loads(resp.read().decode("utf-8") or "{}")
    except urllib.error.HTTPError as exc:
        return [], "HTTP %s from %s" % (exc.code, url)
    except Exception as exc:                # noqa: BLE001 - reported, never raised
        return [], "cannot reach %s: %s" % (url, exc)
    rows = doc.get("data") if isinstance(doc, dict) else None
    if not isinstance(rows, list):
        return [], "%s answered without a model list" % (spec.get("label") or name)
    models = []
    for row in rows:
        if not isinstance(row, dict) or not row.get("id"):
            continue
        # CONTEXT IS A DECLARED NUMBER HERE, not a measured one. /props reports
        # what a server actually allocated; this is what a catalogue claims.
        # 0 means the provider did not say, and 0 is what the bar reads as "no
        # bar" -- an invented limit is worse than none.
        window = 0
        for field in (spec.get("context_keys") or ("context_length",)):
            try:
                window = int(row.get(field) or 0)
            except (TypeError, ValueError):
                window = 0
            if window > 0:
                break
        models.append({"id": str(row["id"]),
                       "name": str(row.get("name") or row["id"]),
                       "context": window if window > 0 else 0,
                       # WHAT THIS SLUG ACCEPTS. Kept because `turn_routing`
                       # decides the parameter filter per model and cannot ask
                       # the network while a turn is being built. A catalogue
                       # that publishes no such field leaves this empty, and
                       # empty means nobody claimed anything.
                       "params": sorted(str(p) for p
                                        in (row.get("supported_parameters") or [])
                                        if isinstance(p, str))})
        # #266: WHETHER IT CAN SEE, as the catalogue declares it
        # (OpenRouter: `architecture.input_modalities`, 289 of 458 list
        # "image" on 2026-09-24). Absent means "did not say" -- the judge
        # tries such a model rather than guessing from its name (#142).
        arch = row.get("architecture") if isinstance(row.get("architecture"),
                                                     dict) else {}
        inputs = arch.get("input_modalities", row.get("input_modalities"))
        if isinstance(inputs, list):
            models[-1]["vision"] = "image" in inputs
    if not models:
        return [], "%s listed no models" % (spec.get("label") or name)
    return models, None


def provider_refresh(name: str) -> "str | None":
    """Fetch the catalog and keep it. The reason it failed, or None."""
    if name not in PROVIDERS:
        return "no provider called %s" % name
    credential, kind, problem = provider_credential(name)
    if problem:
        return problem
    models, problem = provider_fetch_models(name, credential, kind=kind)
    if problem:
        return problem
    doc = provider_doc()
    catalog = doc.get("catalog")
    if not isinstance(catalog, dict):
        catalog = {}
    catalog[name] = {"fetched": int(time.time()), "models": models}
    doc["catalog"] = catalog
    return provider_write(doc)


def provider_model_for(name: str, doc: "dict | None" = None) -> str:
    """The slug picked for this provider, or "" if none was."""
    doc = provider_doc() if doc is None else doc
    picked = doc.get("model")
    if not isinstance(picked, dict):
        return ""
    value = picked.get(name)
    return value.strip() if isinstance(value, str) else ""


def provider_pick(name: str, model: "str | None" = None) -> "str | None":
    """Choose the provider, and the model on it. The problem, or None.

    THE MODEL IS REMEMBERED PER PROVIDER, not once for all of them. A slug is
    the property of whoever serves it: switching to the machine and back must
    not leave `z-ai/glm-5.2:free` standing in front of llama-server, and must not
    lose it either.
    """
    if name not in PROVIDERS:
        return "no provider called %s" % name
    # THE SWITCH IS THE OUTER DOOR: a parked broker refuses the turn pick
    # before the key question is even asked, and the sentence names the one
    # control that changes the answer.
    if name == "openrouter" and not openrouter_on():
        return OPENROUTER_OFF_NOTE
    # A LOGIN COUNTS AS A KEY. Refusing a provider somebody just signed in to,
    # because the key box beside it is empty, would be the sheet answering a
    # question nobody asked.
    if PROVIDERS[name]["needs_key"] and not (provider_key_for(name)
                                             or provider_signed_in(name)
                                             or provider_borrowing(name)):
        return "%s needs a key or a sign-in first" % PROVIDERS[name]["label"]
    doc = provider_doc()
    doc["active"] = name
    if model is not None:
        _model_into(doc, name, model)
    return provider_write(doc)


def _model_into(doc: dict, name: str, model: str) -> None:
    """Write one provider's slug into the doc, or clear it with ""."""
    picked = doc.get("model")
    if not isinstance(picked, dict):
        picked = {}
    model = (model or "").strip()
    if model:
        picked[name] = model
    else:
        picked.pop(name, None)
    doc["model"] = picked


def provider_model_set(name: str, model: str) -> "str | None":
    """Remember a provider's slug WITHOUT routing turns there. Problem or None.

    THE BROKER PAGE WRITES THROUGH THIS: picking a model there configures the
    subsystem -- a free pick is what the delegate default reads -- and where a
    turn goes is a different control's answer. `provider_pick` remains the one
    mover of turns; a second one would be a second answer to the same question.
    """
    if name not in PROVIDERS:
        return "no provider called %s" % name
    doc = provider_doc()
    _model_into(doc, name, model)
    return provider_write(doc)


# des Owners Regel vom 2026-08-28, aus dem laufenden Fenster heraus angesagt:
# Aktiviert man OpenRouter, darf sich lokal NICHT abschalten -- beide laufen
# parallel. The broker got its own page in the sheet for exactly this reason:
# its switch says whether the SUBSYSTEM is in operation -- delegation,
# catalogue, favourites -- and never where a turn goes.
#
# ABSENT MEANS ON: every providers.json written before this build keeps
# delegating exactly as it did, and the file stays clean until somebody parks.
OPENROUTER_OFF_NOTE = ("OpenRouter is switched off -- the OpenRouter page in "
                       "Settings turns it back on")


def openrouter_on(doc: "dict | None" = None) -> bool:
    """Whether the broker is in operation. Absent means on."""
    doc = provider_doc() if doc is None else doc
    return doc.get("openrouter_on") is not False


def openrouter_set(on: bool) -> "str | None":
    """Park or unpark the broker. The problem, or None.

    ON MOVES NO TURN -- that is the whole rule. OFF is the one direction that
    may touch `active`, and it only brings turns home: a parked broker cannot
    keep them, and the machine is always there.
    """
    doc = provider_doc()
    if on:
        doc.pop("openrouter_on", None)
    else:
        doc["openrouter_on"] = False
        if doc.get("active") == "openrouter":
            doc["active"] = LOCAL_PROVIDER
    return provider_write(doc)


def provider_active(doc: "dict | None" = None) -> str:
    """Which provider is chosen. LOCAL_PROVIDER for anything this build lacks.

    A file naming a provider that was removed is not an error worth a message:
    it is a value this build does not have, and the answer to that is the one it
    does have -- the machine, which is always there. A file naming the PARKED
    broker takes the same road home: off means off, however the file got there.

    THERE IS NO TURNS OVERLAY -- des Owners dritter Brueller vom 2026-08-28 abends
    zog den zweiten zurueck: die Broker-Seite routet GAR NICHTS, default ist
    immer lokal, bis der User auf der Model-Seite etwas anderes waehlt. An
    `openrouter_turns` key the one build that had one may have left in the
    file is an unknown key like any other: read by nobody, routing nothing.
    """
    doc = provider_doc() if doc is None else doc
    name = doc.get("active")
    if name == "openrouter" and not openrouter_on(doc):
        return LOCAL_PROVIDER
    return name if name in PROVIDERS else LOCAL_PROVIDER


def provider_headers(name: str, kind: str, credential: str) -> dict:
    """What this provider wants on top of the transport's own headers.

    THE CREDENTIAL DECIDES THE SPELLING, not the provider. Anthropic takes an
    API key as `x-api-key` and an OAuth token as `Authorization: Bearer` with a
    beta flag beside it; the same endpoint, two ways of saying who is asking,
    and sending both is a request with two opinions.
    """
    spec = PROVIDERS.get(name) or {}
    head = {}
    if spec.get("transport") == TRANSPORT_MESSAGES:
        head["anthropic-version"] = ANTHROPIC_VERSION
    if kind == "oauth":
        head.update(PROVIDER_OAUTH_HEADERS.get(name) or {})
    elif kind == "key" and spec.get("catalog_auth") == "anthropic" and credential:
        head["x-api-key"] = credential
    return head


def provider_endpoint(fallback_base_url: str = "", fallback_model: str = "",
                      fallback_key: str = "") -> dict:
    """Where a turn goes, and it is the ONLY answer to that question.

    BOTH CALL PATHS READ THIS ONE. `stream_reply` is the visible one;
    `review_turn` is the one that runs without being asked, with its own body and
    its own Authorization header. A change that reaches only the first leaves the
    background pass talking to whatever the command line said -- which, once a
    key is involved, is a request nobody chose to send.

    THE FALLBACKS ONLY REACH THE LOCAL PROVIDER. A remote endpoint's URL and key
    come from the file, never from an argument somebody typed months ago.
    """
    doc = provider_doc()
    name = provider_active(doc)
    spec = PROVIDERS[name]
    model = provider_model_for(name, doc)
    # THE CAP TRAVELS WITH THE ENDPOINT, because that is what decides whether
    # one exists at all: a provider reserves and prices the maximum when the
    # body names none, and the local server neither reserves nor bills.
    if name == LOCAL_PROVIDER:
        return {"provider": name, "label": spec["label"], "remote": False,
                "base_url": fallback_base_url or spec["base_url"],
                "model": model or fallback_model or DEFAULT_MODEL,
                "api_key": fallback_key or "local-no-provider", "headers": {},
                "transport": TRANSPORT_CHAT,
                "routing": {}, "sticky": False, "filter": False, "params": []}
    credential, kind, _problem = provider_credential(name)
    return {"provider": name, "label": spec["label"], "remote": True,
            "base_url": spec["base_url"], "model": model,
            "api_key": credential,
            "headers": provider_headers(name, kind, credential),
            "transport": spec.get("transport") or TRANSPORT_CHAT,
            # BODY FIELDS ONLY THIS ENDPOINT UNDERSTANDS, and empty for every
            # entry but the broker. It travels with the endpoint for the same
            # reason the cap does: it is a fact about where the turn goes, and a
            # second place deciding it would be a second answer.
            "routing": _routing_copy(spec.get("routing") or {}),
            "sticky": bool(spec.get("sticky")),
            # THE TWO HALVES OF THE PARAMETER FILTER, read here because this is
            # where the model is already known and the catalogue is already
            # open. `turn_routing` decides; it does not go looking.
            "filter": bool(spec.get("filter")),
            "params": provider_params(name, model, doc)}


def _routing_copy(block: dict) -> dict:
    """A fresh dict per turn, two levels deep.

    `PROVIDERS` is module state. A caller that merged `session_id` into the
    entry itself would leave it there for every later turn -- including the
    ones belonging to a different chat, which is the exact fault the key exists
    to prevent.
    """
    return {k: (dict(v) if isinstance(v, dict) else v) for k, v in block.items()}


def sticky_key(session_path: "str | None") -> str:
    """One chat, one routing key. Empty when there is no chat file.

    OpenRouter's API reference, read 2026-08-23: `session_id` is used "as a
    sticky routing key to direct all requests in the session to the same
    provider, maximizing prompt cache hits", with a limit of 256 characters.
    Without one, two turns of the same conversation may be answered by two
    different upstream companies, and nothing either of them cached can hold.

    IT IS A HASH AND NOT THE PATH, and that is the whole reason this is a
    function. A chat path is `%USERPROFILE%\\...` -- sending it would
    hand a stranger's name and directory layout to a third party on every
    request, to identify something only this client needs to tell apart. A
    digest is stable, is 64 characters against a documented 256, and says
    nothing about the machine it came from.

    AN UNSAVED CHAT HAS NO IDENTITY, so it gets no key rather than a shared one:
    an empty string is a value the endpoint would take literally, and every
    unsaved chat would then be one session.
    """
    import hashlib
    if not session_path:
        return ""
    settled = os.path.normcase(os.path.abspath(str(session_path)))
    return hashlib.sha256(settled.encode("utf-8")).hexdigest()


def turn_routing(spot: dict, session_path: "str | None" = "") -> dict:
    """The extra body fields for one turn. BOTH SENDERS READ THIS ONE.

    `stream_reply` is the visible sender; `review_turn` is the one that runs
    without being asked. Hermes shipped this half-missing and fixed it as their
    #70820: their auxiliary call sites passed no key, so each of them routed
    away from the conversation it belonged to. The review is exactly that shape
    here -- same chat, own body, nobody watching -- so it must carry the same
    key or it is a second session inside the first.

    Today the block is the key and nothing else. The static half exists and is
    empty on purpose -- see the OpenRouter entry in `PROVIDERS` for the 404 that
    emptied it.
    """
    block = _routing_copy(spot.get("routing") or {})
    if spot.get("sticky"):
        key = sticky_key(session_path)
        if key:
            block["session_id"] = key
    # THE FILTER IS A QUESTION ABOUT THE MODEL, NOT ABOUT THE PROVIDER, and that
    # is the whole reason it can be asked at all. Measured 2026-08-23 at
    # openrouter.ai: of 337 tool-capable models, 250 accept everything a remote
    # body carries and 87 refuse `temperature` or `top_p` -- the current
    # reasoning models, claude-opus-5 and claude-sonnet-5 among them. Set for
    # everybody, the flag takes those 87 off this client with HTTP 404 on every
    # turn. Set where the catalogue says it holds, it costs nobody anything and
    # prevents the fault it exists for: an upstream without tool support DROPS
    # `tools` and answers anyway, so the model looks like it forgot it can
    # search, remember or reach an MCP server, with nothing on screen saying why.
    #
    # AN EMPTY LIST ASKS FOR NOTHING. "The catalogue did not say" is not "it
    # supports everything", and a filter built on a guess is the 404 again.
    if spot.get("filter"):
        declared = set(spot.get("params") or ())
        if declared.issuperset(_REMOTE_BODY_PARAMETERS):
            block["provider"] = {"require_parameters": True}
    return block


def provider_context(name: str, model: str, doc: "dict | None" = None) -> int:
    """The declared window for one slug, or 0 when nobody declared one.

    0 IS A REAL ANSWER AND NOT A FAILURE, the same one `fetch_n_ctx` gives when a
    server will not say. `should_roll` and `review_due` already read 0 as "the
    server would not say" rather than "no room left", so a provider that lists no
    context degrades into a count without a bar and changes nothing else.

    NO 128K DEFAULT. Hermes' detection chain ends in one, and it is exactly the
    failure this split exists to avoid: a client that measures locally and
    guesses remotely, with nothing on screen saying which it just did.
    """
    if not model:
        return 0
    for row in provider_models(name, doc):
        if row.get("id") == model:
            try:
                window = int(row.get("context") or 0)
            except (TypeError, ValueError):
                return 0
            return window if window > 0 else 0
    return 0


def provider_params(name: str, model: str, doc: "dict | None" = None) -> list:
    """What the catalogue says one slug accepts, or nothing when it did not say.

    AN EMPTY LIST IS NOT "ACCEPTS NOTHING", and reading it that way would be the
    same mistake `provider_context` avoids by refusing a 128k default: it is the
    absence of a claim. Nothing is claimed, so nothing may be required of an
    upstream on the strength of it.
    """
    if not model:
        return []
    for row in provider_models(name, doc):
        if row.get("id") == model:
            params = row.get("params")
            return [str(p) for p in params] if isinstance(params, list) else []
    return []


def provider_view() -> dict:
    """What the sheet draws. Keys appear as masks and never as themselves."""
    doc = provider_doc()
    rows = []
    for name, spec in PROVIDERS.items():
        key = provider_key_for(name)
        models = provider_models(name, doc)
        rows.append({"name": name, "label": spec["label"], "blurb": spec["blurb"],
                     "remote": name != LOCAL_PROVIDER,
                     "needs_key": spec["needs_key"], "key_hint": spec["key_hint"],
                     "key": provider_key_mask(key), "has_key": bool(key),
                     "signed_in": provider_signed_in(name),
                     "borrowing": provider_borrowing(name, doc),
                     "listable": bool(spec["catalog"]), "models": models,
                     "model": provider_model_for(name, doc), "count": len(models)})
    return {"active": provider_active(doc), "providers": rows,
            "subscriptions": provider_subscriptions(),
            # #148: what the favourites dropdowns preselect.
            "delegate_favorites": delegate_favorites(doc),
            # The broker page's switch state (2026-08-28). Absent means on.
            "openrouter_on": openrouter_on(doc),
            "file": PROVIDERS_FILE, "note": REMOTE_ENDPOINT_NOTE}


# ------------------------------------------------------- subscriptions (OAuth)

# NEITHER PROVIDER LETS THIS CLIENT REGISTER ITSELF. Measured 2026-08-22 against
# the endpoints, not read anywhere:
#
#   claude.ai, api.anthropic.com, console.anthropic.com
#       /.well-known/oauth-authorization-server   404
#       /.well-known/openid-configuration         404
#   auth.openai.com
#       /.well-known/openid-configuration         200, authorize + token present,
#                                                 registration_endpoint  null
#
# So the browser leg is buildable -- every piece of it already exists for MCP --
# and the ONE thing missing is a `client_id`. Crow answers that the way it
# already answers it for an MCP server with no dynamic registration: the value
# comes out of the configuration, named, and until it is there the tile says so
# instead of opening a login that comes back 400.
#
# WHAT IS NOT DONE HERE: sending somebody else's `client_id`. A client that
# presents itself as another product to get past a registration it was never
# granted is the disguise half of the line this codebase already draws at
# `User-Agent` -- naming yourself is not dressing up as somebody else. If that
# is wanted it is a value a person puts in the file knowingly, not a constant
# this file ships.
PROVIDER_TOKEN_FILE = os.path.join(crow_platform.config_dir(), "provider_tokens.json")

# Refresh this many seconds before expiry, and the reason is MCP_TOKEN_SKEW's:
# a token valid when the request is built and stale when it arrives is the
# failure a margin exists for.
PROVIDER_TOKEN_SKEW = 60.0

# How long the browser leg may take. A person is reading a consent screen.
PROVIDER_OAUTH_WAIT = 300.0

# Said where a tile cannot open a browser, and it names the file and the key
# rather than the concept -- the same shape the MCP path answers with.
PROVIDER_NO_CLIENT = ("%s does not let a client register itself, so it needs a "
                      "client_id. Put one in providers.json under "
                      "oauth.%s.client_id")


# THE SANCTIONED WAY IN, and it is neither a browser leg nor a borrowed session.
# `claude setup-token` is documented as "generate a long-lived OAuth token for CI
# and scripts. Prints the token to the terminal without saving it. Requires a
# Claude subscription" -- a credential the subscriber mints FOR another program,
# which is exactly what Crow is here. Claude Code itself stores it under the name
# below when it wires up GitHub Actions, and Hermes' own sign-in dialog does the
# same thing: it prints this command and waits.
#
# WHAT IT REPLACES: nothing had to be invented after all. No client_id borrowed
# from another product, no refresh of somebody else's grant, no reading a session
# store that was refused anyway -- measured 2026-08-23, a borrowed Claude Code
# session token authenticated at `/v1/messages` and came back 429 with a body
# that named no limit, while the account's own five-hour window stood at 7 %.
PROVIDER_SETUP = {
    "anthropic": {"command": "claude setup-token",
                  "env": "CLAUDE_CODE_OAUTH_TOKEN",
                  "hint": "sk-ant-oat..."},
}


def provider_setup_env(name: str) -> str:
    """A subscription token handed over by the environment, or "".

    THE SAME NAME CLAUDE CODE USES for it, so a machine that already exports one
    for CI needs nothing typed here at all.
    """
    spec = PROVIDER_SETUP.get(name) or {}
    return (os.environ.get(spec.get("env") or "") or "").strip()


def provider_token_paste(name: str, token: str) -> "str | None":
    """Keep a pasted subscription token. The problem, or None.

    NO REFRESH TOKEN AND NO EXPIRY, because that is what "long-lived" means: it
    is minted once and used until the person revokes it. Storing an expiry this
    client invented would put a deadline on a credential that has none.
    """
    if name not in PROVIDER_SETUP:
        return "%s has no setup command" % name
    token = (token or "").strip()
    doc = provider_tokens()
    if not token:
        doc.pop(name, None)
        return provider_token_write(doc)
    doc[name] = {"access_token": token, "source": "setup-token"}
    return provider_token_write(doc)


def provider_oauth_block(name: str, doc: "dict | None" = None) -> dict:
    """What is known about a provider's login: the built-in half plus the file.

    THE FILE WINS, because everything the built-in half can carry was measured
    against a public endpoint and everything it cannot -- the `client_id` above
    all -- is a value only the person running this has.
    """
    spec = (PROVIDERS.get(name) or {}).get("oauth") or {}
    doc = provider_doc() if doc is None else doc
    theirs = (doc.get("oauth") or {}).get(name)
    block = dict(spec)
    if isinstance(theirs, dict):
        for key, value in theirs.items():
            if isinstance(value, str) and value.strip():
                block[key] = value.strip()
    return block


# WHERE ANOTHER PROGRAM'S SIGN-IN LIVES, and every one of these is a PATTERN
# rather than a value: the home directory is expanded at call time, so no path
# belonging to whoever runs this is written down here, and nothing out of these
# files is ever copied into Crow's own.
#
# READ, NEVER WRITTEN, AND NEVER REFRESHED. The refresh token in these stores
# belongs to the program that owns them; spending it would rotate the credential
# the other product is still using and could sign a person out of the tool they
# were working in. An expired borrowed token is therefore reported and not
# repaired -- the owning program refreshes it the next time it runs.
#
# WHAT IT MEANS ON THE WIRE, said once here because it is the whole trade: a
# request authenticated this way carries a grant issued to that other product.
# Nothing is registered under a false name and no new grant is created, but the
# provider sees that grant. It happens only when somebody switches it on.
PROVIDER_BORROW = {
    "anthropic": {"product": "Claude Code",
                  "path": ("~", ".claude", ".credentials.json"),
                  "block": "claudeAiOauth", "token": "accessToken",
                  "expires": "expiresAt", "unit": 1000.0},
}

# WHY CODEX IS NOT IN THAT TABLE, and it was for one build. `~/.codex/auth.json`
# holds an access token, and borrowing it looked like the same trade as Claude
# Code's. Measured 2026-08-23 the moment it was switched on: `GET
# https://api.openai.com/v1/models` answers **HTTP 403**, not 401 -- the request
# authenticates and is then refused the resource, which is what a token for a
# different audience looks like. That token belongs to the ChatGPT backend
# Codex talks to; the platform API at api.openai.com wants an `sk-...` key from
# a billing account, and no header turns one into the other. Hermes carries the
# same split as two separate providers, `openai-codex` beside `openai-api`.
#
# A CODEX PROVIDER WOULD BE ITS OWN ENTRY with its own base URL, and that URL is
# not written here because nobody has measured it. A tile that said "signed in"
# while every turn came back 403 is the failure this line exists to prevent.


def provider_borrow_path(name: str) -> str:
    """Where that provider's other sign-in would be, expanded. "" if none."""
    spec = PROVIDER_BORROW.get(name)
    if not spec:
        return ""
    parts = list(spec["path"])
    root = os.path.expanduser(parts[0]) if parts[0] == "~" else parts[0]
    return os.path.join(root, *parts[1:])


def provider_borrow_seen(name: str) -> bool:
    """Whether such a store exists at all. Says nothing about what is in it."""
    target = provider_borrow_path(name)
    return bool(target) and os.path.isfile(target)


def provider_borrowed(name: str) -> "tuple[str, str | None]":
    """The token another program holds. (token, problem), and it never writes.

    THE FILE IS OPENED FOR THE ONE FIELD IT IS ASKED FOR. Everything else in it
    -- and these stores hold plenty -- is not read into any structure this
    process keeps, is never logged, and never reaches a view.

    A STALE `expiresAt` IS NOT A VETO, and that was wrong for one build.
    Measured 2026-08-23: the field said 00:11, the clock said 00:49, and the file
    had not been written since 21:41 -- while the program that owns it was
    running the whole time. The timestamp is another program's bookkeeping, and
    the authority on whether a credential still works is the provider that
    issued it. So the token is handed over and the staleness is SAID; a refusal
    here turns "probably expired" into "certainly unusable" on evidence that is
    second-hand. `provider_borrowed_stale` is what a surface asks.
    """
    spec = PROVIDER_BORROW.get(name)
    if not spec:
        return "", "%s has no sign-in to borrow" % name
    target = provider_borrow_path(name)
    if not os.path.isfile(target):
        return "", "no %s sign-in on this machine" % spec["product"]
    try:
        with open(target, encoding="utf-8") as fh:
            doc = json.load(fh)
    except (OSError, ValueError) as exc:
        return "", ("%s's sign-in could not be read (%s)"
                    % (spec["product"], type(exc).__name__))
    block = doc.get(spec["block"])
    token = (block or {}).get(spec["token"]) if isinstance(block, dict) else None
    if not isinstance(token, str) or not token:
        return "", "%s is not signed in" % spec["product"]
    return token, None


def provider_borrowed_stale(name: str) -> str:
    """The line to show when the borrowed token looks past its date, or "".

    NOT REPAIRED, EVER. The refresh token in that file is the other product's,
    and spending it would rotate the credential that program is still using.
    """
    spec = PROVIDER_BORROW.get(name)
    if not spec or not spec["expires"] or not spec["unit"]:
        return ""
    try:
        with open(provider_borrow_path(name), encoding="utf-8") as fh:
            block = (json.load(fh) or {}).get(spec["block"]) or {}
    except (OSError, ValueError):
        return ""
    due = block.get(spec["expires"]) if isinstance(block, dict) else None
    if isinstance(due, (int, float)) and due / spec["unit"] <= time.time():
        return ("%s's sign-in looks expired -- open %s once and it refreshes "
                "itself" % (spec["product"], spec["product"]))
    return ""


def provider_borrowing(name: str, doc: "dict | None" = None) -> bool:
    """Whether this machine's other sign-in is switched on for that provider.

    A FLAG FOR A PROVIDER THIS BUILD CANNOT BORROW FROM IS NOT A STATE. Codex
    was in that table for one build and came out of it after a measured 403; a
    file switched on back then must not leave the resolver reaching for a store
    it no longer knows -- it falls through to the key, which is the answer this
    build has.
    """
    if name not in PROVIDER_BORROW:
        return False
    doc = provider_doc() if doc is None else doc
    return bool((doc.get("borrow") or {}).get(name))


def provider_borrow_set(name: str, on: bool) -> "str | None":
    """Switch it on or off. The problem, or None.

    ON IS A DECISION AND IT IS TAKEN ONCE, in the sheet, by a person who is told
    what it means. Nothing switches it on by finding a file.
    """
    if name not in PROVIDER_BORROW:
        return "%s has no sign-in to borrow" % name
    if on:
        _token, problem = provider_borrowed(name)
        if problem:
            return problem
    doc = provider_doc()
    block = doc.get("borrow")
    if not isinstance(block, dict):
        block = {}
    if on:
        block[name] = True
    else:
        block.pop(name, None)
    doc["borrow"] = block
    return provider_write(doc)


def provider_oauth_set(name: str, fields: dict) -> "str | None":
    """Put a login's missing halves in the file. The problem, or None.

    THE SHEET WRITES THIS AND NOT A PERSON WITH AN EDITOR. The values are the
    ones no endpoint would hand over -- neither provider publishes a
    registration document -- so they have to be typed once; asking somebody to
    find `providers.json` to do it is a control that exists only in a sentence.

    AN EMPTY FIELD CLEARS ITS KEY rather than storing emptiness, the same rule
    `provider_key_set` follows: a box somebody blanked means "not this one", and
    a stored "" would read as a value.
    """
    if name not in PROVIDERS:
        return "no provider called %s" % name
    doc = provider_doc()
    block = doc.get("oauth")
    if not isinstance(block, dict):
        block = {}
    mine = dict(block.get(name) or {})
    for key in ("client_id", "authorize", "token", "scope", "client_secret"):
        if key not in fields:
            continue
        value = str(fields.get(key) or "").strip()
        if value:
            mine[key] = value
        else:
            mine.pop(key, None)
    if mine:
        block[name] = mine
    else:
        block.pop(name, None)
    doc["oauth"] = block
    return provider_write(doc)


def provider_tokens(path: "str | None" = None) -> dict:
    """Every stored token by provider. NEVER handed to a surface as it stands."""
    try:
        with open(path or PROVIDER_TOKEN_FILE, encoding="utf-8") as fh:
            doc = json.load(fh)
    except (OSError, ValueError):
        return {}
    return doc if isinstance(doc, dict) else {}


def provider_token_write(doc: dict, path: "str | None" = None) -> "str | None":
    target = path or PROVIDER_TOKEN_FILE
    try:
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "w", encoding="utf-8") as fh:
            json.dump(doc, fh, indent=1)
        try:
            os.chmod(target, 0o600)
        except OSError:
            pass
    except OSError as exc:
        return "provider_tokens.json could not be written: %s" % exc
    if provider_tokens(target) != doc:
        return "provider_tokens.json did not read back as it was written"
    return None


def provider_token_drop(name: str) -> "str | None":
    """Sign out of one provider. The reason it failed, or None."""
    doc = provider_tokens()
    if name not in doc:
        return None
    doc.pop(name, None)
    return provider_token_write(doc)


def provider_signed_in(name: str) -> bool:
    """Whether a login is on disk. Says nothing about whether it still works."""
    return bool((provider_tokens().get(name) or {}).get("access_token"))


def provider_refresh_token(name: str) -> "str | None":
    """Trade the refresh token for a fresh access token. The problem, or None.

    A PROVIDER THAT ISSUED NO REFRESH TOKEN IS NOT A FAILURE -- it is a login
    that runs out, and the honest answer to that is the tile saying so, not a
    silent retry loop against an endpoint that will keep refusing.
    """
    record = provider_tokens().get(name) or {}
    refresh = record.get("refresh_token")
    if not refresh:
        return "%s issued no refresh token -- sign in again" % name
    meta = {"token_endpoint": record.get("token_endpoint") or ""}
    if not _oauth_safe(meta["token_endpoint"]):
        return "%s has no token endpoint on file -- sign in again" % name
    form = {"grant_type": "refresh_token", "refresh_token": refresh,
            "client_id": record.get("client_id") or ""}
    if record.get("scope"):
        form["scope"] = record["scope"]
    answer, problem = _oauth_exchange(meta, form)
    if problem:
        return problem
    doc = provider_tokens()
    kept = dict(doc.get(name) or {})
    kept["access_token"] = answer["access_token"]
    # THE OLD REFRESH TOKEN IS KEPT WHEN THE ANSWER CARRIES NONE. Overwriting it
    # with an empty value would turn every future refresh into a browser leg.
    if answer.get("refresh_token"):
        kept["refresh_token"] = answer["refresh_token"]
    try:
        kept["expires_at"] = time.time() + float(answer.get("expires_in"))
    except (TypeError, ValueError):
        kept.pop("expires_at", None)
    doc[name] = kept
    return provider_token_write(doc)


def provider_credential(name: str) -> "tuple[str, str, str | None]":
    """(value, kind, problem). `kind` is "oauth", "key" or "".

    A LOGIN OUTRANKS A PASTED KEY, because a person who signed in meant to use
    the subscription they signed in with -- and a key left in the box from last
    week would quietly spend money instead.

    THE KIND TRAVELS WITH THE VALUE and is not derived from it later. A token
    and a key are the same shape on the wire; only the caller that resolved them
    knows which one it holds, and the headers differ.
    """
    record = provider_tokens().get(name) or {}
    token = record.get("access_token")
    if token:
        due = record.get("expires_at")
        if isinstance(due, (int, float)) and due - PROVIDER_TOKEN_SKEW <= time.time():
            problem = provider_refresh_token(name)
            if problem:
                return "", "oauth", problem
            token = (provider_tokens().get(name) or {}).get("access_token") or ""
        return str(token), "oauth", None
    # THEN THE ENVIRONMENT, under the name Claude Code gives it. A machine that
    # already exports one for CI is a machine that has already answered this
    # question, and asking again would be a second place for the same fact.
    token = provider_setup_env(name)
    if token:
        return token, "oauth", None
    # AND ONLY THEN A BORROWED SESSION. It is last among the OAuth sources
    # because it is the one that was refused: measured 2026-08-23, 429 from
    # `/v1/messages` with no limit named and the account's own window at 7 %.
    if provider_borrowing(name):
        token, problem = provider_borrowed(name)
        if problem:
            return "", "oauth", problem
        return token, "oauth", None
    key = provider_key_for(name)
    if key:
        return key, "key", None
    return "", "", None


def provider_authorise(name: str) -> "str | None":
    """The whole browser flow for one provider. None when it worked.

    EVERY PIECE OF THIS ALREADY EXISTED for MCP -- PKCE, the loopback catcher,
    the browser, the metadata check, the exchange. What is new is only where the
    endpoints come from: an MCP server hands them over in its own metadata,
    while these two are named in the configuration because neither publishes a
    document this client is allowed to register against.

    NO `resource`. RFC 8707 binds a token to the API it was issued for, and the
    MCP path sends it because the specification requires it there. Here there is
    no resource identifier to send: asking for a token bound to a name nobody
    published would be this client inventing an audience.
    """
    if name not in PROVIDERS:
        return "no provider called %s" % name
    block = provider_oauth_block(name)
    client_id = block.get("client_id")
    if not client_id:
        return PROVIDER_NO_CLIENT % (PROVIDERS[name]["label"], name)

    issuer = block.get("issuer") or ""
    if issuer:
        meta, problem = _oauth_server_metadata(issuer)
        if problem:
            return problem
    else:
        # NAMED BY HAND, AND CHECKED THE SAME WAY. `_oauth_safe` is what keeps a
        # typo in a config file from sending a consent screen to plain http or
        # to something that is not a URL at all.
        meta = {"authorization_endpoint": block.get("authorize") or "",
                "token_endpoint": block.get("token") or ""}
        for field, key in (("authorization_endpoint", "authorize"),
                           ("token_endpoint", "token")):
            if not _oauth_safe(meta[field]):
                return ("%s has no usable %s -- put one in providers.json under "
                        "oauth.%s.%s" % (PROVIDERS[name]["label"], key, name, key))

    listener, redirect = _oauth_listen(block.get("redirect_host") or "127.0.0.1")
    try:
        verifier, challenge = _oauth_pkce()
        state = _oauth_state()
        query = {"response_type": "code", "client_id": client_id,
                 "redirect_uri": redirect, "state": state,
                 "code_challenge": challenge, "code_challenge_method": "S256"}
        if block.get("scope"):
            query["scope"] = block["scope"]
        where = (meta["authorization_endpoint"]
                 + ("&" if "?" in meta["authorization_endpoint"] else "?")
                 + urllib.parse.urlencode(query))
        _oauth_open(where)
        if not listener.done.wait(PROVIDER_OAUTH_WAIT):
            return ("nobody finished the sign-in for %s within %gs"
                    % (PROVIDERS[name]["label"], PROVIDER_OAUTH_WAIT))
        caught = listener.caught
        if caught.get("error"):
            return ("%s refused: %s %s" % (
                PROVIDERS[name]["label"],
                strip_tag_characters(str(caught.get("error")))[:80],
                strip_tag_characters(str(caught.get("error_description") or ""))[:200]))
        # THE STATE IS THE BINDING. Without it anything that can reach the
        # loopback port can feed this client a code of its own.
        if caught.get("state") != state:
            return "the sign-in came back with a state this client did not send"
        if not caught.get("code"):
            return "the sign-in came back without a code"
        form = {"grant_type": "authorization_code", "code": caught["code"],
                "redirect_uri": redirect, "client_id": client_id,
                "code_verifier": verifier}
        if block.get("client_secret"):
            form["client_secret"] = block["client_secret"]
        answer, problem = _oauth_exchange(meta, form)
        if problem:
            return problem
        record = {"access_token": answer["access_token"],
                  "client_id": str(client_id),
                  "token_endpoint": meta["token_endpoint"]}
        if answer.get("refresh_token"):
            record["refresh_token"] = answer["refresh_token"]
        if block.get("scope"):
            record["scope"] = block["scope"]
        try:
            record["expires_at"] = time.time() + float(answer.get("expires_in"))
        except (TypeError, ValueError):
            pass
        doc = provider_tokens()
        doc[name] = record
        problem = provider_token_write(doc)
        if problem:
            return problem
        # THE CATALOGUE IS FETCHED ON THE WAY OUT, while the person is still
        # looking at the sheet they just signed in from. A list fetched later is
        # a wait nobody is expecting.
        provider_refresh(name)
        return None
    finally:
        listener.shutdown()
        listener.server_close()


def provider_subscriptions() -> list:
    """What the Subscriptions page draws. One row per provider that can log in."""
    doc = provider_doc()
    rows = []
    for name, spec in PROVIDERS.items():
        # `in`, NOT truthiness. Anthropic's block is EMPTY -- it publishes no
        # discovery document, so there is nothing to prefill -- and a tile that
        # vanished because nothing could be measured about it would be the page
        # hiding the provider the person came here for.
        if "oauth" not in spec:
            continue
        block = provider_oauth_block(name, doc)
        # WHICH HALVES ARE MISSING, not merely that one is. A provider that
        # publishes discovery needs the client_id alone; one that publishes
        # nothing needs the two endpoints as well, and a form that asked for all
        # three either way would make the simpler case look like the harder one.
        wants = ["client_id"] if block.get("issuer") else ["client_id", "authorize", "token"]
        borrow = PROVIDER_BORROW.get(name) or {}
        setup = PROVIDER_SETUP.get(name) or {}
        rows.append({"name": name, "label": spec["label"],
                     "command": setup.get("command") or "",
                     "hint": setup.get("hint") or "",
                     "from_env": bool(provider_setup_env(name)),
                     "blurb": spec.get("sub_blurb") or spec["blurb"],
                     "signed_in": provider_signed_in(name),
                     "ready": bool(block.get("client_id")),
                     "wants": wants,
                     "has": {k: bool(block.get(k)) for k in wants},
                     "discovers": bool(block.get("issuer")),
                     # THE STORE IS ONLY REPORTED AS PRESENT OR NOT. What is in
                     # it does not cross into a view, and the product's NAME is
                     # the only thing about it a person is shown.
                     "product": borrow.get("product") or "",
                     "borrowable": provider_borrow_seen(name),
                     "borrowing": provider_borrowing(name, doc),
                     "stale": provider_borrowed_stale(name),
                     "missing": "" if block.get("client_id")
                                else PROVIDER_NO_CLIENT % (spec["label"], name)})
    return rows


def health_url(base_url: str) -> str:
    """Derive the /health URL from an OpenAI-style base URL.

    Its own function because the naive `base_url[:-3] + "health"` produced
    `http://127.0.0.1:8081health` -- a non-numeric port, and an error message
    that pointed at http.client rather than at the caller.
    """
    root = base_url.rstrip("/")
    if root.endswith("/v1"):
        root = root[: -len("/v1")]
    return root.rstrip("/") + "/health"


def check_endpoint(base_url: str, timeout: float = 5.0) -> str:
    """Return the server's health status, or raise CrowError."""
    health = health_url(base_url)
    try:
        with urllib.request.urlopen(health, timeout=timeout) as resp:
            return (json.loads(resp.read().decode("utf-8")) or {}).get("status", "?")
    except urllib.error.URLError as exc:
        raise CrowError(f"no endpoint at {health}: {exc.reason}") from exc


def fetch_n_ctx(base_url: str, timeout: float = 5.0) -> int:
    """How many tokens this server's slot holds, or 0 if it will not say.

    Asked once at startup rather than assumed: with -np 4 the server splits
    its context across slots, so the number a client can actually use is not
    the one on the command line. Returns 0 on any failure - the prompt then
    shows a bare count instead of a wrong bar, because a progress bar against
    an invented limit is worse than no bar.
    """
    root = base_url.rstrip("/")
    if root.endswith("/v1"):
        root = root[: -len("/v1")]
    try:
        with urllib.request.urlopen(root + "/props", timeout=timeout) as resp:
            doc = json.loads(resp.read().decode("utf-8")) or {}
    except Exception:
        return 0
    settings = doc.get("default_generation_settings") or {}
    for value in (settings.get("n_ctx"), doc.get("n_ctx")):
        try:
            if value and int(value) > 0:
                return int(value)
        except (TypeError, ValueError):
            continue
    return 0


# A GGUF path carries two tails that are not the model's name: the shard counter
# and the quantisation tag. Both come off. Anything the patterns do not
# recognise is left standing rather than guessed at -- a name cut short is worse
# than a name with a suffix, because only one of the two is silent about it.
_GGUF_SHARD = re.compile(r"-\d{4,6}-of-\d{4,6}$")
_GGUF_QUANT = re.compile(r"-(?:UD-)?(?:I?Q\d[A-Z0-9_]*|BF16|F16|F32|MXFP4)$", re.IGNORECASE)


def model_display_name(path: str) -> str:
    """`…\\DeepSeek-V4-Flash-0731-UD-IQ3_XXS-00001-of-00004.gguf` → `DeepSeek-V4-Flash-0731`."""
    name = os.path.basename((path or "").replace("\\", "/").rstrip("/"))
    if name.lower().endswith(".gguf"):
        name = name[: -len(".gguf")]
    name = _GGUF_SHARD.sub("", name)
    return _GGUF_QUANT.sub("", name) or name


def fetch_model_name(base_url: str, timeout: float = 5.0) -> str:
    """What the server actually has OPEN, or "" if it will not say.

    Not `--model`. That one is a label in the request body — `crow` by default —
    and a header that printed it would confirm the client's own argument while
    the server ran something else entirely. Step 2 of the README exists because
    that mix-up costs a measurement, and this line is the cheap half of it.

    Its own request rather than a second return value from fetch_n_ctx: both are
    milliseconds against a local socket, and threading a tuple through would
    change a function three tests already pin.
    """
    root = base_url.rstrip("/")
    if root.endswith("/v1"):
        root = root[: -len("/v1")]
    try:
        with urllib.request.urlopen(root + "/props", timeout=timeout) as resp:
            doc = json.loads(resp.read().decode("utf-8")) or {}
    except Exception:
        return ""
    settings = doc.get("default_generation_settings") or {}
    for value in (doc.get("model_path"), doc.get("model"), settings.get("model")):
        if isinstance(value, str) and value.strip():
            return model_display_name(value)
    return ""


def next_context_tokens(current: int, timings: dict) -> int:
    """How full the window is after this turn.

    THE SERVER IS ASKED, NOT ESTIMATED. Until 2026-08-08 this was
    `context_tokens = prompt_n + predicted_n`, and both halves were wrong:

      * it ASSIGNED rather than accumulated, so the bar showed the last turn
        instead of the session -- measured live, it ran 4.7k -> 1.3k -> 792
        BACKWARDS while the conversation grew;
      * `prompt_n` is the count of tokens the server actually PROCESSED, i.e.
        the uncached remainder. On a warm cache it is near zero precisely
        because things went well: 18 for a prompt that was 4,700 tokens long;
      * `predicted_n` counts everything generated, reasoning included.

    `usage.total_tokens` is the whole conversation as the server's own
    tokeniser counted it -- prompt plus completion, absolute, so assignment is
    now the correct operation. Measured on a two-turn conversation:
    prompt_tokens 29 = cached_tokens 11 + prompt_n 18.

    The fallback exists for endpoints that send no usage block. It accumulates,
    which is right only while the prefix holds -- on a break `prompt_n` counts
    old tokens again and the figure runs high. That is the honest failure
    direction: a bar that overstates makes someone reset early, one that
    understates lets them run into the wall.
    """
    total = timings.get("_context_tokens")
    if isinstance(total, int):
        return total
    prompt_n = timings.get("prompt_n")
    predicted_n = timings.get("predicted_n")
    if prompt_n is None or predicted_n is None:
        return current
    return current + int(prompt_n) + int(predicted_n)


FONT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "fonts")

# The name a terminal has to be given, NOT the typographic family in the file.
# GoogleSansCode[MONO,wght].ttf is a variable font; Windows resolves it into
# named instances and registers those. Measured 2026-08-07 after installing:
# the families on offer are "Google Sans Code Monospace", "... Proportional",
# "... Medium Monospa" and so on - "Google Sans Code" is not among them, and
# asking for it gets the "font not found" dialog. Name ID 1 of the file says
# "Google Sans Code", which is what made the first attempt wrong.
FONT_FAMILY = "Google Sans Code Monospace"


# What the family covers, measured 2026-08-07 by reading the cmap of
# GoogleSansCode[MONO,wght].ttf v7.001 against Cascadia Mono as a control:
# block elements U+2580-259F 32/32 and box drawing U+2500-257F 128/128 are
# complete, BRAILLE U+2800-28FF is 0 of 256 (Cascadia has all 256). Any banner
# built from braille cells would fall back to a substitute face here, the cell
# advance changes with it, and the drawing comes apart. Block art is safe.


def font_files() -> list[str]:
    if not os.path.isdir(FONT_DIR):
        return []
    return sorted(f for f in os.listdir(FONT_DIR) if f.lower().endswith((".ttf", ".otf")))


def font_installed() -> list[str]:
    """Names of our font files already present in the per-user font store."""
    target = crow_platform.font_store()
    if not os.path.isdir(target):
        return []
    return [f for f in font_files() if os.path.isfile(os.path.join(target, f))]


# ---------------------------------------------------------------- #143 -----
# DELEGATION, STAGE E1. A subtask is a TOOL CALL in the ordinary loop, not a
# window construct: `delegate` returns at once with an id and starts a thread
# running `run_turn` against a REMOTE spot on a fresh `Conversation`; `collect`
# is an ordinary slow tool call that blocks until the named subtasks finish.
# The parallelism lives BETWEEN the two calls; the sequential tool loop above
# is untouched, and `delegate`/`collect` sit in the parent's history as normal
# tool rows, so a restart replays them like any other call.
#
# THE LOCAL SLOT IS NEVER A DELEGATION TARGET. The llama-server on this box is
# `-np 1` with a warm cache on one prefix -- parallelism is bought at a
# provider, not taken from the card. `delegate_target` refuses `local` even
# when somebody writes it into the file, because every aliasing of that rule
# pays with a halved window and a cold cache -- the exact capital this client
# lives on.
#
# SUBTASKS HAVE NO TOOLS IN v1, and that is a decided scope: text in, text
# out. Executing tools for a remote free model would be a stranger with hands
# on this machine; whether the release levels ever open that door is its own
# decision, not a default. The request therefore declares no tools at all --
# see `send_tools` on `stream_reply` -- and runs `execute_tools=False` behind
# it, so even a model that hallucinates a call gets it reported, never run.
#
# THE REGISTRY IS THIS PROCESS'S MEMORY, NOT THE SESSION'S. Ids and results
# live here; a restart replays the delegate/collect ROWS out of the history but
# cannot re-enter the threads behind them, so `collect` after a restart answers
# "no subtask" honestly rather than pretending to remember.

# One subtask stream may read this long, and one collect call waits at most
# this long before reporting where things stand instead of hanging -- a 429
# or a stalled provider becomes a sentence, never a frozen turn.
SUBTASK_TIMEOUT = 600.0
COLLECT_TIMEOUT = 600.0
_COLLECT_SLICE = 0.25

# A guard against the runaway fan-out, not a budget: free-tier providers
# throttle, and a hundred threads against one 429-happy endpoint is a hundred
# sentences nobody asked for.
SUBTASK_LIMIT = 16

# The delegate spot defaults to the broker because it is the one provider with
# a free tier to point at. WHICH free model is never written in code: it is
# whatever the catalogue on disk declares -- the user's own pick when that is
# already free, else the free entry with the largest declared window, a
# criterion a test can hold. No catalogue, no default -- the sentence says so.
DELEGATE_PROVIDER_DEFAULT = "openrouter"
FREE_MODEL_SUFFIX = ":free"

# What the rail may show for a subtask before anybody names it -- the same
# width the window gives a chat title.
SUBTASK_TITLE_MAX = 52


def _free_model_for(name: str, doc: "dict | None" = None) -> str:
    """The free model the default spot means, or "" when there is none.

    THE USER'S OWN PICK WINS WHEN IT IS FREE: they chose it, and choosing a
    different free model over it would be taste. Otherwise the catalogue's
    free entry with the largest declared window -- measurable, so a test can
    pin the rule -- and "" when the catalogue is empty or lists nothing free.
    """
    picked = provider_model_for(name, doc)
    # THE PICK READS THE HEALTH MEMO TOO (2026-08-28 spaetabends): it was the
    # one rung that did not, so every fresh delegation resolved straight back
    # to the dead pick and paid one failure before the chain could speak.
    if picked.endswith(FREE_MODEL_SUFFIX) and picked not in _SPOT_DEAD:
        return picked
    # #148: a favourite the person picked beats the largest window, in the
    # person's order -- PAID INCLUDED, the owner's correction of 2026-08-28: a
    # billed favourite is the user's explicit choice on their own key. Only
    # what nobody chose stays free. The health memo (#146) speaks first.
    catalogue = {str(m.get("id")) for m in provider_models(name, doc)}
    for fav in delegate_favorites(doc):
        if fav in catalogue and fav not in _SPOT_DEAD:
            return fav
    # #146: the health memo speaks at resolution time -- the largest declared
    # window was the dead provider, and a session that has seen a spot fail
    # does not offer it again.
    free = [m for m in provider_models(name, doc)
            if str(m.get("id") or "").endswith(FREE_MODEL_SUFFIX)
            and str(m.get("id")) not in _SPOT_DEAD]
    if not free:
        return ""
    return str(max(free, key=lambda m: int(m.get("context") or 0)).get("id"))


def delegate_target(doc: "dict | None" = None) -> "tuple[dict | None, str | None]":
    """Where a subtask goes: `(spot, None)` or `(None, why not)`.

    THE SAME SHAPE `provider_endpoint` RETURNS and always the remote branch of
    it, because the local slot is refused above everything else. The setting is
    `providers.json`'s `delegate` block -- `{"provider": ..., "model": ...}` --
    and its absence means the free default, not an error: nothing is billed
    without a word, so the default must be a model that bills nothing.
    """
    if doc is None:
        doc = provider_doc()
    block = doc.get("delegate") if isinstance(doc.get("delegate"), dict) else {}
    name = str(block.get("provider") or "") or DELEGATE_PROVIDER_DEFAULT
    if name == LOCAL_PROVIDER:
        return None, ("the local slot is never a delegation target -- "
                      "parallelism is bought at a provider, not from the card")
    spec = PROVIDERS.get(name)
    if spec is None:
        return None, "no provider named %r for the delegate spot" % name
    # THE SWITCH SPEAKS BEFORE THE SPOT RESOLVES (2026-08-28): a parked broker
    # answers with the control that unparks it, not with a model list.
    if name == "openrouter" and not openrouter_on(doc):
        return None, OPENROUTER_OFF_NOTE
    model = str(block.get("model") or "") or _free_model_for(name, doc)
    if not model:
        return None, ("no delegate spot: no free %s model in the catalogue -- "
                      "set one, or refresh the model list" % spec["label"])
    credential, kind, problem = provider_credential(name)
    if problem:
        return None, problem
    if not credential and spec.get("needs_key"):
        return None, ("%s has no key and no sign-in -- the delegate spot "
                      "needs one" % spec["label"])
    return ({"provider": name, "label": spec["label"], "remote": True,
             "base_url": spec["base_url"], "model": model,
             "api_key": credential,
             "headers": provider_headers(name, kind, credential),
             "transport": spec.get("transport") or TRANSPORT_CHAT,
             "routing": _routing_copy(spec.get("routing") or {}),
             "sticky": bool(spec.get("sticky")),
             "filter": bool(spec.get("filter")),
             "params": provider_params(name, model, doc)}, None)


# #148. THREE FAVOURITES, DEFAULT FREE. The owner's parked routing ask of
# 2026-08-27: the free default used to be "largest declared window", and the
# largest declared window was the dead provider. Favourites are picked by a
# person, tried in THEIR order, and skipped while the health memo says dead --
# the resolution below stays measurable, so a test can pin the rule.
def delegate_favorites(doc: "dict | None" = None) -> "list[str]":
    doc = provider_doc() if doc is None else doc
    favs = doc.get("delegate_favorites")
    if not isinstance(favs, list):
        return []
    return [str(m).strip() for m in favs
            if isinstance(m, str) and str(m).strip()][:3]


def delegate_favorites_set(models: "list | None") -> "str | None":
    """Write the favourites, at most three. The reason it failed, or None."""
    doc = provider_doc()
    clean = [str(m).strip() for m in (models or [])
             if isinstance(m, str) and str(m).strip()][:3]
    if clean:
        doc["delegate_favorites"] = clean
        # des Owners Live-Befund 2026-08-28 spaetabends: drei Favoriten standen
        # in der Oberflaeche, die Delegation nahm weiter den unsichtbaren Pin
        # vom 27.08. Wer Favoriten setzt, sagt die Reihenfolge an -- ein Pin,
        # den keine Seite mehr zeigt, weicht ihnen, statt sie stumm zu
        # schlagen. Clearing favourites orders nothing and unseats nothing.
        doc.pop("delegate", None)
    else:
        doc.pop("delegate_favorites", None)
    return provider_write(doc)


class Subtask:
    """One delegated task: what was asked, who ran it, what came back.

    `status` MOVES EXACTLY ONCE, from "running" to one of "done", "failed" or
    "interrupted", and it moves LAST -- after the result, the clock and the
    failure text are in place -- so a reader that sees the final state sees
    the whole record. Waiting is done on the THREAD, never by polling status:
    the thread's end is the fact, the status is the report.
    """

    def __init__(self, ident: str, task: str, context: str, spot: dict) -> None:
        self.ident = ident
        self.task = task
        self.context = context
        self.model = spot["model"]
        self.label = spot["label"]
        self.status = "running"
        self.result = ""
        self.failure = ""
        self.started = time.monotonic()
        self.seconds = 0.0
        self.prompt_tokens = 0
        self.reply_tokens = 0
        # The endpoint's own `usage.total_tokens`. A remote endpoint reports
        # THIS and not llama.cpp's timings split -- measured live 2026-08-27,
        # nemotron over OpenRouter: prompt_n/predicted_n absent, total 199 --
        # so without it every remote subtask would count 0 tok.
        self.usage_tokens = 0
        self.transcript = ""
        self.collected = False
        # #143 E2. Set by `cancel_subtasks` when the user presses Stop. The
        # stream cannot be torn out from under its thread, so the mark is a
        # promise about the RECORD: whatever the network still delivers is
        # dropped, the status ends "interrupted", no transcript is written.
        self.cancelled = False
        # 2026-08-28 spaetnachts: der Chat, der diese Aufgabe delegiert hat --
        # vom Fenster gestampt, mit persistiert; "" ist der dateilose Live-Chat.
        self.parent = ""
        # #281: the window's Subtasks card was closed over this record. A VIEW
        # mark, not a state: closing never cancels. Persisted, so the card
        # stays shut across a restart; a new subtask starts with False and so
        # brings the card back by itself.
        self.closed = False
        # #216: every failed attempt, in order --
        # `{"model", "class", "reason", "detail"}`. Persisted with the record,
        # so the first spot's own words survive the card and the restart.
        self.chain: "list[dict]" = []
        self.thread: "threading.Thread | None" = None

    @property
    def tokens(self) -> int:
        """The split when the endpoint gave one, its own total otherwise."""
        split = self.prompt_tokens + self.reply_tokens
        return split if split else self.usage_tokens

    def clock(self) -> float:
        """Seconds so far for a running subtask, the final figure after."""
        if self.status == "running":
            return time.monotonic() - self.started
        return self.seconds

    def head(self, limit: int = SUBTASK_TITLE_MAX) -> str:
        lines = self.task.strip().splitlines()
        return (lines[0] if lines else "")[:limit]


# The registry and its lock. The dict preserves delegation order, which is the
# order every listing shows.
SUBTASKS: "dict[str, Subtask]" = {}
_SUBTASK_LOCK = threading.Lock()
_SUBTASK_SEQ = 0


def forget_subtasks() -> None:
    """Tests, and a surface that starts a fresh session over this process.

    THE THREADS ARE NOT JOINED. They are daemons on their own conversations;
    a hung stream must not hang a caller that only wants a clean registry, and
    a finished one has nothing left to do.
    """
    global _SUBTASK_SEQ
    with _SUBTASK_LOCK:
        SUBTASKS.clear()
        _SUBTASK_SEQ = 0


# des Owners Ansage vom 2026-08-28 spaetnachts: delegierte Aufgaben ueberleben
# den Crow-Neustart, solange ihr Chat lebt. Die Registry bleibt das
# Prozessgedaechtnis der THREADS; ihre RECORDS liegen zusaetzlich auf Platte
# im Subtask-Regal der Session und kommen im naechsten Prozess zurueck --
# running ehrlich als "interrupted", denn der Arbeiter ist weg. Geloescht
# wird mit dem CHAT: drop_subtasks raeumt die Datei mit.
_SUBTASKS_RECALLED = False


def _subtask_registry_path() -> str:
    # Zur Laufzeit gebaut: SESSION_DIR wird von Suiten umgebogen, und eine
    # beim Import gefrorene Konstante schriebe an den echten Ort. NEBEN dem
    # Regal, nicht darin: `subtasks/` gehoert den Transkripten allein -- zwei
    # Bestandsfaelle zaehlen dessen Dateien, und die Registry ist keins.
    return os.path.join(SESSION_DIR, "subtasks-registry.json")


def _subtask_persist() -> None:
    """Write the records down. Tolerant like every convenience file."""
    with _SUBTASK_LOCK:
        subs = list(SUBTASKS.values())
    rows = [{"ident": s.ident, "task": s.task, "model": s.model,
             "label": s.label, "status": s.status, "result": s.result,
             "failure": s.failure, "seconds": round(s.clock(), 1),
             "prompt_tokens": s.prompt_tokens, "reply_tokens": s.reply_tokens,
             "usage_tokens": s.usage_tokens, "transcript": s.transcript,
             "collected": s.collected, "parent": getattr(s, "parent", ""),
             "closed": bool(getattr(s, "closed", False)),
             "chain": list(getattr(s, "chain", []))}
            for s in subs]
    path = _subtask_registry_path()
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as fh:
            json.dump({"format": 1, "subtasks": rows}, fh, ensure_ascii=False)
    except OSError:
        pass


def subtasks_recall() -> int:
    """Load what an earlier process delegated. Returns how many came back.

    RUNNING WIRD EHRLICH "interrupted": der Thread dieses Prozesses existiert
    nicht mehr, und ein geladenes "running" waere ein Puls, hinter dem niemand
    arbeitet. Der Zaehler laeuft OBERHALB der geladenen Nummern weiter, sonst
    kollidiert das naechste d1 mit dem geladenen d1.
    """
    global _SUBTASK_SEQ
    try:
        with open(_subtask_registry_path(), encoding="utf-8") as fh:
            raw = json.load(fh)
    except (OSError, ValueError):
        return 0
    loaded = 0
    with _SUBTASK_LOCK:
        for row in (raw.get("subtasks") or []):
            if not isinstance(row, dict):
                continue
            ident = str(row.get("ident") or "")
            if not ident or ident in SUBTASKS:
                continue
            sub = Subtask(ident, str(row.get("task") or ""), "",
                          {"model": str(row.get("model") or ""),
                           "label": str(row.get("label") or "")})
            sub.status = str(row.get("status") or "failed")
            sub.result = str(row.get("result") or "")
            sub.failure = str(row.get("failure") or "")
            sub.seconds = float(row.get("seconds") or 0.0)
            sub.prompt_tokens = int(row.get("prompt_tokens") or 0)
            sub.reply_tokens = int(row.get("reply_tokens") or 0)
            sub.usage_tokens = int(row.get("usage_tokens") or 0)
            sub.transcript = str(row.get("transcript") or "")
            sub.collected = bool(row.get("collected"))
            sub.parent = str(row.get("parent") or "")
            sub.closed = bool(row.get("closed"))
            sub.chain = [c for c in (row.get("chain") or [])
                         if isinstance(c, dict)]
            if sub.status == "running":
                sub.status = "interrupted"
                sub.failure = "crow was closed while it ran"
            m = re.match(r"d(\d+)$", ident)
            if m:
                _SUBTASK_SEQ = max(_SUBTASK_SEQ, int(m.group(1)))
            SUBTASKS[ident] = sub
            loaded += 1
    return loaded


def _ensure_subtasks_recalled() -> None:
    """Lazy, once per process: every surface that looks gets the recall --
    kein Init-Hook je Oberflaeche, der vergessen werden kann."""
    global _SUBTASKS_RECALLED
    if not _SUBTASKS_RECALLED:
        _SUBTASKS_RECALLED = True
        subtasks_recall()


def subtask_parent_set(ident: str, parent: str) -> None:
    """The window's parent stamp, written through to the record and the disk.
    Idempotent -- the tick calls it on every snapshot and it writes only on
    change, the self-healing shape the here-flag already has."""
    with _SUBTASK_LOCK:
        sub = SUBTASKS.get(ident)
        if sub is None or getattr(sub, "parent", "") == parent:
            return
        sub.parent = parent
    _subtask_persist()


def subtask_close(idents: "list[str]", closed: bool = True) -> int:
    """#281. Mark (or unmark) records as closed in the window's Subtasks card.

    A VIEW MARK ONLY: the status, the thread and the result are untouched, so
    a running subtask keeps running -- closing a panel is not cancelling the
    work it shows (the split VS Code keeps between "Close Panel" and "Kill
    Terminal"). Writes only on change. Returns how many records changed.
    """
    changed = 0
    with _SUBTASK_LOCK:
        for ident in idents:
            sub = SUBTASKS.get(ident)
            if sub is not None and bool(getattr(sub, "closed", False)) != closed:
                sub.closed = closed
                changed += 1
    if changed:
        _subtask_persist()
    return changed


def drop_subtasks(idents: "list[str]") -> int:
    """A deleted chat takes its subtasks along (der Owner, 2026-08-28 abends).

    The records leave the registry, so no listing, chip or rail row shows
    them again. A still-running one is CANCELLED first -- the thread cannot
    be torn out of its socket, but the mark is the promise about the record:
    whatever the network still delivers is dropped and no transcript is
    written. A transcript already on disk goes with the chat it belonged to;
    a path that is already gone is not an error worth a sentence.
    """
    with _SUBTASK_LOCK:
        subs = [SUBTASKS.pop(i) for i in list(idents) if i in SUBTASKS]
    for sub in subs:
        if sub.status == "running":
            sub.cancelled = True
        if sub.transcript:
            try:
                os.remove(sub.transcript)
            except OSError:
                pass
    # Der Chat-Loeschpfad raeumt die Platte mit: was hier geht, kommt nach
    # dem naechsten Start nicht wieder (des Owners Ansage, 2026-08-28 spaetnachts).
    _subtask_persist()
    return len(subs)


class _SubtaskEvents(TurnEvents):
    """The silent sink, plus the two facts the registry needs afterwards."""

    def __init__(self) -> None:
        self.failed = ""
        self.interrupted = False

    def turn_failed(self, message: str) -> None:
        self.failed = message

    def turn_interrupted(self) -> None:
        self.interrupted = True


def _subtask_prompt(task: str, context: str) -> str:
    """Context above, ask below: the last thing a model reads is the ask."""
    if not context.strip():
        return task
    return "%s\n\n%s" % (context.rstrip(), task)


def _subtask_close(sub: Subtask, status: str, failure: str = "") -> None:
    """The one place a subtask's record is finished. Status moves LAST."""
    sub.seconds = time.monotonic() - sub.started
    sub.failure = failure
    sub.status = status
    # #169. WAS AUF EINEM FREMDEN SPOT AUSGEGEBEN WURDE, dem laufenden Schritt
    # zugeschlagen -- getrennt von den lokalen Token, nie in dieselbe Summe.
    # Hier, weil dies die eine Stelle ist, an der ein Subtask endet, egal auf
    # welchem der drei Wege.
    goal_delegated_seen(sub.tokens)
    # Jeder Endzustand geht auf die Platte -- die Registry-Datei traegt die
    # Records ueber den Prozess hinaus (2026-08-28 spaetnachts).
    _subtask_persist()


def _subtask_transcript(sub: Subtask, conversation: Conversation,
                        spot: dict, context_tokens: int) -> str:
    """Write the subtask's own chat file, or "" when that failed.

    ONE WRITER PER FILE: this runs on the subtask's own thread, on a path no
    other writer can land on because the id is in the name.

    IN ITS OWN SHELF, `subtasks/` UNDER THE SESSION FOLDER, AND NEVER FLAT.
    The owner, 2026-08-27, at the window: "Subtasks bekommen keinen eigenen
    Wurzelchat, nur Subchats unter dem jeweiligen Wurzelchat". The rail lists
    every flat `chat-*.json` as a root chat, so a transcript written there IS
    a root chat, drawn twice and openable as a live conversation -- measured
    tonight as exactly that structure break. The subfolder is invisible to
    the chat listing; the transcript is reached through the subtask rows and
    nothing else.

    WRITTEN THROUGH `save_session`, never by hand: that function owns the
    format key, the gate and the fingerprint. The two keys added afterwards
    ride on the rule the save itself states -- a reader takes the keys it
    knows and ignores the rest -- and the read-back at the end is the same
    contract `provider_write` keeps: a writer that never reads has only proved
    that `json.dump` did not raise.
    """
    shelf = os.path.join(SESSION_DIR, "subtasks")
    stamp = time.strftime("%Y%m%d-%H%M%S")
    path = os.path.join(shelf, "chat-%s-sub-%s.json" % (stamp, sub.ident))
    extra = 2
    while os.path.exists(path):
        path = os.path.join(shelf, "chat-%s-sub-%s-%d.json"
                            % (stamp, sub.ident, extra))
        extra += 1
    try:
        os.makedirs(shelf, exist_ok=True)
        if save_session(conversation, spot["base_url"], context_tokens,
                        path=path, with_kv=False, model=spot["model"]) is None:
            return ""
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
        data["crow_title"] = sub.head()
        data["crow_subtask"] = {"id": sub.ident, "task": sub.task,
                                "model": spot["model"],
                                "seconds": round(time.monotonic() - sub.started, 1),
                                "tokens": sub.tokens}
        # #216: a result that landed after a fallback says in
        # its own file which spots failed first, and with what words.
        if sub.chain:
            data["crow_subtask"]["chain"] = list(sub.chain)
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(data, fh)
        with open(path, encoding="utf-8") as fh:
            written = json.load(fh)
        if (written.get("crow_subtask") or {}).get("id") != sub.ident:
            return ""
    except Exception:  # noqa: BLE001 - a lost transcript must not lose the result
        return ""
    return path


# #146. THE SPOT HEALTH MEMO, session-lifetime like the approval store: a spot
# that failed retryably is not offered again until the process restarts. This
# is the pin ritual of 2026-08-27 lifted into code -- one answer proves
# nothing, and the largest declared window was the dead provider.
_SPOT_DEAD: dict[str, str] = {}


def forget_spot_health() -> None:
    _SPOT_DEAD.clear()


# The failure classes worth a second spot. Everything else -- a schema error,
# a refusal, an interrupt -- would fail identically anywhere.
#
# THE TWO 404 PHRASES ARE MEASURED, 2026-08-28 spaetabends: the dead Nvidia
# upstream answered HTTP 404 "Provider returned error" (a passthrough -- the
# upstream is sick, not the request) and "No endpoints found that can handle
# the requested parameters" (nobody serves THIS model right now). Both are
# this spot's sickness; the next spot answers. A BARE 404 stays
# non-retryable: an address every spot would 404 on is not a spot question.
_RETRYABLE = ("429", "shared_pool", "timed out", "timeout", "answered nothing",
              "temporarily", "connection", "unavailable", "502", "503",
              "provider returned error", "no endpoints found")

# #216. THREE VERDICTS, NOT TWO. The live run of 2026-09-22
# fell forward from the primary onto `thinkingmachines/inkling-small:free`,
# which OpenRouter serves "only on agentic harnesses" -- HTTP 403 -- and a 403
# was "would fail identically anywhere", so the chain STOPPED on the one spot
# that was nobody's choice. It is the opposite: a 403 is THIS spot refusing
# THIS client, and the next spot answers. Measured the same evening against
# the catalogue on disk: the two largest free windows (1,048,576) are both
# Thinking Machines, so behind any primary the first two fallbacks refuse.
#
#   transient -- this spot is sick right now (429, timeouts, 5xx, "provider
#                returned error"): memo it, next spot.
#   spot      -- this spot will not serve this client (403 gating/moderation,
#                "no endpoints found", 402 on a PAID spot): memo it with the
#                reason, next spot, and it costs no transient attempt -- a
#                refusal is instant and did no work.
#   global    -- the request or the account is wrong (401 key, 402 on a FREE
#                spot = negative balance, schema/400): every spot answers the
#                same, the chain stops and the spot is NOT memoed.
#
# 402 SPLITS ON WHAT WAS ASKED, per OpenRouter's limits page: "If your account
# has a negative credit balance, you may see 402 errors, including for free
# models." A free spot's 402 is therefore the account, not the spot; a paid
# favourite's 402 is its price, and the free spots behind it bill nothing.
_SPOT_REFUSED = ("no endpoints found",)
_TRANSIENT_CODES = (408, 429, 500, 502, 503, 504)


def _http_code(detail: str) -> "int | None":
    """The status `_post_stream` and the mid-stream door write, or None."""
    hit = re.search(r"\bHTTP (\d{3})\b", detail or "")
    return int(hit.group(1)) if hit else None


def _spot_verdict(detail: str, model: str = "") -> "tuple[str, str]":
    """(class, reason) for one failed attempt -- see the table above."""
    low = (detail or "").lower()
    code = _http_code(detail)
    if code == 401:
        return "global", "the key was refused (401)"
    if code == 402:
        if model.endswith(FREE_MODEL_SUFFIX):
            return "global", "the account is out of credits (402, free models included)"
        return "spot", "no credits for this paid model (402)"
    if code == 403:
        if "harness" in low or "only available" in low:
            return "spot", "gated for this client (403)"
        if "moderation" in low or "flagged" in low:
            return "spot", "moderation flag (403)"
        return "spot", "forbidden for this client (403)"
    # #284: a retired free slug ("This model is unavailable for free. The
    # paid version is available now") will never answer again -- its word
    # "unavailable" must not reach _RETRYABLE and cost a transient attempt.
    if "unavailable for free" in low:
        return "spot", "no longer free%s" % (" (%d)" % code if code else "")
    if any(m in low for m in _SPOT_REFUSED):
        return "spot", "no provider serves it%s" % (" (%d)" % code if code else "")
    if code in _TRANSIENT_CODES or any(m in low for m in _RETRYABLE):
        return "transient", ("HTTP %d" % code) if code else "no answer"
    return "global", ("HTTP %d" % code) if code else "refused"


def delegate_fallbacks(spot: dict, doc: "dict | None" = None) -> "list[dict]":
    """The next spots behind `spot`, same provider: favourites first (paid
    included -- the user's own pick on their own key, #148), then FREE models
    by declared window. Excludes the spot itself and everything the health
    memo has marked. What nobody chose never falls forward onto a bill.
    """
    if doc is None:
        doc = provider_doc()
    name = str(spot.get("provider") or "")
    spec = PROVIDERS.get(name)
    if spec is None:
        return []
    skip = {spot.get("model")} | set(_SPOT_DEAD)
    # #148, the owner's correction: favourites lead the chain in the person's order
    # and MAY be paid -- their own pick on their own key. Behind them only
    # FREE models follow, by declared window: what nobody chose must not fall
    # forward onto a bill.
    favs = delegate_favorites(doc)
    rank = {f: i for i, f in enumerate(favs)}
    free = [m for m in provider_models(name, doc)
            if str(m.get("id") or "") not in skip
            and (str(m.get("id")) in rank
                 or str(m.get("id") or "").endswith(FREE_MODEL_SUFFIX))]
    free.sort(key=lambda m: (rank.get(str(m.get("id")), len(favs)),
                             -int(m.get("context") or 0)))
    # Assembled HERE, not through delegate_target: that function answers "where
    # does the next delegation go" and tests rebind it to say so -- a fallback
    # list built by calling it would collapse onto whatever it was pinned to.
    credential, kind, problem = provider_credential(name)
    if problem or (not credential and spec.get("needs_key")):
        return []
    out = []
    for m in free:
        mid = str(m.get("id"))
        out.append({"provider": name, "label": spec["label"], "remote": True,
                    "base_url": spec["base_url"], "model": mid,
                    "api_key": credential,
                    "headers": provider_headers(name, kind, credential),
                    "transport": spec.get("transport") or TRANSPORT_CHAT,
                    "routing": _routing_copy(spec.get("routing") or {}),
                    "sticky": bool(spec.get("sticky")),
                    "filter": bool(spec.get("filter")),
                    "params": provider_params(name, mid, doc)})
    return out


def _subtask_attempt(sub: Subtask, spot: dict) -> "tuple[str, str]":
    """One try on one spot. Returns (state, detail); "done" set sub.result.

    `owns_turn_state=False` IS THE WHOLE REASON THIS MAY RUN BESIDE A TURN:
    the parent's read-permissions and its Ctrl+C flag stay the parent's. See
    the parameter on `run_turn`.
    """
    events = _SubtaskEvents()
    conversation = Conversation()
    conversation.append("user", _subtask_prompt(sub.task, sub.context))
    try:
        sampling = sampling_for(spot["model"])
        turn = run_turn(
            conversation, base_url=spot["base_url"], model=spot["model"],
            api_key=spot["api_key"],
            temperature=sampling["temperature"], top_p=sampling["top_p"],
            min_p=sampling["min_p"], top_k=sampling.get("top_k"),
            presence_penalty=sampling.get("presence_penalty"),
            reasoning_effort=None, timeout=SUBTASK_TIMEOUT,
            extra_headers=spot.get("headers") or None,
            transport=spot.get("transport") or TRANSPORT_CHAT,
            max_tokens=subtask_max_tokens(), remote=True,
            routing=turn_routing(spot, None),
            execute_tools=False, send_tools=False, owns_turn_state=False,
            events=events)
    except Exception as exc:  # noqa: BLE001 - a thread must not die silently
        return "failed", "%s: %s" % (type(exc).__name__, exc)
    # #143 E2: A CANCELLED SUBTASK DELIVERS NOTHING. The user pressed Stop
    # while this ran; whatever the endpoint still returned is dropped here,
    # before the result or a transcript could make it look alive.
    if sub.cancelled:
        return "interrupted", "stopped by the user"
    reply = ""
    for message in reversed(conversation.payload()):
        if message.get("role") == "assistant":
            reply = message_text(message.get("content") or "")
            break
    sub.prompt_tokens = turn.cost.prefilled
    sub.reply_tokens = turn.cost.decoded
    sub.usage_tokens = turn.context_tokens
    if events.interrupted:
        return "interrupted", "interrupted"
    if turn.stopped or not reply.strip():
        return "failed", (events.failed or "the model answered nothing")
    sub.result = reply
    sub.transcript = _subtask_transcript(sub, conversation, spot,
                                         turn.context_tokens)
    return "done", ""


def _run_subtask(sub: Subtask, spot: dict) -> None:
    """The whole life of one subtask, on its own thread.

    EVERYTHING ENDS IN `_subtask_close`. A thread that dies with an exception
    leaves a subtask "running" forever and a `collect` waiting on a corpse;
    catching everything and writing the record is what makes the registry a
    place `collect` can trust.

    #146: A RETRYABLE FAILURE FALLS TO THE NEXT FREE SPOT, at most three
    sick spots, and the record says where it landed -- a card that silently
    swapped its model would be a spot nobody can trust twice. The health memo
    keeps the dead spot out of every later resolution this session.

    #216: a spot that REFUSES this client (403, 402 on a paid
    spot, no endpoints) falls forward too, outside the three; only a global
    verdict (401, a free spot's 402, a schema error) stops the chain. Every
    attempt lands in `sub.chain`, and the failure sentence names them all.
    """
    current = spot
    detail = ""
    transient = refused = 0
    for _ in range(_CHAIN_TRANSIENT + _CHAIN_REFUSALS):
        state, detail = _subtask_attempt(sub, current)
        # #242: A STOP IS NOT A SPOT FAILING. An attempt that raised after the
        # user's Stop came back "failed" -- the chain wrote it down, memoed the
        # spot dead and closed "failed". The mark is read before the verdict.
        if sub.cancelled:
            _subtask_close(sub, "interrupted",
                           _chain_said("stopped by the user", sub.chain))
            return
        if state == "done":
            # The fallback note survives a good landing: a card that says
            # where its result CAME from is the whole point of not swapping
            # models silently.
            _subtask_close(sub, "done", sub.failure)
            return
        model = str(current.get("model"))
        if state == "interrupted":
            _subtask_close(sub, state, _chain_said(detail, sub.chain))
            return
        verdict, reason = _spot_verdict(detail, model)
        # #216: EVERY attempt is written down with its own
        # words before anything is decided -- the first spot's error was
        # the one the live run of 2026-09-22 lost, the card said "403".
        sub.chain.append({"model": model, "class": verdict, "reason": reason,
                          "detail": _chain_detail(detail)})
        if verdict == "global":
            _subtask_close(sub, "failed", "%s -- the chain stops here, every "
                           "spot would answer the same: %s"
                           % (reason, _chain_said(detail, sub.chain[:-1])))
            return
        _SPOT_DEAD[model] = "%s: %s" % (reason, _chain_detail(detail))
        if verdict == "transient":
            transient += 1
        else:
            refused += 1
        if transient >= _CHAIN_TRANSIENT or refused >= _CHAIN_REFUSALS:
            break
        nxt = delegate_fallbacks(current)
        if not nxt or sub.cancelled:
            break
        current = nxt[0]
        sub.model = current["model"]
        sub.label = current["label"]
        sub.failure = "fell back from " + _chain_story(sub.chain)
        # Mid-chain the record is on disk too: a crash between two spots
        # must not lose what the first one said.
        _subtask_persist()
    _subtask_close(sub, "failed", "no spot answered -- tried "
                   + _chain_story(sub.chain))


# #216. The attempt budget, split by verdict: THREE spots that
# were sick (the #146 figure, unchanged -- each can cost a 600 s timeout), and
# up to SIX that refused. A refusal is one instant HTTP answer and did no work;
# counting it against the three is what ended the 2026-09-22 chain on the
# second gated Thinking Machines spot before any healthy one was asked.
_CHAIN_TRANSIENT = 3
_CHAIN_REFUSALS = 6

# What one attempt keeps of its error. `_post_stream` already cuts the body at
# 500; the card shows 4000 chars, and nine attempts must fit in it.
_CHAIN_DETAIL = 240


def _chain_detail(detail: str) -> str:
    """One line, bounded -- the story is read as a first line in the terminal."""
    flat = " ".join(str(detail or "").split())
    return flat if len(flat) <= _CHAIN_DETAIL else flat[:_CHAIN_DETAIL] + "..."


def _chain_story(chain: "list[dict]") -> str:
    """`model (reason: detail); model (...)` -- every spot and why it failed."""
    return "; ".join("%s (%s: %s)" % (c.get("model"), c.get("reason"),
                                      c.get("detail"))
                     for c in chain) or "one spot"


def _chain_said(detail: str, earlier: "list[dict]") -> str:
    """The last detail, and the spots that failed before it when there were."""
    if not earlier:
        return detail
    return "%s -- after %s" % (detail, _chain_story(earlier))


# #149. THE MAKER IS NOT THE CHECKER. A model grading its own diff approves
# it; a second pass with other instructions catches what the first talked
# itself into. Crow's checker is bought where its parallelism is bought: the
# verification rides `delegate`, so the local slot stays the maker and the
# remote spot reads with fresh eyes. User-triggered (/verify) -- a maker that
# may skip its own checker will.
VERIFY_PROMPT = (
    "Review the following changes with fresh eyes; you did not write them. "
    "Name concrete defects -- wrong logic, broken edge cases, a change that "
    "contradicts its own stated intent -- each with its file and the line or "
    "snippet. If nothing is wrong, say so in one sentence. Do not restate the "
    "code, do not praise it.\n\n")

VERIFY_MATERIAL_CHARS = 40000


def verify_material(conversation: "Conversation") -> str:
    """What this conversation wrote, per path, newest first -- "" if nothing.

    Built from the conversation's own tool calls, because that is the one
    record both surfaces share: `write_file` carries whole files, `edit_file`
    carries the replacement. Reads are deliberately absent -- the checker
    reviews what CHANGED.
    """
    blocks: dict[str, list[str]] = {}
    order: list[str] = []
    for message in conversation.payload():
        if message.get("role") != "assistant":
            continue
        for call in message.get("tool_calls") or []:
            fn = (call.get("function") or {})
            name = fn.get("name")
            if name not in ("write_file", "edit_file"):
                continue
            try:
                args = json.loads(fn.get("arguments") or "{}")
            except json.JSONDecodeError:
                continue
            if not isinstance(args, dict):
                continue
            args = canonical_arguments(name, args)  # #215
            path = str(args.get("path") or "")
            if not path:
                continue
            if name == "write_file":
                blocks[path] = ["[written whole]\n" + str(args.get("content") or "")]
            else:
                blocks.setdefault(path, []).append(
                    "[edit] replaced:\n%s\nwith:\n%s"
                    % (str(args.get("old") or ""), str(args.get("new") or "")))
            if path not in order:
                order.append(path)
    if not order:
        return ""
    out = []
    for path in order:
        out.append("=== %s ===\n%s" % (path, "\n".join(blocks[path])))
    material = "\n\n".join(out)
    if len(material) > VERIFY_MATERIAL_CHARS:
        material = material[:VERIFY_MATERIAL_CHARS] + "\n[... cut at %d chars]" % VERIFY_MATERIAL_CHARS
    return material


def verify_start(conversation: "Conversation") -> str:
    """`/verify`: delegate this conversation's changes to the checker spot.

    The answer is `delegate`'s own, word for word -- both surfaces say one
    sentence, and `collect` fetches the verdict like any subtask's."""
    material = verify_material(conversation)
    if not material:
        return "nothing to verify -- this conversation has written no file"
    return tool_delegate(task=VERIFY_PROMPT + material)


# #266. THE JUDGE HAS FRESH EYES, AND ONLY EYES. 2026-09-23, diorama run:
# the model scored its own capture "9+ on every criterion" and the capture
# was a small purple box in a black frame. Anthropic's harness for long
# apps puts a SEPARATE evaluator in front of the page because "agents tend
# to respond by confidently praising the work -- even when ... the quality
# is obviously mediocre"; ArtifactsBench (arXiv 2507.04952) scores rendered
# artifacts with a multimodal judge and a per-task checklist. `/verify`
# (#149) is the text sibling: user-triggered, asynchronous, diffs only --
# it cannot gate a `done` in the same turn and it cannot see a render.
#
# WHAT THE JUDGE GETS: the capture(s), the rubric, the goal's title and the
# step's text. Never the conversation -- the maker's narrative ("the black
# screen was a viewport leak, now fixed") is exactly what talked the maker
# into its own score.
#
# WHO JUDGES, strongest reachable first and never the maker's context:
# a `judge` block in providers.json, then the delegate spot and its chain
# (a catalogue row that says it cannot take images is skipped; one that
# does not say is tried), then this turn's own endpoint in a FRESH request
# -- images and rubric only -- refused up front when /props says it is
# blind. That last one is the same weights with none of the history; on a
# one-slot local server it also costs the next turn a cold prefill, and the
# result says so.

# Where the running turn goes (set by `run_turn` for the turn that owns the
# state), for the judge's last fallback.
_TURN_SPOT: dict = {}

JUDGE_TIMEOUT = 240.0
JUDGE_MAX_IMAGES = 4
JUDGE_MAX_TOKENS = 4096
# How many remote spots one call tries before the fresh local request.
JUDGE_REMOTE_TRIES = 3
JUDGE_MAX_CRITERIA = 10
PLAN_FILE = "PLAN.md"

JUDGE_DEFAULT_RUBRIC = (
    "matches what the task asks for",
    "detail density",
    "lighting and colour",
    "composition: the subject fills the frame",
    "image cleanliness: no artefacts, no blank or black areas",
    "looks finished, not a placeholder",
)

# #295: THE CHECKLIST PROMPT. yes/no/unknown per item, one line of evidence
# each, the 1-10 only as a secondary signal. "unknown" is the judge's way
# out (Anthropic, "Demystifying evals for AI agents": give the grader a way
# to say it cannot tell) -- twice on a step pauses it instead of guessing.
JUDGE_PROMPT = (
    "You are a strict visual reviewer. You did not make this work and you "
    "have not seen how it was made; judge only what the image(s) show.\n\n"
    "Task: %(task)s\n%(images)s\n"
    "Answer every checklist item with yes, no or unknown. yes: the image(s) "
    "clearly show it. no: they clearly show it is missing or wrong -- a "
    "blank, black or mostly empty frame is 'no' on every item it cannot "
    "show. unknown: the image(s) do not show enough to tell; say what is "
    "missing. Give one short line of evidence per item. Give no credit for "
    "anything the image(s) do not show.\n\n"
    "Checklist:\n%(criteria)s\n\n"
    "Answer with JSON only, nothing around it:\n"
    '{"checklist": {"<item exactly as written>": {"answer": "yes|no|unknown", '
    '"evidence": "<what in the image shows it>"}, ...}, '
    '"overall": <1-10>, '
    '"weakest": ["<weakest point>", "<second>", "<third>"], '
    '"verdict": "<one sentence>"}')

_RUBRIC_HEAD = re.compile(r"(?im)^#{1,6}\s+.*\b(?:criteria|rubric)\b.*$")
_RUBRIC_INLINE = re.compile(
    r"(?i)(?:\b(?:criteria|rubric)\b|\bscor\w*\b[^\n:.]{0,80}?\bagainst\b)"
    r"\s*:\s*")
_RUBRIC_BULLET = re.compile(r"^\s*(?:[-*+]|\d+[.)])\s+(?:\[[ xX]\]\s+)?(.+)$")


def _rubric_split(text: str) -> "list[str]":
    """`a, b (x, y), and c.` -> [a, b (x, y), c]: commas and semicolons
    outside brackets, a leading "and", markdown emphasis and the full stop
    dropped."""
    parts, depth, cur = [], 0, ""
    for ch in str(text or ""):
        if ch in "([":
            depth += 1
        elif ch in ")]":
            depth = max(0, depth - 1)
        if ch in ",;" and depth == 0:
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    parts.append(cur)
    out = []
    for part in parts:
        item = re.sub(r"\s+", " ", part.replace("*", "").replace("`", ""))
        item = re.sub(r"(?i)^\s*(?:and|or)\s+", "", item).strip(" .:\t")
        if item and len(item) <= 120 and item not in out:
            out.append(item)
    return out


def rubric_from_text(text: str) -> "list[str]":
    """Criteria written down in a plan or a prompt, or []. Two shapes: a
    heading naming criteria or a rubric with a bullet list under it, and a
    sentence "score each 1-10 against: a, b, c." (the diorama prompt's own,
    wrapped over two lines)."""
    text = str(text or "")
    for head in _RUBRIC_HEAD.finditer(text):
        items: "list[str]" = []
        for line in text[head.end():].splitlines()[1:]:
            hit = _RUBRIC_BULLET.match(line)
            if hit:
                name = re.split(r"\s+[—–-]\s+|:\s", hit.group(1).replace(
                    "*", "").replace("`", ""), maxsplit=1)[0].strip(" .")
                if name:
                    items.append(name[:120])
            elif line.strip() and items or line.lstrip().startswith("#"):
                break
        if len(items) >= 2:
            return items[:JUDGE_MAX_CRITERIA]
    for hit in _RUBRIC_INLINE.finditer(text):
        rest = text[hit.end():]
        # THE SENTENCE, NOT THE LINE: it ends at a blank line, the next list
        # item, or a full stop outside brackets.
        stop = re.search(r"\n\s*\n|\n\s*(?:\d+[.)]|[-*+])\s", rest)
        rest = rest[:stop.start()] if stop else rest
        depth, end = 0, len(rest)
        for n, ch in enumerate(rest):
            depth += ch in "(["
            depth -= ch in ")]" and depth > 0
            if ch == "." and depth == 0 and (n + 1 == len(rest)
                                             or rest[n + 1].isspace()):
                end = n
                break
        items = _rubric_split(rest[:end])
        if len(items) >= 2:
            return items[:JUDGE_MAX_CRITERIA]
    return []


def judge_rubric(criteria=None, step_text=None) -> "tuple[list[str], str]":
    """(criteria, where they came from). The user's `accept:` lines win,
    then PLAN.md, then the caller's own, then the default visual rubric --
    the model may only supply a rubric where none is written down. #286:
    without accept lines the step's own text leads ("delivers: <step>");
    what follows may add to it, never replace it -- step 3 'G-buffer and
    voxel volume' passed on step 2's camera criteria the model re-sent."""
    accept = [c for line in goal_accept_get() for c in _rubric_split(line)]
    if accept:
        return accept[:JUDGE_MAX_CRITERIA], "the user's accept lines"
    rubric, source = [], ""
    root = get_root()
    if root:
        try:
            with open(os.path.join(root, PLAN_FILE), encoding="utf-8",
                      errors="replace") as fh:
                rubric = rubric_from_text(fh.read(200_000))
        except OSError:
            rubric = []
        source = PLAN_FILE if rubric else ""
    if not rubric:
        if isinstance(criteria, (list, tuple)):
            rubric = [str(c).strip() for c in criteria if str(c).strip()]
        else:
            rubric = _rubric_split(criteria or "")
        source = "the caller" if rubric else ""
    if not rubric:
        rubric = list(JUDGE_DEFAULT_RUBRIC)
        source = "the default visual rubric"
    step = re.sub(r"\s+", " ", str(step_text or "")).strip()
    if step:
        own = "delivers: " + step[:160]
        rubric = [own] + [c for c in rubric if c != own]
        source = "the step + " + source
    return rubric[:JUDGE_MAX_CRITERIA], source


def judge_images(images=None, goal: "dict | None" = None,
                 room: int = JUDGE_MAX_IMAGES,
                 found: "dict | None" = None) -> "tuple[list[str], str | None]":
    """The files to judge, or an error. Default: the newest render_page
    capture. A capture's `-crop.png` (the content, enlarged -- #265)
    rides along when it exists.

    #295: when the render recorded clock-stepped `frames` for the capture,
    those go instead (up to `room`), else its `contact_sheet` with the
    capture -- a single frame cannot show rain falling."""
    picked: "list[str]" = []
    if images:
        items = images if isinstance(images, (list, tuple)) \
            else re.split(r"[,\n]", str(images))
        for item in items:
            item = str(item).strip()
            if not item:
                continue
            path = _rooted(item)
            if not os.path.isfile(path):
                return [], "error: no such image: %s" % path
            if os.path.splitext(path)[1].lower() not in IMAGE_TYPES:
                return [], "error: not an image: %s" % path
            picked.append(path)
    else:
        folder = _render_dir()
        try:
            names = [n for n in os.listdir(folder) if n.startswith("render-")
                     and n.endswith(".png") and not n.endswith("-crop.png")]
        except OSError:
            names = []
        if not names:
            return [], ("error: no capture to judge -- call render_page on "
                        "the deliverable first, or pass images")
        newest = max(names, key=lambda n: os.path.getmtime(
            os.path.join(folder, n)))
        picked.append(os.path.join(folder, newest))
    out: "list[str]" = []
    contract = render_contract_of(picked[0], goal) if len(picked) == 1 else None
    if found is not None:
        # The capture and its render facts, for the caller's precheck.
        found.update(capture=picked[0], contract=contract)
    frames = [_rooted(str(f)) for f in (contract or {}).get("frames") or []]
    frames = [f for f in frames if os.path.isfile(f)]
    sheet = (contract or {}).get("contact_sheet")
    sheet = _rooted(str(sheet)) if sheet else None
    if len(frames) >= 2:
        out = frames[:max(1, room)]
    elif sheet and os.path.isfile(sheet):
        out = [picked[0], sheet]
    for path in picked if not out else []:
        if path not in out:
            out.append(path)
        crop = os.path.splitext(path)[0] + "-crop.png"
        if not path.endswith("-crop.png") and os.path.isfile(crop) \
                and crop not in out:
            out.append(crop)
    for path in out:
        if os.path.getsize(path) > IMAGE_MAX_BYTES:
            return [], "error: image is over %d MiB: %s" % (
                IMAGE_MAX_BYTES >> 20, path)
    return out[:max(1, room)], None


def _catalogue_vision(provider: str, model: str,
                      doc: "dict | None" = None) -> "bool | None":
    """What the stored catalogue declares about a model's eyes: True, False,
    or None for "did not say"."""
    for row in provider_models(provider, doc):
        if str(row.get("id")) == model:
            seen = row.get("vision")
            return seen if isinstance(seen, bool) else None
    return None


def judge_spots(doc: "dict | None" = None) -> "list[dict]":
    """Where a judgement is asked, in order. Each spot carries `how`."""
    doc = provider_doc() if doc is None else doc
    remote: "list[dict]" = []
    seen: set = set()

    def add(spot: "dict | None", how: str) -> None:
        if not spot or not spot.get("model") or len(remote) >= JUDGE_REMOTE_TRIES:
            return
        key = (spot.get("provider"), spot.get("model"))
        if key in seen or _catalogue_vision(key[0], key[1], doc) is False:
            return
        seen.add(key)
        remote.append(dict(spot, how=how))

    block = doc.get("judge") if isinstance(doc.get("judge"), dict) else {}
    local_only = block.get("provider") == LOCAL_PROVIDER
    if block.get("provider") and not local_only:
        pinned, _why = delegate_target(dict(doc, delegate=block))
        add(pinned, "pinned as judge in providers.json")
    if not local_only:
        spot, _why = delegate_target(doc)
        if spot:
            add(spot, "the delegate spot")
            for other in delegate_fallbacks(spot, doc):
                add(other, "a delegate fallback")
    own = dict(_TURN_SPOT) if _TURN_SPOT.get("base_url") else None
    if own is None:
        end = provider_endpoint()
        own = {"base_url": end["base_url"], "model": end["model"],
               "api_key": end["api_key"], "remote": end["remote"],
               "headers": end.get("headers") or {},
               "transport": end.get("transport") or TRANSPORT_CHAT,
               "served": end["model"]}
    own.setdefault("provider", "this turn's endpoint")
    own["how"] = "this conversation's own model, in a fresh context"
    return remote + [own]


def _judge_ask(spot: dict, prompt: str, paths: "list[str]") -> str:
    """One request, no history: the prompt and the images. The answer's
    text, or raise."""
    # #297: never while serve holds VRAM on loan -- it parks every chat
    # request until the return, so this one would wait out the TTL. The
    # render's own `finally` already returned it; this pins the order.
    _render_vram_return()
    if not spot.get("remote"):
        blind = refuse_images(spot["base_url"])
        if blind:
            raise CrowError(blind)
    content = [{"type": "text", "text": prompt}] + [image_part(p) for p in paths]
    sampling = sampling_for(spot.get("served") or spot["model"])
    body = {"model": spot["model"], "stream": False,
            "messages": [{"role": "user", "content": content}],
            "temperature": sampling["temperature"], "top_p": sampling["top_p"],
            "min_p": sampling["min_p"], "max_tokens": JUDGE_MAX_TOKENS}
    if sampling.get("top_k") is not None:
        body["top_k"] = sampling["top_k"]
    transport = spot.get("transport") or TRANSPORT_CHAT
    if spot.get("remote"):
        remote_body(body)
    base = str(spot["base_url"]).rstrip("/")
    if transport == TRANSPORT_MESSAGES:
        body = anthropic_body(body)
        url = base + "/messages"
    else:
        url = base + "/chat/completions"
    request = urllib.request.Request(
        url, data=json.dumps(body).encode("utf-8"), method="POST",
        headers=dict(_stream_headers(spot.get("api_key") or "",
                                     spot.get("headers") or None),
                     **{"Accept": "application/json"}))
    try:
        with urllib.request.urlopen(request, timeout=JUDGE_TIMEOUT) as resp:
            answer = json.loads(resp.read().decode("utf-8") or "{}")
    except urllib.error.HTTPError as exc:
        try:
            said = exc.read().decode("utf-8", "replace")
            said = str(((json.loads(said) or {}).get("error") or {})
                       .get("message") or said)
        except Exception:                   # noqa: BLE001 - detail only
            said = ""
        finally:
            exc.close()
        raise CrowError("HTTP %s %s" % (exc.code, said.strip()[:200]))
    if transport == TRANSPORT_MESSAGES:
        text = "".join(b.get("text") or "" for b in answer.get("content") or []
                       if b.get("type") == "text")
    else:
        text = (((answer.get("choices") or [{}])[0].get("message") or {})
                .get("content") or "")
    return _strip_think(text).strip()


def _judge_key(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", str(text).lower()).strip()


def _judge_step(goal: "dict | None", step) -> "int | None":
    """The 0-based step a verdict belongs to: the one named, else the
    running one, else the first open one."""
    steps = (goal or {}).get("steps") or []
    if not steps:
        return None
    try:
        index = int(step) - 1
        if 0 <= index < len(steps):
            return index
    except (TypeError, ValueError):
        pass
    running = next((n for n, s in enumerate(steps)
                    if s.get("status") == GOAL_RUNNING), None)
    return running if running is not None else goal_next_open(goal)


def judge_store(index: int, verdict: dict) -> bool:
    """Write the verdict onto step `index` of the goal on disk. #294: the
    items it answered "yes" join the step's `passed` -- the no-progress
    timer watches that list grow."""
    with _GOAL_LOCK:
        goal = goal_load()
        if not goal or not 0 <= index < len(goal["steps"]):
            return False
        step = goal["steps"][index]
        step["judge"] = verdict
        passed = list(step.get("passed") or [])
        for item, answer in (verdict.get("checklist") or {}).items():
            if answer == "yes" and item not in passed:
                passed.append(item)
        if passed:
            step["passed"] = passed
        goal_write(goal)
        return True


_JUDGE_YES = ("yes", "y", "true", "pass", "passed", "met")
_JUDGE_NO = ("no", "n", "false", "fail", "failed", "not met")


def _judge_answer(value) -> "tuple[str | None, str]":
    """(yes|no|unknown, evidence) from one checklist value, or (None, "")."""
    evidence = ""
    if isinstance(value, dict):
        evidence = str(value.get("evidence") or value.get("why") or "")
        value = value.get("answer", value.get("verdict"))
    if isinstance(value, bool):
        return ("yes" if value else "no"), evidence
    if value is None:
        return None, evidence
    word = str(value).strip().lower().rstrip(".")
    if word in _JUDGE_YES:
        return "yes", evidence
    if word in _JUDGE_NO:
        return "no", evidence
    return "unknown", evidence


def judge_parse_checklist(text: str, items: "list[dict]"
                          ) -> "tuple[dict | None, str | None]":
    """#295. The judge's JSON as {checklist, evidence, must, pass, no,
    unknown, overall, weakest, verdict, missing}, or an error. An item the
    judge left out is "unknown"; more than half left out is no verdict. A
    judge that answered in the old 1-10 form is read with the threshold."""
    raw = str(text or "")
    start, end = raw.find("{"), raw.rfind("}")
    if start < 0 or end <= start:
        return None, "the judge answered without JSON: %r" % raw[:160]
    try:
        doc = json.loads(raw[start:end + 1])
    except ValueError as exc:
        return None, "the judge's JSON does not parse (%s): %r" % (exc, raw[:160])
    if not isinstance(doc, dict):
        return None, "the judge's JSON is not an object"
    given = doc.get("checklist")
    if isinstance(given, list):
        given = {str(x.get("item") or ""): x for x in given
                 if isinstance(x, dict)}
    if not isinstance(given, dict):
        scores = doc.get("scores")
        if not isinstance(scores, dict):
            return None, "the judge's JSON has no checklist object"
        given = {k: ("yes" if _num(v) is not None and _num(v) >= JUDGE_THRESHOLD
                     else "no") for k, v in scores.items()}
    by_key = {_judge_key(k): v for k, v in given.items()}
    answers, evidence, missing = {}, {}, []
    for entry in items:
        name = entry["item"]
        key = _judge_key(name)
        value = by_key.get(key)
        if value is None:
            value = next((v for k, v in by_key.items()
                          if k and (k.startswith(key) or key.startswith(k))),
                         None)
        answer, why = _judge_answer(value)
        if answer is None:
            missing.append(name)
            answer = "unknown"
        answers[name] = answer
        if why:
            evidence[name] = why[:240]
    if len(missing) * 2 > len(items):
        return None, "the judge answered %d of %d checklist items" % (
            len(items) - len(missing), len(items))
    must = [e["item"] for e in items if e.get("must", True)]
    no = [m for m in must if answers[m] == "no"]
    unknown = [m for m in must if answers[m] == "unknown"]
    overall = _num(doc.get("overall"))
    weakest = doc.get("weakest")
    weakest = [str(w)[:240] for w in weakest if str(w).strip()][:3] \
        if isinstance(weakest, list) else []
    return ({"checklist": answers, "evidence": evidence, "must": must,
             "pass": bool(must) and not no and not unknown,
             "no": no, "unknown": unknown,
             "overall": None if overall is None
             else max(1, min(10, int(round(overall)))),
             "weakest": weakest or no[:3] or unknown[:3],
             "verdict": str(doc.get("verdict") or "")[:400],
             "missing": missing}, None)


def tool_judge(images=None, criteria=None, step=None, **_) -> str:
    """#266. Judge a capture with fresh eyes. JSON.

    #295: against the step's FROZEN checklist, yes/no/unknown per item, on
    the render's frames or contact sheet; a capture that fails the cheap
    precheck (software GL on a GPU step, uniform, black, identical frames on
    a motion step) never reaches the judge model -- it is an ENVIRONMENT
    failure. #294: every miss goes through `goal_fail`, and the answer says
    which rung comes next."""
    goal = goal_load()
    index = _judge_step(goal, step)
    pause = goal_paused(goal)
    if pause is not None:
        return json.dumps({"ok": False, "error": (
            "the goal is PAUSED at step %s and waits for the user's line. "
            "Call no tools: write your report and stop." % pause.get("step"))})
    at = time.time()
    room = max(2, JUDGE_MAX_IMAGES - min(len(goal_references()),
                                         GOAL_REFERENCE_MAX))
    picked: dict = {}
    paths, bad = judge_images(images, goal, room=room, found=picked)
    if bad:
        return json.dumps({"ok": False, "error": bad})
    root = get_root()
    shown = [os.path.relpath(p, root) if root and p.startswith(root) else p
             for p in paths]
    capture = picked.get("capture") or paths[0]
    contract = picked.get("contract")
    # THE PRECHECK, before any model is asked and before a checklist is
    # frozen on a frame that shows nothing (#295).
    env = capture_precheck(paths, contract, goal, index)
    if env:
        out = {"ok": False, "class": GOAL_ENV, "judge_called": False,
               "precheck": env, "images": shown,
               "render_mode": (contract or {}).get("render_mode")}
        if index is not None:
            verdict = goal_fail(index, GOAL_ENV, env, capture=capture,
                                source="precheck")
            out.update(step=index + 1, action=verdict["action"],
                       then=goal_fail_said(index, verdict))
        out["error"] = ("environment: %s -- the judge was not asked. %s"
                        % (env, out.get("then") or ""))
        return json.dumps(out, ensure_ascii=False)
    # THE CHECKLIST: frozen at step start, or here at the latest.
    if index is not None:
        if not goal_checklist(goal, index):
            with _GOAL_LOCK:
                fresh = goal_load() or goal
                given = ([str(c) for c in criteria] if isinstance(
                    criteria, (list, tuple)) else _rubric_split(criteria or ""))
                accept = goal_accept_for(index)
                if accept:
                    _checklist_freeze_in(fresh, index, accept,
                                         GOAL_CHECK_FROM_USER, at)
                else:
                    _checklist_freeze_in(fresh, index,
                                         given or [GOAL_CHECK_DEFAULT_FRAME],
                                         GOAL_CHECK_FROM_JUDGE, at)
                goal_write(fresh)
            goal = goal_load() or goal
        items = goal_checklist(goal, index)
        source = goal["steps"][index].get("checklist_from") or "?"
    else:
        rubric, source = judge_rubric(criteria, None)
        items = [{"item": c, "must": True} for c in rubric]
    refs = [c["reference"] for c in items
            if c.get("reference") and os.path.isfile(c["reference"])]
    refs = refs[:GOAL_REFERENCE_MAX]
    task = "a visual deliverable"
    if goal:
        task = goal.get("title") or task
        if index is not None:
            task += " -- current step: %s" % goal["steps"][index]["text"]
    kinds = contract or {}
    framed = [_rooted(str(f)) for f in kinds.get("frames") or []]
    sheet = _rooted(str(kinds["contact_sheet"])) \
        if kinds.get("contact_sheet") else None
    if len(paths) >= 2 and paths[0] in framed:
        said_images = ("The %d images are clock-stepped frames of the same "
                       "page, in time order; judge motion across them."
                       % len(paths))
    elif sheet and sheet in paths:
        said_images = ("The second image is a contact sheet of clock-stepped "
                       "frames of the same page; judge motion across it.")
    elif any(p.endswith("-crop.png") for p in paths[1:]):
        said_images = ("The second image is an enlarged crop of the first "
                       "image's content.")
    else:
        said_images = ""
    if refs:
        said_images += (" The last %d image%s %s REFERENCE image%s the user "
                        "supplied: for each item that names a reference, "
                        "compare the capture with it (pairwise)."
                        % (len(refs), "" if len(refs) == 1 else "s",
                           "is a" if len(refs) == 1 else "are",
                           "" if len(refs) == 1 else "s"))
    prompt = JUDGE_PROMPT % {
        "task": task, "images": said_images,
        "criteria": "\n".join("- %s%s" % (c["item"],
                                          "" if c.get("must", True)
                                          else " (optional)") for c in items)}
    failures = []
    for spot in judge_spots():
        name = "%s/%s" % (spot.get("provider") or "?", spot.get("model") or "?")
        try:
            text = _judge_ask(spot, prompt, paths + refs)
        except Exception as exc:            # noqa: BLE001 - next spot
            failures.append("%s: %s" % (name, str(exc)[:200]))
            continue
        verdict, why = judge_parse_checklist(text, items)
        if verdict is None:
            failures.append("%s: %s" % (name, why))
            continue
        verdict.update({"model": name, "how": spot.get("how"),
                        "images": shown, "references": refs,
                        "checklist_from": source,
                        "rubric_source": source,
                        "criteria": [c["item"] for c in items],
                        "at": round(at, 1)})
        stored = index is not None and judge_store(index, verdict)
        out = {"ok": True, "judge": name, "chosen_as": spot.get("how"),
               "fresh_context": True, "checklist": verdict["checklist"],
               "evidence": verdict["evidence"], "passes": verdict["pass"],
               "overall": verdict["overall"], "weakest": verdict["weakest"],
               "verdict": verdict["verdict"], "checklist_from": source,
               "images": shown, "step": index + 1 if stored else None}
        if verdict["missing"]:
            out["unanswered"] = verdict["missing"]
        if failures:
            out["tried_first"] = failures
        if not spot.get("remote"):
            # Self-preference (Panickssery et al., NeurIPS 2024): the actor's
            # own weights judged -- fresh context, but the same model.
            out["fresh_context_only"] = True
            out["note"] = ("judged by this conversation's own model in a "
                           "fresh request; the next turn re-reads the "
                           "conversation cold")
        if not verdict["pass"] and index is not None:
            if verdict["no"]:
                miss = goal_fail(index, GOAL_CAP, "the judge says no on: %s"
                                 % "; ".join(verdict["no"][:4]),
                                 capture=capture, source="judge")
            else:
                miss = goal_fail(index, GOAL_UNKNOWN, "the judge cannot tell "
                                 "on: %s" % "; ".join(verdict["unknown"][:4]),
                                 capture=capture, source="judge")
            out["failure"] = {"class": miss["class"], "action": miss["action"],
                              "counted": miss["counted"]}
            out["next"] = goal_fail_said(index, miss)
        elif not verdict["pass"]:
            out["next"] = ("fix what the judge said no or unknown to, render "
                           "again, and call judge again")
        return json.dumps(out, ensure_ascii=False)
    out = {"ok": False, "class": GOAL_ENV, "judge_called": True,
           "error": ("no judge answered: %s. Pin a vision model as `judge` "
                     "({\"provider\": ..., \"model\": ...}) in providers.json, "
                     "or run the local server with its projector."
                     % "; ".join(failures))}
    if index is not None:
        miss = goal_fail(index, GOAL_ENV, "no judge answered",
                         capture="judge:" + capture, source="judge")
        out.update(step=index + 1, action=miss["action"],
                   then=goal_fail_said(index, miss))
    return json.dumps(out, ensure_ascii=False)


def tool_delegate(task: str = "", context: str = "", **_) -> str:
    global _SUBTASK_SEQ
    # Vor der ersten Nummernvergabe: die geladenen Nummern zaehlen mit,
    # sonst kollidiert das frische d1 mit dem gestrigen.
    _ensure_subtasks_recalled()
    task = (task or "").strip()
    if not task:
        return "error: delegate needs a task"
    spot, problem = delegate_target()
    if problem:
        return "error: %s" % problem
    with _SUBTASK_LOCK:
        running = sum(1 for s in SUBTASKS.values() if s.status == "running")
        if running >= SUBTASK_LIMIT:
            return ("error: %d subtasks are already running -- collect before "
                    "delegating more" % SUBTASK_LIMIT)
        _SUBTASK_SEQ += 1
        ident = "d%d" % _SUBTASK_SEQ
        sub = Subtask(ident, task, (context or "").strip(), spot)
        SUBTASKS[ident] = sub
    # STARTED OUTSIDE THE LOCK: the thread's first act is network I/O, and
    # nothing it touches needs the registry lock to be held for it.
    thread = threading.Thread(target=_run_subtask, args=(sub, spot), daemon=True)
    sub.thread = thread
    thread.start()
    # Auch der Start steht auf Platte: stirbt Crow mitten im Lauf, kommt der
    # Record als ehrliches "interrupted" zurueck statt gar nicht.
    _subtask_persist()
    return ("%s delegated to %s -- running. It sees only what you sent. "
            "collect('%s') or collect('all') returns the result; subtasks() "
            "shows where things stand." % (ident, spot["model"], ident))


def tool_subtasks(**_) -> str:
    _ensure_subtasks_recalled()
    with _SUBTASK_LOCK:
        subs = list(SUBTASKS.values())
    if not subs:
        return "nothing delegated in this session"
    lines = []
    for sub in subs:
        state = sub.status + (", collected" if sub.collected else "")
        # ASCII on purpose, like the cost line: a tool result is printed on
        # whatever console the terminal has, and cp1252 turns a middle dot
        # into mojibake.
        lines.append("%s %s | %s | %.1f s | %s tok -- %s"
                     % (sub.ident, state, sub.model, sub.clock(),
                        format(sub.tokens, ","), sub.head()))
    return "\n".join(lines)


def _collect_wait(picked: "list[Subtask]") -> "str | None":
    """Wait for the named subtasks, or say why the waiting stopped.

    A POLLING JOIN, NOT A BARE ONE, for two doors out that a blocked call must
    keep open: the INTERRUPT flag -- checked, NEVER cleared, it belongs to the
    turn this call runs inside -- and the deadline that turns a stalled
    provider into a sentence instead of a frozen turn. Ctrl+C lands here as
    KeyboardInterrupt when the process gets the signal mid-join; it is
    answered, not re-raised, because a tool result is recoverable and a killed
    turn costs the whole prefix.
    """
    deadline = time.monotonic() + COLLECT_TIMEOUT
    for sub in picked:
        thread = sub.thread
        while thread is not None and thread.is_alive():
            if INTERRUPT.is_set():
                return ("error: interrupted while waiting -- the subtasks run "
                        "on; collect again for what is still out")
            if time.monotonic() >= deadline:
                return ("error: still running after %.0f s -- subtasks() shows "
                        "the state; collect again to keep waiting"
                        % COLLECT_TIMEOUT)
            try:
                thread.join(_COLLECT_SLICE)
            except KeyboardInterrupt:
                return ("error: interrupted while waiting -- the subtasks run "
                        "on; collect again for what is still out")
    return None


def tool_collect(id: str = "all", **_) -> str:
    _ensure_subtasks_recalled()
    wanted = (id or "all").strip()
    with _SUBTASK_LOCK:
        subs = list(SUBTASKS.values())
    if not subs:
        return "error: nothing delegated -- call delegate first"
    if wanted == "all":
        picked = [s for s in subs if not s.collected]
        if not picked:
            return "every subtask is already collected -- subtasks() lists them"
    else:
        with _SUBTASK_LOCK:
            sub = SUBTASKS.get(wanted)
        if sub is None:
            return ("error: no subtask %s -- subtasks() lists what there is"
                    % wanted)
        picked = [sub]
    problem = _collect_wait(picked)
    if problem:
        return problem
    parts = []
    for sub in picked:
        sub.collected = True
        if sub.status == "done":
            # #216: the fallback note rides along -- the model
            # that reads this result should know it came from a second spot.
            parts.append("== %s | %s | %.1f s | %s tok%s\n%s"
                         % (sub.ident, sub.model, sub.seconds,
                            format(sub.tokens, ","),
                            " | " + sub.failure if sub.failure else "",
                            sub.result.strip()))
        else:
            parts.append("== %s %s after %.1f s -- %s"
                         % (sub.ident, sub.status, sub.seconds, sub.failure))
    # `collected` ist Teil des Records und ueberlebt mit ihm.
    _subtask_persist()
    out = "\n\n".join(parts)
    # THE PREFIX IS THE MODEL'S RECOVERY SIGNAL, so it is earned only when
    # there is nothing to work with: one result among failures is a result.
    if not any(s.status == "done" for s in picked):
        return "error: " + out
    return out


def subtask_view() -> "list[dict]":
    """What a surface draws for the delegation state, one dict per subtask.

    THE REGISTRY SPEAKS ONCE, HERE. The window's cards, its rail children and
    its chip all read this list; a surface with its own idea of subtask state
    would show running where the registry says done. `res` is the RESULT for a
    finished subtask and the FAILURE SENTENCE for a dead one -- both are what
    the reader needs behind the fold -- and empty while it runs.
    """
    _ensure_subtasks_recalled()
    with _SUBTASK_LOCK:
        subs = list(SUBTASKS.values())
    out = []
    for sub in subs:
        if sub.status == "done":
            res = sub.result
        elif sub.status == "running":
            res = ""
        else:
            res = sub.failure
        out.append({"i": sub.ident, "task": sub.head(), "model": sub.model,
                    "st": sub.status, "s": round(sub.clock(), 1),
                    "tok": sub.tokens, "res": res, "path": sub.transcript,
                    "collected": sub.collected,
                    # 2026-08-28 spaetnachts: der Eltern-Chat reist im Record
                    # mit, damit die Rail nach einem Neustart weiss, wohin.
                    "parent": getattr(sub, "parent", ""),
                    # #281: the card was closed over it (view state only).
                    "closed": bool(getattr(sub, "closed", False))})
    return out


def subtasks_running() -> bool:
    """Whether anything delegated is still out."""
    with _SUBTASK_LOCK:
        return any(s.status == "running" for s in SUBTASKS.values())


def cancel_subtasks() -> int:
    """Stop reaches the subtasks too (#143 E2). Returns how many were marked.

    THE MARK IS THE KILL, NOT THE THREAD'S DEATH. A stream blocked in a socket
    read cannot be interrupted from outside; what CAN be promised is that a
    cancelled subtask delivers nothing -- `_run_subtask` drops the result,
    writes no transcript and closes the record as "interrupted". Only running
    subtasks are marked: one that finished before Stop was pressed DID finish,
    and rewriting that would be fiction.
    """
    marked = 0
    with _SUBTASK_LOCK:
        subs = list(SUBTASKS.values())
    for sub in subs:
        if sub.status == "running":
            sub.cancelled = True
            marked += 1
    return marked


# EVERY DECLARED NAME GETS AN IMPLEMENTATION -- the sentence `mcp_apply`
# carries. Late, because the implementations need `run_turn` and the provider
# registry above; `mcp_apply` deletes only `mcp_`-prefixed names on a rebuild,
# so these three survive every one of them.
TOOL_IMPL.update({"delegate": tool_delegate,
                  "subtasks": tool_subtasks,
                  "collect": tool_collect,
                  "goal_set": tool_goal_set,
                  "goal_step": tool_goal_step,
                  "judge": tool_judge})                        # #266


# ---------------------------------------------------------------- #163 -----
#
# DER ZIELSPEICHER. Ein Ziel ist ein Titel und eine Liste von Schritten, und es
# muss VIER Dinge ueberleben, von denen jedes einen anderen Speicher ausschliesst:
#
#   Rollover      `roll_over` ruft `conversation.reset()` -- Nachrichten weg, Pin
#                 weg. Alles, was nur in der Conversation steht, ist beim ersten
#                 Schnitt fort.
#   Serverneustart und Fensterneustart -- alles im Prozess ist fort.
#   Neue Sitzung  ein frisches Fenster weiss nichts von einem Ziel, das laeuft.
#   Chat geloescht  das Ziel gehoert dem NUTZER, nicht dem Chat, in dem es getippt
#                 wurde.
#
# WARUM NICHT DIE SUBTASK-REGISTRY, obwohl ihre Satzform genau passt (status,
# seconds, prompt_tokens, reply_tokens, transcript): sie sagt von sich selbst,
# sie sei "this process's memory, not the session's", und `drop_subtasks` raeumt
# sie MIT dem Chat ab. Beide Lebensdauern sind genau die, die hier nicht sein
# duerfen. Die FORM ist uebernommen, der Ort nicht.
#
# DER FORTSCHRITT STEHT NICHT IM KOPF, und das ist die teuerste Regel hier.
# Titel und Schrittliste gehoeren in den gepinnten Block, damit das Modell weiss,
# worauf es hinarbeitet. Ein Haken daran waere eine Kopfaenderung, und die kostet
# einen vollen Prefill -- gemessen am 2026-08-30 bei 8k Tiefe als `cached 0/7,923`,
# bei 200k sind das Minuten. Fuenf Schritte waeren fuenf volle Prefills. Also:
# der Kopf traegt den PLAN, die Datei traegt den STAND.
#
# DIE UHR IST WANDUHR, NICHT `monotonic`. Sie springt bei einer Zeitumstellung,
# und das ist der kleinere Preis: `monotonic` zaehlt ab Prozessstart und waere
# nach genau dem Neustart wertlos, den dieser Speicher ueberleben soll.

GOAL_FORMAT = 1

# Was ein Schritt sein kann. `running` ist der eine Zustand, den nur EIN Schritt
# gleichzeitig tragen darf -- der lokale Server hat einen Slot (#143), also gibt
# es keine zwei gleichzeitig laufenden Schritte, und ein Speicher, der das
# zuliesse, beschriebe eine Maschine, die es nicht gibt.
GOAL_OPEN, GOAL_RUNNING, GOAL_DONE, GOAL_FAILED = ("open", "running",
                                                   "done", "failed")
# #289: A STEP THAT FAILED TWICE, or one the user skipped (`/goal skip`). It
# counts as NOT done, and the goal moves on past it. 2026-09-24, diorama run:
# step 4 went `failed` with an honest note (software GL cannot show ray
# lighting), `goal_next_open` handed it back as the next step on every turn,
# and the run sat on it for ~2 h 20 min until the user edited goal.json by hand.
GOAL_SKIPPED = "skipped"
# #289: THE GOAL'S OWN STATE when every step is done or skipped and at least
# one is skipped -- "complete with N skipped", never `done`: a skipped step
# is work that did not happen, and `done` would say it did.
GOAL_PARTIAL = "partial"
# #294: NO STEP IS SKIPPED BY THE ENGINE. #289 skipped a step on its second
# `failed`; on 2026-09-24/25 that skipped steps 5-8 of the diorama goal on
# software-GL captures, and nobody was asked (goal.json `failures` 3/2/2/2,
# session.json msg 176/269/313/347). Only the user skips (`/goal skip n`). A
# failure now has a CLASS and a ladder, and the end of every ladder is a
# PAUSE that reports and asks -- see `goal_fail`.
GOAL_PAUSED = "paused"
GOAL_ENV = "environment"      # the instrument failed: no GPU, blank, judge gone
GOAL_CAP = "capability"       # a valid capture, and the judge says: not met
GOAL_UNKNOWN = "unknown"      # the judge cannot tell from the capture
# #294: ENVIRONMENT -- retry at most this often, a short wait apart, then
# pause (Claude Code /goal: "After three automatic retries, the goal pauses
# instead"; the Azure retry pattern: bounded count, delay between).
GOAL_ENV_RETRIES = 2
GOAL_ENV_DELAY = 15.0
# #295: "unknown" on a must-item this often on one step pauses it.
GOAL_UNKNOWN_PAUSE = 2
# #294: THE STEP'S BUDGET. Active wall clock per step (the clock stops while
# the goal is paused), and the no-progress timer: this many nudges on one
# step with no checklist item newly passed. `goal_step_minutes` /
# `goal_no_progress_turns` in settings.json, CROW_GOAL_STEP_MINUTES /
# CROW_GOAL_NO_PROGRESS_TURNS over both. 0 switches one off.
GOAL_STEP_MINUTES_DEFAULT = 60
GOAL_NO_PROGRESS_DEFAULT = 10
GOAL_STEP_MINUTES = GOAL_STEP_MINUTES_DEFAULT
GOAL_NO_PROGRESS_TURNS = GOAL_NO_PROGRESS_DEFAULT


# WIEVIEL KONTEXT GERADE STEHT. Gemeldet von der Runde, die ihn gerade gelesen
# hat -- derselbe Wert, den die Kostenzeile zeigt (`usage.total_tokens`, seit
# #60). 0 heisst "niemand hat es gesagt", und dann bleibt die Tokenspalte eines
# Schritts leer statt falsch.
GOAL_TOKENS_NOW = 0

# LESEN, AENDERN, SCHREIBEN IST DREI SCHRITTE, und zwei Threads tun es. Der Zug
# bucht je Runde, und eine Delegation bucht aus IHREM Thread, wenn sie
# zurueckkommt -- ohne diese Sperre ueberschreibt der spaetere Schreiber den
# frueheren, und die verlorene Buchung ist genau die, die niemand vermisst.
_GOAL_LOCK = threading.Lock()


_GOAL_REBASE = False


def goal_tokens_rebase(total: int) -> None:
    """#263: the context shrank by an ESTIMATE; the next round sets the base."""
    global GOAL_TOKENS_NOW, _GOAL_REBASE
    GOAL_TOKENS_NOW = max(0, int(total or 0))
    _GOAL_REBASE = True


def goal_tokens_mark(total: int) -> None:
    """Den Zaehler setzen, OHNE die Differenz zu verbuchen.

    DER UNTERSCHIED ZU `goal_tokens_seen` IST DER GANZE PUNKT: ein Zug, der auf
    einem wiederhergestellten Chat aufsetzt, findet dort 50k vor, die niemand in
    diesem Moment ausgegeben hat. Wer die als Wachstum verbucht, schreibt einem
    Ziel den ganzen Chat an, in dem es gesetzt wurde. Gesetzt wird deshalb am
    ANFANG eines Zuges, verbucht wird nach jeder Runde.
    """
    global GOAL_TOKENS_NOW
    GOAL_TOKENS_NOW = max(0, int(total or 0))


def goal_tokens_seen(total: int, now: "float | None" = None) -> None:
    """Der Kontextstand nach einer RUNDE, und was er das Ziel gekostet hat.

    JE RUNDE, NICHT JE ZUG -- das ist #169. Der Wert erreichte den Speicher
    einmal am Zugende, abgehakt wird aber mehrfach INNERHALB eines Zuges (der
    Lauf vom 2026-08-30 machte 27 Runden in einem Zug). Zur Hakenzeit stand
    deshalb noch der Stand des VORIGEN Zuges: die ersten Schritte differenzierten
    gegen 0 und lasen 0, der erste Haken nach einer Zuggrenze verschluckte alles.

    DER SPRUNG NACH UNTEN IST KEIN FEHLER, SONDERN EIN NEUER KONTEXT. Nach einem
    Rollover faengt der absolute Zaehler wieder klein an; die neue Tiefe ist
    frisch prefillt, also IST sie Ausgabe. `spent` waechst dadurch monoton weiter
    und ueberlebt den Schnitt -- das ist die Zahl, die #174 im Kopf verlangt, und
    sie ist nicht die Summe der Schrittspalte.
    """
    global GOAL_TOKENS_NOW, _GOAL_REBASE
    total = max(0, int(total or 0))
    before, GOAL_TOKENS_NOW = GOAL_TOKENS_NOW, total
    if _GOAL_REBASE:
        # #263: the first count after a clearing batch is a new baseline --
        # the drop is freed context, not a new one, and the difference to
        # the estimate is not output either. That round's growth goes unbooked.
        _GOAL_REBASE = False
        return
    grew = total - before if total >= before else total
    if grew <= 0:
        return
    with _GOAL_LOCK:
        goal = goal_load()
        if goal is None:
            return
        goal["spent"] = int(goal.get("spent") or 0) + grew
        # DIE ERSTE RUNDE IST DER ANFANG. Frueher gibt es kein Lebenszeichen:
        # zwischen `/goal` und dem ersten Zug passiert nichts als Tippen.
        _goal_begun(goal, float(now if now is not None else time.time()))
        goal_write(goal)


def goal_delegated_seen(tokens: int) -> None:
    """Was eine Delegation gekostet hat, auf dem Schritt, der gerade laeuft.

    GETRENNT GEFUEHRT UND NICHT ADDIERT, und das ist die Entscheidung, die #169
    verlangt: das sind die Token eines FREMDEN Anbieters auf einem fremden Spot.
    In die lokale Summe gemischt waere der Kopf eine Zahl ueber zwei Dinge, und
    niemand koennte sie mehr gegen die Kostenzeile halten.

    DIE DRITTE ANTWORT WAR DIE SCHLECHTESTE: eine stille 0. So standen M1.1 bis
    M1.3 am 2026-08-30 im Panel -- drei delegierte Schritte, achtzehn Minuten,
    "0 tok", und das liest sich wie "hat nichts gekostet".

    LAEUFT KEIN SCHRITT, zaehlt es trotzdem beim Ziel: eine Delegation, die
    zwischen zwei Schritten zurueckkommt, hat stattgefunden.
    """
    tokens = max(0, int(tokens or 0))
    if tokens <= 0:
        return
    with _GOAL_LOCK:
        goal = goal_load()
        if goal is None:
            return
        goal["delegated"] = int(goal.get("delegated") or 0) + tokens
        for step in goal.get("steps") or []:
            if step.get("status") == GOAL_RUNNING:
                step["delegated"] = int(step.get("delegated") or 0) + tokens
                break
        goal_write(goal)


def goal_spent(goal: "dict | None" = None) -> int:
    """Was dieses Ziel gekostet hat, ueber jeden Kontext hinweg, in dem es lebte.

    NICHT DIE SUMME DER SCHRITTE (#174): der Kopf las bis hier die Spalte auf,
    erbte damit jeden Fehler darin und liess alles weg, was zwischen zwei
    Schritten passiert -- Nachdenken, Werkzeuge, der Rollover selbst.
    """
    goal = goal if goal is not None else goal_load()
    return int((goal or {}).get("spent") or 0)


def goal_delegated(goal: "dict | None" = None) -> int:
    """Die Token, die dieses Ziel auf fremden Spots ausgegeben hat."""
    goal = goal if goal is not None else goal_load()
    return int((goal or {}).get("delegated") or 0)


GOAL_FILE = "goal.json"


def goal_path() -> str:
    """Wo das Ziel liegt: im gebundenen Arbeitsbereich, NICHT global.

    DER OWNER, 2026-08-31, LIVE GESEHEN: ein zweites Fenster fing von selbst an,
    ein Ziel abzuarbeiten, das in einem anderen gesetzt worden war. Der Grund
    stand genau hier -- `SESSION_DIR/goal.json` ist EIN Ort fuer alle Fenster,
    also liest jeder Motor dasselbe Ziel und pumpt darauf los. Zwei Fenster
    arbeiteten denselben Plan doppelt ab, in einem Ordner, den nur eines von
    beiden gebunden hatte.

    EIN ZIEL GEHOERT ZU DER ARBEIT, FUER DIE ES GESETZT WURDE, und die Arbeit
    ist der Ordner. Also `<root>/.crow/goal.json`, neben `MEMORY.md` und
    `root.json` -- dieselbe Regel, der `memory_path` seit #120 folgt und die
    `git_repo()` seit #156 als "THE WORKING AREA DECIDES" ueber sich stehen hat.

    ZWEI FENSTER AUF DEMSELBEN ORDNER TEILEN ES WEITERHIN, und das ist richtig:
    dasselbe Arbeitsgebiet ist dieselbe Arbeit. Was aufhoert, ist das Teilen
    zwischen Ordnern, die nichts miteinander zu tun haben.

    OHNE GEBUNDENEN ORDNER bleibt es, wo es war. Ein Chat, der ausdruecklich
    keinen Ordner hat (#101), soll trotzdem ein Ziel halten koennen, und ein
    Ersatzort waere eine Grenze, die niemand gezogen hat -- dieselbe
    Entscheidung, die `memory_path` fuer den wurzellosen Fall trifft.

    DIE FOLGE, DAMIT SIE NICHT UEBERRASCHT: wer den Ordner wechselt, waehrend
    ein Ziel laeuft, wechselt das Ziel mit. Das ist die gemeinte Bedeutung von
    "das Ziel gehoert zum Ordner" und kein Verlust -- das alte steht noch da,
    wo es gesetzt wurde, und kommt mit dem Ordner zurueck.

    Zur Laufzeit gebaut, wie die Subtask-Registry: die Suiten biegen
    `SESSION_DIR` und die Wurzel um, und eine beim Import gefrorene Konstante
    schriebe in die echte Installation.
    """
    root = get_root()
    if root:
        return os.path.join(root, ROOT_MARKER, GOAL_FILE)
    return os.path.join(SESSION_DIR, GOAL_FILE)


def goal_load() -> "dict | None":
    """Das aktive Ziel, oder None.

    TOLERANT WIE JEDE BEQUEMLICHKEITSDATEI, mit einer Ausnahme: eine Datei, die
    da ist und nicht gelesen werden kann, ist NICHT dasselbe wie kein Ziel. Sie
    wird trotzdem als None beantwortet -- ein Fenster, das wegen eines kaputten
    JSON nicht startet, waere der schlechtere Tausch.
    """
    try:
        with open(goal_path(), encoding="utf-8-sig") as fh:
            raw = json.load(fh)
    except (OSError, ValueError):
        return None
    goal = (raw or {}).get("goal")
    if not isinstance(goal, dict) or not goal.get("steps"):
        return None
    _goal_repair_skips(goal)                                   # #296
    return goal


# #296: A `done` WHOSE NOTE BEGINS "skipped" WAS NEVER DONE. 2026-09-24 ~22:00,
# before `/goal skip` existed, step 4 of the diorama goal was set `done` by
# hand with the note "skipped by the owner (2026-09-24 ~22:00): ray lighting is
# not verifiable ..." -- and `goal_counts` counted it, 5/9. Narrow on
# purpose: only a note that STARTS with the word.
_GOAL_SKIP_NOTE = re.compile(r"(?i)^\s*skipped\b")


def _goal_repair_skips(goal: dict) -> None:
    for step in goal.get("steps") or []:
        if (isinstance(step, dict) and step.get("status") == GOAL_DONE
                and _GOAL_SKIP_NOTE.match(str(step.get("note") or ""))):
            step["status"] = GOAL_SKIPPED
            step.setdefault("skipped_by", GOAL_BY_USER)
    states = [s.get("status") for s in goal.get("steps") or []
              if isinstance(s, dict)]
    if (goal.get("status") == GOAL_DONE and GOAL_SKIPPED in states
            and all(x in (GOAL_DONE, GOAL_SKIPPED) for x in states)):
        goal["status"] = GOAL_PARTIAL


def goal_write(goal: "dict | None") -> None:
    """Das Ziel auf Platte. `None` loescht es.

    GESCHRIEBEN WIRD UEBER EINE TEMPDATEI, weil dieser Speicher als einziger
    einen Prozesstod ueberleben SOLL: ein halb geschriebenes goal.json waere
    genau in dem Moment unlesbar, fuer den es existiert. `os.replace` ist auf
    Windows atomar innerhalb desselben Volumes.
    """
    path = goal_path()
    if goal is None:
        try:
            os.remove(path)
        except OSError:
            pass
        return
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    tmp = path + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump({"format": GOAL_FORMAT, "goal": goal}, fh, indent=1,
                      ensure_ascii=False)
        os.replace(tmp, path)
    except OSError:
        try:
            os.remove(tmp)
        except OSError:
            pass


def goal_start(title: str, steps: "list[str]",
               now: "float | None" = None,
               by: "str | None" = None) -> "dict | None":
    """Ein neues Ziel. Ersetzt ein laufendes -- eines zur Zeit.

    LEERE SCHRITTE SIND KEIN ZIEL. Ein Titel ohne Plan waere eine Ueberschrift,
    an der die Anzeige einen Zaehler `0/0` haengt und der Motor nichts zu tun
    findet; None sagt das, statt eine Datei anzulegen, die niemand fuellen kann.
    """
    title = (title or "").strip()
    clean = [str(s).strip() for s in (steps or []) if str(s).strip()]
    if not title or not clean:
        return None
    started = float(now if now is not None else time.time())
    goal = {"title": title,
            # #240: WHO WROTE THE PLAN. `/goal` is the user's word and its
            # paths are mandates (`mandated_paths`); `goal_set` is the model's
            # and mandates nothing. None (a caller that did not say, or a
            # file from before this key) reads as the model's.
            "by": by if by in (GOAL_BY_USER, GOAL_BY_MODEL) else None,
            "created": started,
            # WANN ZULETZT ETWAS PASSIERTE, und wieviel Kontext da stand. Beides
            # gemessen am 2026-08-30 gebraucht: das Modell ruft `goal_step` fast
            # immer nur mit `done`, nie mit `running` -- ohne einen Startpunkt
            # war jede Dauer 0 und jede Tokenzahl 0. Crow misst deshalb selbst,
            # von Uebergang zu Uebergang, statt sich auf eine Meldung zu
            # verlassen, die das Modell nicht abgibt.
            "last_at": started,
            # WANN CROW ANGEFANGEN HAT, und das ist NICHT, wann der Plan
            # geschrieben wurde. Zwischen `/goal` und der Zeile, die die Arbeit
            # anstoesst, liegt Tippzeit -- die lief bis hier in der Zielhur mit
            # und in der Dauer des ersten Schritts gleich mit (der Owner,
            # 2026-08-31). None heisst: noch kein Lebenszeichen, Uhr auf 0.
            "started": None,
            # WAS DAS ZIEL BISHER GEKOSTET HAT, und der Stand davon beim letzten
            # Uebergang. Zwei Zahlen und nicht der absolute Kontextzaehler, weil
            # der beim Rollover auf null faellt: eine Differenz ueber den Schnitt
            # hinweg waere negativ und damit 0 (#174).
            "spent": 0,
            "last_spent": 0,
            # WAS AUF FREMDEN SPOTS AUSGEGEBEN WURDE, getrennt gefuehrt (#169).
            "delegated": 0,
            "status": GOAL_OPEN,
            "steps": [{"text": text, "status": GOAL_OPEN, "started": None,
                       "started_tokens": None,
                       "seconds": 0.0, "tokens": 0, "delegated": 0,
                       "note": ""}
                      for text in clean]}
    goal_write(goal)
    return goal


def _goal_begun(goal: dict, at: float) -> None:
    """Das erste Lebenszeichen setzt die Uhr in Gang, einmal.

    ZWEI DINGE AUF EINMAL, und das zweite ist der eigentliche Fehler: `last_at`
    war die Anlegezeit, also bekam der erste Schritt die Tippzeit als Dauer
    angerechnet, wenn er ohne `running` gemeldet wurde. Beide Uhren fangen dort
    an, wo die Arbeit anfaengt.
    """
    if goal.get("started"):
        return
    goal["started"] = at
    goal["last_at"] = at


def goal_step_begin(index: int, now: "float | None" = None,
                    note: str = "") -> "dict | None":
    """Schritt `index` laeuft ab jetzt. Das Ziel danach, oder None.

    NUR EIN LAUFENDER SCHRITT, und das bleibt so: zwei laufende Schritte waeren
    zwei Uhren auf demselben Slot (der lokale Server hat einen), und die Summe
    waere doppelt so gross wie die Zeit, die vergangen ist. Ein `begin` auf einen
    anderen Schritt LEHNT deshalb nicht mehr ab, sondern PARKT den laufenden:
    seine Uhr und seine Token werden gebucht, er faellt auf `open` zurueck. Das
    Ablehnen war die Falle -- der Motor stoesst den naechsten Schritt selbst an,
    also lief immer einer, und jeder Versuch des Modells, woanders weiterzu-
    arbeiten, verpuffte still.

    ERLEDIGT DARF WIEDER AUFGEHEN (#168). Live gesehen am 2026-08-30: ein
    delegierter Task lieferte Unbrauchbares, Crow baute den Meilenstein neu -- und
    das Panel trug den ganzen Zug ueber den gruenen Haken. Schlimmer als die
    Anzeige ist die Wiederaufnahme: der Speicher ist nach einem Rollover der
    einzige Beleg, wo die Arbeit steht, und der Motor nimmt den ersten Schritt,
    der nicht `done` ist -- er uebersprang also genau die Arbeit, die lief.
    Aufgemacht wird NUR auf diesen Aufruf hin, nie aus einer Vermutung heraus.
    """
    with _GOAL_LOCK:
        goal = goal_load()
        if goal is None or not 0 <= index < len(goal["steps"]):
            return None
        at = float(now if now is not None else time.time())
        _goal_begun(goal, at)
        spent = int(goal.get("spent") or 0)
        for n, other in enumerate(goal["steps"]):
            if n != index and other["status"] == GOAL_RUNNING:
                _goal_close_window(goal, other, at, spent)
                other["status"] = GOAL_OPEN
        step = goal["steps"][index]
        # DER ZAEHLER GEHT ZURUECK, WENN EIN HAKEN ZURUECKGENOMMEN WIRD, und mit
        # ihm der Zustand des Ziels: "Complete" darf nicht stehen bleiben,
        # waehrend an einem Schritt gearbeitet wird.
        # #289: and "complete with N skipped" just as little.
        if goal.get("status") in (GOAL_DONE, GOAL_PARTIAL):
            goal["status"] = GOAL_OPEN
        # #275: A STEP THAT IS ALREADY RUNNING KEEPS ITS CLOCK. 2026-09-24,
        # diorama run: the engine began step 2 at 10:07, the model reported
        # it `running` again at 11:21 (session.json msg 148), and this line
        # set `started` to 11:21 -- 73.5 min and their tokens were never
        # billed, goal.json read `seconds 0, tokens 0`. The same state said
        # twice is one state; nothing moves.
        already = (step["status"] == GOAL_RUNNING
                   and step.get("started") is not None)
        step["status"] = GOAL_RUNNING
        if not already:
            # DIE SEKUNDEN BLEIBEN STEHEN, die Uhr faengt neu an:
            # `goal_step_end` addiert, also traegt ein wieder aufgemachter
            # Schritt am Ende beide Strecken. Dasselbe fuer die Token.
            step["started"] = at
            step["started_tokens"] = spent
            goal["last_at"], goal["last_spent"] = at, spent
        # #275: the note of a `running` call is kept (it was dropped while
        # the tool answered ok); `done`/`failed` replace it with theirs.
        if str(note or "").strip():
            step["note"] = str(note)[:400]
        # #295: THE USER'S ACCEPT LINES FREEZE THE CHECKLIST WHEN THE STEP
        # STARTS -- before any capture exists, so no capture can shape it.
        if not step.get("checklist") and goal_step_needs_render(goal, index):
            accept = goal_accept_for(index)
            if accept:
                _checklist_freeze_in(goal, index, accept,
                                     GOAL_CHECK_FROM_USER, at)
        goal_write(goal)
        return goal


def _goal_close_window(goal: dict, step: dict, at: float, spent: int,
                       tokens: int = 0) -> None:
    """Die Strecke eines Schritts abrechnen: Uhr und Token dazu, Marken weg.

    EINE STELLE FUER BEIDE WEGE -- ein Schritt endet (`done`/`failed`) oder wird
    geparkt, weil woanders weitergearbeitet wird. Rechnete jeder Weg selbst, waere
    genau der geparkte Fall der, den jemand vergisst, und seine Zeit landete beim
    naechsten Schritt.
    """
    began = step.get("started")
    if began is None:
        began = float(goal.get("last_at") or at)
    step["seconds"] = round(float(step.get("seconds") or 0.0)
                            + max(0.0, at - float(began)), 1)
    began_tok = step.get("started_tokens")
    if began_tok is None:
        began_tok = int(goal.get("last_spent") or 0)
    grew = max(0, spent - int(began_tok))
    step["tokens"] = int(step.get("tokens") or 0) + (max(0, int(tokens or 0))
                                                    or grew)
    step["started"] = None
    step["started_tokens"] = None


def goal_step_end(index: int, ok: bool = True, tokens: int = 0,
                  note: str = "", now: "float | None" = None) -> "dict | None":
    """Schritt `index` ist fertig oder gescheitert. Das Ziel danach, oder None.

    DIE SEKUNDEN WERDEN ADDIERT, nicht gesetzt: ein Schritt, der nach einem
    Fehlschlag erneut laeuft, hat zweimal Zeit gekostet, und die Summe ist die
    ehrliche Zahl. Ohne `started` -- ein Schritt, der ohne `begin` beendet wird,
    etwa nach einem Neustart mitten drin -- bleibt sie stehen, statt aus einem
    fehlenden Anfang eine Dauer zu erfinden.
    """
    with _GOAL_LOCK:
        goal = goal_load()
        if goal is None or not 0 <= index < len(goal["steps"]):
            return None
        step = goal["steps"][index]
        end = float(now if now is not None else time.time())
        _goal_begun(goal, end)
        # DER ANFANG IST DER LETZTE UEBERGANG, wenn der Schritt nie `running`
        # war. Das ist der Normalfall: das Modell meldet fast nur `done`. Die
        # Zeit seit dem vorigen Schritt IST die Zeit, die dieser gekostet hat --
        # alles dazwischen war seine Arbeit. Fuer die Token gilt dasselbe,
        # gemessen an `spent` und nicht am absoluten Kontextzaehler: der faellt
        # beim Rollover auf null, und eine Differenz ueber den Schnitt hinweg
        # waere 0 (#169).
        spent = int(goal.get("spent") or 0)
        _goal_close_window(goal, step, end, spent, tokens=tokens)
        goal["last_at"], goal["last_spent"] = end, spent
        if ok:
            step["status"] = GOAL_DONE
            # #294: a finished step owes nothing any more.
            for key in ("pending", "env_seen"):
                step.pop(key, None)
        else:
            # #294: `failed` IS A STATUS, NOT A VERDICT ON THE PLAN. #289
            # skipped the step here on its second failure; the count and
            # what follows now belong to `goal_fail`, which the caller runs.
            step["status"] = GOAL_FAILED
        step["note"] = str(note or "")[:400]
        _goal_settle(goal)
        goal_write(goal)
        return goal


def _goal_settle(goal: dict) -> None:
    """Der Zustand des Ziels aus dem seiner Schritte.

    FERTIG IST DAS ZIEL ERST, WENN KEIN SCHRITT MEHR OFFEN IST -- ein
    gescheiterter zaehlt nicht als erledigt, sonst hiesse "Complete" hier
    "es wird nichts mehr passieren" statt "es ist geschafft".

    #289: EIN UEBERSPRUNGENER AUCH NICHT. Alles erledigt oder uebersprungen,
    und mindestens einer uebersprungen, ist `partial` -- "complete with N
    skipped" --, nie `done`.
    """
    states = [s.get("status") for s in goal.get("steps") or []]
    if states and all(x == GOAL_DONE for x in states):
        goal["status"] = GOAL_DONE
        goal.pop("pause", None)                                # #294
    elif states and all(x in (GOAL_DONE, GOAL_SKIPPED) for x in states):
        goal["status"] = GOAL_PARTIAL
        goal.pop("pause", None)                                # #294
    elif goal.get("status") in (GOAL_DONE, GOAL_PARTIAL):
        goal["status"] = GOAL_OPEN


def goal_step_skip(index: int, note: str = "",
                   now: "float | None" = None) -> "tuple[dict | None, str | None]":
    """#289. `/goal skip <n> [reason]`: the user gives a step up. (goal, None), or
    (None, why not).

    THE USER'S WORD, NOT THE MODEL'S: there is no tool for this. A step the
    model cannot finish goes through `failed` twice; this is the way for the
    step the user already knows cannot be done here. A `done` step is not
    skipped -- that would take back work that happened. There is no
    `/goal done <n>` beside it on purpose: acceptance stays with the evidence
    gate (#250/#267).

    A RUNNING STEP IS BILLED FIRST, like a parked one: its clock and tokens
    are the time spent on it, skipped or not.
    """
    with _GOAL_LOCK:
        goal = goal_load()
        if goal is None:
            return None, "no goal."
        steps = goal.get("steps") or []
        if not 0 <= index < len(steps):
            return None, "no step %d -- the goal has %d." % (index + 1,
                                                            len(steps))
        step = steps[index]
        if step.get("status") == GOAL_DONE:
            return None, "step %d is done; there is nothing to skip." % (
                index + 1)
        at = float(now if now is not None else time.time())
        if step.get("status") == GOAL_RUNNING:
            spent = int(goal.get("spent") or 0)
            _goal_close_window(goal, step, at, spent)
            goal["last_at"], goal["last_spent"] = at, spent
        step["status"] = GOAL_SKIPPED
        step["note"] = (str(note or "").strip()
                        or "skipped by the user")[:400]
        step["skipped_by"] = GOAL_BY_USER
        _goal_settle(goal)
        goal_write(goal)
        return goal, None


def goal_step_redo(index: int) -> "tuple[dict | None, str | None]":
    """#296. `/goal redo <n>`: the user takes their own skip back. The step is
    open again; its failure record stays, its skip mark goes."""
    with _GOAL_LOCK:
        goal = goal_load()
        if goal is None:
            return None, "no goal."
        steps = goal.get("steps") or []
        if not 0 <= index < len(steps):
            return None, "no step %d -- the goal has %d." % (index + 1,
                                                            len(steps))
        step = steps[index]
        if step.get("status") != GOAL_SKIPPED:
            return None, "step %d is %s, not skipped." % (
                index + 1, step.get("status") or "open")
        step["status"] = GOAL_OPEN
        step.pop("skipped_by", None)
        step["note"] = ""
        if goal.get("status") in (GOAL_DONE, GOAL_PARTIAL):
            goal["status"] = GOAL_OPEN
        _goal_settle(goal)
        goal_write(goal)
        return goal, None


def goal_shape(goal: "dict | None") -> str:
    """#289. What a goal display draws apart from its running numbers: the
    title, the goal's state, and each step's text, state and note. It moves
    when a step moves -- through a tool, `/goal`, or a hand edit of
    goal.json -- and not when a round only adds tokens."""
    if not goal:
        return ""
    return json.dumps([goal.get("title"), goal.get("status"),
                       goal.get("pause"),                      # #294
                       [[s.get("text"), s.get("status"), s.get("note"),
                         [x.get("status") for x in s.get("subs") or []],
                         len(s.get("passed") or [])]
                        for s in goal.get("steps") or []]])


def goal_skipped(goal: "dict | None" = None) -> "list[int]":
    """#289: the one-based numbers of the skipped steps."""
    goal = goal if goal is not None else goal_load()
    return [n for n, s in enumerate((goal or {}).get("steps") or [], 1)
            if s.get("status") == GOAL_SKIPPED]


def goal_counts(goal: "dict | None" = None) -> "tuple[int, int]":
    """(erledigt, gesamt) -- der Zaehler, den der Kopf der Anzeige traegt."""
    goal = goal if goal is not None else goal_load()
    if not goal:
        return (0, 0)
    steps = goal.get("steps") or []
    return (sum(1 for s in steps if s.get("status") == GOAL_DONE), len(steps))


def goal_seconds(goal: "dict | None" = None,
                 now: "float | None" = None) -> float:
    """Verstrichene Zeit des ZIELS, Wanduhr seit dem ersten Lebenszeichen.

    NICHT DIE SUMME DER SCHRITTE, und der Unterschied ist der Punkt: zwischen
    zwei Schritten wird nachgedacht, geschrieben und gewartet, und ein Ziel, das
    nur seine Schritte zaehlt, behauptet, diese Zeit sei nicht vergangen. Dieselbe
    Regel, der die Zeile eines Zuges seit jeher folgt.
    """
    goal = goal if goal is not None else goal_load()
    if not goal:
        return 0.0
    # NICHT SEIT `created`: der Plan kann lange dastehen, bevor jemand die
    # Zeile tippt, die ihn anstoesst. Ohne Anfang ist die Uhr 0 und nicht "seit
    # dem Anlegen" -- 0 ist wahr, das andere waere eine erfundene Dauer.
    started = float(goal.get("started") or 0.0)
    if not started:
        return 0.0
    return max(0.0, float(now if now is not None else time.time()) - started)


GOAL_HEAD_NOTE = ("This goal outlives a context rollover: if the conversation "
                  "above was cut, the plan below still stands.")

# #210. DIE SEAM-VARIANTE DES HINWEISES. Der normale Kopf nennt nur den Plan
# (#163: der Stand steht in goal.json, eine Marke im Kopf kaeme einen Prefill
# je Haken). Der Kopf NACH DEM SCHNITT traegt die Marken des Schnittzeitpunkts
# -- dort ist der Prefill ohnehin verloren (#163, "der einzige Moment, an dem
# ein Kopf gratis bewegt werden kann"), und der Zug, der den Stand sagt, ist
# genau der, der weggeschnitten wurde. Gemessen am 2026-09-22: ohne die Marken
# baute das Modell den Plan drei Mal neu und loeschte mit jedem `goal_set` die
# Haken. Die Marken altern bewusst nicht -- sie dokumentieren den Schnitt, bis
# der naechste sie neu setzt.
GOAL_SEAM_NOTE = ("This goal outlives a context rollover: the plan above still "
                  "stands, each step with its status as it was at the cut. "
                  "Continue at the first step not marked done or skipped.")


def goal_block(goal: "dict | None" = None,
               include_status: bool = False) -> "str | None":
    """Der Text, der in den gepinnten Kopf gehoert. None, wenn es kein Ziel gibt.

    OHNE JEDEN STAND, und das ist keine Sparsamkeit, sondern die Rechnung: der
    Block ist Teil des Prompt-Kopfes, und jede Aenderung daran kostet einen
    vollen Prefill. Ein abgehakter Schritt im Text waere ein Prefill je Schritt.
    Was das Modell hier braucht, ist der PLAN; wo es steht, sagt ihm der Zug.

    #210. AUSSER AM SCHNITT (`include_status`). Dort ist der Prefill bereits
    verloren und der Stand nirgends mehr zu lesen -- der Digest, der ihn haette
    tragen koennen, war an einem Tool-Call gestorben. Die Marken reiten einmal
    mit und altern dann bewusst: Sie sind der Stand des Schnitts, nicht des
    Zuges, und der naechste Schnitt setzt sie neu.
    """
    goal = goal if goal is not None else goal_load()
    if not goal:
        return None
    lines = ["Active goal: %s" % goal["title"], "Steps:"]
    steps = goal.get("steps") or []
    if include_status:
        marks = {GOAL_DONE: "[done]", GOAL_FAILED: "[failed]",
                 GOAL_RUNNING: "[running]", GOAL_SKIPPED: "[skipped]"}
        lines += ["%d. %s %s" % (n, marks.get(s.get("status"), "[open]"),
                                 s["text"])
                  for n, s in enumerate(steps, 1)]
        nxt = goal_next_open(goal)                             # #289
        if nxt is not None:
            lines.append("Next: step %d. %s" % (nxt + 1, steps[nxt]["text"]))
        lines.append(GOAL_SEAM_NOTE)
    else:
        lines += ["%d. %s" % (n, s["text"])
                  for n, s in enumerate(steps, 1)]
        lines.append(GOAL_HEAD_NOTE)
    check = goal_check_get()                                   # #250
    if check:
        lines.append("Acceptance check, run when the last step is reported "
                     "done; the goal closes only if it passes: %s" % check)
    accept = goal_accept_get()                                 # #266
    if accept:
        lines.append("Accept criteria (the judge scores captures against "
                     "these): %s" % "; ".join(accept))
    return "\n".join(lines)


def goal_summary(goal: "dict | None" = None,
                 now: "float | None" = None) -> "str | None":
    """Eine Zeile fuer ein Fenster, das gerade erst aufgeht: welches Ziel laeuft
    und wie weit es ist. Der #163-Punkt "eine neue Sitzung verweist auf das
    aktive Ziel" -- ohne das ist ein laufendes Ziel unsichtbar, bis jemand
    zufaellig danach fragt."""
    goal = goal if goal is not None else goal_load()
    if not goal:
        return None
    done, total = goal_counts(goal)
    skipped = goal_skipped(goal)                               # #289
    pause = goal_paused(goal)                                  # #294
    if goal.get("status") == GOAL_DONE:
        state = "complete"
    elif goal.get("status") == GOAL_PARTIAL:
        state = "complete with %d skipped" % len(skipped)
    elif pause is not None:
        state = "PAUSED at step %s (%s): %s -- your next line resumes it" % (
            pause.get("step"), pause.get("class") or "?",
            _clip(pause.get("why") or "?", 200))
    else:
        state = "%d min so far" % int(goal_seconds(goal, now) // 60)
    return "goal: %s -- %d/%d, %s%s" % (
        goal["title"], done, total, state,
        "" if not skipped or goal.get("status") == GOAL_PARTIAL
        else " (skipped: %s)" % ", ".join(str(n) for n in skipped))
